      return Math.Sqrt((StartPoint.X - EndPoint.X) * (StartPoint.X - EndPoint.X) + (StartPoint.Y - EndPoint.Y) * (StartPoint.Y - EndPoint.Y) + (StartPoint.Z - EndPoint.Z) * (StartPoint.Z - EndPoint.Z) + (StartPoint.A - EndPoint.A) * (StartPoint.A - EndPoint.A) + (StartPoint.B - EndPoint.B) * (StartPoint.B - EndPoint.B) + (StartPoint.C - EndPoint.C) * (StartPoint.C - EndPoint.C));
    }
    catch (Exception ex)
    {
      string str = $"Pnt1: {StartPoint.ToString()} - Pnt1: {StartPoint.ToString()}";
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, "");
      return 0.0;
    }
  }

