  public void StepLengthCalculation(
    HeightStepCalculationType StepType,
    double Step,
    double StartZ,
    double EndZ,
    ref List<double> CalculatedHeight)
  {
    try
    {
      double num1 = StartZ - EndZ;
      CalculatedHeight.Clear();
      if (StepType == HeightStepCalculationType.ChangeBaseStepMakeEqualAllStep)
      {
        int int32 = Convert.ToInt32(Math.Ceiling(num1 / Step));
        double num2 = num1 / (double) int32;
        for (int index = 1; index <= int32; ++index)
          CalculatedHeight.Add(StartZ - (double) index * num2);
      }
      if (StepType != HeightStepCalculationType.DontChangeBaseStepMakeExtraStep)
        return;
      int int32_1 = Convert.ToInt32(Math.Floor(num1 / Step));
      double num3 = StartZ;
      for (int index = 1; index <= int32_1; ++index)
      {
        CalculatedHeight.Add(StartZ - (double) index * Step);
        num3 = StartZ - (double) index * Step;
      }
      if (num3 - EndZ <= 0.001)
        return;
      CalculatedHeight.Add(EndZ);
    }
    catch (Exception ex)
    {
      string str = $"StepType: {StepType.ToString()} - Step: {Step.ToString()} - StepStartZ: {StartZ.ToString()} - EndZ: {EndZ.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void MinMaxLengthInPoints(
    List<Pnt3D> RefPoints,
    ref double MinLength,
    ref double MaxLength)
  {
    string callMethod = nameof (MinMaxLengthInPoints);
    try
    {
      if (RefPoints.Count < 1)
      {
        MinLength = 0.0;
        MaxLength = 0.0;
      }
      else
      {
        MinLength = double.MaxValue;
        MaxLength = double.MinValue;
        for (int index = 1; index <= RefPoints.Count - 1; ++index)
        {
          double num = this.Length3D(RefPoints[index - 1], RefPoints[index]);
          if (num < MinLength)
            MinLength = num;
          if (num > MaxLength)
            MaxLength = num;
        }
      }
    }
    catch (Exception ex)
    {
      string str = "RefPoints: " + RefPoints.Count.ToString();
      buLog.addLog(str, "Not Ok", callMethod);
      buException.throwException(ex, callMethod, false, str);
    }
  }

  public void RectangleEdgeDistanceByAngle(
    double Width,
    double Height,
    double Angle,
    ref double CalcLength)
  {
    string callMethod = nameof (RectangleEdgeDistanceByAngle);
    try
    {
      double num1 = Math.Abs(Math.Cos(buConversion.DegreeToRadian(Angle)));
      double num2 = Math.Abs(Math.Sin(buConversion.DegreeToRadian(Angle)));
      if (Width / 2.0 * num2 <= Height / 2.0 * num1)
        CalcLength = Width / 2.0 / num1;
      else
        CalcLength = Height / 2.0 / num2;
    }
    catch (Exception ex)
    {
      string str = $"Width: {Width.ToString()}- Height: {Height.ToString()}- Angle: {Angle.ToString()}";
      buLog.addLog(str, "Not Ok", callMethod);
      buException.throwException(ex, callMethod, false, str);
    }
  }

  public void SawDistance(
    double Diameter,
    double Thickness,
    double TargetZ,
    ref double CalcDistance)
  {
    string callMethod = nameof (SawDistance);
    try
    {
      double num = Math.Pow(Diameter / 2.0 - (Thickness - TargetZ), 2.0);
      CalcDistance = Math.Sqrt(Math.Pow(Diameter / 2.0, 2.0) - num);
    }
    catch (Exception ex)
    {
      string str = $"Diameter: {Diameter.ToString()}- Thickness: {Thickness.ToString()}- TargetZ: {TargetZ.ToString()}";
      buLog.addLog(str, "Not Ok", callMethod);
      buException.throwException(ex, callMethod, false, str);
      CalcDistance = 0.0;
    }
  }

  public void AreaUnitRatioFromMM(LengthUnit Unit, ref double UnitRatio)
  {
    switch (Unit)
    {
      case LengthUnit.mm:
        UnitRatio = 1.0;
        break;
      case LengthUnit.cm:
        UnitRatio = 100.0;
        break;
      case LengthUnit.dm:
        UnitRatio = 10000.0;
        break;
      case LengthUnit.m:
        UnitRatio = 1000000.0;
        break;
      case LengthUnit.dam:
        UnitRatio = 100000000.0;
        break;
      case LengthUnit.hm:
        UnitRatio = 10000000000.0;
        break;
      case LengthUnit.km:
        UnitRatio = 1000000000000.0;
        break;
    }
  }

  public double PointAngle(
    Pnt6D PntEnd,
    Pnt6D PntCenter,
    ref double XY,
    ref double XZ,
    ref double YZ)
  {
    try
    {
      Math.Atan(this.DeltaY(PntEnd.Y, PntCenter.Y) / this.DeltaX(PntEnd.X, PntCenter.X));
      double num1 = buConversion.RadianToDegree(Math.Atan(this.DeltaY(PntEnd.Y, PntCenter.Y) / this.DeltaX(PntEnd.X, PntCenter.X)));
      if (PntEnd.X == PntCenter.X)
        num1 = 90.0;
      if (PntEnd.Y > PntCenter.Y && num1 < 0.0)
        num1 = 180.0 + num1;
      if (PntEnd.Y < PntCenter.Y)
        num1 = num1 >= 0.0 ? 180.0 + num1 : 360.0 + num1;
      if (PntCenter.Y == PntEnd.Y & PntCenter.X > PntEnd.X)
        num1 = 180.0;
      if (PntCenter.X == PntEnd.X & PntCenter.Y == PntEnd.Y)
        num1 = -1.0;
      XY = num1;
      double num2 = buConversion.RadianToDegree(Math.Atan(this.DeltaZ(PntEnd.Z, PntCenter.Z) / this.DeltaX(PntEnd.X, PntCenter.X)));
      if (PntEnd.X == PntCenter.X)
        num2 = 90.0;
      if (PntEnd.Z > PntCenter.Z && num2 < 0.0)
        num2 = 180.0 + num2;
      if (PntEnd.Z < PntCenter.Z)
        num2 = num2 >= 0.0 ? 180.0 + num2 : 360.0 + num2;
      if (PntCenter.Z == PntEnd.Z & PntCenter.X > PntEnd.X)
        num2 = 180.0;
      if (PntCenter.X == PntEnd.X & PntCenter.Z == PntEnd.Z)
        num2 = -1.0;
      XZ = num2;
      double num3 = buConversion.RadianToDegree(Math.Atan(this.DeltaZ(PntEnd.Z, PntCenter.Z) / this.DeltaY(PntEnd.Y, PntCenter.Y)));
      if (PntEnd.Y == PntCenter.Y)
        num3 = 90.0;
      if (PntEnd.Z > PntCenter.Z && num3 < 0.0)
        num3 = 180.0 + num3;
      if (PntEnd.Z < PntCenter.Z)
        num3 = num3 >= 0.0 ? 180.0 + num3 : 360.0 + num3;
      if (PntCenter.Z == PntEnd.Z & PntCenter.Y > PntEnd.Y)
        num3 = 180.0;
      if (PntCenter.Y == PntEnd.Y & PntCenter.Z == PntEnd.Z)
        num3 = -1.0;
      YZ = num3;
      return XY;
    }
    catch (Exception ex)
    {
      string str = $"PntEnd: {PntEnd.ToString()} - PntCenter: {PntCenter.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return 0.0;
    }
  }

