  public double AngleOfTwoLines(
    Pnt3D FirstLineStart,
    Pnt3D FirstLineEnd,
    Pnt3D SecondLineStart,
    Pnt3D SecondLineEnd,
    WorkPlane Plane)
  {
    try
    {
      Pnt3D IntersectionPoint = new Pnt3D();
      Pnt3D pnt3D1 = new Pnt3D();
      Pnt3D pnt3D2 = new Pnt3D();
      bool IsLineIntersect = false;
      this.LineLineIntersection(FirstLineStart, FirstLineEnd, SecondLineStart, SecondLineEnd, Plane, ref IntersectionPoint, ref IsLineIntersect);
      if (!IsLineIntersect)
        return 180.0;
      double num1 = this.Length3D(FirstLineStart, IntersectionPoint);
      double num2 = this.Length3D(FirstLineEnd, IntersectionPoint);
      double num3 = this.Length3D(SecondLineStart, IntersectionPoint);
      double num4 = this.Length3D(SecondLineEnd, IntersectionPoint);
      Pnt3D PntEnd1 = num1 <= num2 ? new Pnt3D(FirstLineEnd) : new Pnt3D(FirstLineStart);
      Pnt3D PntEnd2 = num3 <= num4 ? new Pnt3D(SecondLineEnd) : new Pnt3D(SecondLineStart);
      double num5 = Math.Abs(this.PointAngle(PntEnd1, IntersectionPoint, Plane) - this.PointAngle(PntEnd2, IntersectionPoint, Plane));
      if (num5 > 180.0)
        num5 = 360.0 - num5;
      return num5;
    }
    catch (Exception ex)
    {
      string str = $"FirstLineStart: {FirstLineStart.ToString()} - FirstLineEnd: {FirstLineEnd.ToString()} - SecondLineStart: {SecondLineStart.ToString()} - SecondLineEnd: {SecondLineEnd.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return 0.0;
    }
  }

  public OrientationAngle Vector3dToOrientationAngle(Vec3D d)
  {
    double a = 0.0;
    double b = 0.0;
    double c = 0.0;
    Vec3D vec3D1 = new Vec3D();
    Vec3D.Normalise(d);
    Vec3D RefVector1 = new Vec3D(d.X, d.Y, 0.0);
    Vec3D vec3D2 = new Vec3D();
    Vec3D vec3D3 = Vec3D.Normalise(RefVector1);
    if (d.X > 0.0 & d.Y > 0.0)
      c = RefVector1.X < 0.0 ? (RefVector1.Y <= 0.0 ? 360.0 - buConversion.RadianToDegree(Math.Acos(vec3D3.X)) : buConversion.RadianToDegree(Math.Acos(vec3D3.X))) : (RefVector1.Y <= 0.0 ? 360.0 - buConversion.RadianToDegree(Math.Acos(vec3D3.X)) : buConversion.RadianToDegree(Math.Acos(vec3D3.X)));
    Vec3D RefVector2 = new Vec3D(d.X, 0.0, d.Z);
    Vec3D vec3D4 = new Vec3D();
    Vec3D vec3D5 = Vec3D.Normalise(RefVector2);
    if (d.X > 0.0 & d.Z > 0.0)
      b = RefVector2.X < 0.0 ? (RefVector2.Z <= 0.0 ? 360.0 - buConversion.RadianToDegree(Math.Acos(vec3D5.X)) : buConversion.RadianToDegree(Math.Acos(vec3D5.X))) : (RefVector2.Z <= 0.0 ? 360.0 - buConversion.RadianToDegree(Math.Acos(vec3D5.X)) : buConversion.RadianToDegree(Math.Acos(vec3D5.X)));
    Vec3D RefVector3 = new Vec3D(0.0, d.Y, d.Z);
    Vec3D vec3D6 = new Vec3D();
    Vec3D vec3D7 = Vec3D.Normalise(RefVector3);
    if (d.Y > 0.0 & d.Z > 0.0)
      a = RefVector3.Y < 0.0 ? (RefVector3.Z < 0.0 ? 360.0 - buConversion.RadianToDegree(Math.Acos(vec3D7.Y)) : buConversion.RadianToDegree(Math.Acos(vec3D7.Y))) : (RefVector3.Z < 0.0 ? 360.0 - buConversion.RadianToDegree(Math.Acos(vec3D7.Y)) : buConversion.RadianToDegree(Math.Acos(vec3D7.Y)));
    if (a >= 360.0)
      a -= 360.0;
    if (b >= 360.0)
      b -= 360.0;
    if (c >= 360.0)
      c -= 360.0;
    return new OrientationAngle(a, b, c);
  }

  public void CalculateCAngleFromPointList(List<Pnt3D> RefPoints, ref List<Pnt6D> calcPoints)
  {
    string callMethod = nameof (CalculateCAngleFromPointList);
    try
    {
      if (RefPoints.Count <= 1)
        return;
      double c1 = this.PointAngle(RefPoints[1], RefPoints[0], new WorkPlane());
      calcPoints.Add(new Pnt6D(RefPoints[0].X, RefPoints[0].Y, RefPoints[0].Z, 0.0, 0.0, c1));
      for (int index = 1; index <= RefPoints.Count - 1; ++index)
      {
        double c2 = this.PointAngle(RefPoints[index], RefPoints[index - 1], new WorkPlane());
        calcPoints.Add(new Pnt6D(RefPoints[index].X, RefPoints[index].Y, RefPoints[index].Z, 0.0, 0.0, c2));
      }
    }
    catch (Exception ex)
    {
      string str = "RefPoints: " + RefPoints.Count.ToString();
      buLog.addLog(str, "Not Ok", callMethod);
      buException.throwException(ex, callMethod, false, str);
    }
  }

