  public void BoxSizeCalculate(TriangulationPoints Pnt, ref Pnt3D MinPnt, ref Pnt3D MaxPnt)
  {
    try
    {
      MinPnt = new Pnt3D();
      MaxPnt = new Pnt3D();
      MinPnt.X = double.MaxValue;
      MinPnt.Y = double.MaxValue;
      MinPnt.Z = double.MaxValue;
      MaxPnt.X = double.MinValue;
      MaxPnt.Y = double.MinValue;
      MaxPnt.Z = double.MinValue;
      for (int index = 0; index <= Pnt.Points.Count - 1; ++index)
      {
        if (Pnt.Points[index].X > MaxPnt.X)
          MaxPnt.X = Pnt.Points[index].X;
        if (Pnt.Points[index].Y > MaxPnt.Y)
          MaxPnt.Y = Pnt.Points[index].Y;
        if (Pnt.Points[index].Z > MaxPnt.Z)
          MaxPnt.Z = Pnt.Points[index].Z;
        if (Pnt.Points[index].X < MinPnt.X)
          MinPnt.X = Pnt.Points[index].X;
        if (Pnt.Points[index].Y < MinPnt.Y)
          MinPnt.Y = Pnt.Points[index].Y;
        if (Pnt.Points[index].Z < MinPnt.Z)
          MinPnt.Z = Pnt.Points[index].Z;
      }
    }
    catch (Exception ex)
    {
      string str = "Pnt: " + Pnt.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

