  public void BoxSizeWithContentAlignment(
    List<Pnt3D> RefPoints,
    WorkPlane Plane,
    ref ContentAlignmentPoints AlignPoints)
  {
    try
    {
      Pnt3D MinPoint = new Pnt3D();
      Pnt3D MaxPoint = new Pnt3D();
      Pnt3D MidPoint = new Pnt3D();
      this.BoxSizeCalculate(RefPoints, ref MinPoint, ref MidPoint, ref MaxPoint);
      if (WorkPlane.isPlaneXY(Plane))
      {
        AlignPoints.TopLeftPoint = new Pnt3D(MinPoint.X, MaxPoint.Y, MinPoint.Z);
        AlignPoints.TopCenterPoint = new Pnt3D(MidPoint.X, MaxPoint.Y, MinPoint.Z);
        AlignPoints.TopRightPoint = new Pnt3D(MaxPoint.X, MaxPoint.Y, MinPoint.Z);
        AlignPoints.MiddleLeftPoint = new Pnt3D(MinPoint.X, MidPoint.Y, MinPoint.Z);
        AlignPoints.MiddleCenterPoint = new Pnt3D(MidPoint.X, MidPoint.Y, MinPoint.Z);
        AlignPoints.MiddleRightPoint = new Pnt3D(MaxPoint.X, MidPoint.Y, MinPoint.Z);
        AlignPoints.BottomLeftPoint = new Pnt3D(MinPoint.X, MinPoint.Y, MinPoint.Z);
        AlignPoints.BottomCenterPoint = new Pnt3D(MidPoint.X, MinPoint.Y, MinPoint.Z);
        AlignPoints.BottomRightPoint = new Pnt3D(MaxPoint.X, MinPoint.Y, MinPoint.Z);
      }
      if (WorkPlane.isPlaneXZ(Plane))
      {
        AlignPoints.TopLeftPoint = new Pnt3D(MinPoint.X, MinPoint.Y, MaxPoint.Z);
        AlignPoints.TopCenterPoint = new Pnt3D(MidPoint.X, MinPoint.Y, MaxPoint.Z);
        AlignPoints.TopRightPoint = new Pnt3D(MaxPoint.X, MinPoint.Y, MaxPoint.Z);
        AlignPoints.MiddleLeftPoint = new Pnt3D(MinPoint.X, MinPoint.Y, MidPoint.Z);
        AlignPoints.MiddleCenterPoint = new Pnt3D(MidPoint.X, MinPoint.Y, MidPoint.Z);
        AlignPoints.MiddleRightPoint = new Pnt3D(MaxPoint.X, MinPoint.Y, MidPoint.Z);
        AlignPoints.BottomLeftPoint = new Pnt3D(MinPoint.X, MinPoint.Y, MinPoint.Z);
        AlignPoints.BottomCenterPoint = new Pnt3D(MidPoint.X, MinPoint.Y, MinPoint.Z);
        AlignPoints.BottomRightPoint = new Pnt3D(MaxPoint.X, MinPoint.Y, MinPoint.Z);
      }
      if (!WorkPlane.isPlaneYZ(Plane))
        return;
      AlignPoints.TopLeftPoint = new Pnt3D(MinPoint.X, MinPoint.Y, MaxPoint.Z);
      AlignPoints.TopCenterPoint = new Pnt3D(MinPoint.X, MidPoint.Y, MaxPoint.Z);
      AlignPoints.TopRightPoint = new Pnt3D(MinPoint.X, MaxPoint.Y, MaxPoint.Z);
      AlignPoints.MiddleLeftPoint = new Pnt3D(MinPoint.X, MinPoint.Y, MidPoint.Z);
      AlignPoints.MiddleCenterPoint = new Pnt3D(MinPoint.X, MidPoint.Y, MidPoint.Z);
      AlignPoints.MiddleRightPoint = new Pnt3D(MinPoint.X, MaxPoint.Y, MidPoint.Z);
      AlignPoints.BottomLeftPoint = new Pnt3D(MinPoint.X, MinPoint.Y, MinPoint.Z);
      AlignPoints.BottomCenterPoint = new Pnt3D(MinPoint.X, MidPoint.Y, MinPoint.Z);
      AlignPoints.BottomRightPoint = new Pnt3D(MinPoint.X, MaxPoint.Y, MinPoint.Z);
    }
    catch (Exception ex)
    {
      string str = $"RefPoints: {RefPoints.Count.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

