  public void CircularZHeightRampByLengthAndHeight(
    double Length,
    double ZUp,
    double ZDown,
    double ArcRatio,
    int Count,
    ref List<double> Heights,
    ref List<Pnt3D> Points)
  {
    List<Pnt3D> pts = new List<Pnt3D>();
    Pnt3D ArcCenter = new Pnt3D();
    double ArcSA = 0.0;
    double ArcEA = 0.0;
    Pnt3D pnt3D = new Pnt3D(0.0, ZUp, 0.0);
    Pnt3D ArcEndPoint = new Pnt3D(Length, ZDown, 0.0);
    if (ZDown > ZUp)
    {
      pnt3D = new Pnt3D(0.0, ZDown, 0.0);
      ArcEndPoint = new Pnt3D(Length, ZUp, 0.0);
    }
    double Radius = Length / ArcRatio;
    for (double num1 = 1.0; num1 <= 1000.0; num1 += 0.5)
    {
      double num2 = this.Length3D(new Pnt3D(ArcEndPoint.X, ArcEndPoint.Y + num1), pnt3D);
      Math.Abs(num2 - num1);
      if (buCompare.EQ(num2, num1, 1.0))
      {
        Radius = num2;
        num1 = 1000.0;
      }
    }
    this.ArcWithTwoPointAndRadius(pnt3D, ArcEndPoint, Radius, false, new WorkPlane(), ref ArcCenter, ref ArcSA, ref ArcEA);
    this.ArcWithCenter(ArcCenter, Radius, ArcSA, ArcEA, new WorkPlane(), new EntityResolution(1.0, Count - 1, 10.0, EntityResolutionType.ByNumber), ref pts);
    this.RotateByMatrix(new Pnt3D(), 90.0, VectorType.XVector, ref pts);
    if (ZUp > ZDown)
    {
      if (pts[0].Z < pts[pts.Count - 1].Z)
        pts.Reverse();
    }
    else if (pts[0].Z > pts[pts.Count - 1].Z)
      pts.Reverse();
    for (int index = 0; index <= pts.Count - 1; ++index)
      Heights.Add(pts[index].Z);
    Points.Clear();
    Pnt3D.Copy(pts, ref Points);
  }

  public void Pnt3DToPnt6DByTangentAngle(List<Pnt3D> P3List, ref List<Pnt6D> P6List)
  {
    try
    {
      if (P3List.Count == 0)
        return;
      if (P3List.Count == 1)
      {
        P6List.Add(new Pnt6D(P3List[0]));
      }
      else
      {
        P6List.Clear();
        P6List = new List<Pnt6D>();
        for (int index = 0; index <= P3List.Count - 1; ++index)
        {
          if (index == 0)
          {
            double c = this.PointAngle(P3List[index + 1], P3List[index]);
            Pnt6D pnt6D = new Pnt6D(P3List[index].X, P3List[index].Y, P3List[index].Z, 0.0, 0.0, c);
            P6List.Add(pnt6D);
          }
          else
          {
            double c = this.PointAngle(P3List[index], P3List[index - 1]);
            Pnt6D pnt6D = new Pnt6D(P3List[index].X, P3List[index].Y, P3List[index].Z, 0.0, 0.0, c);
            P6List.Add(pnt6D);
          }
        }
      }
    }
    catch (Exception ex)
    {
      string str = "P3List: " + P3List.Count.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public Pnt3D MiddlePointOfLine(Pnt3D Pnt1, Pnt3D Pnt2)
  {
    try
    {
      Pnt3D pnt3D = new Pnt3D();
      pnt3D.X = (Pnt1.X + Pnt2.X) / 2.0;
      pnt3D.Y = (Pnt1.Y + Pnt2.Y) / 2.0;
      pnt3D.Z = (Pnt1.Z + Pnt2.Z) / 2.0;
      return pnt3D;
    }
    catch (Exception ex)
    {
      string str = $"Pnt1: {Pnt1.ToString()} - Pnt2: {Pnt2.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return new Pnt3D();
    }
  }

