  public void XLengthFromYLengthAndAngle(double YLength, double Angle, ref double XLength)
  {
    try
    {
      if (Angle % 90.0 == 0.0)
        XLength = 0.0;
      else
        XLength = YLength * Math.Tan(buConversion.DegreeToRadian(Angle));
    }
    catch (Exception ex)
    {
      string str = $"YLength: {YLength.ToString()} - Angle: {Angle.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

