  public double XFromXYZ(Pnt3D FirstPoint, Pnt3D SecondPoint, Pnt3D RefPoint)
  {
    try
    {
      double num = 0.0;
      if (!buCompare.EQ(FirstPoint.Y, SecondPoint.Y))
        num = (SecondPoint.X - FirstPoint.X) / (SecondPoint.Y - FirstPoint.Y) * (RefPoint.Y - FirstPoint.Y) + FirstPoint.X;
      else if (!buCompare.EQ(FirstPoint.Z, SecondPoint.Z))
        num = (SecondPoint.X - FirstPoint.X) / (SecondPoint.Z - FirstPoint.Z) * (RefPoint.Z - FirstPoint.Z) + FirstPoint.X;
      else if (buCompare.EQ(FirstPoint.Y, SecondPoint.Y) & buCompare.EQ(FirstPoint.Z, SecondPoint.Z))
        num = FirstPoint.X;
      return num;
    }
    catch (Exception ex)
    {
      string str = $"FirstPoint: {FirstPoint.ToString()} - SecondPoint: {SecondPoint.ToString()} - RefPoint: {RefPoint.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return 0.0;
    }
  }

  public double YFromXYZ(Pnt3D FirstPoint, Pnt3D SecondPoint, Pnt3D RefPoint)
  {
    try
    {
      double num = 0.0;
      if (!buCompare.EQ(FirstPoint.X, SecondPoint.X))
        num = (SecondPoint.Y - FirstPoint.Y) / (SecondPoint.X - FirstPoint.X) * (RefPoint.X - FirstPoint.X) + FirstPoint.Y;
      else if (!buCompare.EQ(FirstPoint.Z, SecondPoint.Z))
        num = (SecondPoint.Y - FirstPoint.Y) / (SecondPoint.Z - FirstPoint.Z) * (RefPoint.Z - FirstPoint.Z) + FirstPoint.Y;
      else if (buCompare.EQ(FirstPoint.X, SecondPoint.X) & buCompare.EQ(FirstPoint.Z, SecondPoint.Z))
        num = FirstPoint.Y;
      return num;
    }
    catch (Exception ex)
    {
      string str = $"FirstPoint: {FirstPoint.ToString()} - SecondPoint: {SecondPoint.ToString()} - RefPoint: {RefPoint.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return 0.0;
    }
  }

  public double ZFromXYZ(Pnt3D FirstPoint, Pnt3D SecondPoint, Pnt3D RefPoint)
  {
    try
    {
      double num = 0.0;
      if (!buCompare.EQ(FirstPoint.X, SecondPoint.X))
        num = (SecondPoint.Z - FirstPoint.Z) / (SecondPoint.X - FirstPoint.X) * (RefPoint.X - FirstPoint.X) + FirstPoint.Z;
      else if (!buCompare.EQ(FirstPoint.Y, SecondPoint.Y))
        num = (SecondPoint.Z - FirstPoint.Z) / (SecondPoint.Y - FirstPoint.Y) * (RefPoint.Y - FirstPoint.Y) + FirstPoint.Z;
      else if (buCompare.EQ(FirstPoint.X, SecondPoint.X) & buCompare.EQ(FirstPoint.Y, SecondPoint.Y))
        num = FirstPoint.Z;
      return num;
    }
    catch (Exception ex)
    {
