  public void XYFromZ(Pnt3D StartPoint, Pnt3D EndPoint, double ZValue, ref Pnt3D CalcPoint)
  {
    try
    {
      double num1 = StartPoint.X - EndPoint.X;
      double num2 = StartPoint.Y - EndPoint.Y;
      double num3 = StartPoint.Z - EndPoint.Z;
      double num4 = StartPoint.Z - ZValue;
      if (num3 != 0.0)
      {
        double num5 = num4 / num3;
        CalcPoint = new Pnt3D(StartPoint.X - num1 * num5, StartPoint.Y - num2 * num5, ZValue);
      }
      else
        CalcPoint = new Pnt3D(StartPoint);
    }
    catch (Exception ex)
    {
      string str = $"StartPoint: {StartPoint.ToString()} - EndPoint: {EndPoint.ToString()} - ZValue: {ZValue.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

