  public void XYValueToPointByPlane(double X, double Y, WorkPlane Plane, ref Pnt3D RefPoint)
  {
    try
    {
      if (WorkPlane.isPlaneXY(Plane) | Plane.PlaneType == planeType.YX)
      {
        RefPoint.X = X;
        RefPoint.Y = Y;
      }
      if (WorkPlane.isPlaneXZ(Plane) | Plane.PlaneType == planeType.ZX)
      {
        RefPoint.X = X;
        RefPoint.Z = Y;
      }
      if (!(WorkPlane.isPlaneYZ(Plane) | Plane.PlaneType == planeType.ZY))
        return;
      RefPoint.Y = X;
      RefPoint.Z = Y;
    }
    catch (Exception ex)
    {
      string str = $"X: {X.ToString()} - Y: {Y.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void MinMaxPointsToAlignPoints(
    Pnt3D MinPoint,
    Pnt3D MaxPoint,
    WorkPlane Plane,
    ref AlingmentPoints AlingPoints)
  {
    try
    {
      Pnt3D MiddlePoint = new Pnt3D();
      this.MiddlePointOfLine(MinPoint, MaxPoint, ref MiddlePoint);
      if (WorkPlane.isPlaneXY(Plane) | Plane.PlaneType == planeType.YX)
      {
        AlingPoints.pntBottomLeft = new Pnt3D(MinPoint.X, MinPoint.Y, MinPoint.Z);
        AlingPoints.pntBottomCenter = new Pnt3D(MiddlePoint.X, MinPoint.Y, MinPoint.Z);
        AlingPoints.pntBottomRight = new Pnt3D(MaxPoint.X, MinPoint.Y, MinPoint.Z);
        AlingPoints.pntMiddleLeft = new Pnt3D(MinPoint.X, MiddlePoint.Y, MinPoint.Z);
        AlingPoints.pntMiddleCenter = new Pnt3D(MiddlePoint.X, MiddlePoint.Y, MinPoint.Z);
        AlingPoints.pntMiddleRight = new Pnt3D(MaxPoint.X, MiddlePoint.Y, MinPoint.Z);
        AlingPoints.pntTopLeft = new Pnt3D(MinPoint.X, MaxPoint.Y, MinPoint.Z);
        AlingPoints.pntTopCenter = new Pnt3D(MiddlePoint.X, MaxPoint.Y, MinPoint.Z);
        AlingPoints.pntTopRight = new Pnt3D(MaxPoint.X, MaxPoint.Y, MinPoint.Z);
      }
      if (WorkPlane.isPlaneXZ(Plane) | Plane.PlaneType == planeType.ZX)
      {
        AlingPoints.pntBottomLeft = new Pnt3D(MinPoint.X, MinPoint.Y, MinPoint.Z);
        AlingPoints.pntBottomCenter = new Pnt3D(MiddlePoint.X, MinPoint.Y, MinPoint.Z);
        AlingPoints.pntBottomRight = new Pnt3D(MaxPoint.X, MinPoint.Y, MinPoint.Z);
        AlingPoints.pntMiddleLeft = new Pnt3D(MinPoint.X, MiddlePoint.Y, MiddlePoint.Z);
        AlingPoints.pntMiddleCenter = new Pnt3D(MiddlePoint.X, MiddlePoint.Y, MiddlePoint.Z);
        AlingPoints.pntMiddleRight = new Pnt3D(MaxPoint.X, MiddlePoint.Y, MiddlePoint.Z);
        AlingPoints.pntTopLeft = new Pnt3D(MinPoint.X, MaxPoint.Y, MaxPoint.Z);
        AlingPoints.pntTopCenter = new Pnt3D(MiddlePoint.X, MaxPoint.Y, MaxPoint.Z);
        AlingPoints.pntTopRight = new Pnt3D(MaxPoint.X, MaxPoint.Y, MaxPoint.Z);
      }
      if (!(WorkPlane.isPlaneYZ(Plane) | Plane.PlaneType == planeType.ZY))
        return;
      AlingPoints.pntBottomLeft = new Pnt3D(MinPoint.X, MinPoint.Y, MinPoint.Z);
      AlingPoints.pntBottomCenter = new Pnt3D(MiddlePoint.X, MiddlePoint.Y, MinPoint.Z);
      AlingPoints.pntBottomRight = new Pnt3D(MaxPoint.X, MaxPoint.Y, MinPoint.Z);
      AlingPoints.pntMiddleLeft = new Pnt3D(MinPoint.X, MinPoint.Y, MiddlePoint.Z);
      AlingPoints.pntMiddleCenter = new Pnt3D(MiddlePoint.X, MiddlePoint.Y, MiddlePoint.Z);
      AlingPoints.pntMiddleRight = new Pnt3D(MaxPoint.X, MaxPoint.Y, MiddlePoint.Z);
      AlingPoints.pntTopLeft = new Pnt3D(MinPoint.X, MinPoint.Y, MaxPoint.Z);
      AlingPoints.pntTopCenter = new Pnt3D(MiddlePoint.X, MiddlePoint.Y, MaxPoint.Z);
      AlingPoints.pntTopRight = new Pnt3D(MaxPoint.X, MaxPoint.Y, MaxPoint.Z);
    }
    catch (Exception ex)
    {
      string str = $"MinPoint: {MinPoint.ToString()} - MaxPoint: {MaxPoint.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
