  public void FindClosestPointOfLine(
    Pnt3D StartPoint,
    Pnt3D EndPoint,
    Pnt3D RefPoint,
    ref ClosestPointType ClosestPoint)
  {
    try
    {
      if (this.Length3D(StartPoint, RefPoint) <= this.Length3D(EndPoint, RefPoint))
        ClosestPoint = ClosestPointType.Start;
      else
        ClosestPoint = ClosestPointType.End;
    }
    catch (Exception ex)
    {
      string str = $"StartPoint: {StartPoint.ToString()} - EndPoint: {EndPoint.ToString()} - RefPoint: {RefPoint.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
