    }
  }

  public void FindRefPointBtSortNextRule(
    ref Pnt3D RefPoint,
    List<eEntities> Entities,
    SortingNextGroupFindRulesType SortNextType)
  {
    Pnt3D MinPoint = new Pnt3D();
    Pnt3D MaxPoint = new Pnt3D();
    this.BoxSizeCalculate(Entities, ref MinPoint, ref MaxPoint);
    if (SortNextType == SortingNextGroupFindRulesType.MaxXMaxY | SortNextType == SortingNextGroupFindRulesType.MaxYMaxX)
      RefPoint = new Pnt3D(MaxPoint.X, MaxPoint.Y);
    if (SortNextType == SortingNextGroupFindRulesType.MaxXMinY | SortNextType == SortingNextGroupFindRulesType.MinYMaxX)
      RefPoint = new Pnt3D(MaxPoint.X, MinPoint.Y);
    if (SortNextType == SortingNextGroupFindRulesType.MinXMaxY | SortNextType == SortingNextGroupFindRulesType.MaxYMinX)
      RefPoint = new Pnt3D(MinPoint.X, MaxPoint.Y);
    if (!(SortNextType == SortingNextGroupFindRulesType.MinXMinY | SortNextType == SortingNextGroupFindRulesType.MinYMinX))
      return;
    RefPoint = new Pnt3D(MinPoint.X, MinPoint.Y);
  }

  public void PointFilterByLength(double FilterLength, int CountLimit, ref List<Pnt3D> Vertice)
  {
    try
    {
      List<Pnt3D> pnt3DList = new List<Pnt3D>();
      List<Pnt3D> pts = new List<Pnt3D>();
      if (Vertice.Count <= 0)
        return;
      for (int index = 0; index <= Vertice.Count - 1; ++index)
        pnt3DList.Add(new Pnt3D(Vertice[index]));
      pts.Add(new Pnt3D(pnt3DList[0]));
      for (int index = 1; index <= pnt3DList.Count - 1; ++index)
      {
        if (this.Length3D(pts[pts.Count - 1], pnt3DList[index]) > FilterLength)
          pts.Add(new Pnt3D(pnt3DList[index]));
      }
      if (pnt3DList.Count >= 2 & pts.Count == 1)
        pts.Add(new Pnt3D(pnt3DList[pnt3DList.Count - 1]));
      if (!buCompare.EQ(pts[pts.Count - 1], pnt3DList[pnt3DList.Count - 1]))
        pts.Add(new Pnt3D(pnt3DList[pnt3DList.Count - 1]));
      if (CountLimit <= 0)
      {
        Vertice.Clear();
        Pnt3D.Copy(pts, ref Vertice);
      }
      else
      {
        if (pts.Count < CountLimit)
          return;
        Vertice.Clear();
        Pnt3D.Copy(pts, ref Vertice);
      }
    }
    catch (Exception ex)
    {
      string str = "FilterLength: " + FilterLength.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void PointFilterByLengthAndAngle(
    double FilterLength,
    double AngleLimit,
    ref List<Pnt3D> Vertice)
  {
    try
    {
      List<Pnt3D> pnt3DList = new List<Pnt3D>();
      if (Vertice.Count <= 0)
        return;
      for (int index = 0; index <= Vertice.Count - 1; ++index)
        pnt3DList.Add(new Pnt3D(Vertice[index]));
      Vertice.Clear();
      Vertice.Add(new Pnt3D(pnt3DList[0]));
      for (int index = 1; index <= pnt3DList.Count - 2; ++index)
      {
        if (this.AngleOfTwoLines(pnt3DList[index - 1], pnt3DList[index], pnt3DList[index], pnt3DList[index + 1], new WorkPlane()) > AngleLimit)
        {
          if (this.Length3D(Vertice[Vertice.Count - 1], pnt3DList[index]) > FilterLength)
            Vertice.Add(new Pnt3D(pnt3DList[index]));
        }
        else
          Vertice.Add(new Pnt3D(pnt3DList[index]));
      }
      Vertice.Add(new Pnt3D(pnt3DList[pnt3DList.Count - 1]));
    }
    catch (Exception ex)
    {
      string str = "FilterLength: " + FilterLength.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public Pnt3D AddOffsetToPoint(Pnt3D RefPoint, double OffsetX, double OffsetY, double OffsetZ)
