  public Pnt3D AddOffsetToPoint(Pnt3D RefPoint, Vec3D OffsetVector, double Value)
  {
    try
    {
      Pnt3D pnt3D = new Pnt3D();
      Pnt3D point = new Pnt3D(RefPoint);
      if (OffsetVector.X > 0.0)
        point.X += Value;
      if (OffsetVector.X < 0.0)
        point.X -= Value;
      if (OffsetVector.Y > 0.0)
        point.Y += Value;
      if (OffsetVector.Y < 0.0)
        point.Y -= Value;
      if (OffsetVector.Z > 0.0)
        point.Z += Value;
      if (OffsetVector.Z < 0.0)
        point.Z -= Value;
      return point;
    }
    catch (Exception ex)
    {
      string str = $"RefPoint: {RefPoint.ToString()} - OffsetVector: {OffsetVector.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return new Pnt3D();
    }
  }

