  public Pnt3D MostClosestPoint(
    Pnt3D RefPoint,
    MostClosestPointType Type,
    WorkPlane Plane,
    List<eEntities> RefVertices,
    ref int Sequence)
  {
    try
    {
      bool flag = false;
      double num1 = 10000000000.0;
      Pnt3D pnt3D = new Pnt3D();
      if (Type == MostClosestPointType.AllEntities)
        flag = true;
      for (int index = 0; index <= RefVertices.Count - 1; ++index)
      {
        if (RefVertices[index].GetType() != typeof (eLine) & RefVertices[index].GetType() != typeof (ePolyline) & RefVertices[index].GetType() != typeof (eCam))
        {
          int count = RefVertices[index].Vertice.Count;
          if (count > 0)
          {
            double num2 = this.Length3D(RefVertices[index].Vertice[0], RefPoint, Plane);
            if (num2 < num1 & (!RefVertices[index].bCamSelected | flag))
            {
              Sequence = index;
              num1 = num2;
              pnt3D = new Pnt3D(RefVertices[index].Vertice[0]);
            }
            double num3 = this.Length3D(RefVertices[index].Vertice[count - 1], RefPoint, Plane);
            if (num3 < num1 & (!RefVertices[index].bCamSelected | flag))
            {
              Sequence = index;
              num1 = num3;
              pnt3D = new Pnt3D(RefVertices[index].Vertice[count - 1]);
            }
          }
        }
        if (RefVertices[index].GetType() == typeof (eLine) | RefVertices[index].GetType() == typeof (ePolyline))
        {
          int count = RefVertices[index].Vertice.Count;
          if (count > 0)
          {
            double num4 = this.Length3D(RefVertices[index].Vertice[0], RefPoint, Plane);
            if (num4 < num1 & (!RefVertices[index].bCamSelected | flag))
            {
              Sequence = index;
