  public void ShiftList(ref List<Pnt3D> List, int ShiftValue)
  {
    if (ShiftValue == 0 || ShiftValue >= List.Count)
      return;
    if (ShiftValue < 0)
    {
      List<Pnt3D> CopiedPnt = new List<Pnt3D>();
      Pnt3D.Copy(List, ref CopiedPnt);
      List.Clear();
      for (int index = Math.Abs(ShiftValue); index <= CopiedPnt.Count - 1; ++index)
        List.Add(new Pnt3D(CopiedPnt[index]));
      for (int index = 0; index < Math.Abs(ShiftValue); ++index)
        List.Add(new Pnt3D(CopiedPnt[index]));
    }
    if (ShiftValue <= 0)
      return;
    List<Pnt3D> CopiedPnt1 = new List<Pnt3D>();
    Pnt3D.Copy(List, ref CopiedPnt1);
    List.Clear();
    for (int index = CopiedPnt1.Count - Math.Abs(ShiftValue) - 1; index <= CopiedPnt1.Count - 1; ++index)
      List.Add(new Pnt3D(CopiedPnt1[index]));
    for (int index = 0; index < CopiedPnt1.Count - Math.Abs(ShiftValue) - 1; ++index)
      List.Add(new Pnt3D(CopiedPnt1[index]));
  }

  public void ShiftPointsByLength(
    Pnt3D FirstRefPoints,
    Pnt3D SecondRefPoints,
    ref List<Pnt3D> Points)
  {
    this.ShiftPointsByLength(FirstRefPoints, SecondRefPoints, false, ref Points);
  }

  public void ShiftPointsByLength(
    Pnt3D FirstRefPoints,
    Pnt3D SecondRefPoints,
    bool OnlyXYPlane,
    ref List<Pnt3D> Points)
  {
    double num1 = double.MaxValue;
    int num2 = 0;
    for (int index = 0; index <= Points.Count - 1; ++index)
    {
      double num3 = this.Length3D(FirstRefPoints, Points[index]);
      if (OnlyXYPlane)
        num3 = this.Length3D(FirstRefPoints, Points[index], new WorkPlane());
      if (num3 < num1)
      {
        num2 = index;
        num1 = num3;
      }
    }
    for (int index = 0; index <= Points.Count - 1; ++index)
    {
      double num4 = this.Length3D(SecondRefPoints, Points[index]);
      if (OnlyXYPlane)
        num4 = this.Length3D(SecondRefPoints, Points[index], new WorkPlane());
      if (num4 < num1)
        num1 = num4;
    }
    if (num2 <= 0)
      return;
    List<Pnt3D> CopiedPnt = new List<Pnt3D>();
    Pnt3D.Copy(Points, ref CopiedPnt);
    Points.Clear();
    for (int index = num2; index <= CopiedPnt.Count - 1; ++index)
      Points.Add(new Pnt3D(CopiedPnt[index]));
    for (int index = 0; index < num2; ++index)
    {
      if (index == 0)
      {
        if (!buCompare.EQ(Points[Points.Count - 1], CopiedPnt[index]))
          Points.Add(new Pnt3D(CopiedPnt[index]));
      }
      else
        Points.Add(new Pnt3D(CopiedPnt[index]));
    }
  }

  public void ShiftPointsByLength(Pnt3D RefPoints, ref List<Pnt3D> Points)
  {
    double num1 = double.MaxValue;
    int num2 = 0;
    bool flag = this.IsClosed(Points);
    for (int index = 0; index <= Points.Count - 1; ++index)
    {
      double num3 = this.Length3D(RefPoints, Points[index]);
      if (num3 < num1)
      {
        num2 = index;
        num1 = num3;
      }
    }
    if (num2 > 0)
    {
      List<Pnt3D> CopiedPnt = new List<Pnt3D>();
      Pnt3D.Copy(Points, ref CopiedPnt);
      Points.Clear();
      for (int index = num2; index <= CopiedPnt.Count - 1; ++index)
        Points.Add(new Pnt3D(CopiedPnt[index]));
      for (int index = 0; index < num2; ++index)
      {
        if (index == 0)
        {
          if (!buCompare.EQ(Points[Points.Count - 1], CopiedPnt[index]))
            Points.Add(new Pnt3D(CopiedPnt[index]));
        }
        else
          Points.Add(new Pnt3D(CopiedPnt[index]));
      }
    }
    if (!(flag & Points.Count > 2) || !(Points[0] != Points[Points.Count - 1]))
      return;
    Points.Add(new Pnt3D(Points[0]));
  }

  public void CheckDuplicatedPointsWithPrevious(ref List<double> Points)
  {
    try
    {
      List<double> doubleList = new List<double>();
      if (Points.Count <= 0)
        return;
      for (int index = 0; index <= Points.Count - 1; ++index)
        doubleList.Add(Points[index]);
      Points.Clear();
      Points.Add(doubleList[0]);
      for (int index = 1; index <= doubleList.Count - 1; ++index)
      {
        if (!buCompare.EQ(Points[Points.Count - 1], doubleList[index]))
          Points.Add(doubleList[index]);
      }
      if (Points.Count <= 0 || buCompare.EQ(Points[Points.Count - 1], doubleList[doubleList.Count - 1]))
        return;
      Points.RemoveAt(Points.Count - 1);
      Points.Add(doubleList[doubleList.Count - 1]);
    }
    catch (Exception ex)
    {
      string str = "";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

