  public void ReCreatsLinearPointsByCount(ref List<Pnt3D> Points, int NewCount)
  {
    double dt = 1.0 / (double) NewCount;
    List<Pnt3D> CalculatedPoints = new List<Pnt3D>();
    this.LineerInterpolation(Points[0], Points[Points.Count - 1], dt, ref CalculatedPoints);
    for (int index1 = 0; index1 <= CalculatedPoints.Count - 1; ++index1)
    {
      for (int index2 = 1; index2 <= Points.Count - 1; ++index2)
      {
        if (this.IsPointOverAndInsideLine(Points[index2 - 1], Points[index2], CalculatedPoints[index1], new WorkPlane(), buSystem.resolutionCompare))
          CalculatedPoints[index1] = new Pnt3D(CalculatedPoints[index1])
          {
            Z = this.ZFromXYZ(Points[index2 - 1], Points[index2], CalculatedPoints[index1])
          };
      }
    }
    Points.Clear();
    Pnt3D.Copy(CalculatedPoints, ref Points);
  }

  public void GetZPositionFromPointsByPlane(
