  {
    try
    {
      ZFound = new List<double>();
      if (WorkPlane.isPlaneYZ(Plane))
      {
        for (int index1 = 0; index1 <= Points.Count - 1; ++index1)
        {
          for (int index2 = 1; index2 <= Points[index1].Count - 1; ++index2)
          {
            Pnt3D pnt3D1 = new Pnt3D(Points[index1][index2 - 1]);
