            if (Math.Abs(this.DeltaY(Points[index1][index2 - 1], Points[index1][index2])) > 0.01)
            {
              if (pnt3D1.Y < pnt3D2.Y && pnt3D1.Y < CheckPoints.Y & CheckPoints.Y <= pnt3D2.Y)
