  public void GetPlanePointFromLenght(WorkPlane refPlane, double Length, ref Pnt3D calcPoint)
  {
    if (!(refPlane.PlaneType == planeType.YZ | refPlane.PlaneType == planeType.ZY))
      return;
    double a = refPlane.Angles.A;
    if (refPlane.isReverse)
      a += 180.0;
    if (!refPlane.UseCenterPoint)
    {
      calcPoint = new Pnt3D();
      this.LineWithLengthAndAngle(refPlane.BasePoint, Length, a, refPlane, ref calcPoint);
    }
    else
      this.LineWithLengthAndAngle(refPlane.MiddlePoint, Length, a, refPlane, ref calcPoint);
  }

  public void PlaneCalculationFromSurfaceQuad(
    Quad3D Quad,
    double Angle,
    double DirectionLenght,
    planeType PerpendicularType,
    ref WorkPlane calcPlane)
  {
    Pnt3D pnt3D1 = new Pnt3D();
    Pnt3D pnt3D2 = new Pnt3D();
