      return;
    Pnt3D MinPoint = new Pnt3D();
    Pnt3D MidPoint = new Pnt3D();
    Pnt3D MaxPoint = new Pnt3D();
    this.BoxSizeCalculate(Quad, ref MinPoint, ref MidPoint, ref MaxPoint);
    if (Angle < 0.0 & Angle > -90.0)
    {
      Pnt3D pnt3D3 = new Pnt3D(MinPoint.X, MaxPoint.Y, MinPoint.Z);
      Pnt3D pnt3D4 = new Pnt3D(MinPoint.X, MinPoint.Y, MaxPoint.Z);
      calcPlane.Angles = new OrientationAngle(Angle, 0.0, 0.0);
      calcPlane.BaseAngle = Angle;
      calcPlane.Lenght = this.Length3D(pnt3D3, pnt3D4);
      calcPlane.BasePoint = new Pnt3D(pnt3D3);
      calcPlane.TipPoint = new Pnt3D(pnt3D4);
      calcPlane.Quad = new Quad3D(Quad);
      calcPlane.PlaneType = planeType.YZ;
      calcPlane.isReverse = true;
      this.QuadToPoints(calcPlane.Quad, ref calcPlane.BoxPoints);
    }
    else if (Angle <= -90.0)
    {
      Pnt3D pnt3D5 = new Pnt3D(MinPoint.X, MaxPoint.Y, MinPoint.Z);
