      calcPlane.PlaneType = planeType.YZ;
      calcPlane.isReverse = true;
      this.QuadToPoints(calcPlane.Quad, ref calcPlane.BoxPoints);
    }
    else if (Angle >= 0.0)
    {
      Pnt3D pnt3D7 = new Pnt3D(MinPoint.X, MinPoint.Y, MinPoint.Z);
      Pnt3D pnt3D8 = new Pnt3D(MinPoint.X, MaxPoint.Y, MaxPoint.Z);
