    else
    {
      Pnt3D pnt3D9 = new Pnt3D(MinPoint.X, MinPoint.Y, MinPoint.Z);
      Pnt3D pnt3D10 = new Pnt3D(MinPoint.X, MaxPoint.Y, MaxPoint.Z);
      double a1 = this.PointAngle(pnt3D10, pnt3D9, new WorkPlane(planeType.YZ, 1));
      if (buCompare.EQ(a1, Angle, 0.1))
      {
        calcPlane.Angles = new OrientationAngle(a1, 0.0, 0.0);
        calcPlane.BaseAngle = a1;
        calcPlane.Lenght = this.Length3D(pnt3D9, pnt3D10);
        calcPlane.BasePoint = new Pnt3D(pnt3D9);
        calcPlane.TipPoint = new Pnt3D(pnt3D10);
        calcPlane.Quad = new Quad3D(Quad);
        calcPlane.PlaneType = planeType.YZ;
        this.QuadToPoints(calcPlane.Quad, ref calcPlane.BoxPoints);
        flag = true;
      }
      if (flag)
        return;
      Pnt3D pnt3D11 = new Pnt3D(MinPoint.X, MaxPoint.Y, MinPoint.Z);
      Pnt3D pnt3D12 = new Pnt3D(MinPoint.X, MinPoint.Y, MaxPoint.Z);
      double a2 = this.PointAngle(pnt3D12, pnt3D11, new WorkPlane(planeType.YZ, 1));
      if (!buCompare.EQ(a2, Angle, 0.1))
        return;
