  public void PlaneCalculationFromDistancesForProfile(
    double Width,
    double Height,
    double Length,
    double DistanceWidth,
    double DistanceHeight,
    planeType Type,
    LeftRightLocationType Direction,
    ProfileYAxisDirection YDirection,
    ref WorkPlane calcPlane)
  {
    Pnt3D EndPnt = new Pnt3D();
    if (!(Type == planeType.YZ | Type == planeType.ZY))
      return;
    if (Direction == LeftRightLocationType.Right)
    {
      double a = 180.0 - buConversion.RadianToDegree(Math.Atan((Height - DistanceHeight) / (Width - DistanceWidth)));
      calcPlane.Angles = new OrientationAngle(a, 0.0, 0.0);
      calcPlane.Lenght = Math.Sqrt(Math.Pow(Height - DistanceHeight, 2.0) + Math.Pow(Width - DistanceWidth, 2.0));
      this.LineWithLengthAndAngle(new Pnt3D(), calcPlane.Lenght, calcPlane.Angles.A, new WorkPlane(planeType.YZ, 1), ref EndPnt);
      calcPlane.BasePoint = new Pnt3D(0.0, Width, DistanceHeight);
      calcPlane.TipPoint = new Pnt3D(0.0, DistanceWidth, Height);
      calcPlane.Quad = new Quad3D(calcPlane.BasePoint, calcPlane.TipPoint, new Pnt3D(Length, calcPlane.TipPoint.Y, calcPlane.TipPoint.Z), new Pnt3D(Length, calcPlane.BasePoint.Y, calcPlane.BasePoint.Z));
      if (YDirection == ProfileYAxisDirection.NegativeDirection)
      {
        this.Move(new Pnt3D(), new Pnt3D(0.0, -Width, 0.0), ref calcPlane.Quad);
        this.Move(new Pnt3D(), new Pnt3D(0.0, -Width, 0.0), ref calcPlane.BasePoint);
        this.Move(new Pnt3D(), new Pnt3D(0.0, -Width, 0.0), ref calcPlane.TipPoint);
      }
      calcPlane.PlaneType = planeType.YZ;
      this.QuadToPoints(calcPlane.Quad, ref calcPlane.BoxPoints);
    }
    if (Direction != LeftRightLocationType.Left)
      return;
    double degree = buConversion.RadianToDegree(Math.Atan((Height - DistanceHeight) / (Width - DistanceWidth)));
    calcPlane.Angles = new OrientationAngle(degree, 0.0, 0.0);
    calcPlane.Lenght = Math.Sqrt(Math.Pow(Height - DistanceHeight, 2.0) + Math.Pow(Width - DistanceWidth, 2.0));
    this.LineWithLengthAndAngle(new Pnt3D(), calcPlane.Lenght, calcPlane.Angles.A, new WorkPlane(planeType.YZ, 1), ref EndPnt);
    calcPlane.BasePoint = new Pnt3D(0.0, 0.0, DistanceHeight);
    calcPlane.TipPoint = new Pnt3D(0.0, Width - DistanceWidth, Height);
    calcPlane.Quad = new Quad3D(calcPlane.BasePoint, calcPlane.TipPoint, new Pnt3D(Length, calcPlane.TipPoint.Y, calcPlane.TipPoint.Z), new Pnt3D(Length, calcPlane.BasePoint.Y, calcPlane.BasePoint.Z));
    calcPlane.PlaneType = planeType.YZ;
    if (YDirection == ProfileYAxisDirection.NegativeDirection)
    {
      this.Move(new Pnt3D(), new Pnt3D(0.0, -Width, 0.0), ref calcPlane.Quad);
      this.Move(new Pnt3D(), new Pnt3D(0.0, -Width, 0.0), ref calcPlane.BasePoint);
      this.Move(new Pnt3D(), new Pnt3D(0.0, -Width, 0.0), ref calcPlane.TipPoint);
    }
    this.QuadToPoints(calcPlane.Quad, ref calcPlane.BoxPoints);
  }

  public void PlaneCalculationFromAngleLenghtForProfile(
    double PlaneLenght,
    double PlaneAngle,
    Pnt3D BasePoint,
    bool UseCenterPoint,
    double ProfileLength,
    ref WorkPlane calcPlane)
  {
    Pnt3D EndPnt = new Pnt3D();
    double a = PlaneAngle;
    double num1 = 0.0;
    double num2 = 180.0;
    if (a < 0.0)
    {
      num1 = 180.0;
      num2 = 0.0;
      calcPlane.isReverse = true;
    }
    calcPlane.Angles = new OrientationAngle(a, 0.0, 0.0);
    calcPlane.BaseAngle = a;
    calcPlane.Lenght = PlaneLenght;
    if (UseCenterPoint)
    {
      this.LineWithLengthAndAngle(BasePoint, calcPlane.Lenght / 2.0, calcPlane.Angles.A - num2, new WorkPlane(planeType.YZ, 1), ref calcPlane.BasePoint);
      this.LineWithLengthAndAngle(calcPlane.BasePoint, calcPlane.Lenght, calcPlane.Angles.A + num1, new WorkPlane(planeType.YZ, 1), ref calcPlane.TipPoint);
      calcPlane.MiddlePoint = new Pnt3D(BasePoint);
    }
    else
    {
      calcPlane.BasePoint = new Pnt3D(BasePoint);
      this.LineWithLengthAndAngle(calcPlane.BasePoint, calcPlane.Lenght, calcPlane.Angles.A + num1, new WorkPlane(planeType.YZ, 1), ref EndPnt);
      calcPlane.TipPoint = new Pnt3D(EndPnt);
    }
    calcPlane.Quad = new Quad3D(calcPlane.BasePoint, calcPlane.TipPoint, new Pnt3D(ProfileLength, calcPlane.TipPoint.Y, calcPlane.TipPoint.Z), new Pnt3D(ProfileLength, calcPlane.BasePoint.Y, calcPlane.BasePoint.Z));
    calcPlane.PlaneType = planeType.YZ;
    this.QuadToPoints(calcPlane.Quad, ref calcPlane.BoxPoints);
  }

  public int AddPocketToLine(
    Pnt3D Start,
    Pnt3D End,
    List<Pnt3D> Location,
    List<double> Width,
    List<double> Height,
    VectorType Direction,
    UpCenterDownLocationType VerDir,
    LeftMiddleRightLocationType PocketDirection,
    ref List<Pnt3D> Calculated)
  {
    try
    {
      List<double> RefList = new List<double>();
      if (Location.Count <= 0)
      {
        Calculated.Clear();
        Calculated.Add(new Pnt3D(Start));
        Calculated.Add(new Pnt3D(End));
      }
      if (Direction == VectorType.XVector)
      {
        for (int index = 0; index <= Location.Count - 1; ++index)
          RefList.Add(Location[index].X);
      }
      if (Direction == VectorType.YVector)
      {
        for (int index = 0; index <= Location.Count - 1; ++index)
          RefList.Add(Location[index].Y);
      }
      double num = -1.0;
      if (VerDir == UpCenterDownLocationType.Up)
        num = 1.0;
      Calculated.Clear();
      Calculated.Add(new Pnt3D(Start));
      this.SortList(SortDirectionType.Lower, ref RefList);
      for (int index = 0; index <= RefList.Count - 1; ++index)
      {
        if (PocketDirection == LeftMiddleRightLocationType.Middle)
        {
          Calculated.Add(new Pnt3D(Start.X + RefList[index] - Width[index] / 2.0, Start.Y));
          Calculated.Add(new Pnt3D(Start.X + RefList[index] - Width[index] / 2.0, Start.Y + num * Height[index]));
          Calculated.Add(new Pnt3D(Start.X + RefList[index] + Width[index] / 2.0, Start.Y + num * Height[index]));
          Calculated.Add(new Pnt3D(Start.X + RefList[index] + Width[index] / 2.0, Start.Y));
        }
        if (PocketDirection == LeftMiddleRightLocationType.Left)
        {
          Calculated.Add(new Pnt3D(Start.X + RefList[index], Start.Y));
          Calculated.Add(new Pnt3D(Start.X + RefList[index], Start.Y + num * Height[index]));
          Calculated.Add(new Pnt3D(Start.X + RefList[index] + Width[index], Start.Y + num * Height[index]));
          Calculated.Add(new Pnt3D(Start.X + RefList[index] + Width[index], Start.Y));
        }
        if (PocketDirection == LeftMiddleRightLocationType.Right)
        {
          Calculated.Add(new Pnt3D(Start.X + RefList[index] - Width[index], Start.Y));
          Calculated.Add(new Pnt3D(Start.X + RefList[index] - Width[index], Start.Y + num * Height[index]));
          Calculated.Add(new Pnt3D(Start.X + RefList[index], Start.Y + num * Height[index]));
          Calculated.Add(new Pnt3D(Start.X + RefList[index], Start.Y));
        }
      }
      Calculated.Add(new Pnt3D(End));
      return 1;
    }
    catch (Exception ex)
    {
      string str = $"Start: {Start.ToString()} - End: {End.ToString()} - Location: {Location.Count.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return -1;
    }
  }

