      Pnt3D pnt3D2 = new Pnt3D(StartPoint, TotalHeight);
      CalcPoints.Add(pnt3D2);
      Pnt3D pnt3D3 = new Pnt3D(num6 / 2.0 + StartPoint + StartOffset, TotalHeight);
      CalcPoints.Add(pnt3D3);
      Pnt3D pnt3D4 = new Pnt3D(num6 / 2.0 + StartPoint + StartOffset, y);
      CalcPoints.Add(pnt3D4);
      double num7 = num6 / 2.0 + StartOffset;
      for (int index = 0; index < num4; ++index)
      {
        PerfoPoints.Add(new PerfoPoint()
        {
          X = StartPoint + num7 + FamaleWidth / 2.0,
          Width = FamaleWidth,
          Height = MaleHeight
        });
        double num8 = num7 + FamaleWidth;
        Pnt3D pnt3D5 = new Pnt3D(num8 + StartPoint, y);
        CalcPoints.Add(pnt3D5);
        Pnt3D pnt3D6 = new Pnt3D(num8 + StartPoint, TotalHeight);
