        CalcPoints.Add(pnt3D7);
        Pnt3D pnt3D8 = new Pnt3D(num7 + StartPoint, y);
        CalcPoints.Add(pnt3D8);
      }
      PerfoPoints.Add(new PerfoPoint()
      {
        X = StartPoint + num7 + FamaleWidth / 2.0,
