  public void ReCalculateEntitiesSawDepth(
    List<eEntities> RefEntities,
    bool InsideCalculation,
    ToolBase Tool,
    double MaterialThickness,
    double TargetZ,
    double InnerCutSafeDistance,
    bool IfEntitiesOpenTrimFromStartPoint,
    bool IfEntitiesOpenTrimFromEndPoint,
    double CutSawDistanceOverlap,
    ref List<List<eEntities>> calcEntities)
  {
    List<eEntities> CopiedEnt1 = new List<eEntities>();
    eEntities.CopyEntities(RefEntities, ref CopiedEnt1);
    bool ReverseThetaCalculation = InsideCalculation;
    List<List<eEntities>> eEntitiesListList1 = new List<List<eEntities>>();
    List<List<eEntities>> eEntitiesListList2 = new List<List<eEntities>>();
    List<eEntities> eEntitiesList1 = new List<eEntities>();
    eEntities copiedEnt1 = new eEntities();
    eEntities copiedEnt2 = new eEntities();
    List<eEntities> baseEnt1 = new List<eEntities>();
    eEntities ModifiedFirstEntity = new eEntities();
    eEntities ModifiedLastEntity1 = new eEntities();
    eEntities.CopyEntity(CopiedEnt1[0], ref copiedEnt1);
    eEntities.CopyEntity(CopiedEnt1[CopiedEnt1.Count - 1], ref copiedEnt2);
    bool flag = this.IsClosed(CopiedEnt1);
    ClockDirectionType ClockDir = this.EntitiesClockDirection(CopiedEnt1, new WorkPlane());
    double num = Math.Sqrt(Math.Pow(Tool.Geometry.Diameter / 2.0, 2.0) - Math.Pow(Tool.Geometry.Diameter / 2.0 - (MaterialThickness - TargetZ), 2.0));
    if (Tool.Purpose == ToolPurpose.Saw && flag)
    {
      this.EntityCornerModifyByConvexConcave(copiedEnt2, copiedEnt1, ClockDir, ReverseThetaCalculation, num + InnerCutSafeDistance, ref ModifiedFirstEntity, ref ModifiedLastEntity1);
      CopiedEnt1[0] = ModifiedLastEntity1;
      CopiedEnt1[CopiedEnt1.Count - 1] = ModifiedFirstEntity;
    }
    for (int index = 0; index <= CopiedEnt1.Count - 1; ++index)
    {
      ModifiedFirstEntity = new eEntities();
      eEntities ModifiedLastEntity2 = new eEntities();
      if (index < CopiedEnt1.Count - 1)
      {
        if (Tool.Purpose == ToolPurpose.Saw)
        {
          this.EntityCornerModifyByConvexConcave(CopiedEnt1[index], CopiedEnt1[index + 1], ClockDir, ReverseThetaCalculation, num + InnerCutSafeDistance, ref ModifiedFirstEntity, ref ModifiedLastEntity2);
          CopiedEnt1[index] = ModifiedFirstEntity;
          CopiedEnt1[index + 1] = ModifiedLastEntity2;
          baseEnt1.Add(ModifiedFirstEntity);
        }
        else
        {
          baseEnt1.Add(eEntities.CopyEntity(CopiedEnt1[index]));
          baseEnt1[baseEnt1.Count - 1].bCamSelected = false;
          baseEnt1[baseEnt1.Count - 1].bSelected = false;
        }
      }
      if (index == CopiedEnt1.Count - 1)
      {
        baseEnt1.Add(eEntities.CopyEntity(CopiedEnt1[index]));
        baseEnt1[baseEnt1.Count - 1].bCamSelected = false;
        baseEnt1[baseEnt1.Count - 1].bSelected = false;
      }
    }
    if (!flag && baseEnt1.Count >= 1)
    {
      if (IfEntitiesOpenTrimFromStartPoint)
      {
        eEntities ModifiedEntity = new eEntities();
        this.EntityLengthModify(baseEnt1[0], StartPointType.Start, num + CutSawDistanceOverlap, ref ModifiedEntity);
        baseEnt1[0] = ModifiedEntity;
      }
      if (IfEntitiesOpenTrimFromEndPoint)
      {
        eEntities ModifiedEntity = new eEntities();
        this.EntityLengthModify(baseEnt1[baseEnt1.Count - 1], StartPointType.End, num + CutSawDistanceOverlap, ref ModifiedEntity);
        baseEnt1[baseEnt1.Count - 1] = ModifiedEntity;
      }
    }
    List<eEntities> CopiedEnt2 = new List<eEntities>();
    List<eEntities> eEntitiesList2 = new List<eEntities>();
    eEntities copiedEnt3 = new eEntities();
    eEntities.CopyEntity(baseEnt1[0], ref copiedEnt3);
    eEntities.CopyEntities(baseEnt1, ref CopiedEnt2);
    eEntitiesList2.Add(copiedEnt3);
    for (int index = 1; index <= CopiedEnt2.Count - 1; ++index)
    {
      eEntities copiedEnt4 = new eEntities();
      eEntities.CopyEntity(CopiedEnt2[index], ref copiedEnt4);
      if (CopiedEnt2[index].GetType() != typeof (eUpperLine))
      {
        if (eEntitiesList2.Count > 0)
        {
          if (CopiedEnt2[index].Orientation == eEntitiesList2[eEntitiesList2.Count - 1].Orientation)
          {
            Pnt3D pntStart = new Pnt3D();
            Pnt3D pntEnd = new Pnt3D();
            this.GetStartPointOfEntityByCamDirection(CopiedEnt2[index], ref pntStart);
            this.GetEndPointOfEntityByCamDirection(eEntitiesList2[eEntitiesList2.Count - 1], ref pntEnd);
            if (buCompare.EQ(pntEnd, pntStart))
            {
              eEntitiesList2.Add(copiedEnt4);
            }
            else
            {
              eEntitiesListList1.Add(eEntitiesList2);
              eEntitiesList2 = new List<eEntities>();
              eEntitiesList2.Add(copiedEnt4);
            }
          }
          else
          {
            eEntitiesListList1.Add(eEntitiesList2);
            eEntitiesList2 = new List<eEntities>();
            eEntitiesList2.Add(copiedEnt4);
          }
        }
        else
          eEntitiesList2.Add(copiedEnt4);
      }
      else if (eEntitiesList2.Count > 0)
      {
        eEntitiesListList1.Add(eEntitiesList2);
        eEntitiesList2 = new List<eEntities>();
      }
    }
    if (eEntitiesList2.Count > 0)
      eEntitiesListList1.Add(eEntitiesList2);
    calcEntities = new List<List<eEntities>>();
    for (int index = 0; index <= eEntitiesListList1.Count - 1; ++index)
    {
      List<eEntities> baseEnt2 = new List<eEntities>();
      eEntities.CopyEntities(eEntitiesListList1[index], ref baseEnt2);
      this.ChangeEntityByCamDirection(ref baseEnt2);
      calcEntities.Add(eEntities.CopyEntities(baseEnt2));
    }
  }

  public void DimensionFromEntity(
    eEntities RefEntity,
    int VerticeIndex,
    Pnt3D pntActive,
    WorkPlane Plane,
    bool ForceVertical,
    bool ForceHorizontal,
    ref Pnt3D StartPoint,
    ref Pnt3D EndPoint,
    ref int CatchIndex,
    ref DimensionType DimType)
  {
    Pnt3D CalculatedPoint = new Pnt3D();
    DimType = DimensionType.None;
    if (RefEntity.Vertice.Count <= 0)
      return;
    if (RefEntity.GetType() == typeof (eLine))
    {
      CatchIndex = this.Length3D(pntActive, RefEntity.Vertice[0]) >= this.Length3D(pntActive, RefEntity.Vertice[RefEntity.Vertice.Count - 1]) ? RefEntity.Vertice.Count - 1 : 0;
      double Distance = 0.0;
      if (this.IsPointOverEntity(RefEntity, pntActive, Plane, 0.1, ref CalculatedPoint, ref Distance) & !ForceHorizontal & !ForceVertical)
      {
        eEntities CalcEnt = new eEntities();
        this.Move(CalculatedPoint, pntActive, RefEntity, ref CalcEnt);
        StartPoint = new Pnt3D(CalcEnt.Vertice[0]);
        EndPoint = new Pnt3D(CalcEnt.Vertice[CalcEnt.Vertice.Count - 1]);
        DimType = DimensionType.Length;
      }
      else
      {
        if (RefEntity.geoMinPoint.X < pntActive.X & pntActive.X <= RefEntity.geoMaxPoint.X & !ForceVertical)
        {
          StartPoint = new Pnt3D(pntActive);
          EndPoint = new Pnt3D(pntActive);
          StartPoint.X = RefEntity.geoMinPoint.X;
          EndPoint.X = RefEntity.geoMaxPoint.X;
          DimType = DimensionType.Horizontal;
        }
        if (RefEntity.geoMinPoint.Y < pntActive.Y & pntActive.Y <= RefEntity.geoMaxPoint.Y & !ForceHorizontal)
        {
          StartPoint = new Pnt3D(pntActive);
          EndPoint = new Pnt3D(pntActive);
          StartPoint.Y = RefEntity.geoMinPoint.Y;
          EndPoint.Y = RefEntity.geoMaxPoint.Y;
          DimType = DimensionType.Vertical;
        }
      }
    }
    if (RefEntity.GetType() == typeof (ePolyline) && VerticeIndex >= 0 & VerticeIndex <= RefEntity.Vertice.Count - 2)
    {
      eEntities eEntities = (eEntities) new eLine(RefEntity.Vertice[VerticeIndex], RefEntity.Vertice[VerticeIndex + 1]);
      CatchIndex = this.Length3D(pntActive, eEntities.Vertice[0]) >= this.Length3D(pntActive, eEntities.Vertice[1]) ? 1 : 0;
      double Distance = 0.0;
      if (this.IsPointOverEntity(eEntities, pntActive, Plane, 0.1, ref CalculatedPoint, ref Distance))
      {
        eEntities CalcEnt = new eEntities();
        this.Move(CalculatedPoint, pntActive, eEntities, ref CalcEnt);
        StartPoint = new Pnt3D(CalcEnt.Vertice[0]);
        EndPoint = new Pnt3D(CalcEnt.Vertice[CalcEnt.Vertice.Count - 1]);
        DimType = DimensionType.Length;
      }
      else
      {
        if (eEntities.geoMinPoint.X < pntActive.X & pntActive.X <= eEntities.geoMaxPoint.X)
        {
          StartPoint = new Pnt3D(pntActive);
          EndPoint = new Pnt3D(pntActive);
          StartPoint.X = eEntities.geoMinPoint.X;
          EndPoint.X = eEntities.geoMaxPoint.X;
          DimType = DimensionType.Horizontal;
        }
        if (eEntities.geoMinPoint.Y < pntActive.Y & pntActive.Y <= eEntities.geoMaxPoint.Y)
        {
          StartPoint = new Pnt3D(pntActive);
          EndPoint = new Pnt3D(pntActive);
          StartPoint.Y = eEntities.geoMinPoint.Y;
          EndPoint.Y = eEntities.geoMaxPoint.Y;
          DimType = DimensionType.Vertical;
        }
      }
    }
    if (RefEntity.GetType() == typeof (eArc))
    {
      if (this.Length3D(pntActive, ((ePlaneEntities) RefEntity).CenterPoint) > ((eCircle) RefEntity).Radius)
      {
        double Angle = this.PointAngle(pntActive, ((ePlaneEntities) RefEntity).CenterPoint);
        Pnt3D BasePnt = new Pnt3D();
        Pnt3D EndPnt = new Pnt3D();
        this.LineWithLengthAndAngle(((ePlaneEntities) RefEntity).CenterPoint, ((eCircle) RefEntity).Radius, Angle, new WorkPlane(), ref BasePnt, ref EndPnt);
        StartPoint = new Pnt3D(((ePlaneEntities) RefEntity).CenterPoint);
        EndPoint = new Pnt3D(EndPnt);
        DimType = DimensionType.Radius;
      }
      else
      {
        StartPoint = new Pnt3D(((eArc) RefEntity).StartPoint);
        EndPoint = new Pnt3D(((eArc) RefEntity).EndPoint);
        DimType = DimensionType.Length;
      }
    }
    if (RefEntity.GetType() == typeof (eCircle))
    {
      if (this.Length3D(pntActive, ((ePlaneEntities) RefEntity).CenterPoint) > ((eCircle) RefEntity).Radius)
      {
        double Angle = this.PointAngle(pntActive, ((ePlaneEntities) RefEntity).CenterPoint);
        Pnt3D BasePnt = new Pnt3D();
        Pnt3D EndPnt = new Pnt3D();
        this.LineWithLengthAndAngle(((ePlaneEntities) RefEntity).CenterPoint, ((eCircle) RefEntity).Radius, Angle, new WorkPlane(), ref BasePnt, ref EndPnt);
        StartPoint = new Pnt3D(((ePlaneEntities) RefEntity).CenterPoint);
        EndPoint = new Pnt3D(EndPnt);
        DimType = DimensionType.Radius;
      }
      else
      {
        this.CircleDiameterLine(((ePlaneEntities) RefEntity).CenterPoint, ((eCircle) RefEntity).Radius, pntActive, ref StartPoint, ref EndPoint);
        DimType = DimensionType.Diameter;
      }
    }
    if (RefEntity.GetType() == typeof (eEllipse))
    {
      if (this.IsPointInsidePolygon(RefEntity.Vertice, pntActive))
        this.EllipseMinorDiameterLine(((ePlaneEntities) RefEntity).CenterPoint, ((eEllipse) RefEntity).MinorRadius, ((eEllipse) RefEntity).Angle, pntActive, ref StartPoint, ref EndPoint);
      else
        this.EllipseMajorDiameterLine(((ePlaneEntities) RefEntity).CenterPoint, ((eEllipse) RefEntity).MajorRadius, ((eEllipse) RefEntity).Angle, pntActive, ref StartPoint, ref EndPoint);
      DimType = DimensionType.Diameter;
    }
    if (!(RefEntity.GetType() == typeof (eBSpline) | RefEntity.GetType() == typeof (eBezeir)))
      return;
    if (RefEntity.geoMinPoint.X < pntActive.X & pntActive.X <= RefEntity.geoMaxPoint.X)
    {
      StartPoint = new Pnt3D(pntActive);
      EndPoint = new Pnt3D(pntActive);
      StartPoint.X = RefEntity.geoMinPoint.X;
      EndPoint.X = RefEntity.geoMaxPoint.X;
      DimType = DimensionType.Horizontal;
    }
    if (!(RefEntity.geoMinPoint.Y < pntActive.Y & pntActive.Y <= RefEntity.geoMaxPoint.Y))
      return;
    StartPoint = new Pnt3D(pntActive);
    EndPoint = new Pnt3D(pntActive);
    StartPoint.Y = RefEntity.geoMinPoint.Y;
    EndPoint.Y = RefEntity.geoMaxPoint.Y;
    DimType = DimensionType.Vertical;
  }

  public void DimensionLinear(
    Pnt3D StartPoint,
    Pnt3D EndPoint,
    Pnt3D SetPoint,
    double dimTextHeight,
    ref eEntities StartPointExtension,
    ref eEntities EndPointExtension,
    ref eEntities DimLine)
  {
    bool flag = SetPoint.X > StartPoint.X && SetPoint.X > EndPoint.X || SetPoint.X < StartPoint.X && SetPoint.X < EndPoint.X;
    Pnt3D pnt3D1 = new Pnt3D();
    Pnt3D pnt3D2 = new Pnt3D();
    Pnt3D pnt3D3;
    Pnt3D EndPoint1;
    if (flag)
    {
      pnt3D3 = new Pnt3D(SetPoint.X, StartPoint.Y);
      EndPoint1 = new Pnt3D(SetPoint.X, EndPoint.Y);
      if ((SetPoint.X <= StartPoint.X ? 0 : (SetPoint.X > EndPoint.X ? 1 : 0)) != 0)
      {
        pnt3D3.X += dimTextHeight / 2.0;
        EndPoint1.X += dimTextHeight / 2.0;
      }
      else
      {
        pnt3D3.X -= dimTextHeight / 2.0;
        EndPoint1.X -= dimTextHeight / 2.0;
      }
    }
    else
    {
      pnt3D3 = new Pnt3D(StartPoint.X, SetPoint.Y);
      EndPoint1 = new Pnt3D(EndPoint.X, SetPoint.Y);
      if ((SetPoint.Y <= StartPoint.Y ? 0 : (SetPoint.Y > EndPoint.Y ? 1 : 0)) != 0)
      {
        pnt3D3.Y += dimTextHeight / 2.0;
        EndPoint1.Y += dimTextHeight / 2.0;
      }
      else
      {
        pnt3D3.Y -= dimTextHeight / 2.0;
        EndPoint1.Y -= dimTextHeight / 2.0;
      }
    }
    StartPointExtension = (eEntities) new eLine(StartPoint, pnt3D3);
    EndPointExtension = (eEntities) new eLine(EndPoint, EndPoint1);
    DimLine = (eEntities) new eLine(pnt3D3, EndPoint1);
  }

