  public void DiagonalLengthByAnglePerpendicularDistance(
    Pnt3D BasePoint,
    double Angle,
    double PerpendicularDistance,
    WorkPlane Plane,
    ref Pnt3D CalcPoint)
  {
    try
    {
      if (!(Math.Abs(Angle) >= -90.0 & Math.Abs(Angle) <= 180.0))
        return;
      double num1 = PerpendicularDistance / Math.Cos(buConversion.DegreeToRadian(Angle));
      if (WorkPlane.isPlaneXY(Plane))
      {
        Pnt3D BasePnt = new Pnt3D(BasePoint);
        BasePnt.Y += PerpendicularDistance;
        double num2 = this.PointAngle(BasePnt, BasePoint, Plane);
        CalcPoint = new Pnt3D(BasePoint);
        this.LineWithLengthAndAngle(BasePoint, Math.Abs(num1), num2 + Angle, Plane, ref BasePnt, ref CalcPoint);
      }
      if (WorkPlane.isPlaneXZ(Plane))
      {
        Pnt3D BasePnt = new Pnt3D(BasePoint);
        BasePnt.Z += PerpendicularDistance;
        double num3 = this.PointAngle(BasePnt, BasePoint, Plane);
        CalcPoint = new Pnt3D(BasePoint);
        this.LineWithLengthAndAngle(BasePoint, Math.Abs(num1), num3 + Angle, Plane, ref BasePnt, ref CalcPoint);
      }
      if (!WorkPlane.isPlaneYZ(Plane))
        return;
      Pnt3D BasePnt1 = new Pnt3D(BasePoint);
      BasePnt1.Z += PerpendicularDistance;
      double num4 = this.PointAngle(BasePnt1, BasePoint, Plane);
      CalcPoint = new Pnt3D(BasePoint);
      this.LineWithLengthAndAngle(BasePoint, Math.Abs(num1), num4 + Angle, Plane, ref BasePnt1, ref CalcPoint);
    }
    catch (Exception ex)
    {
      string str = $"BasePoint: {BasePoint.ToString()} - Angle: {Angle.ToString()} - PerpendicularDistance: {PerpendicularDistance.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void LineWithOrientationAngle(
    Pnt3D BasePoint,
    OrientationAngle Angles,
    double Length,
    ref Pnt3D calcPoint)
  {
    try
    {
      calcPoint.X = BasePoint.X + Length * Math.Sin(buConversion.DegreeToRadian(Angles.A)) * Math.Cos(buConversion.DegreeToRadian(Angles.C + 90.0));
      calcPoint.Y = BasePoint.Y + Length * Math.Sin(buConversion.DegreeToRadian(Angles.A)) * Math.Sin(buConversion.DegreeToRadian(Angles.C + 90.0));
      calcPoint.Z = BasePoint.Z + Length * Math.Cos(buConversion.DegreeToRadian(Angles.A));
    }
    catch (Exception ex)
    {
      string str = $"BasePoint: {BasePoint.ToString()} - Angles: {Angles.ToString()} - Length: {Length.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void LineWithLengthAndAngle(
    Pnt3D CenterPnt,
    double Length,
    double Angle,
    WorkPlane Plane,
    ref Pnt3D EndPnt)
  {
    try
    {
      Pnt3D BasePnt = new Pnt3D();
      this.LineWithLengthAndAngle(CenterPnt, Length, Angle, Plane, ref BasePnt, ref EndPnt);
    }
    catch (Exception ex)
    {
      string str = $"Center: {CenterPnt.ToString()} - Len: {Length.ToString()} - Angle: {Angle.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void LineWithLengthAndAngle(
    Pnt3D CenterPnt,
    double Length,
    double Angle,
    WorkPlane Plane,
    ref Pnt3D BasePnt,
    ref Pnt3D EndPnt)
  {
    try
    {
      BasePnt = new Pnt3D();
      EndPnt = new Pnt3D();
      if (WorkPlane.isPlaneXY(Plane) | Plane.PlaneType == planeType.YX)
      {
        BasePnt.X = CenterPnt.X;
        BasePnt.Y = CenterPnt.Y;
        BasePnt.Z = CenterPnt.Z;
        EndPnt.X = CenterPnt.X + Length * Math.Cos(buConversion.DegreeToRadian(Angle));
        EndPnt.Y = CenterPnt.Y + Length * Math.Sin(buConversion.DegreeToRadian(Angle));
        EndPnt.Z = CenterPnt.Z;
      }
      if (Plane.PlaneType == planeType.XZ | Plane.PlaneType == planeType.ZX)
      {
        BasePnt.X = CenterPnt.X;
        BasePnt.Y = CenterPnt.Y;
        BasePnt.Z = CenterPnt.Z;
        EndPnt.X = CenterPnt.X + Length * Math.Cos(buConversion.DegreeToRadian(Angle));
        EndPnt.Y = CenterPnt.Y;
        EndPnt.Z = CenterPnt.Z + Length * Math.Sin(buConversion.DegreeToRadian(Angle));
      }
      if (!(Plane.PlaneType == planeType.YZ | Plane.PlaneType == planeType.ZY))
        return;
      BasePnt.X = CenterPnt.X;
      BasePnt.Y = CenterPnt.Y;
      BasePnt.Z = CenterPnt.Z;
      EndPnt.X = CenterPnt.X;
      EndPnt.Y = CenterPnt.Y + Length * Math.Cos(buConversion.DegreeToRadian(Angle));
      EndPnt.Z = CenterPnt.Z + Length * Math.Sin(buConversion.DegreeToRadian(Angle));
    }
    catch (Exception ex)
    {
      string str = $"Center: {CenterPnt.ToString()} - Len: {Length.ToString()} - Angle: {Angle.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void LinePerpendicular(
    double LX1,
    double LY1,
    double LX2,
    double LY2,
    double BaseX,
    double BaseY,
    double Length,
    ref double CalcX1,
    ref double CalcY1,
    ref double CalcX2,
    ref double CalcY2)
  {
    double num1 = 0.0;
    double num2 = 0.0;
    double num3 = 0.0;
    double num4 = 0.0;
    double x1 = Length;
    if (!buCompare.EQ(LX1, LX2))
    {
      double x2 = (LY2 - LY1) / (LX2 - LX1);
      num1 = -0.5 * x2 / (Math.Pow(x2, 2.0) + 1.0) * (2.0 * Math.Pow(x2, 2.0) * BaseY + 2.0 * BaseY + 2.0 * Math.Pow(Math.Pow(x2, 2.0) * Math.Pow(x1, 2.0) + Math.Pow(x1, 2.0), 0.5)) + x2 * BaseY + BaseX;
      num3 = -0.5 * x2 / (Math.Pow(x2, 2.0) + 1.0) * (2.0 * Math.Pow(x2, 2.0) * BaseY + 2.0 * BaseY - 2.0 * Math.Pow(Math.Pow(x2, 2.0) * Math.Pow(x1, 2.0) + Math.Pow(x1, 2.0), 0.5)) + x2 * BaseY + BaseX;
      num2 = 0.5 / (Math.Pow(x2, 2.0) + 1.0) * (2.0 * Math.Pow(x2, 2.0) * BaseY + 2.0 * BaseY + 2.0 * Math.Pow(Math.Pow(x2, 2.0) * Math.Pow(x1, 2.0) + Math.Pow(x1, 2.0), 0.5));
      num4 = 0.5 / (Math.Pow(x2, 2.0) + 1.0) * (2.0 * Math.Pow(x2, 2.0) * BaseY + 2.0 * BaseY - 2.0 * Math.Pow(Math.Pow(x2, 2.0) * Math.Pow(x1, 2.0) + Math.Pow(x1, 2.0), 0.5));
    }
    if (buCompare.EQ(LX1, LX2))
    {
      num1 = LX1 + x1;
      num3 = LX1 - x1;
      num2 = BaseY;
      num4 = BaseY;
    }
    CalcX1 = num1;
    CalcY1 = num2;
    CalcX2 = num3;
    CalcY2 = num4;
  }

  public void LinePerpendicular(
    Pnt3D RefStartPoint,
    Pnt3D RefEndPoint,
    Pnt3D BasePoint,
    double Length,
    WorkPlane Plane,
    ref Pnt3D CalcStartPoint,
    ref Pnt3D CalcEndPoint)
  {
    double CalcX1 = 0.0;
    double CalcY1 = 0.0;
    double CalcX2 = 0.0;
    double CalcY2 = 0.0;
    CalcStartPoint = new Pnt3D();
    CalcEndPoint = new Pnt3D();
    if (WorkPlane.isPlaneXY(Plane))
    {
      this.LinePerpendicular(RefStartPoint.X, RefStartPoint.Y, RefEndPoint.X, RefEndPoint.Y, BasePoint.X, BasePoint.Y, Length, ref CalcX1, ref CalcY1, ref CalcX2, ref CalcY2);
      CalcStartPoint.X = CalcX1;
      CalcStartPoint.Y = CalcY1;
      CalcStartPoint.Z = BasePoint.Z;
      CalcEndPoint.X = CalcX2;
      CalcEndPoint.Y = CalcY2;
      CalcEndPoint.Z = BasePoint.Z;
    }
    if (WorkPlane.isPlaneXZ(Plane))
    {
      this.LinePerpendicular(RefStartPoint.X, RefStartPoint.Z, RefEndPoint.X, RefEndPoint.Z, BasePoint.X, BasePoint.Z, Length, ref CalcX1, ref CalcY1, ref CalcX2, ref CalcY2);
      CalcStartPoint.X = CalcX1;
      CalcStartPoint.Y = BasePoint.Y;
      CalcStartPoint.Z = CalcY1;
      CalcEndPoint.X = CalcX2;
      CalcEndPoint.Y = BasePoint.Y;
      CalcEndPoint.Z = CalcY2;
    }
    if (!WorkPlane.isPlaneYZ(Plane))
      return;
    this.LinePerpendicular(RefStartPoint.Y, RefStartPoint.Z, RefEndPoint.Y, RefEndPoint.Z, BasePoint.Y, BasePoint.Z, Length, ref CalcX1, ref CalcY1, ref CalcX2, ref CalcY2);
    CalcStartPoint.X = BasePoint.X;
    CalcStartPoint.Y = CalcX1;
    CalcStartPoint.Z = CalcY1;
    CalcEndPoint.X = BasePoint.X;
    CalcEndPoint.Y = CalcX2;
    CalcEndPoint.Z = CalcY2;
  }

  public void LineParalelToLine(
    double LX1,
    double LY1,
    double LX2,
    double LY2,
    double Length,
    ref double CalcLX1_1,
    ref double CalcLY1_1,
    ref double CalcLX2_1,
    ref double CalcLY2_1,
    ref double CalcLX1_2,
    ref double CalcLY1_2,
    ref double CalcLX2_2,
    ref double CalcLY2_2)
  {
    double CalcX1_1 = 0.0;
    double CalcY1_1 = 0.0;
    double CalcX2_1 = 0.0;
    double CalcY2_1 = 0.0;
    double CalcX1_2 = 0.0;
    double CalcY1_2 = 0.0;
    double CalcX2_2 = 0.0;
    double CalcY2_2 = 0.0;
    this.LinePerpendicular(LX1, LY1, LX2, LY2, LX1, LY1, Length, ref CalcX1_1, ref CalcY1_1, ref CalcX2_1, ref CalcY2_1);
    this.LinePerpendicular(LX1, LY1, LX2, LY2, LX2, LY2, Length, ref CalcX1_2, ref CalcY1_2, ref CalcX2_2, ref CalcY2_2);
    CalcLX1_1 = CalcX1_1;
    CalcLY1_1 = CalcY1_1;
    CalcLX2_1 = CalcX1_2;
    CalcLY2_1 = CalcY1_2;
    CalcLX1_2 = CalcX2_1;
    CalcLY1_2 = CalcY2_1;
    CalcLX2_2 = CalcX2_2;
    CalcLY2_2 = CalcY2_2;
  }

  public void LineParalelToLine(
    Line3D RefLine,
    double Distance,
    ref Line3D CalculatedLine1,
    ref Line3D CalculatedLine2)
  {
    double CalcLX1_1 = 0.0;
    double CalcLY1_1 = 0.0;
    double CalcLX2_1 = 0.0;
    double CalcLY2_1 = 0.0;
    double CalcLX1_2 = 0.0;
    double CalcLY1_2 = 0.0;
    double CalcLX2_2 = 0.0;
    double CalcLY2_2 = 0.0;
    Pnt3D Pnt = new Pnt3D();
    double z1 = RefLine.Start.Z;
    double z2 = RefLine.End.Z;
    double z3 = RefLine.Start.Z;
    double z4 = RefLine.End.Z;
    this.LineParalelToLine(RefLine.Start.X, RefLine.Start.Y, RefLine.End.X, RefLine.End.Y, Distance, ref CalcLX1_1, ref CalcLY1_1, ref CalcLX2_1, ref CalcLY2_1, ref CalcLX1_2, ref CalcLY1_2, ref CalcLX2_2, ref CalcLY2_2);
    Pnt.X = CalcLX1_1;
    Pnt.Y = CalcLY1_1;
    Pnt.Z = z1;
    CalculatedLine1.Start = new Pnt3D(Pnt);
    Pnt.X = CalcLX2_1;
    Pnt.Y = CalcLY2_1;
    Pnt.Z = z2;
    CalculatedLine1.End = new Pnt3D(Pnt);
    Pnt.X = CalcLX1_2;
    Pnt.Y = CalcLY1_2;
    Pnt.Z = z3;
    CalculatedLine2.Start = new Pnt3D(Pnt);
    Pnt.X = CalcLX2_2;
    Pnt.Y = CalcLY2_2;
    Pnt.Z = z4;
    CalculatedLine2.End = new Pnt3D(Pnt);
  }

  public void LineParalelToLine(
    Line3D RefLine,
    double Distance,
    WorkPlane Plane,
    ref Line3D CalculatedLine1,
    ref Line3D CalculatedLine2)
  {
    Line3D RefLine1 = new Line3D();
    Line3D CalculatedLine1_1 = new Line3D();
    Line3D CalculatedLine2_1 = new Line3D();
    Pnt3D pnt3D = new Pnt3D();
    if (WorkPlane.isPlaneXY(Plane))
    {
      RefLine1 = RefLine;
      this.LineParalelToLine(RefLine1, Distance, ref CalculatedLine1_1, ref CalculatedLine2_1);
      CalculatedLine1 = CalculatedLine1_1;
      CalculatedLine2 = CalculatedLine2_1;
    }
    if (WorkPlane.isPlaneXZ(Plane))
    {
      Pnt3D Pnt1 = new Pnt3D();
      Pnt1.X = RefLine.Start.X;
      Pnt1.Y = RefLine.Start.Z;
      Pnt1.Z = RefLine.Start.Y;
      RefLine1.Start = new Pnt3D(Pnt1);
      Pnt3D Pnt2 = new Pnt3D();
      Pnt2.X = RefLine.End.X;
      Pnt2.Y = RefLine.End.Z;
      Pnt2.Z = RefLine.End.Y;
      RefLine1.End = new Pnt3D(Pnt2);
      this.LineParalelToLine(RefLine1, Distance, ref CalculatedLine1_1, ref CalculatedLine2_1);
      Pnt3D Pnt3 = new Pnt3D();
      Pnt3.X = CalculatedLine1_1.Start.X;
      Pnt3.Y = RefLine.Start.Y;
      Pnt3.Z = CalculatedLine1_1.Start.Y;
      CalculatedLine1.Start = new Pnt3D(Pnt3);
      Pnt3D Pnt4 = new Pnt3D();
      Pnt4.X = CalculatedLine1_1.End.X;
      Pnt4.Y = RefLine.End.Y;
      Pnt4.Z = CalculatedLine1_1.End.Y;
      CalculatedLine1.End = new Pnt3D(Pnt4);
      Pnt3D Pnt5 = new Pnt3D();
      Pnt5.X = CalculatedLine2_1.Start.X;
      Pnt5.Y = RefLine.Start.Y;
      Pnt5.Z = CalculatedLine2_1.Start.Y;
      CalculatedLine2.Start = new Pnt3D(Pnt5);
      Pnt3D Pnt6 = new Pnt3D();
      Pnt6.X = CalculatedLine2_1.End.X;
      Pnt6.Y = RefLine.End.Y;
      Pnt6.Z = CalculatedLine2_1.End.Y;
      CalculatedLine2.End = new Pnt3D(Pnt6);
    }
    if (!WorkPlane.isPlaneYZ(Plane))
      return;
    Pnt3D Pnt7 = new Pnt3D();
    Pnt7.X = RefLine.Start.Y;
    Pnt7.Y = RefLine.Start.Z;
    Pnt7.Z = RefLine.Start.X;
    RefLine1.Start = new Pnt3D(Pnt7);
    Pnt3D Pnt8 = new Pnt3D();
    Pnt8.X = RefLine.End.Y;
    Pnt8.Y = RefLine.End.Z;
    Pnt8.Z = RefLine.End.X;
    RefLine1.End = new Pnt3D(Pnt8);
    this.LineParalelToLine(RefLine1, Distance, ref CalculatedLine1_1, ref CalculatedLine2_1);
    Pnt3D Pnt9 = new Pnt3D();
    Pnt9.X = CalculatedLine1_1.Start.Z;
    Pnt9.Y = CalculatedLine1_1.Start.X;
    Pnt9.Z = CalculatedLine1_1.Start.Y;
    CalculatedLine1.Start = new Pnt3D(Pnt9);
    Pnt3D Pnt10 = new Pnt3D();
    Pnt10.X = CalculatedLine1_1.End.Z;
    Pnt10.Y = CalculatedLine1_1.End.X;
    Pnt10.Z = CalculatedLine1_1.End.Y;
    CalculatedLine1.End = new Pnt3D(Pnt10);
    Pnt3D Pnt11 = new Pnt3D();
    Pnt11.X = CalculatedLine2_1.Start.Z;
    Pnt11.Y = CalculatedLine2_1.Start.X;
    Pnt11.Z = CalculatedLine2_1.Start.Y;
    CalculatedLine2.Start = new Pnt3D(Pnt11);
    Pnt3D Pnt12 = new Pnt3D();
    Pnt12.X = CalculatedLine2_1.End.Z;
    Pnt12.Y = CalculatedLine2_1.End.X;
    Pnt12.Z = CalculatedLine2_1.End.Y;
    CalculatedLine2.End = new Pnt3D(Pnt12);
  }

  public bool LineSplitByRefPoint(
    eEntities LineEntity,
    Pnt3D RefPoint,
    ref eEntities FirstEntity,
    ref eEntities SecondEntity)
  {
    try
    {
      if (LineEntity.GetType() == typeof (eLine))
      {
        Line3D FirstLine = new Line3D();
        Line3D SecondLine = new Line3D();
        bool flag;
        if (flag = this.LineSplitByRefPoint(LineEntity.Vertice[0], LineEntity.Vertice[1], RefPoint, ref FirstLine, ref SecondLine))
        {
          FirstEntity = (eEntities) new eLine(FirstLine.Start, FirstLine.End);
          eEntities.CopyCommonPorperties(LineEntity, ref FirstEntity);
          SecondEntity = (eEntities) new eLine(SecondLine.Start, SecondLine.End);
          eEntities.CopyCommonPorperties(LineEntity, ref SecondEntity);
        }
        else
        {
          FirstEntity = new eEntities();
          SecondEntity = new eEntities();
          eEntities.CopyEntity(LineEntity, ref FirstEntity);
          eEntities.CopyEntity(LineEntity, ref SecondEntity);
        }
        return flag;
      }
      FirstEntity = new eEntities();
      SecondEntity = new eEntities();
      eEntities.CopyEntity(LineEntity, ref FirstEntity);
      eEntities.CopyEntity(LineEntity, ref SecondEntity);
      return false;
    }
    catch (Exception ex)
    {
      string str = $"LineEntity: {LineEntity.ToString()} - RefPoint: {RefPoint.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return false;
    }
  }

  public bool LineSplitByRefPoint(
    Pnt3D StartPoint,
    Pnt3D EndPoint,
    Pnt3D RefPoint,
    ref Line3D FirstLine,
    ref Line3D SecondLine)
  {
    try
    {
      Pnt3D CalculatedPoint = new Pnt3D();
      bool flag;
      if (this.IsPointOverAndInsideLine(StartPoint, EndPoint, RefPoint, new WorkPlane(), buSystem.resolutionCompare, ref CalculatedPoint))
      {
        FirstLine = new Line3D(StartPoint, CalculatedPoint);
        SecondLine = new Line3D(CalculatedPoint, EndPoint);
        flag = true;
      }
      else
      {
        FirstLine = new Line3D(StartPoint, EndPoint);
        SecondLine = new Line3D(StartPoint, EndPoint);
        flag = false;
      }
      return flag;
    }
    catch (Exception ex)
    {
      string str = $"StartPoint: {StartPoint.ToString()} - EndPoint: {EndPoint.ToString()} - RefPoint: {RefPoint.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return false;
    }
  }

