  public bool AddPointToPolylineIfOnPath(
    ref eEntities PolylineEnt,
    Pnt3D AddingPoint,
    double Resolution)
  {
    try
    {
      bool polylineIfOnPath = false;
      if (PolylineEnt.GetType() == typeof (ePolyline))
      {
        for (int index = 1; index <= PolylineEnt.Vertice.Count - 1; ++index)
        {
          if (this.IsPointOverAndInsideLine(PolylineEnt.Vertice[index - 1], PolylineEnt.Vertice[index], AddingPoint, new WorkPlane(), Resolution) && PolylineEnt.Vertice[index - 1] != AddingPoint & PolylineEnt.Vertice[index] != AddingPoint)
          {
            PolylineEnt.Vertice.Insert(index, new Pnt3D(AddingPoint));
            PolylineEnt.Update();
            polylineIfOnPath = true;
          }
        }
      }
      return polylineIfOnPath;
    }
    catch (Exception ex)
    {
      string str = $"PolylineEnt: {PolylineEnt.ToString()} - AddingPoint: {AddingPoint.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return false;
    }
  }

  public void CircleWithCenter(
    Pnt3D Center,
    double Radius,
    WorkPlane Plane,
    EntityResolution EntResolution,
    ref List<Pnt3D> Vertices)
  {
    try
    {
      Pnt3D pnt3D1 = new Pnt3D();
      Vertices.Clear();
      int num = this.CircleVerticeCountByResolution(Radius, EntResolution);
      for (int index = 0; index <= num; ++index)
      {
        Pnt3D pnt3D2 = new Pnt3D();
        if (WorkPlane.isPlaneXY(Plane))
        {
          pnt3D2.X = Center.X + Radius * Math.Cos(buConversion.DegreeToRadianGreat360((double) index * 360.0 / (double) num));
          pnt3D2.Y = Center.Y + Radius * Math.Sin(buConversion.DegreeToRadianGreat360((double) index * 360.0 / (double) num));
          pnt3D2.Z = Center.Z;
          Vertices.Add(pnt3D2);
        }
        if (Plane.PlaneType == planeType.XZ)
        {
          pnt3D2.X = Center.X + Radius * Math.Cos(buConversion.DegreeToRadianGreat360((double) index * 360.0 / (double) num));
          pnt3D2.Y = Center.Y;
          pnt3D2.Z = Center.Z + Radius * Math.Sin(buConversion.DegreeToRadianGreat360((double) index * 360.0 / (double) num));
          Vertices.Add(pnt3D2);
        }
        if (Plane.PlaneType == planeType.YZ)
        {
          pnt3D2.X = Center.X;
          pnt3D2.Y = Center.Y + Radius * Math.Cos(buConversion.DegreeToRadianGreat360((double) index * 360.0 / (double) num));
          pnt3D2.Z = Center.Z + Radius * Math.Sin(buConversion.DegreeToRadianGreat360((double) index * 360.0 / (double) num));
          Vertices.Add(pnt3D2);
        }
      }
    }
    catch (Exception ex)
    {
      string str = $"Center: {Center.ToString()} - Rad: {Radius.ToString()} - Plane: {Plane.ToString()} - EntResolution: {EntResolution.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

