  public void Circle2Point(
    Pnt3D FirstPoint,
    Pnt3D SecondPoint,
    WorkPlane Plane,
    EntityResolution EntResolution,
    ref Pnt3D CenterPoint,
    ref double Radius,
    ref List<Pnt3D> Vertices)
  {
    try
    {
      Vertices.Clear();
      if (WorkPlane.isPlaneXY(Plane))
      {
        Radius = Math.Sqrt(Math.Pow(FirstPoint.X - SecondPoint.X, 2.0) + Math.Pow(FirstPoint.Y - SecondPoint.Y, 2.0)) / 2.0;
        if (Radius <= 0.0)
          return;
        CenterPoint.X = FirstPoint.X + (SecondPoint.X - FirstPoint.X) / 2.0;
        CenterPoint.Y = FirstPoint.Y + (SecondPoint.Y - FirstPoint.Y) / 2.0;
        CenterPoint.Z = FirstPoint.Z;
        int num = this.CircleVerticeCountByResolution(Radius, EntResolution);
        if (num < 10)
          num = 10;
        for (int index = 0; index <= num; ++index)
        {
          if (WorkPlane.isPlaneXY(Plane))
          {
            Pnt3D pnt3D = new Pnt3D();
            pnt3D.X = CenterPoint.X + Radius * Math.Cos(buConversion.DegreeToRadianGreat360((double) index * 360.0 / (double) num));
            pnt3D.Y = CenterPoint.Y + Radius * Math.Sin(buConversion.DegreeToRadianGreat360((double) index * 360.0 / (double) num));
            pnt3D.Z = CenterPoint.Z;
            Vertices.Add(pnt3D);
          }
        }
      }
      if (WorkPlane.isPlaneXZ(Plane))
      {
        Radius = Math.Sqrt(Math.Pow(FirstPoint.X - SecondPoint.X, 2.0) + Math.Pow(FirstPoint.Z - SecondPoint.Z, 2.0)) / 2.0;
        if (Radius <= 0.0)
          return;
        CenterPoint.X = FirstPoint.X + (SecondPoint.X - FirstPoint.X) / 2.0;
        CenterPoint.Y = FirstPoint.Y;
        CenterPoint.Z = FirstPoint.Z + (SecondPoint.Z - FirstPoint.Z) / 2.0;
        int num = this.CircleVerticeCountByResolution(Radius, EntResolution);
        if (num < 10)
          num = 10;
        for (int index = 0; index <= num; ++index)
        {
          if (WorkPlane.isPlaneXZ(Plane))
          {
            Pnt3D pnt3D = new Pnt3D();
            pnt3D.X = CenterPoint.X + Radius * Math.Cos(buConversion.DegreeToRadianGreat360((double) index * 360.0 / (double) num));
            pnt3D.Y = CenterPoint.Y;
            pnt3D.Z = CenterPoint.Z + Radius * Math.Sin(buConversion.DegreeToRadianGreat360((double) index * 360.0 / (double) num));
            Vertices.Add(pnt3D);
          }
        }
      }
      if (!WorkPlane.isPlaneYZ(Plane))
        return;
      Radius = Math.Sqrt(Math.Pow(FirstPoint.Y - SecondPoint.Y, 2.0) + Math.Pow(FirstPoint.Z - SecondPoint.Z, 2.0)) / 2.0;
      if (Radius <= 0.0)
        return;
      CenterPoint.X = FirstPoint.X;
      CenterPoint.Y = FirstPoint.Y + (SecondPoint.Y - FirstPoint.Y) / 2.0;
      CenterPoint.Z = FirstPoint.Z + (SecondPoint.Z - FirstPoint.Z) / 2.0;
      int num1 = this.CircleVerticeCountByResolution(Radius, EntResolution);
      if (num1 < 10)
        num1 = 10;
      for (int index = 0; index <= num1; ++index)
      {
        if (WorkPlane.isPlaneYZ(Plane))
        {
          Pnt3D pnt3D = new Pnt3D();
          pnt3D.X = CenterPoint.X;
          pnt3D.Y = CenterPoint.Y + Radius * Math.Cos(buConversion.DegreeToRadianGreat360((double) index * 360.0 / (double) num1));
          pnt3D.Z = CenterPoint.Z + Radius * Math.Sin(buConversion.DegreeToRadianGreat360((double) index * 360.0 / (double) num1));
          Vertices.Add(pnt3D);
        }
      }
    }
    catch (Exception ex)
    {
      string str = $"FirstPoint: {FirstPoint.ToString()} - SecondPoint: {SecondPoint.ToString()} - Plane: {Plane.ToString()} - EntResolution: {EntResolution.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

