      if (WorkPlane.isPlaneXY(Plane))
      {
        double num1 = 0.5 * Math.Pow((Math.Pow(SecondPoint.Y, 2.0) - 2.0 * SecondPoint.Y * ThirdPoint.Y + Math.Pow(ThirdPoint.Y, 2.0) + Math.Pow(SecondPoint.X, 2.0) + Math.Pow(ThirdPoint.X, 2.0) - 2.0 * SecondPoint.X * ThirdPoint.X) * (-2.0 * FirstPoint.X * ThirdPoint.X + Math.Pow(FirstPoint.X, 2.0) - 2.0 * FirstPoint.Y * ThirdPoint.Y + Math.Pow(FirstPoint.Y, 2.0) + Math.Pow(ThirdPoint.Y, 2.0) + Math.Pow(ThirdPoint.X, 2.0)) * (Math.Pow(FirstPoint.X, 2.0) - 2.0 * SecondPoint.X * FirstPoint.X + Math.Pow(FirstPoint.Y, 2.0) + Math.Pow(SecondPoint.X, 2.0) + Math.Pow(SecondPoint.Y, 2.0) - 2.0 * FirstPoint.Y * SecondPoint.Y), 0.5) / (FirstPoint.X * SecondPoint.Y - FirstPoint.X * ThirdPoint.Y - FirstPoint.Y * SecondPoint.X + FirstPoint.Y * ThirdPoint.X - ThirdPoint.X * SecondPoint.Y + ThirdPoint.Y * SecondPoint.X);
        double num2 = -0.5 * Math.Pow((Math.Pow(SecondPoint.Y, 2.0) - 2.0 * SecondPoint.Y * ThirdPoint.Y + Math.Pow(ThirdPoint.Y, 2.0) + Math.Pow(SecondPoint.X, 2.0) + Math.Pow(ThirdPoint.X, 2.0) - 2.0 * SecondPoint.X * ThirdPoint.X) * (-2.0 * FirstPoint.X * ThirdPoint.X + Math.Pow(FirstPoint.X, 2.0) - 2.0 * FirstPoint.Y * ThirdPoint.Y + Math.Pow(FirstPoint.Y, 2.0) + Math.Pow(ThirdPoint.Y, 2.0) + Math.Pow(ThirdPoint.X, 2.0)) * (Math.Pow(FirstPoint.X, 2.0) - 2.0 * SecondPoint.X * FirstPoint.X + Math.Pow(FirstPoint.Y, 2.0) + Math.Pow(SecondPoint.X, 2.0) + Math.Pow(SecondPoint.Y, 2.0) - 2.0 * FirstPoint.Y * SecondPoint.Y), 0.5) / (FirstPoint.X * SecondPoint.Y - FirstPoint.X * ThirdPoint.Y - FirstPoint.Y * SecondPoint.X + FirstPoint.Y * ThirdPoint.X - ThirdPoint.X * SecondPoint.Y + ThirdPoint.Y * SecondPoint.X);
        double num3 = 0.5 * ((SecondPoint.Y - ThirdPoint.Y) * Math.Pow(FirstPoint.X, 2.0) - FirstPoint.Y * Math.Pow(SecondPoint.X, 2.0) + ThirdPoint.Y * Math.Pow(SecondPoint.X, 2.0) - ThirdPoint.Y * Math.Pow(FirstPoint.Y, 2.0) + FirstPoint.Y * Math.Pow(ThirdPoint.X, 2.0) - SecondPoint.Y * Math.Pow(ThirdPoint.Y, 2.0) - Math.Pow(ThirdPoint.X, 2.0) * SecondPoint.Y + Math.Pow(ThirdPoint.Y, 2.0) * FirstPoint.Y + SecondPoint.Y * Math.Pow(FirstPoint.Y, 2.0) + Math.Pow(SecondPoint.Y, 2.0) * ThirdPoint.Y - Math.Pow(SecondPoint.Y, 2.0) * FirstPoint.Y) / ((SecondPoint.Y - ThirdPoint.Y) * FirstPoint.X - ThirdPoint.X * SecondPoint.Y + ThirdPoint.Y * SecondPoint.X - FirstPoint.Y * SecondPoint.X + FirstPoint.Y * ThirdPoint.X);
        double num4 = 0.5 * ((SecondPoint.Y - ThirdPoint.Y) * Math.Pow(FirstPoint.X, 2.0) - FirstPoint.Y * Math.Pow(SecondPoint.X, 2.0) + ThirdPoint.Y * Math.Pow(SecondPoint.X, 2.0) - ThirdPoint.Y * Math.Pow(FirstPoint.Y, 2.0) + FirstPoint.Y * Math.Pow(ThirdPoint.X, 2.0) - SecondPoint.Y * Math.Pow(ThirdPoint.Y, 2.0) - Math.Pow(ThirdPoint.X, 2.0) * SecondPoint.Y + Math.Pow(ThirdPoint.Y, 2.0) * FirstPoint.Y + SecondPoint.Y * Math.Pow(FirstPoint.Y, 2.0) + Math.Pow(SecondPoint.Y, 2.0) * ThirdPoint.Y - Math.Pow(SecondPoint.Y, 2.0) * FirstPoint.Y) / ((SecondPoint.Y - ThirdPoint.Y) * FirstPoint.X - ThirdPoint.X * SecondPoint.Y + ThirdPoint.Y * SecondPoint.X - FirstPoint.Y * SecondPoint.X + FirstPoint.Y * ThirdPoint.X);
        double num5 = -0.5 * ((SecondPoint.X - ThirdPoint.X) * Math.Pow(FirstPoint.X, 2.0) + (Math.Pow(ThirdPoint.X, 2.0) + Math.Pow(ThirdPoint.Y, 2.0) - Math.Pow(SecondPoint.X, 2.0) - Math.Pow(SecondPoint.Y, 2.0)) * FirstPoint.X - Math.Pow(ThirdPoint.X, 2.0) * SecondPoint.X + ThirdPoint.X * Math.Pow(SecondPoint.X, 2.0) + Math.Pow(FirstPoint.Y, 2.0) * SecondPoint.X - Math.Pow(FirstPoint.Y, 2.0) * ThirdPoint.X + ThirdPoint.X * Math.Pow(SecondPoint.Y, 2.0) - Math.Pow(ThirdPoint.Y, 2.0) * SecondPoint.X) / ((SecondPoint.Y - ThirdPoint.Y) * FirstPoint.X - ThirdPoint.X * SecondPoint.Y + ThirdPoint.Y * SecondPoint.X - FirstPoint.Y * SecondPoint.X + FirstPoint.Y * ThirdPoint.X);
        double num6 = -0.5 * ((SecondPoint.X - ThirdPoint.X) * Math.Pow(FirstPoint.X, 2.0) + (Math.Pow(ThirdPoint.X, 2.0) + Math.Pow(ThirdPoint.Y, 2.0) - Math.Pow(SecondPoint.X, 2.0) - Math.Pow(SecondPoint.Y, 2.0)) * FirstPoint.X - Math.Pow(ThirdPoint.X, 2.0) * SecondPoint.X + ThirdPoint.X * Math.Pow(SecondPoint.X, 2.0) + Math.Pow(FirstPoint.Y, 2.0) * SecondPoint.X - Math.Pow(FirstPoint.Y, 2.0) * ThirdPoint.X + ThirdPoint.X * Math.Pow(SecondPoint.Y, 2.0) - Math.Pow(ThirdPoint.Y, 2.0) * SecondPoint.X) / ((SecondPoint.Y - ThirdPoint.Y) * FirstPoint.X - ThirdPoint.X * SecondPoint.Y + ThirdPoint.Y * SecondPoint.X - FirstPoint.Y * SecondPoint.X + FirstPoint.Y * ThirdPoint.X);
