  public int Circle3Point(
    Pnt3D FirstPoint,
    Pnt3D SecondPoint,
    Pnt3D ThirdPoint,
    WorkPlane Plane,
    EntityResolution EntResolution,
    ref List<Pnt3D> Vertices)
  {
    Pnt3D CenterPoint = new Pnt3D();
    double Radius = 0.0;
    this.Circle3Point(FirstPoint, SecondPoint, ThirdPoint, Plane, EntResolution, ref CenterPoint, ref Radius, ref Vertices);
    return 1;
  }

  public int Circle3Point(
    Pnt3D FirstPoint,
    Pnt3D SecondPoint,
    Pnt3D ThirdPoint,
    WorkPlane Plane,
    ref Pnt3D CenterPoint,
    ref double Radius)
  {
    List<Pnt3D> Vertices = new List<Pnt3D>();
    this.Circle3Point(FirstPoint, SecondPoint, ThirdPoint, Plane, new EntityResolution(), ref CenterPoint, ref Radius, ref Vertices);
    Vertices.Clear();
    return 1;
  }

  public int CircleVerticeCountByResolution(double Radius, EntityResolution EntResolution)
  {
    try
    {
      int num = 10;
      if (EntResolution.ResolutionTypes == EntityResolutionType.ByNumber)
        num = EntResolution.GeometricCount;
      if (EntResolution.ResolutionTypes == EntityResolutionType.ByLength && buNumeric.IsNumeric(Radius.ToString()))
        num = Convert.ToInt32(2.0 * Math.PI * Radius / EntResolution.GeometricLength);
      if (EntResolution.ResolutionTypes == EntityResolutionType.ByLnRadius && buNumeric.IsNumeric(Radius.ToString()) && Radius > 0.0)
        num = Convert.ToInt32(Math.Log(Radius, Math.E) * EntResolution.LnRatio);
      if (num < EntResolution.MinPointCount)
        num = EntResolution.MinPointCount;
      return num;
    }
    catch (Exception ex)
    {
      string str = $"R: {Radius.ToString()} - Entitiy Res: {EntResolution.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return -1;
    }
  }

  public double CircleArea(double Radius, double StartAngle, double EndAngle)
  {
    try
    {
      return Math.PI * Radius * Radius;
    }
    catch (Exception ex)
    {
      string str = $"R: {Radius.ToString()} - SA: {StartAngle.ToString()} - EA: {EndAngle.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return 0.0;
    }
  }

  public double CircleCircumference(double Radius, double StartAngle, double EndAngle)
  {
    try
    {
      return Radius * Math.PI * 2.0;
    }
    catch (Exception ex)
    {
      string str = $"R: {Radius.ToString()} - SA: {StartAngle.ToString()} - EA: {EndAngle.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return 0.0;
    }
  }

  public void CircleDiameterLine(
    Pnt3D Center,
    double Radius,
    Pnt3D ActivePoint,
    ref Pnt3D FirstPoint,
    ref Pnt3D SecondPoint)
  {
    try
    {
      if (Radius <= 0.0)
        return;
      double Angle = this.PointAngle(ActivePoint, Center);
      Pnt3D BasePnt = new Pnt3D();
      Pnt3D EndPnt = new Pnt3D();
      this.LineWithLengthAndAngle(Center, Radius, Angle, new WorkPlane(), ref BasePnt, ref EndPnt);
      this.LineWithLengthAndAngle(EndPnt, Radius * 2.0, Angle + 180.0, new WorkPlane(), ref FirstPoint, ref SecondPoint);
    }
    catch (Exception ex)
    {
      string str = $"R: {Radius.ToString()} - Center: {Center.ToString()} - ActivePoint: {ActivePoint.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void CircleRadiusLine(
    Pnt3D Center,
    double Radius,
    Pnt3D ActivePoint,
    ref Pnt3D FirstPoint,
    ref Pnt3D SecondPoint)
  {
    try
    {
      if (Radius <= 0.0)
        return;
      double Angle = this.PointAngle(ActivePoint, Center);
      this.LineWithLengthAndAngle(Center, Radius, Angle, new WorkPlane(), ref FirstPoint, ref SecondPoint);
    }
    catch (Exception ex)
    {
      string str = $"R: {Radius.ToString()} - Center: {Center.ToString()} - ActivePoint: {ActivePoint.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void CircleQuadrantPoints(
    Pnt3D Center,
    double Radius,
    ref Pnt3D Point0,
    ref Pnt3D Point90,
    ref Pnt3D Point180,
    ref Pnt3D Point270)
  {
    try
    {
      Point0.X = Center.X + Radius * Math.Cos(buConversion.DegreeToRadian(0.0));
      Point0.Y = Center.Y + Radius * Math.Sin(buConversion.DegreeToRadian(0.0));
      Point90.X = Center.X + Radius * Math.Cos(buConversion.DegreeToRadian(90.0));
      Point90.Y = Center.Y + Radius * Math.Sin(buConversion.DegreeToRadian(90.0));
      Point180.X = Center.X + Radius * Math.Cos(buConversion.DegreeToRadian(180.0));
      Point180.Y = Center.Y + Radius * Math.Sin(buConversion.DegreeToRadian(180.0));
      Point270.X = Center.X + Radius * Math.Cos(buConversion.DegreeToRadian(270.0));
      Point270.Y = Center.Y + Radius * Math.Sin(buConversion.DegreeToRadian(270.0));
    }
    catch (Exception ex)
    {
      string str = $"R: {Radius.ToString()} - Center: {Center.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public double CircleSegmentLengthByDepth(double Radius, double RemoveLength)
  {
    try
    {
      double x = Radius - RemoveLength;
      return Math.Sqrt(Math.Pow(Radius, 2.0) - Math.Pow(x, 2.0)) * 2.0;
    }
    catch (Exception ex)
    {
      string str = $"R: {Radius.ToString()} - RemoveLength: {RemoveLength.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return 0.0;
    }
  }

  public void CirclePointAngleByLenght(double Radius, double RefLenght, ref double calcAngle)
  {
    double num = this.CircleCircumference(Radius, 0.0, 360.0);
    calcAngle = RefLenght / num * 360.0;
  }

  public void ArcWithCenter(
    Pnt3D Center,
    double Radius,
    double StartAngle,
    double EndAngle,
    WorkPlane Plane,
    EntityResolution EntResolution,
    ref List<Pnt3D> Vertices)
  {
    try
    {
      Pnt3D pnt3D1 = new Pnt3D();
      Vertices.Clear();
      int num = this.ArcVerticeCountByResolution(Radius, StartAngle, EndAngle, EntResolution);
      for (int index = 0; index <= num; ++index)
      {
        Pnt3D pnt3D2 = new Pnt3D();
        if (WorkPlane.isPlaneXY(Plane))
        {
          pnt3D2.X = Center.X + Radius * Math.Cos(buConversion.DegreeToRadianGreat360(StartAngle + (double) index * (EndAngle - StartAngle) / (double) num));
          pnt3D2.Y = Center.Y + Radius * Math.Sin(buConversion.DegreeToRadianGreat360(StartAngle + (double) index * (EndAngle - StartAngle) / (double) num));
          pnt3D2.Z = Center.Z;
          Vertices.Add(pnt3D2);
        }
        if (Plane.PlaneType == planeType.XZ)
        {
          pnt3D2.X = Center.X + Radius * Math.Cos(buConversion.DegreeToRadianGreat360(StartAngle + (double) index * (EndAngle - StartAngle) / (double) num));
          pnt3D2.Y = Center.Y;
          pnt3D2.Z = Center.Z + Radius * Math.Sin(buConversion.DegreeToRadianGreat360(StartAngle + (double) index * (EndAngle - StartAngle) / (double) num));
          Vertices.Add(pnt3D2);
        }
        if (Plane.PlaneType == planeType.YZ)
        {
          pnt3D2.X = Center.X;
          pnt3D2.Y = Center.Y + Radius * Math.Cos(buConversion.DegreeToRadianGreat360(StartAngle + (double) index * (EndAngle - StartAngle) / (double) num));
          pnt3D2.Z = Center.Z + Radius * Math.Sin(buConversion.DegreeToRadianGreat360(StartAngle + (double) index * (EndAngle - StartAngle) / (double) num));
          Vertices.Add(pnt3D2);
        }
      }
    }
    catch (Exception ex)
    {
      string str = $"Center: {Center.ToString()} - Rad: {Radius.ToString()} - SA: {StartAngle.ToString()} - EA: {EndAngle.ToString()} - Plane: {Plane.ToString()} - EntResolution: {EntResolution.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void ArcWithTwoPointAndRadius(
    Pnt3D ArcStartPoint,
    Pnt3D ArcEndPoint,
    double Radius,
    bool CW,
    WorkPlane Plane,
    ref Pnt3D ArcCenter,
    ref double ArcSA,
    ref double ArcEA)
  {
    try
    {
      Pnt3D MiddlePoint = new Pnt3D();
      Pnt3D pnt3D1 = new Pnt3D();
      Pnt3D pnt3D2 = new Pnt3D();
      bool flag = false;
      if (Radius < 0.0)
        flag = true;
      this.MiddlePointOfLine(ArcStartPoint, ArcEndPoint, ref MiddlePoint);
      Radius = Math.Abs(Radius);
      if (!buCompare.EQ(ArcStartPoint.Y, ArcEndPoint.Y))
      {
        double x1 = (ArcStartPoint.X - ArcEndPoint.X) / (ArcEndPoint.Y - ArcStartPoint.Y);
        double x2 = Math.Sqrt(Math.Pow(ArcEndPoint.Y - MiddlePoint.Y, 2.0) + Math.Pow(ArcEndPoint.X - MiddlePoint.X, 2.0));
        double num = Math.Sqrt(Math.Abs(Math.Pow(Radius, 2.0) - Math.Pow(x2, 2.0))) / Math.Sqrt(Math.Pow(x1, 2.0) + 1.0);
        pnt3D1.Y = MiddlePoint.Y + x1 * num;
        pnt3D2.Y = MiddlePoint.Y - x1 * num;
        pnt3D1.X = MiddlePoint.X + num;
        pnt3D2.X = MiddlePoint.X - num;
      }
      else
      {
        double x = Math.Sqrt(Math.Pow(ArcEndPoint.Y - MiddlePoint.Y, 2.0) + Math.Pow(ArcEndPoint.X - MiddlePoint.X, 2.0));
        double d = Math.Pow(Radius, 2.0) - Math.Pow(x, 2.0);
        if (d < 0.0)
          d = 0.0;
        double num = Math.Sqrt(d);
        pnt3D1.Y = MiddlePoint.Y + num;
        pnt3D2.Y = MiddlePoint.Y - num;
        pnt3D1.X = MiddlePoint.X;
        pnt3D2.X = MiddlePoint.X;
      }
      if (CW)
      {
        double num1 = this.PointAngle(ArcStartPoint, pnt3D1, Plane);
        double num2 = this.PointAngle(ArcEndPoint, pnt3D1, Plane);
        double num3 = this.PointAngle(ArcStartPoint, pnt3D2, Plane);
        double num4 = this.PointAngle(ArcEndPoint, pnt3D2, Plane);
        if (!flag)
        {
