        if (d < 0.0)
          d = 0.0;
        double num = Math.Sqrt(d);
        pnt3D1.Y = MiddlePoint.Y + num;
        pnt3D2.Y = MiddlePoint.Y - num;
        pnt3D1.X = MiddlePoint.X;
        pnt3D2.X = MiddlePoint.X;
