  public void ArcWithIJK(
    Pnt3D PreviousPoint,
    Pnt3D NextPoint,
    double I,
    double J,
    double K,
    int ArcDir,
    ref Pnt3D ArcCenter,
    ref double Radius,
    ref double StartAngle,
    ref double EndAngle)
  {
    ArcCenter = new Pnt3D();
    double num1 = 0.0;
    double num2 = 0.0;
    bool flag = false;
    ArcCenter.X = PreviousPoint.X + I;
    ArcCenter.Y = PreviousPoint.Y + J;
    ArcCenter.Z = PreviousPoint.Z + K;
    if (ArcDir == 2)
    {
      num1 = this.PointAngle(PreviousPoint, ArcCenter);
      num2 = this.PointAngle(NextPoint, ArcCenter);
      if (!flag)
      {
        if (num2 > 180.0 & buCompare.EQ(num1, 0.0, 0.01))
          num1 = 360.0;
        if (num1 < 180.0 & buCompare.EQ(num2, 0.0, 0.01))
          num2 = 0.0;
      }
      if (num2 > num1)
        num1 = 360.0 + num1;
    }
    if (ArcDir == 3)
    {
      num1 = this.PointAngle(PreviousPoint, ArcCenter);
      num2 = this.PointAngle(NextPoint, ArcCenter);
      if (!flag)
      {
        if (num1 > 180.0 & buCompare.EQ(num2, 0.0, 0.01))
          num2 = 360.0;
        if (num2 < 180.0 & buCompare.EQ(num1, 0.0, 0.01))
          num1 = 0.0;
      }
      if (num1 > num2)
        num2 = 360.0 + num2;
    }
    if (num1 > num2)
    {
      StartAngle = num2;
      EndAngle = num1;
    }
    else
    {
      StartAngle = num1;
      EndAngle = num2;
    }
    if (StartAngle > EndAngle)
      EndAngle = 360.0 + EndAngle;
    Radius = this.Length3D(PreviousPoint, ArcCenter);
  }

