  public void ArcStartMiddleEndPoint(
    Pnt3D CenterPoint,
    double Radius,
    double StartAngle,
    double EndAngle,
    WorkPlane Plane,
    ref Pnt3D MiddlePoint)
  {
    Pnt3D StartPoint = new Pnt3D();
    Pnt3D EndPoint = new Pnt3D();
    this.ArcStartMiddleEndPoint(CenterPoint, Radius, StartAngle, EndAngle, Plane, ref StartPoint, ref MiddlePoint, ref EndPoint);
  }

  public void ArcStartMiddleEndPoint(
    Pnt3D CenterPoint,
    double Radius,
    double StartAngle,
