        MiddlePoint.Z = CenterPoint.Z + Radius * Math.Sin(buConversion.DegreeToRadian((StartAngle + EndAngle) / 2.0));
        EndPoint.X = CenterPoint.X + Radius * Math.Cos(buConversion.DegreeToRadian(EndAngle));
        EndPoint.Y = CenterPoint.Y;
        EndPoint.Z = CenterPoint.Z + Radius * Math.Sin(buConversion.DegreeToRadian(EndAngle));
      }
      if (!WorkPlane.isPlaneYZ(Plane))
        return;
      StartPoint.X = CenterPoint.X;
      StartPoint.Y = CenterPoint.Y + Radius * Math.Cos(buConversion.DegreeToRadian(StartAngle));
      StartPoint.Z = CenterPoint.Z + Radius * Math.Sin(buConversion.DegreeToRadian(StartAngle));
