      MiddlePoint.Y = CenterPoint.Y + Radius * Math.Cos(buConversion.DegreeToRadian((StartAngle + EndAngle) / 2.0));
      MiddlePoint.Z = CenterPoint.Z + Radius * Math.Sin(buConversion.DegreeToRadian((StartAngle + EndAngle) / 2.0));
      EndPoint.X = CenterPoint.X;
      EndPoint.Y = CenterPoint.Y + Radius * Math.Cos(buConversion.DegreeToRadian(EndAngle));
      EndPoint.Z = CenterPoint.Z + Radius * Math.Sin(buConversion.DegreeToRadian(EndAngle));
    }
    catch (Exception ex)
    {
      string str = $"CenterPoint: {CenterPoint.ToString()} - Radius: {Radius.ToString()} - StartAngle: {StartAngle.ToString()} - EndAngle: {EndAngle.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void ArcOutsidePoints(
    Pnt3D CenterPoint,
    double Radius,
    double StartAngle,
    double EndAngle,
    WorkPlane Plane,
    ref List<Pnt3D> OutsidePoints)
  {
    try
    {
      OutsidePoints.Clear();
      Pnt3D pnt3D1 = new Pnt3D(CenterPoint);
      pnt3D1.X += Radius;
      if (this.IsPointInsideArc(CenterPoint, Radius, StartAngle, EndAngle, pnt3D1, Plane))
        OutsidePoints.Add(new Pnt3D(pnt3D1));
      Pnt3D pnt3D2 = new Pnt3D(CenterPoint);
      pnt3D2.X -= Radius;
      if (this.IsPointInsideArc(CenterPoint, Radius, StartAngle, EndAngle, pnt3D2, Plane))
        OutsidePoints.Add(new Pnt3D(pnt3D2));
      Pnt3D pnt3D3 = new Pnt3D(CenterPoint);
      pnt3D3.Y += Radius;
      if (this.IsPointInsideArc(CenterPoint, Radius, StartAngle, EndAngle, pnt3D3, Plane))
        OutsidePoints.Add(new Pnt3D(pnt3D3));
      Pnt3D pnt3D4 = new Pnt3D(CenterPoint);
      pnt3D4.Y -= Radius;
      if (!this.IsPointInsideArc(CenterPoint, Radius, StartAngle, EndAngle, pnt3D4, Plane))
        return;
      OutsidePoints.Add(new Pnt3D(pnt3D4));
    }
    catch (Exception ex)
    {
      string str = $"Center: {CenterPoint.ToString()} - Radius: {Radius.ToString()} - StartAngle: {StartAngle.ToString()} - EndAngle: {EndAngle.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public int ArcVerticeCountByResolution(
    double Radius,
    double StartAngle,
    double EndAngle,
    EntityResolution EntResolution)
  {
    try
    {
      int num = 10;
      if (EntResolution.ResolutionTypes == EntityResolutionType.ByNumber)
      {
        num = EntResolution.GeometricCount;
        if (num < EntResolution.MinPointCount)
          num = EntResolution.MinPointCount;
      }
      if (EntResolution.ResolutionTypes == EntityResolutionType.ByLength)
      {
        if (buNumeric.IsNumeric(Radius.ToString()))
          num = Convert.ToInt32(2.0 * Math.PI * Radius * ((EndAngle - StartAngle) / 360.0) / EntResolution.GeometricLength);
        if (num < EntResolution.MinPointCount)
          num = EntResolution.MinPointCount;
      }
      if (EntResolution.ResolutionTypes == EntityResolutionType.ByLnRadius)
      {
        if (buNumeric.IsNumeric(Radius.ToString()) && Radius > 0.0)
          num = Convert.ToInt32(Math.Log(Radius, Math.E) * EntResolution.LnRatio);
        if (num < EntResolution.MinPointCount)
          num = EntResolution.MinPointCount;
      }
      return num;
    }
    catch (Exception ex)
    {
      string str = $"R: {Radius.ToString()} - SA: {StartAngle.ToString()} - EA: {EndAngle.ToString()} - Ent Res:{EntResolution.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return -1;
    }
  }

  public double ArcArea(double Radius, double StartAngle, double EndAngle)
  {
    try
    {
      return Math.PI * Radius * Radius * (EndAngle - StartAngle) / 360.0;
    }
    catch (Exception ex)
    {
      string str = $"R: {Radius.ToString()} - SA: {StartAngle.ToString()} - EA: {EndAngle.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return 0.0;
    }
  }

  public double ArcCircumference(double Radius, double StartAngle, double EndAngle)
  {
    try
    {
      return Radius * Math.PI * 2.0 * (EndAngle - StartAngle) / 360.0;
    }
    catch (Exception ex)
    {
      string str = $"R: {Radius.ToString()} - SA: {StartAngle.ToString()} - EA: {EndAngle.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return 0.0;
    }
  }

  public void ArcByLength(
    Pnt3D Center,
    double Radius,
    double SA,
    double EA,
    double Length,
    ArcDirectionType Direction,
    ref double CalcSA,
    ref double CalcEA)
  {
    try
    {
      double num1 = Math.Abs(EA - SA);
      double num2 = Math.PI * Radius * 2.0 * num1 / 360.0;
      double num3 = Length / num2;
      if (Direction == ArcDirectionType.FromStart)
      {
        CalcEA = SA + num1 * num3;
        CalcSA = SA;
      }
      if (Direction == ArcDirectionType.FromEnd)
      {
        CalcSA = EA - num1 * num3;
        CalcEA = EA;
      }
      if (Direction != ArcDirectionType.FromMiddle)
        return;
      CalcEA = (SA + EA) / 2.0 + num1 * num3;
      CalcSA = (SA + EA) / 2.0;
    }
    catch (Exception ex)
    {
      string str = $"Center: {Center.ToString()} - Radius: {Radius.ToString()} - SA: {SA.ToString()} - EA: {EA.ToString()} - Length: {Length.ToString()} - Direction: {Direction.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

