  public void ArcSplitToTwoArc(eEntities RefArc, ref eArc FirstArc, ref eArc SecondArc)
  {
    try
    {
      if (!(RefArc.GetType() == typeof (eArc)))
        return;
      FirstArc = new eArc(RefArc);
      SecondArc = new eArc(RefArc);
      FirstArc.EndAngle = (((eArc) RefArc).StartAngle + ((eArc) RefArc).EndAngle) / 2.0;
      FirstArc.Update();
      SecondArc.StartAngle = (((eArc) RefArc).StartAngle + ((eArc) RefArc).EndAngle) / 2.0;
      SecondArc.Update();
    }
    catch (Exception ex)
    {
      string str = "RefArc: " + RefArc.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void ArcTo3Point(eEntities RefArc, ref List<Pnt3D> Points)
  {
    try
    {
      if (!(RefArc.GetType() == typeof (eArc)) || RefArc.Vertice.Count < 3)
        return;
      if (RefArc.camDirections == camPathDirectionType.Normal)
      {
        int int32 = Convert.ToInt32(RefArc.Vertice.Count / 2);
        Points.Add(new Pnt3D(RefArc.Vertice[0]));
        Points.Add(new Pnt3D(RefArc.Vertice[int32]));
        Points.Add(new Pnt3D(RefArc.Vertice[RefArc.Vertice.Count - 1]));
      }
      if (RefArc.camDirections != camPathDirectionType.Reverse)
        return;
      int int32_1 = Convert.ToInt32(RefArc.Vertice.Count / 2);
      Points.Add(new Pnt3D(RefArc.Vertice[RefArc.Vertice.Count - 1]));
      Points.Add(new Pnt3D(RefArc.Vertice[int32_1]));
      Points.Add(new Pnt3D(RefArc.Vertice[0]));
    }
    catch (Exception ex)
    {
      string str = "RefArc: " + RefArc.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void ArcStartMiddleEndPoint(
    Pnt3D CenterPoint,
    double Radius,
    double StartAngle,
    double EndAngle,
    ref Pnt3D StartPoint,
    ref Pnt3D MiddlePoint,
    ref Pnt3D EndPoint)
  {
    StartPoint.X = CenterPoint.X + Radius * Math.Cos(buConversion.DegreeToRadian(StartAngle));
    StartPoint.Y = CenterPoint.Y + Radius * Math.Sin(buConversion.DegreeToRadian(StartAngle));
    StartPoint.Z = CenterPoint.Z;
    MiddlePoint.X = CenterPoint.X + Radius * Math.Cos(buConversion.DegreeToRadian((StartAngle + EndAngle) / 2.0));
    MiddlePoint.Y = CenterPoint.Y + Radius * Math.Sin(buConversion.DegreeToRadian((StartAngle + EndAngle) / 2.0));
    MiddlePoint.Z = CenterPoint.Z;
    EndPoint.X = CenterPoint.X + Radius * Math.Cos(buConversion.DegreeToRadian(EndAngle));
    EndPoint.Y = CenterPoint.Y + Radius * Math.Sin(buConversion.DegreeToRadian(EndAngle));
    EndPoint.Z = CenterPoint.Z;
  }

