      pnt3D5.X = CornerPoint.X - LeftWidth;
      pnt3D5.Y = CornerPoint.Y + TopHeight;
      pnt3D5.Z = CornerPoint.Z;
      Vertices.Add(pnt3D5);
      Pnt3D pnt3D6 = new Pnt3D();
      pnt3D6.X = CornerPoint.X - LeftWidth;
      pnt3D6.Y = CornerPoint.Y - BottomHeight;
      pnt3D6.Z = CornerPoint.Z;
      Vertices.Add(pnt3D6);
    }
    catch (Exception ex)
    {
      string str = $"CornerPoint: {CornerPoint.ToString()} - LeftWidth: {LeftWidth.ToString()} - RigthWidth: {RigthWidth.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void RectangleCenter(
    Pnt3D Center,
    Pnt3D RefPoint,
    WorkPlane Plane,
    ref List<Pnt3D> Vertices)
  {
    try
    {
      Pnt3D pnt3D1 = new Pnt3D();
      Vertices.Clear();
      if (WorkPlane.isPlaneXY(Plane))
      {
        double num1 = Math.Abs(Center.X - RefPoint.X);
        double num2 = Math.Abs(Center.Y - RefPoint.Y);
        Pnt3D pnt3D2 = new Pnt3D();
        pnt3D2.X = Center.X - num1;
        pnt3D2.Y = Center.Y - num2;
        pnt3D2.Z = Center.Z;
        Vertices.Add(pnt3D2);
        Pnt3D pnt3D3 = new Pnt3D();
        pnt3D3.X = Center.X + num1;
        pnt3D3.Y = Center.Y - num2;
        pnt3D3.Z = Center.Z;
        Vertices.Add(pnt3D3);
        Pnt3D pnt3D4 = new Pnt3D();
        pnt3D4.X = Center.X + num1;
        pnt3D4.Y = Center.Y + num2;
        pnt3D4.Z = Center.Z;
        Vertices.Add(pnt3D4);
        Pnt3D pnt3D5 = new Pnt3D();
        pnt3D5.X = Center.X - num1;
        pnt3D5.Y = Center.Y + num2;
        pnt3D5.Z = Center.Z;
        Vertices.Add(pnt3D5);
        Pnt3D pnt3D6 = new Pnt3D();
        pnt3D6.X = Center.X - num1;
        pnt3D6.Y = Center.Y - num2;
        pnt3D6.Z = Center.Z;
        Vertices.Add(pnt3D6);
      }
      if (Plane.PlaneType == planeType.XZ)
      {
        double num3 = Math.Abs(Center.X - RefPoint.X);
        double num4 = Math.Abs(Center.Z - RefPoint.Z);
        Pnt3D pnt3D7 = new Pnt3D();
        pnt3D7.X = Center.X - num3;
        pnt3D7.Y = Center.Y;
        pnt3D7.Z = Center.Z - num4;
        Vertices.Add(pnt3D7);
        Pnt3D pnt3D8 = new Pnt3D();
        pnt3D8.X = Center.X + num3;
        pnt3D8.Y = Center.Y;
        pnt3D8.Z = Center.Z - num4;
        Vertices.Add(pnt3D8);
        Pnt3D pnt3D9 = new Pnt3D();
        pnt3D9.X = Center.X + num3;
        pnt3D9.Y = Center.Y;
        pnt3D9.Z = Center.Z + num4;
        Vertices.Add(pnt3D9);
        Pnt3D pnt3D10 = new Pnt3D();
        pnt3D10.X = Center.X - num3;
        pnt3D10.Y = Center.Y;
        pnt3D10.Z = Center.Z + num4;
        Vertices.Add(pnt3D10);
        Pnt3D pnt3D11 = new Pnt3D();
        pnt3D11.X = Center.X - num3;
        pnt3D11.Y = Center.Y;
        pnt3D11.Z = Center.Z - num4;
        Vertices.Add(pnt3D11);
      }
      if (Plane.PlaneType != planeType.YZ)
        return;
      double num5 = Math.Abs(Center.Y - RefPoint.Y);
      double num6 = Math.Abs(Center.Z - RefPoint.Z);
      Pnt3D pnt3D12 = new Pnt3D();
      pnt3D12.X = Center.X;
      pnt3D12.Y = Center.Y - num5;
      pnt3D12.Z = Center.Z - num6;
      Vertices.Add(pnt3D12);
      Pnt3D pnt3D13 = new Pnt3D();
      pnt3D13.X = Center.X;
      pnt3D13.Y = Center.Y + num5;
      pnt3D13.Z = Center.Z - num6;
      Vertices.Add(pnt3D13);
      Pnt3D pnt3D14 = new Pnt3D();
      pnt3D14.X = Center.X;
      pnt3D14.Y = Center.Y + num5;
      pnt3D14.Z = Center.Z + num6;
      Vertices.Add(pnt3D14);
      Pnt3D pnt3D15 = new Pnt3D();
      pnt3D15.X = Center.X;
      pnt3D15.Y = Center.Y - num5;
      pnt3D15.Z = Center.Z + num6;
      Vertices.Add(pnt3D15);
      Pnt3D pnt3D16 = new Pnt3D();
      pnt3D16.X = Center.X;
      pnt3D16.Y = Center.Y - num5;
      pnt3D16.Z = Center.Z - num6;
      Vertices.Add(pnt3D16);
    }
    catch (Exception ex)
    {
      string str = $"Center: {Center.ToString()} - RefPoint: {RefPoint.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void RectangleAngleWithCenter(
    Pnt3D Center,
    double Width,
    double Height,
    double Angle,
    WorkPlane Plane,
    ref List<Pnt3D> Vertices)
  {
    try
    {
      Pnt3D pnt3D1 = new Pnt3D();
      List<Pnt3D> SourceList = new List<Pnt3D>();
      if (Plane.PlaneType == planeType.XY)
      {
        Pnt3D CornerPoint = new Pnt3D();
        CornerPoint.X = Center.X - Width / 2.0;
        CornerPoint.Y = Center.Y - Height / 2.0;
        CornerPoint.Z = Center.Z;
        this.RectangleCorner(CornerPoint, Width, Height, Plane, ref Vertices);
        for (int index = 0; index <= Vertices.Count - 1; ++index)
        {
          Pnt3D pnt3D2 = new Pnt3D();
          double num = this.Length3D(Vertices[index], Center, Plane);
          double Degree = this.PointAngle(Vertices[index].X, Vertices[index].Y, Center.X, Center.Y) + Angle;
          pnt3D2.X = Center.X + num * Math.Cos(buConversion.DegreeToRadian(Degree));
          pnt3D2.Y = Center.Y + num * Math.Sin(buConversion.DegreeToRadian(Degree));
          pnt3D2.Z = Center.Z;
          SourceList.Add(pnt3D2);
        }
      }
      if (Plane.PlaneType == planeType.XZ)
      {
        Pnt3D CornerPoint = new Pnt3D();
        CornerPoint.X = Center.X - Width / 2.0;
        CornerPoint.Y = Center.Y;
        CornerPoint.Z = Center.Z - Height / 2.0;
        this.RectangleCorner(CornerPoint, Width, Height, Plane, ref Vertices);
        for (int index = 0; index <= Vertices.Count - 1; ++index)
        {
          Pnt3D pnt3D3 = new Pnt3D();
          double num = this.Length3D(Vertices[index], Center, Plane);
          double Degree = this.PointAngle(Vertices[index].X, Vertices[index].Z, Center.X, Center.Z) + Angle;
          pnt3D3.X = Center.X + num * Math.Cos(buConversion.DegreeToRadian(Degree));
          pnt3D3.Y = Center.Y;
          pnt3D3.Z = Center.Z + num * Math.Sin(buConversion.DegreeToRadian(Degree));
          SourceList.Add(pnt3D3);
        }
      }
      if (Plane.PlaneType == planeType.YZ)
      {
        Pnt3D CornerPoint = new Pnt3D();
        CornerPoint.X = Center.X;
        CornerPoint.Y = Center.Y - Width / 2.0;
        CornerPoint.Z = Center.Z - Height / 2.0;
        this.RectangleCorner(CornerPoint, Width, Height, Plane, ref Vertices);
        for (int index = 0; index <= Vertices.Count - 1; ++index)
        {
          Pnt3D pnt3D4 = new Pnt3D();
          double num = this.Length3D(Vertices[index], Center, Plane);
          double Degree = this.PointAngle(Vertices[index].Y, Vertices[index].Z, Center.Y, Center.Z) + Angle;
          pnt3D4.X = Center.X;
          pnt3D4.Y = Center.Y + num * Math.Cos(buConversion.DegreeToRadian(Degree));
          pnt3D4.Z = Center.Z + num * Math.Sin(buConversion.DegreeToRadian(Degree));
          SourceList.Add(pnt3D4);
        }
      }
      Vertices.Clear();
      buGeneral.CopyLists(SourceList, ref Vertices);
    }
    catch (Exception ex)
    {
      string str = $"Center: {Center.ToString()} - Width: {Width.ToString()} - Height: {Height.ToString()} - Angle: {Angle.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void RectangleChamfer(
    Pnt3D CornerPnt1,
    double Width,
    double Height,
    double Chamfer,
    WorkPlane Plane,
    ref List<Pnt3D> Points)
  {
    Pnt3D CornerPnt2 = new Pnt3D();
    if (WorkPlane.isPlaneXY(Plane))
      CornerPnt2 = new Pnt3D(CornerPnt1.X + Width, CornerPnt1.Y + Height, CornerPnt1.Z);
    if (WorkPlane.isPlaneXZ(Plane))
      CornerPnt2 = new Pnt3D(CornerPnt1.X + Width, CornerPnt1.Y, CornerPnt1.Z + Height);
    if (WorkPlane.isPlaneYZ(Plane))
      CornerPnt2 = new Pnt3D(CornerPnt1.X, CornerPnt1.Y + Width, CornerPnt1.Z + Height);
    this.RectangleChamfer(CornerPnt1, CornerPnt2, Chamfer, Plane, ref Points);
  }

  public void RectangleChamfer(
    Pnt3D CornerPnt1,
    Pnt3D CornerPnt2,
    double Chamfer,
    WorkPlane Plane,
    ref List<Pnt3D> Points)
  {
    try
    {
      Points.Clear();
      if (WorkPlane.isPlaneXY(Plane))
      {
        double num1 = Math.Sqrt(Math.Pow(Chamfer, 2.0) / 2.0);
        double num2 = Math.Sqrt(Math.Pow(Chamfer, 2.0) / 2.0);
        double num3;
        double num4;
        if (CornerPnt2.X > CornerPnt1.X)
        {
          if (CornerPnt2.Y > CornerPnt1.Y)
          {
            num3 = num1 * 1.0;
            num4 = num2 * 1.0;
          }
          else
          {
            num3 = num1 * 1.0;
            num4 = num2 * -1.0;
          }
        }
        else if (CornerPnt2.Y > CornerPnt1.Y)
        {
          num3 = num1 * -1.0;
          num4 = num2 * 1.0;
        }
        else
        {
          num3 = num1 * -1.0;
          num4 = num2 * -1.0;
        }
        Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt1.Y + num4, CornerPnt1.Z));
        Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt2.Y - num4, CornerPnt1.Z));
        Points.Add(new Pnt3D(CornerPnt1.X + num3, CornerPnt2.Y, CornerPnt1.Z));
        Points.Add(new Pnt3D(CornerPnt2.X - num3, CornerPnt2.Y, CornerPnt1.Z));
        Points.Add(new Pnt3D(CornerPnt2.X, CornerPnt2.Y - num4, CornerPnt1.Z));
        Points.Add(new Pnt3D(CornerPnt2.X, CornerPnt1.Y + num4, CornerPnt1.Z));
        Points.Add(new Pnt3D(CornerPnt2.X - num3, CornerPnt1.Y, CornerPnt1.Z));
        Points.Add(new Pnt3D(CornerPnt1.X + num3, CornerPnt1.Y, CornerPnt1.Z));
        Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt1.Y + num4, CornerPnt1.Z));
      }
      if (WorkPlane.isPlaneXZ(Plane))
      {
        double num5 = Math.Sqrt(Math.Pow(Chamfer, 2.0) / 2.0);
        double num6 = Math.Sqrt(Math.Pow(Chamfer, 2.0) / 2.0);
        double num7;
        double num8;
        if (CornerPnt2.X > CornerPnt1.X)
        {
          if (CornerPnt2.Z > CornerPnt1.Z)
          {
            num7 = num5 * 1.0;
            num8 = num6 * 1.0;
          }
          else
          {
            num7 = num5 * 1.0;
            num8 = num6 * -1.0;
          }
        }
        else if (CornerPnt2.Z > CornerPnt1.Z)
        {
          num7 = num5 * -1.0;
          num8 = num6 * 1.0;
        }
        else
        {
          num7 = num5 * -1.0;
          num8 = num6 * -1.0;
        }
        Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt1.Y, CornerPnt1.Z + num8));
        Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt1.Y, CornerPnt2.Z - num8));
        Points.Add(new Pnt3D(CornerPnt1.X + num7, CornerPnt1.Y, CornerPnt2.Z));
        Points.Add(new Pnt3D(CornerPnt2.X - num7, CornerPnt1.Y, CornerPnt2.Z));
        Points.Add(new Pnt3D(CornerPnt2.X, CornerPnt1.Y, CornerPnt2.Z - num8));
        Points.Add(new Pnt3D(CornerPnt2.X, CornerPnt1.Y, CornerPnt1.Z + num8));
        Points.Add(new Pnt3D(CornerPnt2.X - num7, CornerPnt1.Y, CornerPnt1.Z));
        Points.Add(new Pnt3D(CornerPnt1.X + num7, CornerPnt1.Y, CornerPnt1.Z));
        Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt1.Y, CornerPnt1.Z + num8));
        Points.Add(new Pnt3D());
      }
      if (!WorkPlane.isPlaneYZ(Plane))
        return;
      double num9 = Math.Sqrt(Math.Pow(Chamfer, 2.0) / 2.0);
      double num10 = Math.Sqrt(Math.Pow(Chamfer, 2.0) / 2.0);
      double num11;
      double num12;
      if (CornerPnt2.Y > CornerPnt1.Y)
      {
        if (CornerPnt2.Z > CornerPnt1.Z)
        {
          num11 = num9 * 1.0;
          num12 = num10 * 1.0;
        }
        else
        {
          num11 = num9 * 1.0;
          num12 = num10 * -1.0;
        }
      }
      else if (CornerPnt2.Z > CornerPnt1.Z)
      {
        num11 = num9 * -1.0;
        num12 = num10 * 1.0;
      }
      else
      {
        num11 = num9 * -1.0;
        num12 = num10 * -1.0;
      }
      Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt1.Y, CornerPnt1.Z + num12));
      Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt1.Y, CornerPnt2.Z - num12));
      Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt1.Y + num11, CornerPnt2.Z));
      Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt2.Y - num11, CornerPnt2.Z));
      Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt2.Y, CornerPnt2.Z - num12));
      Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt2.Y, CornerPnt1.Z + num12));
      Points.Add(new Pnt3D(CornerPnt2.X, CornerPnt2.Y - num11, CornerPnt1.Z));
      Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt1.Y + num11, CornerPnt1.Z));
      Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt1.Y, CornerPnt1.Z + num12));
    }
    catch (Exception ex)
    {
      string str = $"CornerPnt1: {CornerPnt1.ToString()} - CornerPnt2: {CornerPnt2.ToString()} - Plane: {Plane.ToString()} - Chamfer: {Chamfer.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void RectangleFillet(
    Pnt3D Center,
    double Width,
    double Height,
    double Radius,
    WorkPlane Plane,
    ref List<Pnt3D> Vertices)
  {
    this.RectangleFillet(Center, Width, Height, Radius, 0.0, Plane, ref Vertices);
  }

  public void RectangleFillet(
    Pnt3D Center,
    double Width,
    double Height,
    double Radius,
    double Angle,
    WorkPlane Plane,
    ref List<Pnt3D> Vertices)
  {
    try
    {
      Pnt3D pnt3D1 = new Pnt3D();
      Pnt3D pnt3D2 = new Pnt3D();
      if (WorkPlane.isPlaneXY(Plane))
      {
        Pnt3D CornerPnt1 = new Pnt3D(Center);
        CornerPnt1.X = Center.X - Width / 2.0;
        CornerPnt1.Y = Center.Y - Height / 2.0;
        Pnt3D CornerPnt2 = new Pnt3D(Center);
        CornerPnt2.X = Center.X + Width / 2.0;
        CornerPnt2.Y = Center.Y + Height / 2.0;
        this.RectangleFillet(CornerPnt1, CornerPnt2, Radius, Plane, ref Vertices);
      }
      if (WorkPlane.isPlaneXZ(Plane))
      {
        Pnt3D CornerPnt1 = new Pnt3D(Center);
        CornerPnt1.X = Center.X - Width / 2.0;
        CornerPnt1.Z = Center.Z - Height / 2.0;
        Pnt3D CornerPnt2 = new Pnt3D(Center);
        CornerPnt2.X = Center.X + Width / 2.0;
        CornerPnt2.Z = Center.Z + Height / 2.0;
        this.RectangleFillet(CornerPnt1, CornerPnt2, Radius, Plane, ref Vertices);
      }
      if (WorkPlane.isPlaneYZ(Plane))
      {
        Pnt3D CornerPnt1 = new Pnt3D(Center);
        CornerPnt1.Y = Center.Y - Width / 2.0;
        CornerPnt1.Z = Center.Z - Height / 2.0;
        Pnt3D CornerPnt2 = new Pnt3D(Center);
        CornerPnt2.Y = Center.Y + Width / 2.0;
        CornerPnt2.Z = Center.Z + Height / 2.0;
        this.RectangleFillet(CornerPnt1, CornerPnt2, Radius, Plane, ref Vertices);
      }
      if (Angle == 0.0)
        return;
      this.Rotate(Center, Angle, Plane, ref Vertices);
    }
    catch (Exception ex)
    {
      string str = $"Center: {Center.ToString()} - Width: {Width.ToString()} - Height: {Height.ToString()} - Plane: {Plane.ToString()} - Radius: {Radius.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void RectangleFillet(
    Pnt3D CornerPnt1,
    Pnt3D CornerPnt2,
    double Radius,
    WorkPlane Plane,
    ref List<eEntities> Entities)
  {
    try
    {
      eLine eLine1 = new eLine();
      eArc eArc1 = new eArc();
      Entities.Clear();
      Pnt3D pnt3D1 = new Pnt3D();
      Pnt3D pnt3D2 = new Pnt3D();
      if (WorkPlane.isPlaneXY(Plane))
      {
        pnt3D1.Z = CornerPnt1.Z;
        pnt3D2.Z = CornerPnt1.Z;
        if (CornerPnt2.X > CornerPnt1.X)
        {
          pnt3D2.X = CornerPnt2.X;
          pnt3D1.X = CornerPnt1.X;
          if (CornerPnt2.Y > CornerPnt1.Y)
          {
            pnt3D2.Y = CornerPnt2.Y;
            pnt3D1.Y = CornerPnt1.Y;
          }
          else
          {
            pnt3D2.Y = CornerPnt1.Y;
            pnt3D1.Y = CornerPnt2.Y;
          }
        }
        else
        {
          pnt3D2.X = CornerPnt1.X;
          pnt3D1.X = CornerPnt2.X;
          if (CornerPnt2.Y > CornerPnt1.Y)
          {
            pnt3D2.Y = CornerPnt2.Y;
            pnt3D1.Y = CornerPnt1.Y;
          }
          else
          {
            pnt3D2.Y = CornerPnt1.Y;
            pnt3D1.Y = CornerPnt2.Y;
          }
        }
        eLine eLine2 = new eLine(new Pnt3D(pnt3D1.X + Radius, pnt3D1.Y, pnt3D1.Z), new Pnt3D(pnt3D2.X - Radius, pnt3D1.Y, pnt3D1.Z));
        Entities.Add((eEntities) eLine2);
        eArc eArc2 = new eArc(new Pnt3D(pnt3D2.X - Radius, pnt3D1.Y + Radius, pnt3D1.Z), Radius, 270.0, 360.0, Plane);
        Entities.Add((eEntities) eArc2);
        eLine eLine3 = new eLine(new Pnt3D(pnt3D2.X, pnt3D1.Y + Radius, pnt3D1.Z), new Pnt3D(pnt3D2.X, pnt3D2.Y - Radius, pnt3D1.Z));
        Entities.Add((eEntities) eLine3);
        eArc eArc3 = new eArc(new Pnt3D(pnt3D2.X - Radius, pnt3D2.Y - Radius, pnt3D1.Z), Radius, 0.0, 90.0, Plane);
        Entities.Add((eEntities) eArc3);
        eLine eLine4 = new eLine(new Pnt3D(pnt3D2.X - Radius, pnt3D2.Y, pnt3D1.Z), new Pnt3D(pnt3D1.X + Radius, pnt3D2.Y, pnt3D1.Z));
        Entities.Add((eEntities) eLine4);
        eArc eArc4 = new eArc(new Pnt3D(pnt3D1.X + Radius, pnt3D2.Y - Radius, pnt3D1.Z), Radius, 90.0, 180.0, Plane);
        Entities.Add((eEntities) eArc4);
        eLine eLine5 = new eLine(new Pnt3D(pnt3D1.X, pnt3D2.Y - Radius, pnt3D1.Z), new Pnt3D(pnt3D1.X, pnt3D1.Y + Radius, pnt3D1.Z));
        Entities.Add((eEntities) eLine5);
        eArc eArc5 = new eArc(new Pnt3D(pnt3D1.X + Radius, pnt3D1.Y + Radius, pnt3D1.Z), Radius, 180.0, 270.0, Plane);
        Entities.Add((eEntities) eArc5);
      }
      if (WorkPlane.isPlaneXZ(Plane))
      {
        pnt3D1.Y = CornerPnt1.Y;
        pnt3D2.Y = CornerPnt1.Y;
        if (CornerPnt2.X > CornerPnt1.X)
        {
          pnt3D2.X = CornerPnt2.X;
          pnt3D1.X = CornerPnt1.X;
          if (CornerPnt2.Z > CornerPnt1.Z)
          {
            pnt3D2.Z = CornerPnt2.Z;
            pnt3D1.Z = CornerPnt1.Z;
          }
          else
          {
            pnt3D2.Z = CornerPnt1.Z;
            pnt3D1.Z = CornerPnt2.Z;
          }
        }
        else
        {
          pnt3D2.X = CornerPnt1.X;
          pnt3D1.X = CornerPnt2.X;
          if (CornerPnt2.Z > CornerPnt1.Z)
          {
            pnt3D2.Z = CornerPnt2.Z;
            pnt3D1.Z = CornerPnt1.Z;
          }
          else
          {
            pnt3D2.Z = CornerPnt1.Z;
            pnt3D1.Z = CornerPnt2.Z;
          }
        }
        eLine eLine6 = new eLine(new Pnt3D(pnt3D1.X + Radius, pnt3D1.Y, pnt3D1.Z), new Pnt3D(pnt3D2.X - Radius, pnt3D1.Y, pnt3D1.Z));
        Entities.Add((eEntities) eLine6);
        eArc eArc6 = new eArc(new Pnt3D(pnt3D2.X - Radius, pnt3D1.Y, pnt3D1.Z + Radius), Radius, 270.0, 360.0, Plane);
        Entities.Add((eEntities) eArc6);
        eLine eLine7 = new eLine(new Pnt3D(pnt3D2.X, pnt3D1.Y, pnt3D1.Z + Radius), new Pnt3D(pnt3D2.X, pnt3D1.Y, pnt3D2.Z - Radius));
        Entities.Add((eEntities) eLine7);
        eArc eArc7 = new eArc(new Pnt3D(pnt3D2.X - Radius, pnt3D1.Y, pnt3D2.Z - Radius), Radius, 0.0, 90.0, Plane);
        Entities.Add((eEntities) eArc7);
        eLine eLine8 = new eLine(new Pnt3D(pnt3D2.X - Radius, pnt3D1.Y, pnt3D2.Z), new Pnt3D(pnt3D1.X + Radius, pnt3D1.Y, pnt3D2.Z));
        Entities.Add((eEntities) eLine8);
        eArc eArc8 = new eArc(new Pnt3D(pnt3D1.X + Radius, pnt3D1.Y, pnt3D2.Z - Radius), Radius, 90.0, 180.0, Plane);
        Entities.Add((eEntities) eArc8);
        eLine eLine9 = new eLine(new Pnt3D(pnt3D1.X, pnt3D1.Y, pnt3D2.Z - Radius), new Pnt3D(pnt3D1.X, pnt3D1.Y, pnt3D1.Z + Radius));
        Entities.Add((eEntities) eLine9);
        eArc eArc9 = new eArc(new Pnt3D(pnt3D1.X + Radius, pnt3D1.Y, pnt3D1.Z + Radius), Radius, 180.0, 270.0, Plane);
        Entities.Add((eEntities) eArc9);
      }
      if (!WorkPlane.isPlaneYZ(Plane))
        return;
      pnt3D1.X = CornerPnt1.X;
      pnt3D2.X = CornerPnt1.X;
      if (CornerPnt2.Y > CornerPnt1.Y)
      {
        pnt3D2.Y = CornerPnt2.Y;
        pnt3D1.Y = CornerPnt1.Y;
        if (CornerPnt2.Z > CornerPnt1.Z)
        {
          pnt3D2.Z = CornerPnt2.Z;
          pnt3D1.Z = CornerPnt1.Z;
        }
        else
        {
          pnt3D2.Z = CornerPnt1.Z;
          pnt3D1.Z = CornerPnt2.Z;
        }
      }
      else
      {
        pnt3D2.Y = CornerPnt1.Y;
        pnt3D1.Y = CornerPnt2.Y;
        if (CornerPnt2.Z > CornerPnt1.Z)
        {
          pnt3D2.Z = CornerPnt2.Z;
          pnt3D1.Z = CornerPnt1.Z;
        }
        else
        {
          pnt3D2.Z = CornerPnt1.Z;
          pnt3D1.Z = CornerPnt2.Z;
        }
      }
      eLine eLine10 = new eLine(new Pnt3D(pnt3D1.X, pnt3D1.Y + Radius, pnt3D1.Z), new Pnt3D(pnt3D1.X, pnt3D2.Y - Radius, pnt3D1.Z));
      Entities.Add((eEntities) eLine10);
      eArc eArc10 = new eArc(new Pnt3D(pnt3D1.X, pnt3D2.Y - Radius, pnt3D1.Z + Radius), Radius, 270.0, 360.0, Plane);
      Entities.Add((eEntities) eArc10);
      eLine eLine11 = new eLine(new Pnt3D(pnt3D1.X, pnt3D2.Y, pnt3D1.Z + Radius), new Pnt3D(pnt3D1.X, pnt3D2.Y, pnt3D2.Z - Radius));
      Entities.Add((eEntities) eLine11);
      eArc eArc11 = new eArc(new Pnt3D(pnt3D2.X, pnt3D2.Y - Radius, pnt3D2.Z - Radius), Radius, 0.0, 90.0, Plane);
      Entities.Add((eEntities) eArc11);
      eLine eLine12 = new eLine(new Pnt3D(pnt3D1.X, pnt3D2.Y - Radius, pnt3D2.Z), new Pnt3D(pnt3D1.X, pnt3D1.Y + Radius, pnt3D2.Z));
      Entities.Add((eEntities) eLine12);
      eArc eArc12 = new eArc(new Pnt3D(pnt3D1.X, pnt3D1.Y + Radius, pnt3D2.Z - Radius), Radius, 90.0, 180.0, Plane);
      Entities.Add((eEntities) eArc12);
      eLine eLine13 = new eLine(new Pnt3D(pnt3D1.X, pnt3D1.Y, pnt3D2.Z - Radius), new Pnt3D(pnt3D1.X, pnt3D1.Y, pnt3D1.Z + Radius));
      Entities.Add((eEntities) eLine13);
      eArc eArc13 = new eArc(new Pnt3D(pnt3D1.X, pnt3D1.Y + Radius, pnt3D1.Z + Radius), Radius, 180.0, 270.0, Plane);
      Entities.Add((eEntities) eArc13);
    }
    catch (Exception ex)
    {
      string str = $"CornerPnt1: {CornerPnt1.ToString()} - CornerPnt2: {CornerPnt2.ToString()} - Plane: {Plane.ToString()} - Radius: {Radius.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

