  public void Rectangle3Point(
    Pnt3D FirstPoint,
    Pnt3D SecondPoint,
    Pnt3D ThirdPoint,
    WorkPlane Plane,
    ref List<Pnt3D> Vertices,
    ref Pnt3D ConnectPoint)
  {
    try
    {
      Pnt3D CalculatedPoint = new Pnt3D();
      Pnt3D pnt3D1 = new Pnt3D();
      Pnt3D pnt3D2 = new Pnt3D();
      Pnt3D pnt3D3 = new Pnt3D();
      double Distance = 0.0;
      Vertices.Clear();
      if (this.IsPointOverAndInsideLine(FirstPoint, SecondPoint, ThirdPoint, Plane, buSystem.resolutionCompare))
      {
        Vertices.Add(new Pnt3D(FirstPoint));
        Vertices.Add(new Pnt3D(SecondPoint));
      }
      Pnt3D pnt3D4 = !this.IsPointOverLine(FirstPoint, SecondPoint, ThirdPoint, Plane, ref CalculatedPoint, ref Distance) ? (this.Length3D(FirstPoint, ThirdPoint) >= this.Length3D(SecondPoint, ThirdPoint) ? new Pnt3D(SecondPoint) : new Pnt3D(FirstPoint)) : CalculatedPoint;
      ConnectPoint = new Pnt3D(pnt3D4);
      double Length1 = this.Length3D(pnt3D4, ThirdPoint);
      double Length2 = this.Length3D(FirstPoint, SecondPoint);
      double num1 = this.PointAngle(FirstPoint, SecondPoint, Plane);
      Vertices.Add(new Pnt3D(FirstPoint));
      Vertices.Add(new Pnt3D(SecondPoint));
      Pnt3D BasePnt1 = new Pnt3D();
      Pnt3D BasePnt2 = new Pnt3D();
      Pnt3D EndPnt1 = new Pnt3D();
      Pnt3D EndPnt2 = new Pnt3D();
      this.LineWithLengthAndAngle(SecondPoint, Length1, num1 - 90.0, Plane, ref BasePnt1, ref EndPnt1);
      this.LineWithLengthAndAngle(SecondPoint, Length1, num1 + 90.0, Plane, ref BasePnt2, ref EndPnt2);
      Pnt3D PntEnd1;
      Pnt3D pnt3D5;
      int num2;
      if (this.Length3D(EndPnt1, ThirdPoint) < this.Length3D(EndPnt2, ThirdPoint))
      {
        Vertices.Add(new Pnt3D(EndPnt1));
        PntEnd1 = new Pnt3D(BasePnt1);
        pnt3D5 = new Pnt3D(EndPnt1);
        num2 = -1;
      }
      else
      {
        Vertices.Add(new Pnt3D(EndPnt2));
        PntEnd1 = new Pnt3D(BasePnt2);
        pnt3D5 = new Pnt3D(EndPnt2);
        num2 = 1;
      }
      double num3 = this.PointAngle(PntEnd1, pnt3D5, Plane);
      this.LineWithLengthAndAngle(pnt3D5, Length2, num3 + (double) (90 * num2), Plane, ref BasePnt1, ref EndPnt1);
      Vertices.Add(new Pnt3D(EndPnt1));
      Pnt3D PntEnd2 = new Pnt3D(BasePnt1);
      Pnt3D pnt3D6 = new Pnt3D(EndPnt1);
      double num4 = this.PointAngle(PntEnd2, pnt3D6, Plane);
      this.LineWithLengthAndAngle(pnt3D6, Length1, num4 + (double) (90 * num2), Plane, ref BasePnt1, ref EndPnt1);
      Vertices.Add(new Pnt3D(EndPnt1));
      pnt3D2 = new Pnt3D(BasePnt1);
      pnt3D3 = new Pnt3D(EndPnt1);
    }
    catch (Exception ex)
    {
      string str = $"FirstPoint: {FirstPoint.ToString()} - SecondPoint: {SecondPoint.ToString()} - ThirdPoint: {ThirdPoint.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void Slot(
    Pnt3D BasePoint,
    double Width,
    double Height,
    double Angle,
    WorkPlane Plane,
    EntityResolution EntitiesResolution,
    ref List<Pnt3D> Vertices,
    ref List<eEntities> Entities)
  {
    try
    {
      Entities.Clear();
      Entities = new List<eEntities>();
      if (WorkPlane.isPlaneXY(Plane))
      {
        eArc eArc1 = new eArc(new Pnt3D(BasePoint.X + Height / 2.0, BasePoint.Y, BasePoint.Z), Height / 2.0, 90.0, 270.0, Plane);
        eArc eArc2 = new eArc(new Pnt3D(BasePoint.X + Width - Height / 2.0, BasePoint.Y, BasePoint.Z), Height / 2.0, 270.0, 450.0, Plane);
        eLine eLine1 = new eLine(new Pnt3D(BasePoint.X + Height / 2.0, BasePoint.Y - Height / 2.0, BasePoint.Z), new Pnt3D(BasePoint.X + Width - Height / 2.0, BasePoint.Y - Height / 2.0, BasePoint.Z));
        eLine eLine2 = new eLine(new Pnt3D(BasePoint.X + Width - Height / 2.0, BasePoint.Y + Height / 2.0, BasePoint.Z), new Pnt3D(BasePoint.X + Height / 2.0, BasePoint.Y + Height / 2.0, BasePoint.Z));
        Entities.Add((eEntities) eLine1);
        Entities.Add((eEntities) eArc2);
        Entities.Add((eEntities) eLine2);
        Entities.Add((eEntities) eArc1);
        this.Rotate(BasePoint, Angle, ClockDirectionType.CCW, Plane, ref Entities);
        this.EntityToPoint(Entities, EntitiesResolution, ref Vertices);
        this.CheckDuplicatedPointsWithPrevious(ref Vertices);
      }
      if (WorkPlane.isPlaneXZ(Plane))
      {
        eArc eArc3 = new eArc(new Pnt3D(BasePoint.X + Height / 2.0, BasePoint.Y, BasePoint.Z), Height / 2.0, 90.0, 270.0, Plane);
        eArc eArc4 = new eArc(new Pnt3D(Width - Height / 2.0, BasePoint.Y, BasePoint.Z), Height / 2.0, 270.0, 450.0, Plane);
        eLine eLine3 = new eLine(new Pnt3D(BasePoint.X + Height / 2.0, BasePoint.Y, BasePoint.Z - Height / 2.0), new Pnt3D(Width - Height / 2.0, BasePoint.Y, BasePoint.Z - Height / 2.0));
        eLine eLine4 = new eLine(new Pnt3D(Width - Height / 2.0, BasePoint.Y, BasePoint.Z + Height / 2.0), new Pnt3D(BasePoint.X + Height / 2.0, BasePoint.Y, BasePoint.Z + Height / 2.0));
        Entities.Add((eEntities) eLine3);
        Entities.Add((eEntities) eArc4);
        Entities.Add((eEntities) eLine4);
        Entities.Add((eEntities) eArc3);
        this.Rotate(BasePoint, Angle, ClockDirectionType.CCW, Plane, ref Entities);
        this.EntityToPoint(Entities, EntitiesResolution, ref Vertices);
        this.CheckDuplicatedPointsWithPrevious(ref Vertices);
      }
      if (!WorkPlane.isPlaneYZ(Plane))
        return;
      eArc eArc5 = new eArc(new Pnt3D(BasePoint.X, BasePoint.Y + Height / 2.0, BasePoint.Z), Height / 2.0, 90.0, 270.0, Plane);
      eArc eArc6 = new eArc(new Pnt3D(Width, BasePoint.Y - Height / 2.0, BasePoint.Z), Height / 2.0, 270.0, 450.0, Plane);
      eLine eLine5 = new eLine(new Pnt3D(BasePoint.X, BasePoint.Y + Height / 2.0, BasePoint.Z - Height / 2.0), new Pnt3D(Width, BasePoint.Y - Height / 2.0, BasePoint.Z - Height / 2.0));
      eLine eLine6 = new eLine(new Pnt3D(Width, BasePoint.Y - Height / 2.0, BasePoint.Z + Height / 2.0), new Pnt3D(BasePoint.X, BasePoint.Y + Height / 2.0, BasePoint.Z + Height / 2.0));
      Entities.Add((eEntities) eLine5);
      Entities.Add((eEntities) eArc6);
      Entities.Add((eEntities) eLine6);
      Entities.Add((eEntities) eArc5);
      this.Rotate(BasePoint, Angle, ClockDirectionType.CCW, Plane, ref Entities);
      this.EntityToPoint(Entities, EntitiesResolution, ref Vertices);
      this.CheckDuplicatedPointsWithPrevious(ref Vertices);
    }
    catch (Exception ex)
    {
      string str = $"BasePoint: {BasePoint.ToString()} - Width: {Width.ToString()} - Height: {Height.ToString()} - Angle: {Angle.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

