    }
  }

  public void PolygonCenter(
    double BaseX,
    double BaseY,
    double BaseZ,
    double PointX,
    double PointY,
    double PointZ,
    int Side,
    WorkPlane Plane,
    ref List<double> VerticeX,
    ref List<double> VerticeY,
    ref List<double> VerticeZ)
  {
    try
    {
      if (Side <= 2)
        return;
      VerticeX.Clear();
      VerticeY.Clear();
      VerticeZ.Clear();
      if (WorkPlane.isPlaneXY(Plane))
      {
        double num1 = Math.Sqrt(Math.Pow(PointX - BaseX, 2.0) + Math.Pow(PointY - BaseY, 2.0));
        double num2 = 360.0 / (double) Side;
        double num3 = this.PointAngle(PointX, PointY, BaseX, BaseY);
        VerticeX.Add(BaseX + num1 * Math.Cos(buConversion.DegreeToRadian(num3 + 0.0 * num2)));
        VerticeY.Add(BaseY + num1 * Math.Sin(buConversion.DegreeToRadian(num3 + 0.0 * num2)));
        VerticeZ.Add(BaseZ);
        for (int index = 0; index <= Side - 1; ++index)
        {
          VerticeX.Add(BaseX + num1 * Math.Cos(buConversion.DegreeToRadian(num3 + (double) (index + 1) * num2)));
          VerticeY.Add(BaseY + num1 * Math.Sin(buConversion.DegreeToRadian(num3 + (double) (index + 1) * num2)));
          VerticeZ.Add(BaseZ);
        }
      }
      if (Plane.PlaneType == planeType.XZ)
      {
        double num4 = Math.Sqrt(Math.Pow(PointX - BaseX, 2.0) + Math.Pow(PointZ - BaseZ, 2.0));
        double num5 = 360.0 / (double) Side;
        double num6 = this.PointAngle(PointX, PointZ, BaseX, BaseZ);
        VerticeX.Add(BaseX + num4 * Math.Cos(buConversion.DegreeToRadian(num6 + 0.0 * num5)));
        VerticeY.Add(BaseY);
        VerticeZ.Add(BaseZ + num4 * Math.Sin(buConversion.DegreeToRadian(num6 + 0.0 * num5)));
        for (int index = 0; index <= Side - 1; ++index)
        {
          VerticeX.Add(BaseX + num4 * Math.Cos(buConversion.DegreeToRadian(num6 + (double) (index + 1) * num5)));
          VerticeY.Add(BaseY);
          VerticeZ.Add(BaseZ + num4 * Math.Sin(buConversion.DegreeToRadian(num6 + (double) (index + 1) * num5)));
        }
      }
      if (Plane.PlaneType != planeType.YZ)
        return;
      double num7 = Math.Sqrt(Math.Pow(PointY - BaseY, 2.0) + Math.Pow(PointZ - BaseZ, 2.0));
      double num8 = 360.0 / (double) Side;
      double num9 = this.PointAngle(PointY, PointZ, BaseY, BaseZ);
      VerticeX.Add(BaseX);
      VerticeY.Add(BaseY + num7 * Math.Cos(buConversion.DegreeToRadian(num9 + 0.0 * num8)));
      VerticeZ.Add(BaseZ + num7 * Math.Sin(buConversion.DegreeToRadian(num9 + 0.0 * num8)));
      for (int index = 0; index <= Side - 1; ++index)
      {
        VerticeX.Add(BaseX);
        VerticeY.Add(BaseY + num7 * Math.Cos(buConversion.DegreeToRadian(num9 + (double) (index + 1) * num8)));
        VerticeZ.Add(BaseZ + num7 * Math.Sin(buConversion.DegreeToRadian(num9 + (double) (index + 1) * num8)));
      }
    }
    catch (Exception ex)
    {
      string str = $"BaseX: {BaseX.ToString()} - BaseY: {BaseY.ToString()} - BaseZ: {BaseZ.ToString()} - PointX: {PointX.ToString()} - PointZ: {PointY.ToString()} - PointZ: {PointZ.ToString()} - Side: {Side.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void PolygonCenter(
    Pnt3D Center,
    Pnt3D RefPoint,
    int Side,
