      List<double> VerticeZ = new List<double>();
      this.PolygonCenter(Center.X, Center.Y, Center.Z, RefPoint.X, RefPoint.Y, RefPoint.Z, Side, Plane, ref VerticeX, ref VerticeY, ref VerticeZ);
      Vertices.Clear();
      for (int index = 0; index <= VerticeX.Count - 1; ++index)
      {
        Pnt3D pnt3D2 = new Pnt3D();
        pnt3D2.X = VerticeX[index];
        pnt3D2.Y = VerticeY[index];
        pnt3D2.Z = VerticeZ[index];
        Vertices.Add(pnt3D2);
      }
    }
    catch (Exception ex)
    {
      string str = $"Center: {Center.ToString()} - RefPoint: {RefPoint.ToString()} - Side: {Side.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void PolygonCenter(
    Pnt3D Center,
    double Radius,
    int Side,
    WorkPlane Plane,
    ref List<Pnt3D> Vertices)
  {
    try
    {
      Pnt3D pnt3D1 = new Pnt3D();
      Pnt3D pnt3D2 = new Pnt3D();
      List<double> VerticeX = new List<double>();
      List<double> VerticeY = new List<double>();
      List<double> VerticeZ = new List<double>();
      if (WorkPlane.isPlaneXY(Plane))
      {
        pnt3D2 = new Pnt3D(Center);
        pnt3D2.X += Radius;
      }
      if (Plane.PlaneType == planeType.XZ)
      {
        pnt3D2 = new Pnt3D(Center);
        pnt3D2.X += Radius;
      }
      if (Plane.PlaneType == planeType.YZ)
      {
        pnt3D2 = new Pnt3D(Center);
        pnt3D2.Y += Radius;
      }
      this.PolygonCenter(Center.X, Center.Y, Center.Z, pnt3D2.X, pnt3D2.Y, pnt3D2.Z, Side, Plane, ref VerticeX, ref VerticeY, ref VerticeZ);
      Vertices.Clear();
      for (int index = 0; index <= VerticeX.Count - 1; ++index)
      {
        Pnt3D pnt3D3 = new Pnt3D();
        pnt3D3.X = VerticeX[index];
        pnt3D3.Y = VerticeY[index];
        pnt3D3.Z = VerticeZ[index];
        Vertices.Add(pnt3D3);
      }
    }
    catch (Exception ex)
    {
      string str = $"Center: {Center.ToString()} - Radius: {Radius.ToString()} - Side: {Side.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void PolygonSide(
    double BaseX,
    double BaseY,
    double BaseZ,
    double PointX,
    double PointY,
    double PointZ,
    int Side,
    WorkPlane Plane,
    ref List<double> VerticeX,
    ref List<double> VerticeY,
    ref List<double> VerticeZ)
  {
    try
    {
      if (Side <= 2)
        return;
      VerticeX.Clear();
      VerticeY.Clear();
      VerticeZ.Clear();
      if (WorkPlane.isPlaneXY(Plane))
      {
        double num1 = BaseX;
        double num2 = PointX;
        double num3 = BaseY;
        double num4 = PointY;
        double num5 = BaseZ;
        double num6 = 360.0 / (double) Side;
        double x = this.Length2D(num1, num3, num2, num4) / 2.0 / Math.Sin(buConversion.DegreeToRadian(num6 / 2.0));
