  public void PolygonSide(
    Pnt3D Center,
    Pnt3D RefPoint,
    int Side,
    bool Reverse,
    WorkPlane Plane,
    ref List<Pnt3D> Vertices)
  {
    try
    {
      Pnt3D pnt3D1 = new Pnt3D();
      List<double> VerticeX = new List<double>();
      List<double> VerticeY = new List<double>();
      List<double> VerticeZ = new List<double>();
      List<Pnt3D> pnt3DList = new List<Pnt3D>();
      this.PolygonSide(Center.X, Center.Y, Center.Z, RefPoint.X, RefPoint.Y, RefPoint.Z, Side, Plane, ref VerticeX, ref VerticeY, ref VerticeZ);
      Vertices.Clear();
      for (int index = 0; index <= VerticeX.Count - 1; ++index)
      {
        Pnt3D pnt3D2 = new Pnt3D();
        pnt3D2.X = VerticeX[index];
        pnt3D2.Y = VerticeY[index];
        pnt3D2.Z = VerticeZ[index];
        pnt3DList.Add(pnt3D2);
      }
      if (Reverse)
        this.Mirror(Center, RefPoint, pnt3DList, Plane, 0.0, ref Vertices);
      else
        buGeneral.CopyLists(pnt3DList, ref Vertices);
    }
    catch (Exception ex)
    {
      string str = $"Center: {Center.ToString()} - RefPoint: {RefPoint.ToString()} - Reverse: {Reverse.ToString()} - Side: {Side.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

