          VerticeY.Add(BaseY);
          VerticeZ.Add(BaseZ + num5 * Math.Sin(buConversion.DegreeToRadian(num8 + (double) (index + 1) * num7)));
        }
      }
      if (Plane.PlaneType != planeType.YZ)
        return;
      double num9 = Math.Sqrt(Math.Pow(FirstY - BaseY, 2.0) + Math.Pow(FirstZ - BaseZ, 2.0));
      double num10 = Math.Sqrt(Math.Pow(SecondY - BaseY, 2.0) + Math.Pow(SecondZ - BaseZ, 2.0));
      double num11 = 72.0;
      double num12 = this.PointAngle(FirstY, FirstZ, BaseY, BaseZ);
      VerticeX.Add(BaseX);
      VerticeY.Add(BaseY + num9 * Math.Cos(buConversion.DegreeToRadian(num12 + 0.0)));
      VerticeZ.Add(BaseZ + num9 * Math.Sin(buConversion.DegreeToRadian(num12 + 0.0)));
      for (int index = 0; index <= 4; ++index)
      {
        VerticeX.Add(BaseX);
        VerticeY.Add(BaseY + num10 * Math.Cos(buConversion.DegreeToRadian(num12 + num11 / 2.0 + (double) index * num11)));
        VerticeZ.Add(BaseZ + num10 * Math.Sin(buConversion.DegreeToRadian(num12 + num11 / 2.0 + (double) index * num11)));
        VerticeX.Add(BaseX);
        VerticeY.Add(BaseY + num9 * Math.Cos(buConversion.DegreeToRadian(num12 + (double) (index + 1) * num11)));
        VerticeZ.Add(BaseZ + num9 * Math.Sin(buConversion.DegreeToRadian(num12 + (double) (index + 1) * num11)));
      }
    }
    catch (Exception ex)
    {
      string str = $"BaseX: {BaseX.ToString()} - BaseY: {BaseY.ToString()} - BaseZ: {BaseZ.ToString()} - FirstX: {FirstX.ToString()} - FirstY: {FirstY.ToString()} - FirstZ: {FirstZ.ToString()} - SecondX: {SecondX.ToString()} - SecondY: {SecondY.ToString()} - SecondZ: {SecondZ.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

