  public void PolygonStar(
    double BaseX,
    double BaseY,
    double BaseZ,
    double FirstX,
    double FirstY,
    double FirstZ,
    double SecondX,
    double SecondY,
    double SecondZ,
    WorkPlane Plane,
    int Slice,
    ref List<double> VerticeX,
    ref List<double> VerticeY,
    ref List<double> VerticeZ)
  {
    try
    {
      VerticeX.Clear();
      VerticeY.Clear();
      VerticeZ.Clear();
      if (Slice < 3)
        Slice = 3;
      if (WorkPlane.isPlaneXY(Plane))
      {
        double num1 = Math.Sqrt(Math.Pow(FirstX - BaseX, 2.0) + Math.Pow(FirstY - BaseY, 2.0));
        double num2 = Math.Sqrt(Math.Pow(SecondX - BaseX, 2.0) + Math.Pow(SecondY - BaseY, 2.0));
        double num3 = 360.0 / (double) Slice;
        double num4 = this.PointAngle(FirstX, FirstY, BaseX, BaseY);
        VerticeX.Add(BaseX + num1 * Math.Cos(buConversion.DegreeToRadian(num4 + 0.0 * num3)));
        VerticeY.Add(BaseY + num1 * Math.Sin(buConversion.DegreeToRadian(num4 + 0.0 * num3)));
        VerticeZ.Add(BaseZ);
        for (int index = 0; index <= Slice - 1; ++index)
        {
          VerticeX.Add(BaseX + num2 * Math.Cos(buConversion.DegreeToRadian(num4 + num3 / 2.0 + (double) index * num3)));
          VerticeY.Add(BaseY + num2 * Math.Sin(buConversion.DegreeToRadian(num4 + num3 / 2.0 + (double) index * num3)));
          VerticeZ.Add(BaseZ);
          VerticeX.Add(BaseX + num1 * Math.Cos(buConversion.DegreeToRadian(num4 + (double) (index + 1) * num3)));
          VerticeY.Add(BaseY + num1 * Math.Sin(buConversion.DegreeToRadian(num4 + (double) (index + 1) * num3)));
          VerticeZ.Add(BaseZ);
        }
      }
      if (Plane.PlaneType == planeType.XZ)
      {
        double num5 = Math.Sqrt(Math.Pow(FirstX - BaseX, 2.0) + Math.Pow(FirstZ - BaseZ, 2.0));
        double num6 = Math.Sqrt(Math.Pow(SecondX - BaseX, 2.0) + Math.Pow(SecondZ - BaseZ, 2.0));
        double num7 = 360.0 / (double) Slice;
        double num8 = this.PointAngle(FirstX, FirstZ, BaseX, BaseZ);
        VerticeX.Add(BaseX + num5 * Math.Cos(buConversion.DegreeToRadian(num8 + 0.0 * num7)));
        VerticeY.Add(BaseY);
        VerticeZ.Add(BaseZ + num5 * Math.Sin(buConversion.DegreeToRadian(num8 + 0.0 * num7)));
        for (int index = 0; index <= Slice - 1; ++index)
        {
          VerticeX.Add(BaseX + num6 * Math.Cos(buConversion.DegreeToRadian(num8 + num7 / 2.0 + (double) index * num7)));
          VerticeY.Add(BaseY);
          VerticeZ.Add(BaseZ + num6 * Math.Sin(buConversion.DegreeToRadian(num8 + num7 / 2.0 + (double) index * num7)));
          VerticeX.Add(BaseX + num5 * Math.Cos(buConversion.DegreeToRadian(num8 + (double) (index + 1) * num7)));
          VerticeY.Add(BaseY);
          VerticeZ.Add(BaseZ + num5 * Math.Sin(buConversion.DegreeToRadian(num8 + (double) (index + 1) * num7)));
        }
      }
      if (Plane.PlaneType != planeType.YZ)
        return;
      double num9 = Math.Sqrt(Math.Pow(FirstY - BaseY, 2.0) + Math.Pow(FirstZ - BaseZ, 2.0));
      double num10 = Math.Sqrt(Math.Pow(SecondY - BaseY, 2.0) + Math.Pow(SecondZ - BaseZ, 2.0));
      double num11 = 360.0 / (double) Slice;
      double num12 = this.PointAngle(FirstY, FirstZ, BaseY, BaseZ);
      VerticeX.Add(BaseX);
      VerticeY.Add(BaseY + num9 * Math.Cos(buConversion.DegreeToRadian(num12 + 0.0 * num11)));
      VerticeZ.Add(BaseZ + num9 * Math.Sin(buConversion.DegreeToRadian(num12 + 0.0 * num11)));
      for (int index = 0; index <= Slice - 1; ++index)
      {
        VerticeX.Add(BaseX);
        VerticeY.Add(BaseY + num10 * Math.Cos(buConversion.DegreeToRadian(num12 + num11 / 2.0 + (double) index * num11)));
        VerticeZ.Add(BaseZ + num10 * Math.Sin(buConversion.DegreeToRadian(num12 + num11 / 2.0 + (double) index * num11)));
        VerticeX.Add(BaseX);
        VerticeY.Add(BaseY + num9 * Math.Cos(buConversion.DegreeToRadian(num12 + (double) (index + 1) * num11)));
        VerticeZ.Add(BaseZ + num9 * Math.Sin(buConversion.DegreeToRadian(num12 + (double) (index + 1) * num11)));
      }
    }
    catch (Exception ex)
    {
      string str = $"BaseX: {BaseX.ToString()} - BaseY: {BaseY.ToString()} - BaseZ: {BaseZ.ToString()} - FirstX: {FirstX.ToString()} - FirstY: {FirstY.ToString()} - FirstZ: {FirstZ.ToString()} - SecondX: {SecondX.ToString()} - SecondY: {SecondY.ToString()} - SecondZ: {SecondZ.ToString()} - Slice: {Slice.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

