  public void PolygonTriangleTwin(
    Pnt3D BasePoint,
    double Width,
    double Height,
    WorkPlane Plane,
    ref List<Pnt3D> Vertices)
  {
    try
    {
      if (WorkPlane.isPlaneXY(Plane))
      {
        Vertices.Clear();
        Vertices.Add(new Pnt3D(BasePoint));
        Vertices.Add(new Pnt3D(BasePoint.X + Width / 2.0, BasePoint.Y, BasePoint.Z));
        Vertices.Add(new Pnt3D(BasePoint.X, BasePoint.Y + Height, BasePoint.Z));
        Vertices.Add(new Pnt3D(BasePoint.X - Width / 2.0, BasePoint.Y, BasePoint.Z));
        Vertices.Add(new Pnt3D(BasePoint));
      }
      if (WorkPlane.isPlaneXZ(Plane))
      {
        Vertices.Clear();
        Vertices.Add(new Pnt3D(BasePoint));
        Vertices.Add(new Pnt3D(BasePoint.X + Width / 2.0, BasePoint.Y, BasePoint.Z));
        Vertices.Add(new Pnt3D(BasePoint.X, BasePoint.Y, BasePoint.Z + Height));
        Vertices.Add(new Pnt3D(BasePoint.X - Width / 2.0, BasePoint.Y, BasePoint.Z));
        Vertices.Add(new Pnt3D(BasePoint));
      }
      if (!WorkPlane.isPlaneYZ(Plane))
        return;
      Vertices.Clear();
      Vertices.Add(new Pnt3D(BasePoint));
      Vertices.Add(new Pnt3D(BasePoint.X, BasePoint.Y + Width / 2.0, BasePoint.Z));
      Vertices.Add(new Pnt3D(BasePoint.X, BasePoint.Y, BasePoint.Z + Height));
      Vertices.Add(new Pnt3D(BasePoint.X, BasePoint.Y - Width / 2.0, BasePoint.Z));
      Vertices.Add(new Pnt3D(BasePoint));
    }
    catch (Exception ex)
    {
      string str = $"BasePoint: {BasePoint.ToString()} - Width: {Width.ToString()} - Height: {Height.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

