  public void Trapezoid(
    Pnt3D StartPoint,
    double Length,
    double Width,
    double FirstAngle,
    double SecondAngle,
    WorkPlane Plane,
    ref List<Pnt3D> Vertices)
  {
    try
    {
      double Length1 = Width;
      double num1 = Width;
      double num2 = Width;
      Pnt3D pnt3D1 = new Pnt3D();
      Pnt3D pnt3D2 = new Pnt3D();
      if (FirstAngle < 90.0)
      {
        double num3 = Width / Math.Cos(buConversion.DegreeToRadian(FirstAngle));
        num1 = Math.Tan(buConversion.DegreeToRadian(FirstAngle)) * Width;
      }
      if (SecondAngle < 90.0)
      {
        Length1 = Width / Math.Cos(buConversion.DegreeToRadian(SecondAngle));
        num2 = Math.Tan(buConversion.DegreeToRadian(SecondAngle)) * Width;
      }
      if (FirstAngle == 90.0)
        num1 = 0.0;
      if (SecondAngle == 90.0)
        num2 = 0.0;
      Vertices.Clear();
      Pnt3D Pnt = new Pnt3D(StartPoint);
      Vertices.Add(new Pnt3D(Pnt));
      Pnt3D pnt3D3 = new Pnt3D(new Pnt3D(StartPoint));
      pnt3D3.X += Length;
      Vertices.Add(new Pnt3D(pnt3D3));
      Pnt3D BasePnt1 = new Pnt3D();
      Pnt3D EndPnt1 = new Pnt3D();
      this.LineWithLengthAndAngle(pnt3D3, Length1, 180.0 + SecondAngle, Plane, ref BasePnt1, ref EndPnt1);
      Vertices.Add(new Pnt3D(EndPnt1));
      Pnt3D CenterPnt = new Pnt3D(new Pnt3D(EndPnt1));
      Pnt3D BasePnt2 = new Pnt3D();
      Pnt3D EndPnt2 = new Pnt3D();
      this.LineWithLengthAndAngle(CenterPnt, Length - num1 - num2, 180.0, Plane, ref BasePnt2, ref EndPnt2);
      Vertices.Add(new Pnt3D(EndPnt2));
      Vertices.Add(new Pnt3D(StartPoint));
    }
    catch (Exception ex)
    {
      string str = $"StartPoint: {StartPoint.ToString()} - Length: {Length.ToString()} - Width: {Width.ToString()} - FirstAngle: {FirstAngle.ToString()} - SecondAngle: {SecondAngle.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

