  public ClockDirectionType PolygonDirection(
    List<Pnt3D> Vertices,
    WorkPlane Plane,
    ref double TotalArea)
  {
    try
    {
      double num1 = 0.0;
      double num2 = 0.0;
      List<Pnt3D> CopiedPnt = new List<Pnt3D>();
      Pnt3D.Copy(Vertices, ref CopiedPnt);
      if (!this.IsClosed(CopiedPnt))
        CopiedPnt.Add(new Pnt3D(Vertices[0]));
      if (WorkPlane.isPlaneXY(Plane))
      {
        for (int index = 1; index <= CopiedPnt.Count - 1; ++index)
        {
          double num3 = CopiedPnt[index].X - CopiedPnt[index - 1].X;
          double num4 = CopiedPnt[index].Y + CopiedPnt[index - 1].Y;
          num1 += (CopiedPnt[index].X - CopiedPnt[index - 1].X) * (CopiedPnt[index].Y + CopiedPnt[index - 1].Y) / 2.0;
          num2 += (CopiedPnt[index - 1].X * CopiedPnt[index].Y - CopiedPnt[index].X * CopiedPnt[index - 1].Y) / 2.0;
        }
      }
      if (WorkPlane.isPlaneXZ(Plane))
      {
        for (int index = 1; index <= CopiedPnt.Count - 1; ++index)
          num1 += (CopiedPnt[index].X - CopiedPnt[index - 1].X) * (CopiedPnt[index].Z + CopiedPnt[index - 1].Z) / 2.0;
      }
      if (WorkPlane.isPlaneYZ(Plane))
      {
        for (int index = 1; index <= CopiedPnt.Count - 1; ++index)
          num1 += (CopiedPnt[index].Y - CopiedPnt[index - 1].Y) * (CopiedPnt[index].Z + CopiedPnt[index - 1].Z) / 2.0;
      }
      TotalArea = num1;
      return num1 > 0.0 ? ClockDirectionType.CW : ClockDirectionType.CCW;
    }
    catch (Exception ex)
    {
      string str = $"Vertices: {Vertices.Count.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return ClockDirectionType.CW;
    }
  }

  public double PolygonArea(List<Pnt3D> Vertices, WorkPlane Plane)
  {
    try
    {
      double num = 0.0;
      if (WorkPlane.isPlaneXY(Plane))
      {
        for (int index = 1; index <= Vertices.Count - 1; ++index)
          num += (Vertices[index].X - Vertices[index - 1].X) * (Vertices[index].Y + Vertices[index - 1].Y) / 2.0;
      }
      if (WorkPlane.isPlaneXZ(Plane))
      {
        for (int index = 1; index <= Vertices.Count - 1; ++index)
          num += (Vertices[index].X - Vertices[index - 1].X) * (Vertices[index].Z + Vertices[index - 1].Z) / 2.0;
      }
      if (WorkPlane.isPlaneYZ(Plane))
      {
        for (int index = 1; index <= Vertices.Count - 1; ++index)
          num += (Vertices[index].Y - Vertices[index - 1].Y) * (Vertices[index].Z + Vertices[index - 1].Z) / 2.0;
      }
      return Math.Abs(num);
    }
    catch (Exception ex)
    {
      string str = $"Vertices: {Vertices.Count.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return 0.0;
    }
  }

  public bool PolygonIsConvex(List<Pnt3D> Vertices)
  {
    bool flag1 = false;
    bool flag2 = false;
    bool flag3;
    for (int index1 = 0; index1 < Vertices.Count - 1; ++index1)
    {
      int index2 = (index1 + 1) % Vertices.Count;
      int index3 = (index2 + 1) % Vertices.Count;
      double num = this.CrossProductLength(Vertices[index1].X, Vertices[index1].Y, Vertices[index2].X, Vertices[index2].Y, Vertices[index3].X, Vertices[index3].Y);
      if (num < 0.0)
        flag1 = true;
      else if (num > 0.0)
        flag2 = true;
      if (flag1 & flag2)
      {
        flag3 = false;
        goto label_10;
      }
    }
    flag3 = true;
label_10:
    return flag3;
  }

  public double CrossProductLength(Pnt3D PA, Pnt3D PB, Pnt3D PC)
  {
    return this.CrossProductLength(PA.X, PA.Y, PB.X, PB.Y, PC.X, PC.Y);
  }

  public double CrossProductLength(
    double Ax,
    double Ay,
    double Bx,
    double By,
    double Cx,
    double Cy)
  {
    double num1 = Ax - Bx;
    double num2 = Ay - By;
    double num3 = Cx - Bx;
    double num4 = Cy - By;
    return num1 * num4 - num2 * num3;
  }

