  public void EllipseArcWithCenter(
    Pnt3D Center,
    double MajorRadius,
    double MinorRadius,
    double StartAngle,
    double EndAngle,
    double Angle,
    WorkPlane Plane,
    EntityResolution EntResolution,
    ref List<Pnt3D> Vertices)
  {
    try
    {
      double num1 = 0.0;
      double Degree1 = StartAngle;
      double Degree2 = EndAngle;
      int num2 = this.EllipseVerticeCountByResolution(MajorRadius, MinorRadius, EntResolution);
      if (num2 < 10)
        num2 = 10;
      double radianGreat360_1 = buConversion.DegreeToRadianGreat360((Degree2 - Degree1) / (double) num2);
      Vertices.Clear();
      if (WorkPlane.isPlaneXY(Plane))
      {
        double num3 = (360.0 - Angle) * Math.PI / 180.0;
        double num4 = Math.Sin(num3);
        double num5 = Math.Cos(num3);
        num1 = buConversion.DegreeToRadianGreat360(Degree1);
        for (int index = 0; index <= num2 - 1; ++index)
        {
          Pnt3D pnt3D = new Pnt3D();
          double num6 = Convert.ToDouble(index) * radianGreat360_1;
          double num7 = MajorRadius * Math.Cos(num6);
          double num8 = MinorRadius * Math.Sin(num6);
          pnt3D.X = Center.X + num7 * num5 + num8 * num4;
          pnt3D.Y = Center.Y - num7 * num4 + num8 * num5;
          pnt3D.Z = Center.Z;
          Vertices.Add(pnt3D);
        }
      }
      if (Plane.PlaneType == planeType.XZ)
      {
        double num9 = (360.0 - Angle) * Math.PI / 180.0;
        double num10 = Math.Sin(num9);
        double num11 = Math.Cos(num9);
        num1 = buConversion.DegreeToRadianGreat360(Degree1);
        for (double radianGreat360_2 = buConversion.DegreeToRadianGreat360(Degree1); radianGreat360_2 <= buConversion.DegreeToRadianGreat360(Degree2); radianGreat360_2 += radianGreat360_1)
        {
          Pnt3D pnt3D = new Pnt3D();
          double num12 = radianGreat360_2;
          double num13 = MajorRadius * Math.Cos(num12);
          double num14 = MinorRadius * Math.Sin(num12);
          pnt3D.X = Center.X + num13 * num11 + num14 * num10;
          pnt3D.Y = Center.Y;
          pnt3D.Z = Center.Z - num13 * num10 + num14 * num11;
          Vertices.Add(pnt3D);
        }
      }
      if (Plane.PlaneType == planeType.YZ)
      {
        double num15 = (360.0 - Angle) * Math.PI / 180.0;
        double num16 = Math.Sin(num15);
        double num17 = Math.Cos(num15);
        num1 = buConversion.DegreeToRadianGreat360(Degree1);
        for (double radianGreat360_3 = buConversion.DegreeToRadianGreat360(Degree1); radianGreat360_3 <= buConversion.DegreeToRadianGreat360(Degree2); radianGreat360_3 += radianGreat360_1)
        {
          Pnt3D pnt3D = new Pnt3D();
          double num18 = radianGreat360_3;
          double num19 = MajorRadius * Math.Cos(num18);
          double num20 = MinorRadius * Math.Sin(num18);
          pnt3D.X = Center.X;
          pnt3D.Y = Center.Y + num19 * num17 + num20 * num16;
          pnt3D.Z = Center.Z - num19 * num16 + num20 * num17;
          Vertices.Add(pnt3D);
        }
      }
      if (!buCompare.EQ(EndAngle - StartAngle, 360.0) || buCompare.EQ(Vertices[0], Vertices[Vertices.Count - 1]) || Vertices.Count <= 0)
        return;
      Vertices.Add(new Pnt3D(Vertices[0]));
    }
    catch (Exception ex)
    {
      string str = $"Center: {Center.ToString()} - Major Rad: {MajorRadius.ToString()} - Minor Rad: {MinorRadius.ToString()} - SA: {StartAngle.ToString()} - EA: {EndAngle.ToString()} - Angle: {Angle.ToString()} - Plane: {Plane.ToString()} - EntResolution: {EntResolution.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

