  public int EllipseArcVerticeCountByResolution(
    double MajorRadius,
    double MinorRadius,
    double StartAngle,
    double EndAngle,
    EntityResolution EntResolution)
  {
    try
    {
      int num1 = 10;
      if (EntResolution.ResolutionTypes == EntityResolutionType.ByNumber)
      {
        num1 = EntResolution.GeometricCount;
        if (num1 < EntResolution.MinPointCount)
          num1 = EntResolution.MinPointCount;
      }
      if (EntResolution.ResolutionTypes == EntityResolutionType.ByLength)
      {
        num1 = Convert.ToInt32(this.EllipseCircumference(MajorRadius, MinorRadius) / EntResolution.GeometricLength * ((EndAngle - StartAngle) / 360.0));
        if (num1 < EntResolution.MinPointCount)
          num1 = EntResolution.MinPointCount;
      }
      if (EntResolution.ResolutionTypes == EntityResolutionType.ByLnRadius)
      {
        double num2 = MajorRadius;
        if (MinorRadius < MajorRadius)
          num2 = MinorRadius;
        if (num2 > 0.0)
          num1 = Convert.ToInt32(Math.Log(Math.Abs(num2), Math.E) * EntResolution.LnRatio * ((EndAngle - StartAngle) / 360.0));
        if (num1 < EntResolution.MinPointCount)
          num1 = EntResolution.MinPointCount;
      }
      return num1;
    }
    catch (Exception ex)
    {
      string str = $"Major R: {MajorRadius.ToString()} - Minor R: {MinorRadius.ToString()} - Entitiy Res: {EntResolution.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return -1;
    }
  }

