  public void EllipseMajorDiameterLine(
    Pnt3D Center,
    double MajorRadius,
    double Angle,
    Pnt3D ActivePoint,
    ref Pnt3D FirstPoint,
    ref Pnt3D SecondPoint)
  {
    try
    {
      if (MajorRadius <= 0.0)
        return;
      double Angle1 = Angle;
      Pnt3D BasePnt = new Pnt3D();
      Pnt3D EndPnt = new Pnt3D();
      this.LineWithLengthAndAngle(Center, MajorRadius, Angle1, new WorkPlane(), ref BasePnt, ref EndPnt);
      this.LineWithLengthAndAngle(EndPnt, MajorRadius * 2.0, Angle1 + 180.0, new WorkPlane(), ref FirstPoint, ref SecondPoint);
    }
    catch (Exception ex)
    {
      string str = $"Center: {Center.ToString()} - MajorRadius: {MajorRadius.ToString()} - Angle: {Angle.ToString()} - ActivePoint: {ActivePoint.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

