  public double EllipseAngle(
    Pnt3D CenterPoint,
    double MajorRadius,
    double MinorRadius,
    Pnt3D RefPoint,
    WorkPlane Plane)
  {
    try
    {
      double num1 = 0.0;
      double x1 = 0.0;
      double y1 = 0.0;
      double x2 = 0.0;
      double y2 = 0.0;
      int ClosestPoint = 0;
      if (WorkPlane.isPlaneXY(Plane))
      {
        if (CenterPoint.X != RefPoint.X)
