  public double EllipseArea(double MajorRadius, double MinorRadius)
  {
    try
    {
      return Math.PI * MajorRadius * MinorRadius;
    }
    catch (Exception ex)
    {
      string str = $"Major R: {MajorRadius.ToString()} - Minor R: {MinorRadius.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return 0.0;
    }
  }

  public double EllipseCircumference(double MajorRadius, double MinorRadius)
  {
    try
    {
      return Math.Sqrt((MajorRadius * MajorRadius + MinorRadius * MinorRadius) * 0.5) * Math.PI * 2.0;
    }
    catch (Exception ex)
    {
      string str = $"Major R: {MajorRadius.ToString()} - Minor R: {MinorRadius.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return 0.0;
    }
  }

  public double ArcEllipseArea(
    double MajorRadius,
    double MinorRadius,
    double StartAngle,
    double EndAngle)
  {
    try
    {
      return Math.PI * MajorRadius * MinorRadius * (EndAngle - StartAngle) / 360.0;
    }
    catch (Exception ex)
    {
      string str = $"Major R: {MajorRadius.ToString()} - Minor R: {MinorRadius.ToString()}- SA: {StartAngle.ToString()} - EA: {EndAngle.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return 0.0;
    }
  }

  public double ArcEllipseCircumference(
    double MajorRadius,
    double MinorRadius,
    double StartAngle,
    double EndAngle)
  {
    try
    {
      return Math.Sqrt((MajorRadius * MajorRadius + MinorRadius * MinorRadius) * 0.5) * Math.PI * 2.0 * (EndAngle - StartAngle) / 360.0;
    }
    catch (Exception ex)
    {
      string str = $"Major R: {MajorRadius.ToString()} - Minor R: {MinorRadius.ToString()}- SA: {StartAngle.ToString()} - EA: {EndAngle.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return 0.0;
    }
  }

  public void EllipseRadiusByAngle(
    double MajorRadius,
    double MinorRadius,
    double Angle,
    ref double CalcRadius)
  {
    string callMethod = nameof (EllipseRadiusByAngle);
    try
    {
      CalcRadius = MajorRadius * MinorRadius / Math.Sqrt(Math.Pow(MajorRadius * Math.Sin(buConversion.DegreeToRadian(Angle)), 2.0) + Math.Pow(MinorRadius * Math.Cos(buConversion.DegreeToRadian(Angle)), 2.0));
    }
    catch (Exception ex)
    {
      string str = $"MajorRadius: {MajorRadius.ToString()}- MinorRadius: {MinorRadius.ToString()}- Angle: {Angle.ToString()}";
      buLog.addLog(str, "Not Ok", callMethod);
      buException.throwException(ex, callMethod, false, str);
    }
  }

