        Pnt3D EndPnt = new Pnt3D();
        Pnt3D BasePnt = new Pnt3D();
        this.LineWithLengthAndAngle(HeadPosition, Length, Angle + num1, Plane, ref BasePnt, ref EndPnt);
        double StartAngle4 = 270.0 + Angle + num1;
        double EndAngle4 = 450.0 + Angle + num1;
        if (StartAngle4 > 360.0 & EndAngle4 > 360.0)
        {
          StartAngle4 -= 360.0;
          EndAngle4 -= 360.0;
        }
        TaleArc = new eArc(new Pnt3D(EndPnt), TaleRadius, StartAngle4, EndAngle4, Plane);
        return true;
      }
      if (!WorkPlane.isPlaneYZ(Plane))
        return true;
      double num10 = HeadPosition.Z + TaleRadius;
      double num11 = Math.Sqrt(Math.Pow(HeadRadius, 2.0) - Math.Pow(HeadPosition.Z - num10, 2.0));
      double num12 = HeadPosition.Y + num11;
      double degree1 = buConversion.RadianToDegree(Math.Atan((num10 - HeadPosition.Z) / (num12 - HeadPosition.Y)));
      double num13 = 360.0 - degree1;
      double StartAngle5 = degree1 + Angle + num1;
      double EndAngle5 = num13 + Angle + num1;
      if (StartAngle5 > 360.0 & EndAngle5 > 360.0)
      {
        StartAngle5 -= 360.0;
        EndAngle5 -= 360.0;
      }
      HeadArc = new eArc(new Pnt3D(HeadPosition), HeadRadius, StartAngle5, EndAngle5, Plane);
      Pnt3D EndPnt1 = new Pnt3D();
      Pnt3D BasePnt1 = new Pnt3D();
      this.LineWithLengthAndAngle(HeadPosition, Length + num1, Angle, Plane, ref BasePnt1, ref EndPnt1);
      double StartAngle6 = 270.0 + Angle + num1;
      double EndAngle6 = 450.0 + Angle + num1;
      if (StartAngle6 > 360.0 & EndAngle6 > 360.0)
      {
        StartAngle6 -= 360.0;
        EndAngle6 -= 360.0;
      }
      TaleArc = new eArc(new Pnt3D(EndPnt1), TaleRadius, StartAngle6, EndAngle6, Plane);
      return true;
    }
    catch (Exception ex)
    {
      string str = $"HeadPosition: {HeadPosition.ToString()} - HeadRadius: {HeadRadius.ToString()} - TaleRadius: {TaleRadius.ToString()} - Length: {Length.ToString()} - Angle: {Angle.ToString()} - Plane: {Plane.ToString()} - EntResolution: {EntResolution.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return false;
    }
  }

  public bool Barrel(
