  public void HermiteCubicSplineWithStartEndVector(
    List<Pnt3D> ControlPoints,
    double dt,
    double Multiply,
    double Offset,
    Vec3D StartVector,
    Vec3D EndVector,
    ref List<Pnt3D> CalculatedPoints)
  {
    try
    {
      Pnt3D pnt3D1 = new Pnt3D();
      double num1 = 2.0;
      double num2 = -2.0;
      double num3 = 1.0;
      double num4 = 1.0;
      double num5 = -3.0;
      double num6 = 3.0;
      double num7 = -2.0;
      double num8 = -1.0;
      double num9 = 0.0;
      double num10 = 0.0;
      double num11 = 1.0;
      double num12 = 0.0;
      double num13 = 1.0;
      double num14 = 0.0;
      double num15 = 0.0;
      double num16 = 0.0;
      double num17 = 0.0;
      double num18 = 0.0;
      double num19 = 0.0;
      double num20 = 0.0;
      double num21 = 0.0;
      double num22 = 0.0;
      double num23 = 0.0;
      CalculatedPoints.Clear();
      int int32 = Convert.ToInt32(1.0 / dt);
      for (int index1 = 0; index1 <= ControlPoints.Count - 2; ++index1)
      {
        if (ControlPoints.Count > 2)
        {
          if (index1 == 0)
          {
            num23 = (180.0 - this.AngleOfTwoLines(ControlPoints[index1], ControlPoints[index1 + 1], ControlPoints[index1 + 1], ControlPoints[index1 + 2], new WorkPlane())) / 2.0;
            double num24 = this.PointAngle(ControlPoints[index1], ControlPoints[index1 + 1]);
            double num25 = this.PointAngle(ControlPoints[index1 + 2], ControlPoints[index1 + 1]);
            double num26 = (num24 + num25) / 2.0;
            double Degree = (num25 <= num24 ? num26 - 90.0 : num26 + 90.0) + Offset;
            num17 = StartVector.X;
            num19 = StartVector.Y;
            double num27 = Math.Abs(this.DeltaX(ControlPoints[index1 + 1], ControlPoints[index1])) * Multiply;
            double num28 = Math.Abs(this.DeltaY(ControlPoints[index1 + 1], ControlPoints[index1])) * Multiply;
            double num29 = Math.Abs(this.DeltaZ(ControlPoints[index1 + 1], ControlPoints[index1])) * Multiply;
            num18 = num27 * Math.Cos(buConversion.DegreeToRadian(Degree));
            num20 = num28 * Math.Sin(buConversion.DegreeToRadian(Degree));
            num22 = num29 * Math.Cos(buConversion.DegreeToRadian(Degree));
          }
          if (index1 > 0 & index1 < ControlPoints.Count - 2)
          {
            num23 = (180.0 - this.AngleOfTwoLines(ControlPoints[index1], ControlPoints[index1 + 1], ControlPoints[index1 + 1], ControlPoints[index1 + 2], new WorkPlane())) / 2.0;
            double num30 = this.PointAngle(ControlPoints[index1], ControlPoints[index1 + 1]);
            double num31 = this.PointAngle(ControlPoints[index1 + 2], ControlPoints[index1 + 1]);
            double num32 = (num30 + num31) / 2.0;
            double Degree = (num31 <= num30 ? num32 - 90.0 : num32 + 90.0) + Offset;
            double num33 = Math.Abs(this.DeltaX(ControlPoints[index1 + 1], ControlPoints[index1])) * Multiply;
            double num34 = Math.Abs(this.DeltaY(ControlPoints[index1 + 1], ControlPoints[index1])) * Multiply;
            double num35 = Math.Abs(this.DeltaZ(ControlPoints[index1 + 1], ControlPoints[index1])) * Multiply;
            num18 = num33 * Math.Cos(buConversion.DegreeToRadian(Degree));
            num20 = num34 * Math.Sin(buConversion.DegreeToRadian(Degree));
            num22 = num35 * Math.Cos(buConversion.DegreeToRadian(Degree));
          }
          if (index1 == ControlPoints.Count - 2)
          {
            num18 = EndVector.X;
            num20 = EndVector.Y;
            num22 = EndVector.Z;
          }
        }
        else
        {
          num17 = StartVector.X;
          num19 = StartVector.Y;
          num21 = StartVector.Z;
          num18 = EndVector.X;
          num20 = EndVector.Y;
          num22 = EndVector.Z;
        }
        for (int index2 = 0; index2 <= int32; ++index2)
        {
          Pnt3D pnt3D2 = new Pnt3D();
          double x1 = (double) index2 * dt;
          double x2 = ControlPoints[index1].X;
          double x3 = ControlPoints[index1 + 1].X;
          double num36 = num17;
          double num37 = num18;
          double num38 = (Math.Pow(x1, 3.0) * num1 + Math.Pow(x1, 2.0) * num5 + x1 * num9 + num13) * x2;
          double num39 = (Math.Pow(x1, 3.0) * num2 + Math.Pow(x1, 2.0) * num6 + x1 * num10 + num14) * x3;
          double num40 = (Math.Pow(x1, 3.0) * num3 + Math.Pow(x1, 2.0) * num7 + x1 * num11 + num15) * num36;
          double num41 = (Math.Pow(x1, 3.0) * num4 + Math.Pow(x1, 2.0) * num8 + x1 * num12 + num16) * num37;
          pnt3D2.X = num38 + num39 + num40 + num41;
          double y1 = ControlPoints[index1].Y;
          double y2 = ControlPoints[index1 + 1].Y;
          double num42 = num19;
          double num43 = num20;
          double num44 = (Math.Pow(x1, 3.0) * num1 + Math.Pow(x1, 2.0) * num5 + x1 * num9 + num13) * y1;
          double num45 = (Math.Pow(x1, 3.0) * num2 + Math.Pow(x1, 2.0) * num6 + x1 * num10 + num14) * y2;
          double num46 = (Math.Pow(x1, 3.0) * num3 + Math.Pow(x1, 2.0) * num7 + x1 * num11 + num15) * num42;
          double num47 = (Math.Pow(x1, 3.0) * num4 + Math.Pow(x1, 2.0) * num8 + x1 * num12 + num16) * num43;
          pnt3D2.Y = num44 + num45 + num46 + num47;
          double z1 = ControlPoints[index1].Z;
          double z2 = ControlPoints[index1 + 1].Z;
          double num48 = num21;
          double num49 = num22;
          double num50 = (Math.Pow(x1, 3.0) * num1 + Math.Pow(x1, 2.0) * num5 + x1 * num9 + num13) * z1;
          double num51 = (Math.Pow(x1, 3.0) * num2 + Math.Pow(x1, 2.0) * num6 + x1 * num10 + num14) * z2;
          double num52 = (Math.Pow(x1, 3.0) * num3 + Math.Pow(x1, 2.0) * num7 + x1 * num11 + num15) * num48;
          double num53 = (Math.Pow(x1, 3.0) * num4 + Math.Pow(x1, 2.0) * num8 + x1 * num12 + num16) * num49;
          pnt3D2.Z = num50 + num51 + num52 + num53;
          CalculatedPoints.Add(pnt3D2);
        }
        num17 = num18;
        num19 = num20;
        num21 = num22;
      }
    }
    catch (Exception ex)
    {
      string str = $"ControlPoints: {ControlPoints.Count.ToString()} - dt: {dt.ToString()} - Multiply: {Multiply.ToString()} - Offset: {Offset.ToString()} - StartVector: {StartVector.ToString()} - EndVector: {EndVector.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void BezeirCurve(List<Pnt3D> ControlPoints, double dt, ref List<Pnt3D> CalculatedPoints)
  {
    try
    {
      Pnt3D pnt3D1 = new Pnt3D();
      if (ControlPoints.Count <= 1)
        return;
      if (dt <= 0.0)
        dt = 0.1;
      dt /= (double) ControlPoints.Count;
      CalculatedPoints.Clear();
      int int32 = Convert.ToInt32(1.0 / dt);
      int n = ControlPoints.Count - 1;
      for (int index1 = 0; index1 <= int32; ++index1)
      {
        Pnt3D pnt3D2 = new Pnt3D();
        double t = (double) index1 * dt;
        double num1 = 0.0;
        double num2 = 0.0;
        double num3 = 0.0;
        for (int index2 = 0; index2 <= ControlPoints.Count - 1; ++index2)
        {
          buVector.BezeirBlend(n, index2, t);
          num1 += ControlPoints[index2].X * buVector.BezeirBlend(n, index2, t);
          num2 += ControlPoints[index2].Y * buVector.BezeirBlend(n, index2, t);
          num3 += ControlPoints[index2].Z * buVector.BezeirBlend(n, index2, t);
        }
        pnt3D2.X = num1;
        pnt3D2.Y = num2;
        pnt3D2.Z = num3;
        CalculatedPoints.Add(pnt3D2);
      }
    }
    catch (Exception ex)
    {
      string str = $"ControlPoints: {ControlPoints.Count.ToString()} - dt: {dt.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void SplineCubicUniform(
    List<Pnt3D> ControlPoints,
    double dt,
    ref List<Pnt3D> CalculatedPoints)
  {
    try
    {
      if (dt <= 0.0)
        dt = 0.1;
      CalculatedPoints.Clear();
      double[] x = new double[ControlPoints.Count];
      double[] y = new double[ControlPoints.Count];
      double[] z = new double[ControlPoints.Count];
      int int32 = Convert.ToInt32(1.0 / dt * (double) ControlPoints.Count);
      for (int index = 0; index <= ControlPoints.Count - 1; ++index)
      {
        x[index] = ControlPoints[index].X;
        y[index] = ControlPoints[index].Y;
        z[index] = ControlPoints[index].Z;
      }
      double[] xs;
      double[] ys;
      double[] zs;
      CubicSpline.FitGeometric(x, y, z, int32, out xs, out ys, out zs);
      for (int index = 0; index <= xs.Length - 1; ++index)
        CalculatedPoints.Add(new Pnt3D(xs[index], ys[index], zs[index]));
    }
    catch (Exception ex)
    {
      string str = $"ControlPoints: {ControlPoints.Count.ToString()} - dt: {dt.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public static double BezeirBlend(int n, int i, double t)
  {
    try
    {
      Math.Pow(t, (double) i);
      Math.Pow(1.0 - t, (double) (n - i));
      return buVector.Factorial(n) / (buVector.Factorial(i) * buVector.Factorial(n - i)) * Math.Pow(t, (double) i) * Math.Pow(1.0 - t, (double) (n - i));
    }
    catch (Exception ex)
    {
      string str = $"n: {n.ToString()} - i: {i.ToString()} - t: {t.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return 0.0;
    }
  }

  public static void KnotBSpline(int PointNumber, int Order, List<int> KnotVector)
  {
    try
    {
      int num1 = PointNumber + Order;
      int num2 = PointNumber + 1;
      KnotVector.Clear();
      KnotVector.Add(0);
      for (int index = 1; index <= num1 - 1; ++index)
      {
        if ((index <= Order - 1 ? 0 : (index < num2 ? 1 : 0)) != 0)
          KnotVector.Add(KnotVector[index - 1] + 1);
        else
          KnotVector.Add(KnotVector[index - 1]);
      }
    }
    catch (Exception ex)
    {
      string str = $"PointNumber: {PointNumber.ToString()} - Order: {Order.ToString()} - KnotVector: {KnotVector.Count.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public static void BasisBSpline(
    int Order,
    double Parameter,
    int PointNumber,
    List<int> KnotVector,
    List<double> BasisFunctions)
  {
    List<double> doubleList = new List<double>();
    BasisFunctions.Clear();
    int num1 = PointNumber + Order;
    for (int index = 0; index <= num1 - 2; ++index)
    {
      if ((Parameter < (double) KnotVector[index] ? 0 : (Parameter < (double) KnotVector[index + 1] ? 1 : 0)) != 0)
        doubleList.Add(1.0);
      else
        doubleList.Add(0.0);
    }
    for (int index1 = 2; index1 <= Order; ++index1)
    {
      for (int index2 = 0; index2 <= num1 - index1 - 1; ++index2)
      {
        double num2 = doubleList[index2] == 0.0 ? 0.0 : (Parameter - (double) KnotVector[index2]) * doubleList[index2] / (double) (KnotVector[index2 + index1 - 1] - KnotVector[index2]);
        double num3 = doubleList[index2 + 1] == 0.0 ? 0.0 : ((double) KnotVector[index2 + index1] - Parameter) * doubleList[index2 + 1] / (double) (KnotVector[index2 + index1] - KnotVector[index2 + 1]);
        doubleList[index2] = num2 + num3;
      }
    }
    if (Parameter == (double) KnotVector[num1 - 1])
      doubleList[PointNumber - 1] = 1.0;
    for (int index = 0; index <= PointNumber - 1; ++index)
      BasisFunctions.Add(doubleList[index]);
  }

  public static void BasisRegionalBSpline(
    int Order,
    double Parameter,
    int PointNumber,
    List<int> KnotVector,
    List<double> Weigth,
    List<double> BasisFunctions)
  {
    try
    {
      List<double> doubleList = new List<double>();
      int num1 = PointNumber + Order;
      for (int index = 0; index <= num1 - 2; ++index)
      {
        if ((Parameter < (double) KnotVector[index] ? 0 : (Parameter < (double) KnotVector[index + 1] ? 1 : 0)) != 0)
          doubleList.Add(1.0);
        else
          doubleList.Add(0.0);
      }
      for (int index1 = 2; index1 <= Order; ++index1)
      {
        for (int index2 = 0; index2 <= num1 - index1 - 1; ++index2)
        {
          double num2 = doubleList[index2] == 0.0 ? 0.0 : (Parameter - (double) KnotVector[index2]) * doubleList[index2] / (double) (KnotVector[index2 + index1 - 1] - KnotVector[index2]);
          double num3 = doubleList[index2 + 1] == 0.0 ? 0.0 : ((double) KnotVector[index2 + index1] - Parameter) * doubleList[index2 + 1] / (double) (KnotVector[index2 + index1] - KnotVector[index2 + 1]);
          doubleList[index2] = num2 + num3;
        }
      }
      if (Parameter == (double) KnotVector[num1 - 1])
        doubleList[PointNumber - 1] = 1.0;
      double num4 = 0.0;
      for (int index = 0; index <= PointNumber - 1; ++index)
        num4 += doubleList[index] * Weigth[index];
      for (int index = 0; index <= PointNumber - 1; ++index)
        BasisFunctions[index] = num4 == 0.0 ? 0.0 : doubleList[index] * Weigth[index] / num4;
    }
    catch (Exception ex)
    {
      string str = $"Order: {Order.ToString()} - Parameter: {Parameter.ToString()} - PointNumber: {PointNumber.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public static double SumRegionalBasic(
    int UCount,
    int WCount,
    List<double> NBasis,
    List<double> MBasis,
    List<double> Weigth)
  {
    double num = 0.0;
    for (int index1 = 0; index1 <= UCount - 1; ++index1)
    {
      if (NBasis[index1] != 0.0)
      {
        for (int index2 = 0; index2 <= WCount - 1; ++index2)
        {
          if (MBasis[index2] != 0.0)
            num += Weigth[index2] * NBasis[index1] * MBasis[index2];
        }
      }
    }
    return num;
  }

  public static double Factorial(int Value)
  {
    try
    {
      int num = 1;
      for (int index = 1; index <= Value; ++index)
        num *= index;
      return (double) num;
    }
    catch (Exception ex)
    {
      string str = "Value: " + Value.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return 0.0;
    }
  }

  public void EntityToTriangleIndex(
    eEntities refEnt,
    ref List<Pnt3D> Vertices,
    ref List<TriangleIndex> TriIndex)
  {
    if (!(refEnt.GetType() == typeof (eSurface)))
      return;
    Vertices.Clear();
    TriIndex.Clear();
    if (refEnt.Triangles == null)
      return;
    int num1 = 0;
    for (int index = 0; index <= refEnt.Triangles.Count - 1; ++index)
    {
      TriangleIndex triangleIndex = new TriangleIndex();
      Vertices.Add(new Pnt3D(refEnt.Triangles[index].FirstPoint));
      triangleIndex.V1 = num1;
      int num2 = num1 + 1;
      Vertices.Add(new Pnt3D(refEnt.Triangles[index].FirstPoint));
      triangleIndex.V2 = num2;
      num1 = num2 + 1;
      Vertices.Add(new Pnt3D(refEnt.Triangles[index].FirstPoint));
      triangleIndex.V3 = num1;
      TriIndex.Add(triangleIndex);
    }
  }

