  public void TriangleAtPointByLineRef(
    Pnt3D BasePoint,
    Pnt3D RefPoint,
    double TrianglePointAngle,
    double TriangleLength,
    WorkPlane Plane,
    bool Reverse,
    bool FromBaseLine,
    ref Pnt3D FirstPoint,
    ref Pnt3D SecondPoint,
    ref Pnt3D ThirdPoint)
  {
    try
    {
      Pnt3D BasePnt1 = new Pnt3D();
      Pnt3D EndPnt1 = new Pnt3D();
      double num1 = 0.0;
      Pnt3D pnt3D = new Pnt3D(BasePoint);
      if (Reverse)
        num1 = 180.0;
      double num2 = this.PointAngle(RefPoint, BasePoint);
      if (FromBaseLine)
      {
        num2 = this.PointAngle(BasePoint, RefPoint);
        pnt3D = new Pnt3D(RefPoint);
      }
      this.LineWithLengthAndAngle(pnt3D, TriangleLength, num2 + TrianglePointAngle + num1, Plane, ref BasePnt1, ref EndPnt1);
      FirstPoint = new Pnt3D(pnt3D);
      SecondPoint = new Pnt3D(EndPnt1);
      Pnt3D BasePnt2 = new Pnt3D();
      Pnt3D EndPnt2 = new Pnt3D();
      this.LineWithLengthAndAngle(pnt3D, TriangleLength, num2 - TrianglePointAngle + num1, Plane, ref BasePnt2, ref EndPnt2);
      ThirdPoint = new Pnt3D(EndPnt2);
    }
    catch (Exception ex)
    {
      string str = $"BasePoint: {BasePoint.ToString()} - RefPoint: {RefPoint.ToString()} - TrianglePointAngle: {TrianglePointAngle.ToString()} - TriangleLength: {TriangleLength.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void QuadToTriangle(
    Quad3D Quad,
    ref Triangle3D FirstTriangle,
    ref Triangle3D SecondTriangle)
  {
    try
    {
      Pnt3D pnt3D = new Pnt3D();
      if (this.Length3D(Quad.FirstPoint, Quad.ThirdPoint) > this.Length3D(Quad.SecondPoint, Quad.FourthPoint))
      {
        pnt3D = new Pnt3D();
        Pnt3D Pnt1 = new Pnt3D(Quad.FirstPoint);
        FirstTriangle.FirstPoint = new Pnt3D(Pnt1);
        pnt3D = new Pnt3D();
        Pnt3D Pnt2 = new Pnt3D(Quad.SecondPoint);
        FirstTriangle.SecondPoint = new Pnt3D(Pnt2);
        pnt3D = new Pnt3D();
        Pnt3D Pnt3 = new Pnt3D(Quad.ThirdPoint);
        FirstTriangle.ThirdPoint = new Pnt3D(Pnt3);
        pnt3D = new Pnt3D();
        Pnt3D Pnt4 = new Pnt3D(Quad.FirstPoint);
        SecondTriangle.FirstPoint = new Pnt3D(Pnt4);
        pnt3D = new Pnt3D();
        Pnt3D Pnt5 = new Pnt3D(Quad.ThirdPoint);
        SecondTriangle.SecondPoint = new Pnt3D(Pnt5);
        pnt3D = new Pnt3D();
        Pnt3D Pnt6 = new Pnt3D(Quad.FourthPoint);
        SecondTriangle.ThirdPoint = new Pnt3D(Pnt6);
      }
      else
      {
        pnt3D = new Pnt3D();
        Pnt3D Pnt7 = new Pnt3D(Quad.SecondPoint);
        FirstTriangle.FirstPoint = new Pnt3D(Pnt7);
        pnt3D = new Pnt3D();
        Pnt3D Pnt8 = new Pnt3D(Quad.ThirdPoint);
        FirstTriangle.SecondPoint = new Pnt3D(Pnt8);
        pnt3D = new Pnt3D();
        Pnt3D Pnt9 = new Pnt3D(Quad.FourthPoint);
        FirstTriangle.ThirdPoint = new Pnt3D(Pnt9);
        pnt3D = new Pnt3D();
        Pnt3D Pnt10 = new Pnt3D(Quad.SecondPoint);
        SecondTriangle.FirstPoint = new Pnt3D(Pnt10);
        pnt3D = new Pnt3D();
        Pnt3D Pnt11 = new Pnt3D(Quad.FourthPoint);
        SecondTriangle.SecondPoint = new Pnt3D(Pnt11);
        pnt3D = new Pnt3D();
        Pnt3D Pnt12 = new Pnt3D(Quad.FirstPoint);
        SecondTriangle.ThirdPoint = new Pnt3D(Pnt12);
      }
    }
    catch (Exception ex)
    {
      string str = "Quad: " + Quad.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
