  public double TriangleArea(Triangle3D Triangle)
  {
    try
    {
      Pnt3D pnt3D1 = new Pnt3D();
      Pnt3D pnt3D2 = new Pnt3D();
      Pnt3D pnt3D3 = new Pnt3D();
      pnt3D1.X = Triangle.SecondPoint.X - Triangle.FirstPoint.X;
      pnt3D1.Y = Triangle.SecondPoint.Y - Triangle.FirstPoint.Y;
      pnt3D1.Z = Triangle.SecondPoint.Z - Triangle.FirstPoint.Z;
      pnt3D2.X = Triangle.ThirdPoint.X - Triangle.FirstPoint.X;
      pnt3D2.Y = Triangle.ThirdPoint.Y - Triangle.FirstPoint.Y;
      pnt3D2.Z = Triangle.ThirdPoint.Z - Triangle.FirstPoint.Z;
      pnt3D3.X = pnt3D1.Y * pnt3D2.Z - pnt3D1.Z * pnt3D2.Y;
      pnt3D3.Y = pnt3D1.Z * pnt3D2.X - pnt3D1.X * pnt3D2.Z;
      pnt3D3.Z = pnt3D1.X * pnt3D2.Y - pnt3D1.Y * pnt3D2.X;
      return 0.5 * Math.Sqrt(pnt3D3.X * pnt3D3.X + pnt3D3.Y * pnt3D3.Y + pnt3D3.Z * pnt3D3.Z);
    }
    catch (Exception ex)
    {
      string str = "Triangle: " + Triangle.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return 0.0;
    }
  }

