    catch (Exception ex)
    {
      return 0.0;
    }
  }

  public void DirectionArrowToVertices(
    DirectionArrow arrow,
    WorkPlane Plane,
    double ArrowAngle,
    ref List<Pnt3D> Vertices)
  {
    try
    {
      Pnt3D EndPnt1 = new Pnt3D();
      Pnt3D EndPnt2 = new Pnt3D();
      double num = 0.0;
      if (arrow.Reverse)
        num = 180.0;
      Vertices.Clear();
      this.LineWithLengthAndAngle(arrow.Point, arrow.Length, arrow.Angle + 180.0 + num - ArrowAngle, Plane, ref EndPnt1);
      this.LineWithLengthAndAngle(arrow.Point, arrow.Length, arrow.Angle + 180.0 + num + ArrowAngle, Plane, ref EndPnt2);
      Vertices.Add(EndPnt1);
      Vertices.Add(arrow.Point);
      Vertices.Add(EndPnt2);
    }
    catch (Exception ex)
    {
      string str = $"arrow: {arrow.ToString()} | arrow: {arrow.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public Pnt3D TriangleNormal(Pnt3D FirstPoint, Pnt3D SecondPoint, Pnt3D ThirdPoint)
  {
    try
    {
      Pnt3D pnt3D = new Pnt3D();
      double num1 = SecondPoint.X - FirstPoint.X;
      double num2 = SecondPoint.Y - FirstPoint.Y;
      double num3 = SecondPoint.Z - FirstPoint.Z;
      double num4 = ThirdPoint.X - SecondPoint.X;
