            this.QuadToTriangle(Quad, ref FirstTriangle, ref SecondTriangle);
            Triangles.Add(FirstTriangle);
            Triangles.Add(SecondTriangle);
          }
        }
      }
      if (Vec3D.isVectorYAxis(Vec))
      {
        WorkPlane Plane = new WorkPlane(planeType.XZ, 1);
        this.CircleWithCenter(new Pnt3D(BasePoint.X, BasePoint.Y, BasePoint.Z), BottomRadius, Plane, EntResolution, ref pnt3DList1);
        this.CircleWithCenter(new Pnt3D(BasePoint.X, BasePoint.Y + Length, BasePoint.Z), TopRadius, Plane, EntResolution, ref pnt3DList2);
        Points1 = new Pnt3D(BasePoint.X, BasePoint.Y, BasePoint.Z);
        Points2 = new Pnt3D(BasePoint.X, BasePoint.Y + Length, BasePoint.Z);
        this.Rotate(BasePoint, Angle, Plane, ref pnt3DList1);
        this.Rotate(BasePoint, Angle, Plane, ref pnt3DList2);
        this.Rotate(BasePoint, Angle, Plane, ref Points1);
        this.Rotate(BasePoint, Angle, Plane, ref Points2);
        Vertices.Add(pnt3DList1);
        Vertices.Add(pnt3DList2);
        Entities.Add((eEntities) new eCircle(new Pnt3D(BasePoint.X - Length / 2.0, BasePoint.Y, BasePoint.Z), BottomRadius, Plane));
        Entities.Add((eEntities) new eCircle(new Pnt3D(BasePoint.X + Length / 2.0, BasePoint.Y, BasePoint.Z), TopRadius, Plane));
        for (int index = 0; index <= pnt3DList1.Count - 1; ++index)
        {
          Vertices.Add(new List<Pnt3D>()
          {
            new Pnt3D(pnt3DList1[index]),
            new Pnt3D(pnt3DList2[index])
          });
          eLine eLine = new eLine(new Pnt3D(pnt3DList1[index]), new Pnt3D(pnt3DList2[index]));
          Entities.Add((eEntities) eLine);
          if (index > 0)
          {
            Triangle3D FirstTriangle = new Triangle3D();
            SecondTriangle = new Triangle3D();
            Quad3D Quad = new Quad3D(pnt3DList1[index - 1], pnt3DList2[index - 1], pnt3DList2[index], pnt3DList1[index]);
            Quads.Add(Quad);
            this.QuadToTriangle(Quad, ref FirstTriangle, ref SecondTriangle);
            Triangles.Add(FirstTriangle);
            Triangles.Add(SecondTriangle);
          }
        }
      }
      if (Vec3D.isVectorZAxis(Vec))
      {
        WorkPlane Plane = new WorkPlane(planeType.XY, 1);
        this.CircleWithCenter(new Pnt3D(BasePoint.X, BasePoint.Y, BasePoint.Z), BottomRadius, Plane, EntResolution, ref pnt3DList1);
        this.CircleWithCenter(new Pnt3D(BasePoint.X, BasePoint.Y, BasePoint.Z + Length), TopRadius, Plane, EntResolution, ref pnt3DList2);
        Points1 = new Pnt3D(BasePoint.X, BasePoint.Y, BasePoint.Z);
        Points2 = new Pnt3D(BasePoint.X, BasePoint.Y, BasePoint.Z + Length);
        this.Rotate(BasePoint, Angle, Plane, ref pnt3DList1);
        this.Rotate(BasePoint, Angle, Plane, ref pnt3DList2);
        this.Rotate(BasePoint, Angle, Plane, ref Points1);
        this.Rotate(BasePoint, Angle, Plane, ref Points2);
        Vertices.Add(pnt3DList1);
        Vertices.Add(pnt3DList2);
        Entities.Add((eEntities) new eCircle(new Pnt3D(BasePoint.X - Length / 2.0, BasePoint.Y, BasePoint.Z), BottomRadius, Plane));
        Entities.Add((eEntities) new eCircle(new Pnt3D(BasePoint.X + Length / 2.0, BasePoint.Y, BasePoint.Z), TopRadius, Plane));
        for (int index = 0; index <= pnt3DList1.Count - 1; ++index)
        {
          Vertices.Add(new List<Pnt3D>()
          {
            new Pnt3D(pnt3DList1[index]),
            new Pnt3D(pnt3DList2[index])
          });
          eLine eLine = new eLine(new Pnt3D(pnt3DList1[index]), new Pnt3D(pnt3DList2[index]));
          Entities.Add((eEntities) eLine);
          if (index > 0)
          {
            Triangle3D FirstTriangle = new Triangle3D();
            SecondTriangle = new Triangle3D();
            Quad3D Quad = new Quad3D(pnt3DList1[index - 1], pnt3DList2[index - 1], pnt3DList2[index], pnt3DList1[index]);
            Quads.Add(Quad);
            this.QuadToTriangle(Quad, ref FirstTriangle, ref SecondTriangle);
            Triangles.Add(FirstTriangle);
            Triangles.Add(SecondTriangle);
          }
        }
      }
      for (int index = 1; index <= pnt3DList1.Count - 1; ++index)
        Triangles.Add(new Triangle3D()
        {
          FirstPoint = new Pnt3D(Points1),
          SecondPoint = new Pnt3D(pnt3DList1[index - 1]),
          ThirdPoint = new Pnt3D(pnt3DList1[index])
        });
      for (int index = 1; index <= pnt3DList2.Count - 1; ++index)
        Triangles.Add(new Triangle3D()
        {
          FirstPoint = new Pnt3D(Points2),
          SecondPoint = new Pnt3D(pnt3DList2[index - 1]),
          ThirdPoint = new Pnt3D(pnt3DList2[index])
        });
    }
    catch (Exception ex)
    {
      string str = $"BasePoint: {BasePoint.ToString()} - Length: {Length.ToString()} - Radius: {BottomRadius.ToString()} - Angle: {Angle.ToString()} - Vec: {Vec.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void CylinderWithAngle3D(
    Pnt3D BasePoint,
    double Length,
    double Radius,
    double StartAngle,
    double EndAngle,
    double Angle,
    Vec3D Vec,
    EntityResolution EntResolution,
    ref List<Triangle3D> Triangles)
  {
    try
    {
      Pnt3D Points1 = new Pnt3D();
      Pnt3D Points2 = new Pnt3D();
      List<Pnt3D> pnt3DList1 = new List<Pnt3D>();
      List<Pnt3D> pnt3DList2 = new List<Pnt3D>();
      Quad3D quad3D = new Quad3D();
      Triangle3D triangle3D1 = new Triangle3D();
      Triangle3D triangle3D2 = new Triangle3D();
      Triangle3D FirstTriangle;
      if (Vec3D.isVectorXAxis(Vec))
      {
        WorkPlane Plane = new WorkPlane(planeType.YZ, 1);
        this.ArcWithCenter(new Pnt3D(BasePoint.X - Length / 2.0, BasePoint.Y, BasePoint.Z), Radius, StartAngle, EndAngle, Plane, EntResolution, ref pnt3DList1);
        this.ArcWithCenter(new Pnt3D(BasePoint.X + Length / 2.0, BasePoint.Y, BasePoint.Z), Radius, StartAngle, EndAngle, Plane, EntResolution, ref pnt3DList2);
        Points1 = new Pnt3D(BasePoint.X - Length / 2.0, BasePoint.Y, BasePoint.Z);
        Points2 = new Pnt3D(BasePoint.X + Length / 2.0, BasePoint.Y, BasePoint.Z);
        this.Rotate(BasePoint, Angle, Plane, ref pnt3DList1);
        this.Rotate(BasePoint, Angle, Plane, ref pnt3DList2);
        this.Rotate(BasePoint, Angle, Plane, ref Points1);
        this.Rotate(BasePoint, Angle, Plane, ref Points2);
        Triangles.Clear();
        for (int index = 1; index <= pnt3DList1.Count - 1; ++index)
        {
          FirstTriangle = new Triangle3D();
          Triangle3D SecondTriangle = new Triangle3D();
          this.QuadToTriangle(new Quad3D(pnt3DList1[index - 1], pnt3DList2[index - 1], pnt3DList2[index], pnt3DList1[index]), ref FirstTriangle, ref SecondTriangle);
          Triangles.Add(FirstTriangle);
          Triangles.Add(SecondTriangle);
        }
      }
      if (Vec3D.isVectorYAxis(Vec))
      {
        WorkPlane Plane = new WorkPlane(planeType.XZ, 1);
        this.CircleWithCenter(new Pnt3D(BasePoint.X, BasePoint.Y - Length / 2.0, BasePoint.Z), Radius, Plane, EntResolution, ref pnt3DList1);
        this.CircleWithCenter(new Pnt3D(BasePoint.X, BasePoint.Y + Length / 2.0, BasePoint.Z), Radius, Plane, EntResolution, ref pnt3DList2);
        Points1 = new Pnt3D(BasePoint.X, BasePoint.Y - Length / 2.0, BasePoint.Z);
        Points2 = new Pnt3D(BasePoint.X, BasePoint.Y + Length / 2.0, BasePoint.Z);
        this.Rotate(BasePoint, Angle, Plane, ref pnt3DList1);
        this.Rotate(BasePoint, Angle, Plane, ref pnt3DList2);
        this.Rotate(BasePoint, Angle, Plane, ref Points1);
        this.Rotate(BasePoint, Angle, Plane, ref Points2);
        Triangles.Clear();
        for (int index = 1; index <= pnt3DList1.Count - 1; ++index)
        {
          FirstTriangle = new Triangle3D();
          Triangle3D SecondTriangle = new Triangle3D();
          this.QuadToTriangle(new Quad3D(pnt3DList1[index - 1], pnt3DList2[index - 1], pnt3DList2[index], pnt3DList1[index]), ref FirstTriangle, ref SecondTriangle);
          Triangles.Add(FirstTriangle);
          Triangles.Add(SecondTriangle);
        }
      }
      if (Vec3D.isVectorZAxis(Vec))
      {
        WorkPlane Plane = new WorkPlane(planeType.XY, 1);
        this.CircleWithCenter(new Pnt3D(BasePoint.X, BasePoint.Y, BasePoint.Z), Radius, Plane, EntResolution, ref pnt3DList1);
        this.CircleWithCenter(new Pnt3D(BasePoint.X, BasePoint.Y, BasePoint.Z + Length), Radius, Plane, EntResolution, ref pnt3DList2);
        Points1 = new Pnt3D(BasePoint.X, BasePoint.Y, BasePoint.Z);
        Points2 = new Pnt3D(BasePoint.X, BasePoint.Y, BasePoint.Z + Length);
        this.Rotate(BasePoint, Angle, Plane, ref pnt3DList1);
        this.Rotate(BasePoint, Angle, Plane, ref pnt3DList2);
        this.Rotate(BasePoint, Angle, Plane, ref Points1);
        this.Rotate(BasePoint, Angle, Plane, ref Points2);
        Triangles.Clear();
        for (int index = 1; index <= pnt3DList1.Count - 1; ++index)
        {
          FirstTriangle = new Triangle3D();
          Triangle3D SecondTriangle = new Triangle3D();
          this.QuadToTriangle(new Quad3D(pnt3DList1[index - 1], pnt3DList2[index - 1], pnt3DList2[index], pnt3DList1[index]), ref FirstTriangle, ref SecondTriangle);
          Triangles.Add(FirstTriangle);
          Triangles.Add(SecondTriangle);
        }
      }
      for (int index = 1; index <= pnt3DList1.Count - 1; ++index)
      {
        FirstTriangle = new Triangle3D();
        FirstTriangle.FirstPoint = new Pnt3D(Points1);
        FirstTriangle.SecondPoint = new Pnt3D(pnt3DList1[index - 1]);
        FirstTriangle.ThirdPoint = new Pnt3D(pnt3DList1[index]);
        Triangles.Add(FirstTriangle);
      }
      for (int index = 1; index <= pnt3DList2.Count - 1; ++index)
      {
        FirstTriangle = new Triangle3D();
        FirstTriangle.FirstPoint = new Pnt3D(Points2);
        FirstTriangle.SecondPoint = new Pnt3D(pnt3DList2[index - 1]);
        FirstTriangle.ThirdPoint = new Pnt3D(pnt3DList2[index]);
        Triangles.Add(FirstTriangle);
      }
      FirstTriangle = new Triangle3D();
      FirstTriangle.FirstPoint = new Pnt3D(pnt3DList1[0]);
      FirstTriangle.SecondPoint = new Pnt3D(pnt3DList2[0]);
      FirstTriangle.ThirdPoint = new Pnt3D(pnt3DList2[pnt3DList2.Count - 1]);
      Triangles.Add(FirstTriangle);
      FirstTriangle = new Triangle3D();
      FirstTriangle.FirstPoint = new Pnt3D(pnt3DList2[pnt3DList2.Count - 1]);
      FirstTriangle.SecondPoint = new Pnt3D(pnt3DList1[pnt3DList1.Count - 1]);
      FirstTriangle.ThirdPoint = new Pnt3D(pnt3DList1[0]);
      Triangles.Add(FirstTriangle);
    }
    catch (Exception ex)
    {
      string str = $"BasePoint: {BasePoint.ToString()} - Length: {Length.ToString()} - Radius: {Radius.ToString()} - StartAngle: {StartAngle.ToString()} - EndAngle: {EndAngle.ToString()} - Angle: {Angle.ToString()} - Vec: {Vec.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

