  public void CylinderHollow3D(
    Pnt3D CenterPoint,
    double OuterRadius,
    double InnerRadius,
    double Heigth,
    WorkPlane Plane,
    EntityResolution EntResolution,
    ref List<List<Pnt3D>> Vertices,
    ref List<Triangle3D> TriangleList)
  {
    try
    {
      List<Pnt3D> Vertices1 = new List<Pnt3D>();
      List<Pnt3D> Vertices2 = new List<Pnt3D>();
      List<Pnt3D> pnt3DList = new List<Pnt3D>();
      List<Pnt3D> SecondVertice = new List<Pnt3D>();
      List<Triangle3D> SurfaceTriangles = new List<Triangle3D>();
      Pnt3D pnt3D = new Pnt3D();
      if (InnerRadius >= OuterRadius)
        return;
      TriangleList.Clear();
      if (Plane.PlaneType == planeType.XY)
      {
        this.CircleWithCenter(CenterPoint, OuterRadius, Plane, EntResolution, ref Vertices1);
        this.CircleWithCenter(CenterPoint, InnerRadius, Vertices1.Count - 1, Plane, ref Vertices2);
        for (int index = 0; index <= Vertices1.Count - 1; ++index)
        {
          Pnt3D Pnt = new Pnt3D(Vertices1[index]);
          Pnt.Z += Heigth;
          pnt3DList.Add(new Pnt3D(Pnt));
        }
        for (int index = 0; index <= Vertices2.Count - 1; ++index)
        {
          Pnt3D Pnt = new Pnt3D(Vertices2[index]);
          Pnt.Z += Heigth;
          SecondVertice.Add(new Pnt3D(Pnt));
        }
        SurfaceTriangles.Clear();
        this.SurfaceWithTwoVerticeList(Vertices1, Vertices2, ref SurfaceTriangles);
        for (int index = 0; index <= SurfaceTriangles.Count - 1; ++index)
          TriangleList.Add(new Triangle3D(SurfaceTriangles[index]));
        SurfaceTriangles.Clear();
        this.SurfaceWithTwoVerticeList(pnt3DList, SecondVertice, ref SurfaceTriangles);
        for (int index = 0; index <= SurfaceTriangles.Count - 1; ++index)
          TriangleList.Add(new Triangle3D(SurfaceTriangles[index]));
        this.SurfaceWithTwoVerticeList(Vertices1, pnt3DList, ref SurfaceTriangles);
        for (int index = 0; index <= SurfaceTriangles.Count - 1; ++index)
          TriangleList.Add(new Triangle3D(SurfaceTriangles[index]));
        this.SurfaceWithTwoVerticeList(Vertices2, SecondVertice, ref SurfaceTriangles);
        for (int index = 0; index <= SurfaceTriangles.Count - 1; ++index)
          TriangleList.Add(new Triangle3D(SurfaceTriangles[index]));
      }
      if (Plane.PlaneType == planeType.XZ)
      {
        this.CircleWithCenter(CenterPoint, OuterRadius, Plane, EntResolution, ref Vertices1);
        this.CircleWithCenter(CenterPoint, InnerRadius, Vertices1.Count - 1, Plane, ref Vertices2);
        for (int index = 0; index <= Vertices1.Count - 1; ++index)
        {
          Pnt3D Pnt = new Pnt3D(Vertices1[index]);
          Pnt.Y += Heigth;
          pnt3DList.Add(new Pnt3D(Pnt));
        }
        for (int index = 0; index <= Vertices2.Count - 1; ++index)
        {
          Pnt3D Pnt = new Pnt3D(Vertices2[index]);
          Pnt.Y += Heigth;
          SecondVertice.Add(new Pnt3D(Pnt));
        }
        SurfaceTriangles.Clear();
        this.SurfaceWithTwoVerticeList(Vertices1, Vertices2, ref SurfaceTriangles);
        for (int index = 0; index <= SurfaceTriangles.Count - 1; ++index)
          TriangleList.Add(new Triangle3D(SurfaceTriangles[index]));
        SurfaceTriangles.Clear();
        this.SurfaceWithTwoVerticeList(pnt3DList, SecondVertice, ref SurfaceTriangles);
        for (int index = 0; index <= SurfaceTriangles.Count - 1; ++index)
          TriangleList.Add(new Triangle3D(SurfaceTriangles[index]));
        this.SurfaceWithTwoVerticeList(Vertices1, pnt3DList, ref SurfaceTriangles);
        for (int index = 0; index <= SurfaceTriangles.Count - 1; ++index)
          TriangleList.Add(new Triangle3D(SurfaceTriangles[index]));
        this.SurfaceWithTwoVerticeList(Vertices2, SecondVertice, ref SurfaceTriangles);
        for (int index = 0; index <= SurfaceTriangles.Count - 1; ++index)
          TriangleList.Add(new Triangle3D(SurfaceTriangles[index]));
      }
      if (Plane.PlaneType == planeType.YZ)
      {
        this.CircleWithCenter(CenterPoint, OuterRadius, Plane, EntResolution, ref Vertices1);
        this.CircleWithCenter(CenterPoint, InnerRadius, Vertices1.Count - 1, Plane, ref Vertices2);
        for (int index = 0; index <= Vertices1.Count - 1; ++index)
        {
          Pnt3D Pnt = new Pnt3D(Vertices1[index]);
          Pnt.X += Heigth;
          pnt3DList.Add(new Pnt3D(Pnt));
        }
        for (int index = 0; index <= Vertices2.Count - 1; ++index)
        {
          Pnt3D Pnt = new Pnt3D(Vertices2[index]);
          Pnt.X += Heigth;
          SecondVertice.Add(new Pnt3D(Pnt));
        }
        SurfaceTriangles.Clear();
        this.SurfaceWithTwoVerticeList(Vertices1, Vertices2, ref SurfaceTriangles);
        for (int index = 0; index <= SurfaceTriangles.Count - 1; ++index)
          TriangleList.Add(new Triangle3D(SurfaceTriangles[index]));
        SurfaceTriangles.Clear();
        this.SurfaceWithTwoVerticeList(pnt3DList, SecondVertice, ref SurfaceTriangles);
        for (int index = 0; index <= SurfaceTriangles.Count - 1; ++index)
          TriangleList.Add(new Triangle3D(SurfaceTriangles[index]));
        this.SurfaceWithTwoVerticeList(Vertices1, pnt3DList, ref SurfaceTriangles);
        for (int index = 0; index <= SurfaceTriangles.Count - 1; ++index)
          TriangleList.Add(new Triangle3D(SurfaceTriangles[index]));
        this.SurfaceWithTwoVerticeList(Vertices2, SecondVertice, ref SurfaceTriangles);
        for (int index = 0; index <= SurfaceTriangles.Count - 1; ++index)
          TriangleList.Add(new Triangle3D(SurfaceTriangles[index]));
      }
      Vertices.Add(Vertices1);
      Vertices.Add(Vertices2);
      Vertices.Add(pnt3DList);
      Vertices.Add(SecondVertice);
      for (int index = 0; index <= Vertices1.Count - 1; ++index)
        Vertices.Add(new List<Pnt3D>()
        {
          new Pnt3D(Vertices1[index]),
          new Pnt3D(pnt3DList[index])
        });
      for (int index = 0; index <= Vertices2.Count - 1; ++index)
        Vertices.Add(new List<Pnt3D>()
        {
          new Pnt3D(Vertices2[index]),
          new Pnt3D(SecondVertice[index])
        });
    }
    catch (Exception ex)
    {
      string str = $"CenterPoint: {CenterPoint.ToString()} - OuterRadius: {OuterRadius.ToString()} - InnerRadius: {InnerRadius.ToString()} - Heigth: {Heigth.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void ConeOpen3D(
    Pnt3D BasePoint,
    double Length,
    double BottomRadius,
    double TopRadius,
    double Angle,
    WorkPlane Plane,
    EntityResolution EntResolution,
    ref List<Triangle3D> Triangles)
  {
    try
    {
      Pnt3D BasePnt = new Pnt3D();
      Pnt3D EndPnt = new Pnt3D();
      List<Pnt3D> RefPoint = new List<Pnt3D>();
      List<Pnt3D> pnt3DList = new List<Pnt3D>();
      Quad3D quad3D = new Quad3D();
      Triangle3D triangle3D1 = new Triangle3D();
      Triangle3D triangle3D2 = new Triangle3D();
      if (Plane.PlaneType != planeType.XY)
        return;
      this.CircleWithCenter(BasePoint, BottomRadius, Plane, EntResolution, ref RefPoint);
      double num = TopRadius / BottomRadius;
      if (num <= 0.0)
        num = 1.0;
      this.Scale(BasePoint, 1.0, num, num, false, true, true, RefPoint, ref pnt3DList);
      this.Rotate(BasePoint, Angle, Plane, ref RefPoint);
      this.Rotate(BasePoint, Angle, Plane, ref pnt3DList);
      this.LineWithLengthAndAngle(BasePoint, Length, Angle, Plane, ref BasePnt, ref EndPnt);
      double OffsetX = EndPnt.X - BasePnt.X;
      double OffsetY = EndPnt.Y - BasePnt.Y;
      double OffsetZ = EndPnt.Z - BasePnt.Z;
      for (int index = 0; index <= pnt3DList.Count - 1; ++index)
      {
        Pnt3D pnt3D = new Pnt3D();
        Pnt3D point = this.AddOffsetToPoint(pnt3DList[index], OffsetX, OffsetY, OffsetZ);
        pnt3DList[index] = new Pnt3D(point);
      }
      Triangles.Clear();
      for (int index = 1; index <= RefPoint.Count - 1; ++index)
      {
        Triangle3D FirstTriangle = new Triangle3D();
        Triangle3D SecondTriangle = new Triangle3D();
        this.QuadToTriangle(new Quad3D(RefPoint[index - 1], pnt3DList[index - 1], pnt3DList[index], RefPoint[index]), ref FirstTriangle, ref SecondTriangle);
        Triangles.Add(FirstTriangle);
        Triangles.Add(SecondTriangle);
      }
    }
    catch (Exception ex)
    {
      string str = $"BasePoint: {BasePoint.ToString()} - BottomRadius: {BottomRadius.ToString()} - TopRadius: {TopRadius.ToString()} - Length: {Length.ToString()} - Angle: {Angle.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void ConeHollow3D(
    Pnt3D CenterPoint,
    double TopRadius,
    double BottomRadius,
    double Heigth,
    double Thickness,
    WorkPlane Plane,
    EntityResolution EntResolution,
    ref List<List<Pnt3D>> Vertices,
    ref List<Triangle3D> TriangleList)
  {
    try
    {
      List<Pnt3D> Vertices1 = new List<Pnt3D>();
      List<Pnt3D> Vertices2 = new List<Pnt3D>();
      List<Pnt3D> Vertices3 = new List<Pnt3D>();
      List<Pnt3D> Vertices4 = new List<Pnt3D>();
      List<Triangle3D> SurfaceTriangles = new List<Triangle3D>();
      Pnt3D Center = new Pnt3D();
      TriangleList.Clear();
      if (Plane.PlaneType == planeType.XY)
        Center = this.AddOffsetToPoint(CenterPoint, 0.0, 0.0, Heigth);
      if (Plane.PlaneType == planeType.XZ)
        Center = this.AddOffsetToPoint(CenterPoint, 0.0, Heigth, 0.0);
      if (Plane.PlaneType == planeType.YZ)
        Center = this.AddOffsetToPoint(CenterPoint, Heigth, 0.0, 0.0);
      if (TopRadius > BottomRadius)
      {
        this.CircleWithCenter(Center, TopRadius, Plane, EntResolution, ref Vertices1);
        this.CircleWithCenter(CenterPoint, BottomRadius, Vertices1.Count - 1, Plane, ref Vertices2);
        this.CircleWithCenter(Center, TopRadius - Thickness, Vertices1.Count - 1, Plane, ref Vertices3);
        this.CircleWithCenter(CenterPoint, BottomRadius - Thickness, Vertices1.Count - 1, Plane, ref Vertices4);
      }
      else
      {
        this.CircleWithCenter(CenterPoint, BottomRadius, Plane, EntResolution, ref Vertices2);
        this.CircleWithCenter(Center, TopRadius, Vertices2.Count - 1, Plane, ref Vertices1);
        this.CircleWithCenter(CenterPoint, BottomRadius - Thickness, Vertices2.Count - 1, Plane, ref Vertices4);
        this.CircleWithCenter(Center, TopRadius - Thickness, Vertices2.Count - 1, Plane, ref Vertices3);
      }
      SurfaceTriangles.Clear();
      this.SurfaceWithTwoVerticeList(Vertices1, Vertices3, ref SurfaceTriangles);
      for (int index = 0; index <= SurfaceTriangles.Count - 1; ++index)
        TriangleList.Add(new Triangle3D(SurfaceTriangles[index]));
      SurfaceTriangles.Clear();
      this.SurfaceWithTwoVerticeList(Vertices2, Vertices4, ref SurfaceTriangles);
      for (int index = 0; index <= SurfaceTriangles.Count - 1; ++index)
        TriangleList.Add(new Triangle3D(SurfaceTriangles[index]));
      SurfaceTriangles.Clear();
      this.SurfaceWithTwoVerticeList(Vertices1, Vertices2, ref SurfaceTriangles);
      for (int index = 0; index <= SurfaceTriangles.Count - 1; ++index)
        TriangleList.Add(new Triangle3D(SurfaceTriangles[index]));
      SurfaceTriangles.Clear();
      this.SurfaceWithTwoVerticeList(Vertices3, Vertices4, ref SurfaceTriangles);
      for (int index = 0; index <= SurfaceTriangles.Count - 1; ++index)
        TriangleList.Add(new Triangle3D(SurfaceTriangles[index]));
    }
    catch (Exception ex)
    {
      string str = $"CenterPoint: {CenterPoint.ToString()} - BottomRadius: {BottomRadius.ToString()} - TopRadius: {TopRadius.ToString()} - Heigth: {Heigth.ToString()} - Thickness: {Thickness.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void BoxCorner3D(
    Pnt3D CornerPoint,
    double Width,
    double Height,
    double Thickness,
    WorkPlane Plane,
    ref List<eEntities> Entities)
  {
    List<List<Pnt3D>> Vertices = new List<List<Pnt3D>>();
    List<Triangle3D> Triangles = new List<Triangle3D>();
    this.BoxCorner3D(CornerPoint, Width, Height, Thickness, Plane, ref Vertices, ref Triangles);
    Entities.Clear();
    for (int index1 = 0; index1 <= Vertices.Count - 1; ++index1)
    {
      for (int index2 = 1; index2 <= Vertices[index1].Count - 1; ++index2)
      {
        eLine eLine = new eLine(Vertices[index1][index2 - 1], Vertices[index1][index2]);
        Entities.Add((eEntities) eLine);
      }
    }
  }

