  public void BoxWith4Point3D(
    Pnt3D FirstPoint,
    Pnt3D SecondPoint,
    Pnt3D ThirdPoint,
    Pnt3D FourthPoint,
    double Thickness,
    WorkPlane Plane,
    ref List<List<Pnt3D>> Vertices,
    ref List<Triangle3D> Triangles,
    ref List<Quad3D> Quads,
    ref List<eEntities> Entities)
  {
    try
    {
      Entities.Clear();
      Vertices.Clear();
      Triangles.Clear();
      Quads.Clear();
      Pnt3D pnt3D1 = new Pnt3D(FirstPoint.X, FirstPoint.Y, FirstPoint.Z + Thickness);
      Pnt3D pnt3D2 = new Pnt3D(SecondPoint.X, SecondPoint.Y, SecondPoint.Z + Thickness);
      Pnt3D pnt3D3 = new Pnt3D(ThirdPoint.X, ThirdPoint.Y, ThirdPoint.Z + Thickness);
      Pnt3D pnt3D4 = new Pnt3D(FourthPoint.X, FourthPoint.Y, FourthPoint.Z + Thickness);
      Vertices.Add(new List<Pnt3D>()
      {
        FirstPoint,
        SecondPoint,
        ThirdPoint,
        FourthPoint,
        FirstPoint
      });
      Vertices.Add(new List<Pnt3D>()
      {
        pnt3D1,
        pnt3D2,
        pnt3D3,
        pnt3D4,
        pnt3D1
      });
      Vertices.Add(new List<Pnt3D>()
      {
        FirstPoint,
        pnt3D1,
        pnt3D4,
        FourthPoint,
        FirstPoint
      });
      Vertices.Add(new List<Pnt3D>()
      {
        SecondPoint,
        pnt3D2,
        pnt3D3,
        ThirdPoint,
        SecondPoint
      });
      Vertices.Add(new List<Pnt3D>()
      {
        FirstPoint,
        SecondPoint,
        pnt3D2,
        pnt3D1,
        FirstPoint
      });
      Vertices.Add(new List<Pnt3D>()
      {
        ThirdPoint,
        FourthPoint,
        pnt3D4,
        pnt3D3,
        ThirdPoint
      });
      for (int index1 = 0; index1 <= Vertices.Count - 1; ++index1)
      {
        Quad3D Quad = new Quad3D();
        Triangle3D FirstTriangle = new Triangle3D();
        Triangle3D SecondTriangle = new Triangle3D();
        this.PointsToQuad(Vertices[0], ref Quad);
        Quads.Add(Quad);
        this.QuadToTriangle(Quad, ref FirstTriangle, ref SecondTriangle);
        Triangles.Add(FirstTriangle);
        Triangles.Add(SecondTriangle);
        for (int index2 = 1; index2 <= Vertices[index1].Count - 1; ++index2)
        {
          if (index1 > 0)
          {
            eLine eLine = new eLine(Vertices[index1][index2 - 1], Vertices[index1][index2]);
            Entities.Add((eEntities) eLine);
          }
        }
      }
    }
    catch (Exception ex)
    {
      string str = $"FirstPoint: {FirstPoint.ToString()} - SecondPoint: {SecondPoint.ToString()} - ThirdPoint: {ThirdPoint.ToString()} - FourthPoint: {FourthPoint.ToString()} - Thickness: {Thickness.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

