      });
      Triangles.Add(new Triangle3D()
      {
        FirstPoint = new Pnt3D(pnt3DList2[3]),
        SecondPoint = new Pnt3D(Vertices2[3]),
        ThirdPoint = new Pnt3D(Vertices2[0])
      });
      Triangles.Add(new Triangle3D()
      {
        FirstPoint = new Pnt3D(Vertices2[1]),
        SecondPoint = new Pnt3D(pnt3DList2[1]),
        ThirdPoint = new Pnt3D(pnt3DList2[2])
      });
      Triangles.Add(new Triangle3D()
      {
        FirstPoint = new Pnt3D(pnt3DList2[2]),
        SecondPoint = new Pnt3D(Vertices2[2]),
        ThirdPoint = new Pnt3D(Vertices2[1])
      });
      Triangles.Add(new Triangle3D()
      {
        FirstPoint = new Pnt3D(Vertices2[0]),
        SecondPoint = new Pnt3D(pnt3DList2[0]),
        ThirdPoint = new Pnt3D(pnt3DList2[1])
      });
      Triangles.Add(new Triangle3D()
      {
