  public void Sphere3D(
    Pnt3D CenterPoint,
    double Radius,
    EntityResolution EntResolution,
    ref List<List<Pnt3D>> Vertices,
    ref List<Triangle3D> TriangleList)
  {
    try
    {
      List<Pnt3D> pnt3DList1 = new List<Pnt3D>();
      List<Pnt3D> pnt3DList2 = new List<Pnt3D>();
      List<Triangle3D> SurfaceTriangles = new List<Triangle3D>();
      int index1 = 0;
      TriangleList.Clear();
      this.ArcWithCenter(CenterPoint, Radius, 0.0, 360.0, new WorkPlane(), EntResolution, ref pnt3DList1);
      for (int index2 = 0; index2 <= pnt3DList1.Count - 1; ++index2)
        pnt3DList2.Add(new Pnt3D(pnt3DList1[index2]));
      int num1 = this.CircleVerticeCountByResolution(Radius, EntResolution);
      if (num1 < 30)
        num1 = 30;
      double num2 = 360.0 / (double) num1;
      List<Pnt3D>[] pnt3DListArray = new List<Pnt3D>[num1 + 1];
      for (int index3 = 0; index3 <= num1; ++index3)
      {
        this.Rotate(CenterPoint, (double) index3 * num2, new WorkPlane(planeType.XZ, 1), ref pnt3DList1);
        pnt3DListArray[index1] = new List<Pnt3D>();
        for (int index4 = 0; index4 <= pnt3DList1.Count - 1; ++index4)
          pnt3DListArray[index1].Add(new Pnt3D(pnt3DList1[index4]));
        pnt3DList1.Clear();
        for (int index5 = 0; index5 <= pnt3DList2.Count - 1; ++index5)
          pnt3DList1.Add(new Pnt3D(pnt3DList2[index5]));
        ++index1;
      }
      for (int index6 = 1; index6 <= pnt3DListArray.Length - 1; ++index6)
      {
        List<Pnt3D> pnt3DList3 = new List<Pnt3D>();
        for (int index7 = 0; index7 <= pnt3DListArray[index6].Count - 1; ++index7)
          pnt3DList3.Add(new Pnt3D(pnt3DListArray[index6][index7]));
        Vertices.Add(pnt3DList3);
        SurfaceTriangles.Clear();
        this.SurfaceWithTwoConnectedVertice(pnt3DListArray[index6 - 1], pnt3DListArray[index6], ref SurfaceTriangles);
        for (int index8 = 0; index8 <= SurfaceTriangles.Count - 1; ++index8)
          TriangleList.Add(new Triangle3D(SurfaceTriangles[index8]));
      }
    }
    catch (Exception ex)
    {
      string str = $"CenterPoint: {CenterPoint.ToString()} - Radius: {Radius.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void SphereHalf3D(
    Pnt3D CenterPoint,
    double Radius,
    double StartAngle,
    double EndAngle,
    EntityResolution EntResolution,
    WorkPlane Plane,
    ref List<Triangle3D> TriangleList)
  {
    try
    {
      List<Pnt3D> pnt3DList1 = new List<Pnt3D>();
      List<Pnt3D> pnt3DList2 = new List<Pnt3D>();
      List<Triangle3D> SurfaceTriangles = new List<Triangle3D>();
      int index1 = 0;
      TriangleList.Clear();
      if (Plane.PlaneType == planeType.XY)
        this.ArcWithCenter(CenterPoint, Radius, 0.0, 180.0, Plane, EntResolution, ref pnt3DList1);
      if (Plane.PlaneType == planeType.XZ)
        this.ArcWithCenter(CenterPoint, Radius, 0.0, 180.0, Plane, EntResolution, ref pnt3DList1);
      if (Plane.PlaneType == planeType.YZ)
        this.ArcWithCenter(CenterPoint, Radius, 0.0, 180.0, Plane, EntResolution, ref pnt3DList1);
      for (int index2 = 0; index2 <= pnt3DList1.Count - 1; ++index2)
        pnt3DList2.Add(new Pnt3D(pnt3DList1[index2]));
      int num1 = this.CircleVerticeCountByResolution(Radius, EntResolution);
      if (num1 < 30)
        num1 = 30;
      double num2 = (EndAngle - StartAngle) / (double) num1;
      List<Pnt3D>[] pnt3DListArray = new List<Pnt3D>[num1 + 1];
      for (int index3 = 0; index3 <= num1; ++index3)
      {
        if (Plane.PlaneType == planeType.XY)
          this.Rotate(CenterPoint, StartAngle + (double) index3 * num2, Plane, ref pnt3DList1);
        if (Plane.PlaneType == planeType.XZ)
          this.Rotate(CenterPoint, StartAngle - 90.0 + (double) index3 * num2, Plane, ref pnt3DList1);
        if (Plane.PlaneType == planeType.YZ)
          this.Rotate(CenterPoint, StartAngle + 180.0 + (double) index3 * num2, Plane, ref pnt3DList1);
        pnt3DListArray[index1] = new List<Pnt3D>();
        for (int index4 = 0; index4 <= pnt3DList1.Count - 1; ++index4)
          pnt3DListArray[index1].Add(new Pnt3D(pnt3DList1[index4]));
        pnt3DList1.Clear();
        for (int index5 = 0; index5 <= pnt3DList2.Count - 1; ++index5)
          pnt3DList1.Add(new Pnt3D(pnt3DList2[index5]));
        ++index1;
      }
      for (int index6 = 1; index6 <= pnt3DListArray.Length - 1; ++index6)
      {
        SurfaceTriangles.Clear();
        this.SurfaceWithTwoConnectedVertice(pnt3DListArray[index6 - 1], pnt3DListArray[index6], ref SurfaceTriangles);
        for (int index7 = 0; index7 <= SurfaceTriangles.Count - 1; ++index7)
          TriangleList.Add(new Triangle3D(SurfaceTriangles[index7]));
      }
      SurfaceTriangles.Clear();
      this.SurfaceWithVerticeToPoint(pnt3DListArray[0], CenterPoint, ref SurfaceTriangles);
      for (int index8 = 0; index8 <= SurfaceTriangles.Count - 1; ++index8)
        TriangleList.Add(new Triangle3D(SurfaceTriangles[index8]));
      SurfaceTriangles.Clear();
      this.SurfaceWithVerticeToPoint(pnt3DListArray[pnt3DListArray.Length - 1], CenterPoint, ref SurfaceTriangles);
      for (int index9 = 0; index9 <= SurfaceTriangles.Count - 1; ++index9)
        TriangleList.Add(new Triangle3D(SurfaceTriangles[index9]));
    }
    catch (Exception ex)
    {
      string str = $"CenterPoint: {CenterPoint.ToString()} - Radius: {Radius.ToString()} - StartAngle: {StartAngle.ToString()} - EndAngle: {EndAngle.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

