  public void Trapezoid3D(
    Pnt3D TopLeftPoint,
    double TrapezTopWidth,
    double TrapezHeight,
    double TrapezTopLeftAngle,
    double TrapezTopRightAngle,
    Vec3D LengthDirection,
    double DirectionLength,
    double Rotation,
    ref List<Pnt3D> Vertice2D,
    ref List<List<Pnt3D>> Vertice3D,
    ref List<Quad3D> Quads3D,
    ref List<Triangle3D> Triangles3D,
    ref List<eEntities> Entities3D,
    ref eEntities SurfaceEntity)
  {
    Pnt3D pnt3D1 = new Pnt3D();
    Pnt3D pnt3D2 = new Pnt3D();
    Pnt3D CalcPoint1 = new Pnt3D();
    Pnt3D CalcPoint2 = new Pnt3D();
    ContentAlignmentPoints AlignPoints = new ContentAlignmentPoints();
    List<Pnt3D> CopiedPnt = new List<Pnt3D>();
    List<Pnt3D> Points = new List<Pnt3D>();
    List<Pnt3D> pnt3DList1 = new List<Pnt3D>();
    Quad3D quad3D = new Quad3D();
    Triangle3D triangle3D1 = new Triangle3D();
    Triangle3D triangle3D2 = new Triangle3D();
    Vertice2D.Clear();
    Vertice3D.Clear();
    Quads3D.Clear();
    Triangles3D.Clear();
    Entities3D.Clear();
    Quad3D Quad;
    Triangle3D FirstTriangle;
    if (Vec3D.isVectorZAxis(LengthDirection))
    {
      Pnt3D BasePoint1 = new Pnt3D(0.0, TrapezHeight, 0.0);
      Pnt3D BasePoint2 = new Pnt3D(TrapezTopWidth, TrapezHeight, 0.0);
      this.DiagonalLengthByAnglePerpendicularDistance(BasePoint1, 90.0 - TrapezTopLeftAngle, -TrapezHeight, new WorkPlane(), ref CalcPoint1);
      this.DiagonalLengthByAnglePerpendicularDistance(BasePoint2, TrapezTopRightAngle - 90.0, -TrapezHeight, new WorkPlane(), ref CalcPoint2);
      Points.Add(BasePoint1);
      Points.Add(BasePoint2);
      Points.Add(CalcPoint2);
      Points.Add(CalcPoint1);
      Points.Add(BasePoint1);
      this.BoxSizeWithContentAlignment(Points, new WorkPlane(LengthDirection), ref AlignPoints);
      this.Move(AlignPoints.TopLeftPoint, TopLeftPoint, ref Points);
      Pnt3D.Copy(Points, ref CopiedPnt);
      this.Rotate(TopLeftPoint, Rotation, new WorkPlane(), ref Points);
      Pnt3D.Copy(Points, ref Vertice2D);
      Vertice3D.Add(Points);
      ePolyline ePolyline1 = new ePolyline(Points);
      Entities3D.Add((eEntities) ePolyline1);
      Quad = new Quad3D();
      this.PointsToQuad(Points, ref Quad);
      Quads3D.Add(Quad);
      FirstTriangle = new Triangle3D();
      Triangle3D SecondTriangle1 = new Triangle3D();
      this.QuadToTriangle(Quad, ref FirstTriangle, ref SecondTriangle1);
      Triangles3D.Add(FirstTriangle);
      Triangles3D.Add(SecondTriangle1);
      Pnt3D.Copy(Points, ref pnt3DList1);
      Pnt3D.Offset(ref pnt3DList1, 0.0, 0.0, DirectionLength);
      Vertice3D.Add(pnt3DList1);
      ePolyline ePolyline2 = new ePolyline(pnt3DList1);
      Entities3D.Add((eEntities) ePolyline2);
      Quad = new Quad3D();
      this.PointsToQuad(pnt3DList1, ref Quad);
      Quads3D.Add(Quad);
      FirstTriangle = new Triangle3D();
      Triangle3D SecondTriangle2 = new Triangle3D();
      this.QuadToTriangle(Quad, ref FirstTriangle, ref SecondTriangle2);
      Triangles3D.Add(FirstTriangle);
      Triangles3D.Add(SecondTriangle2);
      for (int index = 0; index <= 3; ++index)
      {
        List<Pnt3D> pnt3DList2 = new List<Pnt3D>();
        pnt3DList2.Add(new Pnt3D(Points[index]));
        pnt3DList2.Add(new Pnt3D(Points[index + 1]));
        pnt3DList2.Add(new Pnt3D(pnt3DList1[index + 1]));
        pnt3DList2.Add(new Pnt3D(pnt3DList1[index]));
        pnt3DList2.Add(new Pnt3D(Points[index]));
        Vertice3D.Add(pnt3DList2);
        ePolyline ePolyline3 = new ePolyline(pnt3DList2);
        Entities3D.Add((eEntities) ePolyline3);
        Quad = new Quad3D();
        this.PointsToQuad(pnt3DList2, ref Quad);
        Quads3D.Add(Quad);
        FirstTriangle = new Triangle3D();
        Triangle3D SecondTriangle3 = new Triangle3D();
        this.QuadToTriangle(Quad, ref FirstTriangle, ref SecondTriangle3);
        Triangles3D.Add(FirstTriangle);
        Triangles3D.Add(SecondTriangle3);
      }
    }
    if (Vec3D.isVectorYAxis(LengthDirection))
    {
      Pnt3D BasePoint3 = new Pnt3D(0.0, 0.0, TrapezHeight);
      Pnt3D BasePoint4 = new Pnt3D(TrapezTopWidth, 0.0, TrapezHeight);
      this.DiagonalLengthByAnglePerpendicularDistance(BasePoint3, 90.0 - TrapezTopLeftAngle, -TrapezHeight, new WorkPlane(planeType.XZ, 1), ref CalcPoint1);
      this.DiagonalLengthByAnglePerpendicularDistance(BasePoint4, TrapezTopRightAngle - 90.0, -TrapezHeight, new WorkPlane(planeType.XZ, 1), ref CalcPoint2);
      Points.Add(BasePoint3);
      Points.Add(BasePoint4);
      Points.Add(CalcPoint2);
      Points.Add(CalcPoint1);
      Points.Add(BasePoint3);
      this.BoxSizeWithContentAlignment(Points, new WorkPlane(LengthDirection), ref AlignPoints);
      this.Move(AlignPoints.TopLeftPoint, TopLeftPoint, ref Points);
      Pnt3D.Copy(Points, ref CopiedPnt);
      this.Rotate(TopLeftPoint, Rotation, new WorkPlane(), ref Points);
      Pnt3D.Copy(Points, ref Vertice2D);
      Vertice3D.Add(Points);
      ePolyline ePolyline4 = new ePolyline(Points);
      Entities3D.Add((eEntities) ePolyline4);
      Quad = new Quad3D();
      this.PointsToQuad(Points, ref Quad);
      Quads3D.Add(Quad);
      FirstTriangle = new Triangle3D();
      Triangle3D SecondTriangle4 = new Triangle3D();
      this.QuadToTriangle(Quad, ref FirstTriangle, ref SecondTriangle4);
      Triangles3D.Add(FirstTriangle);
      Triangles3D.Add(SecondTriangle4);
      Pnt3D.Copy(CopiedPnt, ref pnt3DList1);
      Pnt3D.Offset(ref pnt3DList1, 0.0, DirectionLength, 0.0);
      this.Rotate(TopLeftPoint, Rotation, new WorkPlane(), ref pnt3DList1);
      Vertice3D.Add(pnt3DList1);
      ePolyline ePolyline5 = new ePolyline(pnt3DList1);
      Entities3D.Add((eEntities) ePolyline5);
      Quad = new Quad3D();
      this.PointsToQuad(pnt3DList1, ref Quad);
      Quads3D.Add(Quad);
      FirstTriangle = new Triangle3D();
      Triangle3D SecondTriangle5 = new Triangle3D();
      this.QuadToTriangle(Quad, ref FirstTriangle, ref SecondTriangle5);
      Triangles3D.Add(FirstTriangle);
      Triangles3D.Add(SecondTriangle5);
      for (int index = 0; index <= 3; ++index)
      {
        List<Pnt3D> pnt3DList3 = new List<Pnt3D>();
        pnt3DList3.Add(new Pnt3D(Points[index]));
        pnt3DList3.Add(new Pnt3D(Points[index + 1]));
        pnt3DList3.Add(new Pnt3D(pnt3DList1[index + 1]));
        pnt3DList3.Add(new Pnt3D(pnt3DList1[index]));
        pnt3DList3.Add(new Pnt3D(Points[index]));
        Vertice3D.Add(pnt3DList3);
        ePolyline ePolyline6 = new ePolyline(pnt3DList3);
        Entities3D.Add((eEntities) ePolyline6);
        Quad = new Quad3D();
        this.PointsToQuad(pnt3DList3, ref Quad);
        Quads3D.Add(Quad);
        FirstTriangle = new Triangle3D();
        Triangle3D SecondTriangle6 = new Triangle3D();
        this.QuadToTriangle(Quad, ref FirstTriangle, ref SecondTriangle6);
        Triangles3D.Add(FirstTriangle);
        Triangles3D.Add(SecondTriangle6);
      }
    }
    if (Vec3D.isVectorXAxis(LengthDirection))
    {
      Pnt3D BasePoint5 = new Pnt3D(0.0, 0.0, TrapezHeight);
      Pnt3D BasePoint6 = new Pnt3D(0.0, TrapezTopWidth, TrapezHeight);
      this.DiagonalLengthByAnglePerpendicularDistance(BasePoint5, 90.0 - TrapezTopLeftAngle, -TrapezHeight, new WorkPlane(planeType.YZ, 1), ref CalcPoint1);
      this.DiagonalLengthByAnglePerpendicularDistance(BasePoint6, TrapezTopRightAngle - 90.0, -TrapezHeight, new WorkPlane(planeType.YZ, 1), ref CalcPoint2);
      Points.Add(BasePoint5);
      Points.Add(BasePoint6);
      Points.Add(CalcPoint2);
      Points.Add(CalcPoint1);
      Points.Add(BasePoint5);
      this.BoxSizeWithContentAlignment(Points, new WorkPlane(LengthDirection), ref AlignPoints);
      this.Move(AlignPoints.TopLeftPoint, TopLeftPoint, ref Points);
      Pnt3D.Copy(Points, ref CopiedPnt);
      this.Rotate(TopLeftPoint, Rotation, new WorkPlane(), ref Points);
      Pnt3D.Copy(Points, ref Vertice2D);
      Vertice3D.Add(Points);
      ePolyline ePolyline7 = new ePolyline(Points);
      Entities3D.Add((eEntities) ePolyline7);
      Quad = new Quad3D();
      this.PointsToQuad(Points, ref Quad);
      Quads3D.Add(Quad);
      FirstTriangle = new Triangle3D();
      Triangle3D SecondTriangle7 = new Triangle3D();
      this.QuadToTriangle(Quad, ref FirstTriangle, ref SecondTriangle7);
      Triangles3D.Add(FirstTriangle);
      Triangles3D.Add(SecondTriangle7);
      Pnt3D.Copy(CopiedPnt, ref pnt3DList1);
      Pnt3D.Offset(ref pnt3DList1, DirectionLength, 0.0, 0.0);
      this.Rotate(TopLeftPoint, Rotation, new WorkPlane(), ref pnt3DList1);
