      ePolyline ePolyline8 = new ePolyline(pnt3DList1);
      Entities3D.Add((eEntities) ePolyline8);
      Quad = new Quad3D();
      this.PointsToQuad(pnt3DList1, ref Quad);
      Quads3D.Add(Quad);
      FirstTriangle = new Triangle3D();
      Triangle3D SecondTriangle8 = new Triangle3D();
      this.QuadToTriangle(Quad, ref FirstTriangle, ref SecondTriangle8);
      Triangles3D.Add(FirstTriangle);
      Triangles3D.Add(SecondTriangle8);
      for (int index = 0; index <= 3; ++index)
      {
        List<Pnt3D> pnt3DList4 = new List<Pnt3D>();
        pnt3DList4.Add(new Pnt3D(Points[index]));
        pnt3DList4.Add(new Pnt3D(Points[index + 1]));
        pnt3DList4.Add(new Pnt3D(pnt3DList1[index + 1]));
        pnt3DList4.Add(new Pnt3D(pnt3DList1[index]));
        pnt3DList4.Add(new Pnt3D(Points[index]));
        Vertice3D.Add(pnt3DList4);
        ePolyline ePolyline9 = new ePolyline(pnt3DList4);
        Entities3D.Add((eEntities) ePolyline9);
        Quad = new Quad3D();
        this.PointsToQuad(pnt3DList4, ref Quad);
        Quads3D.Add(Quad);
        FirstTriangle = new Triangle3D();
        Triangle3D SecondTriangle9 = new Triangle3D();
        this.QuadToTriangle(Quad, ref FirstTriangle, ref SecondTriangle9);
        Triangles3D.Add(FirstTriangle);
        Triangles3D.Add(SecondTriangle9);
      }
    }
    if (Triangles3D.Count <= 0)
      return;
    SurfaceEntity = (eEntities) new eSurface(Triangles3D, Color.Gray);
  }

  public void Plane3D(
    Pnt3D CornerPoint,
    Vec3D Vector,
    OrientationAngle Rotations,
    double Width,
    double Height,
    ref List<Pnt3D> Vertices)
  {
    Vertices.Clear();
    if (Vec3D.isVectorXAxis(Vector))
    {
      this.RectangleCorner(CornerPoint, Width, Height, new WorkPlane(), ref Vertices);
      this.RotateBySequanceOrientationAngle(CornerPoint, Rotations, RotationSequance.AC, ref Vertices);
    }
    if (Vec3D.isVectorYAxis(Vector))
    {
      int num1 = (int) MessageBox.Show("Not Developted");
    }
    if (!Vec3D.isVectorZAxis(Vector))
      return;
    int num2 = (int) MessageBox.Show("Not Developted");
  }

  public void Clamper3D(
    double XPosition,
    int Type,
    double ProfileWidth,
