  public void CreatMeshSurfaceFromGridPoins(
    List<List<Pnt3D>> GridPoints,
    ref List<Triangle3D> Triangles)
  {
    Triangles = new List<Triangle3D>();
    for (int index1 = 1; index1 <= GridPoints.Count - 1; ++index1)
    {
      if (GridPoints[index1 - 1].Count == GridPoints[index1].Count)
      {
        for (int index2 = 1; index2 <= GridPoints[index1].Count - 1; ++index2)
        {
          Triangle3D FirstTriangle = new Triangle3D();
          Triangle3D SecondTriangle = new Triangle3D();
          this.QuadToTriangle(new Quad3D(GridPoints[index1 - 1][index2 - 1], GridPoints[index1 - 1][index2], GridPoints[index1][index2], GridPoints[index1][index2 - 1]), ref FirstTriangle, ref SecondTriangle);
          Triangles.Add(FirstTriangle);
          Triangles.Add(SecondTriangle);
        }
      }
    }
  }

  public void GetGridPointsFromXYZList(
    List<string> CoordinateList,
    FileOpenModes Properties,
    ref List<List<Pnt3D>> GridPoints)
  {
    GridPoints = new List<List<Pnt3D>>();
    List<Pnt3D> pnt3DList1 = new List<Pnt3D>();
    int num = 3;
    if (!Properties.XYZMode)
      num = 2;
    for (int index = 0; index <= CoordinateList.Count - 1; ++index)
    {
      string[] strArray = (!Properties.TxtFileIsSeperatorCharSpace ? CoordinateList[index].Replace(Properties.TxtFileSeperatorChar, ";") : CoordinateList[index].Replace("\t0", ";").Replace("\t1", ";").Replace("\t", ";")).Split(';');
      if (strArray != null)
      {
        if (strArray.Length >= num)
        {
          double x = 0.0;
          double y = 0.0;
          double z = 0.0;
          if (buNumeric.IsNumeric(strArray[0]))
            x = double.Parse(strArray[0]);
          if (buNumeric.IsNumeric(strArray[1]))
            y = double.Parse(strArray[1]);
          if (strArray.Length >= 3 && buNumeric.IsNumeric(strArray[2]))
            z = double.Parse(strArray[2]);
          Pnt3D pnt3D = new Pnt3D(x, y, z);
          if (Properties.CreateMesh)
          {
            if (pnt3DList1.Count == 0)
              pnt3DList1.Add(pnt3D);
            else if (buCompare.EQ(pnt3DList1[pnt3DList1.Count - 1].Y, pnt3D.Y))
            {
              pnt3DList1.Add(pnt3D);
            }
            else
            {
              GridPoints.Add(pnt3DList1);
              pnt3DList1 = new List<Pnt3D>();
              pnt3DList1.Add(pnt3D);
            }
          }
          if (!Properties.CreateMesh)
            pnt3DList1.Add(pnt3D);
        }
        else if (pnt3DList1.Count > 0)
        {
          GridPoints.Add(pnt3DList1);
          pnt3DList1 = new List<Pnt3D>();
        }
      }
      else if (pnt3DList1.Count > 0)
      {
        GridPoints.Add(pnt3DList1);
        pnt3DList1 = new List<Pnt3D>();
      }
    }
    List<Pnt3D> pnt3DList2;
    if (Properties.CreateMesh)
    {
      if (pnt3DList1.Count <= 0)
        return;
      GridPoints.Add(pnt3DList1);
      pnt3DList2 = new List<Pnt3D>();
    }
    else
    {
      if (pnt3DList1.Count <= 0)
        return;
      GridPoints.Add(pnt3DList1);
      pnt3DList2 = new List<Pnt3D>();
    }
  }

