    this.Hatch(AreaPoints, new List<List<Pnt3D>>(), GridDistance.Y, 0.0, 0.0, 0.0, false, 0.0, HatchType.Vertical, HatchSortType.ByClosestLength, VerticalDirectionType.DownToUp, HorizontalDirectionType.LeftToRight, new WorkPlane(), 0.0, 0.0, false, ref HatchLines2, ref HatchEntities2);
    for (int index = 0; index <= HatchLines1.Count - 1; ++index)
    {
      List<Pnt3D> CopiedPnt = new List<Pnt3D>();
      Pnt3D.Copy(HatchLines1[index].Vertice, ref CopiedPnt);
      XVectorSurfPoint.Add(CopiedPnt);
    }
    for (int index = 0; index <= HatchLines2.Count - 1; ++index)
    {
      List<Pnt3D> CopiedPnt = new List<Pnt3D>();
      Pnt3D.Copy(HatchLines2[index].Vertice, ref CopiedPnt);
      YVectorSurfPoint.Add(CopiedPnt);
    }
  }

  public void GridFromBoxsize(
    Pnt3D MinPoint,
    Pnt3D MaxPoint,
    Vec3D Distances,
    ref List<List<Pnt3D>> XVectorSurfPoint,
    ref List<List<Pnt3D>> YVectorSurfPoint)
  {
    this.GridFromBoxsize(MinPoint, MaxPoint, Distances, 0.0, true, true, false, ref XVectorSurfPoint, ref YVectorSurfPoint);
  }

  public void GridFromBoxsize(
    Pnt3D MinPoint,
    Pnt3D MaxPoint,
    Vec3D Distances,
    double ZValue,
    bool XEnable,
    bool YEnable,
    bool DevideLines,
    ref List<List<Pnt3D>> XVectorSurfPoint,
    ref List<List<Pnt3D>> YVectorSurfPoint)
  {
    List<Pnt3D> Vertices = new List<Pnt3D>();
    List<eEntities> HatchLines1 = new List<eEntities>();
    List<eEntities> HatchLines2 = new List<eEntities>();
    List<List<eEntities>> HatchEntities1 = new List<List<eEntities>>();
    List<List<eEntities>> HatchEntities2 = new List<List<eEntities>>();
    this.RectangleCorner(MinPoint, MaxPoint, new WorkPlane(), ref Vertices);
    if (XEnable)
      this.Hatch(Vertices, new List<List<Pnt3D>>(), Distances.X, 0.0, 0.0, 0.0, false, 0.0, HatchType.Horizontal, HatchSortType.ByClosestLength, VerticalDirectionType.DownToUp, HorizontalDirectionType.LeftToRight, new WorkPlane(), 0.0, 0.0, false, ref HatchLines1, ref HatchEntities1);
    if (YEnable)
      this.Hatch(Vertices, new List<List<Pnt3D>>(), Distances.Y, 0.0, 0.0, 0.0, false, 0.0, HatchType.Vertical, HatchSortType.ByClosestLength, VerticalDirectionType.DownToUp, HorizontalDirectionType.LeftToRight, new WorkPlane(), 0.0, 0.0, false, ref HatchLines2, ref HatchEntities2);
    XVectorSurfPoint.Clear();
    XVectorSurfPoint = new List<List<Pnt3D>>();
    YVectorSurfPoint.Clear();
    YVectorSurfPoint = new List<List<Pnt3D>>();
    if (YEnable)
    {
      for (int index1 = 0; index1 <= HatchLines1.Count - 1; ++index1)
      {
        List<Pnt3D> Points = new List<Pnt3D>();
        Pnt3D pnt3D1 = new Pnt3D(HatchLines1[index1].Vertice[0]);
        Pnt3D pnt3D2 = new Pnt3D(HatchLines1[index1].Vertice[1]);
        Pnt3D pnt3D3 = new Pnt3D();
        Pnt3D pnt3D4 = new Pnt3D();
        if (index1 <= HatchLines1.Count - 2)
        {
          Pnt3D pnt3D5 = new Pnt3D(HatchLines1[index1 + 1].Vertice[0]);
          Pnt3D pnt3D6 = new Pnt3D(HatchLines1[index1 + 1].Vertice[1]);
        }
        Points.Add(new Pnt3D(pnt3D1));
        for (int index2 = 0; index2 <= HatchLines2.Count - 1; ++index2)
        {
          bool IsLineIntersect = false;
          bool IsIntersecPointInsideLines = false;
          Pnt3D IntersectionPoint = new Pnt3D();
          this.LineLineIntersection(new Pnt3D(HatchLines2[index2].Vertice[0]), new Pnt3D(HatchLines2[index2].Vertice[1]), pnt3D1, pnt3D2, new WorkPlane(), ref IntersectionPoint, ref IsLineIntersect, ref IsIntersecPointInsideLines);
          if (IsLineIntersect & IsIntersecPointInsideLines)
            Points.Add(new Pnt3D(IntersectionPoint.X, IntersectionPoint.Y));
        }
        Points.Add(new Pnt3D(pnt3D2));
        this.CheckDuplicatedPointsWithPrevious(ref Points);
        XVectorSurfPoint.Add(Points);
      }
    }
    else
    {
      for (int index = 0; index <= HatchLines1.Count - 1; ++index)
      {
        if (!DevideLines)
        {
          XVectorSurfPoint.Add(new List<Pnt3D>()
          {
            new Pnt3D(HatchLines1[index].Vertice[0]),
            new Pnt3D(HatchLines1[index].Vertice[1])
          });
        }
        else
        {
          List<Pnt3D> Points = new List<Pnt3D>();
          this.EntitiesToPoint((eEntities) new eLine(new Pnt3D(HatchLines1[index].Vertice[0]), new Pnt3D(HatchLines1[index].Vertice[1])), new EntitiesResolution()
          {
            LineResolution = {
              ResolutionTypes = EntityResolutionType.ByLength,
              GeometricLength = Distances.Y
            }
          }, ref Points);
          XVectorSurfPoint.Add(Points);
        }
      }
    }
    if (XEnable)
    {
      for (int index3 = 0; index3 <= HatchLines2.Count - 1; ++index3)
      {
        List<Pnt3D> Points = new List<Pnt3D>();
        Pnt3D pnt3D7 = new Pnt3D(HatchLines2[index3].Vertice[0]);
        Pnt3D pnt3D8 = new Pnt3D(HatchLines2[index3].Vertice[1]);
        Points.Add(new Pnt3D(pnt3D7));
        for (int index4 = 0; index4 <= HatchLines1.Count - 1; ++index4)
        {
          bool IsLineIntersect = false;
          bool IsIntersecPointInsideLines = false;
          Pnt3D IntersectionPoint = new Pnt3D();
          this.LineLineIntersection(new Pnt3D(HatchLines1[index4].Vertice[0]), new Pnt3D(HatchLines1[index4].Vertice[1]), pnt3D7, pnt3D8, new WorkPlane(), ref IntersectionPoint, ref IsLineIntersect, ref IsIntersecPointInsideLines);
          if (IsLineIntersect & IsIntersecPointInsideLines)
            Points.Add(new Pnt3D(IntersectionPoint.X, IntersectionPoint.Y));
        }
        Points.Add(new Pnt3D(pnt3D8));
        this.CheckDuplicatedPointsWithPrevious(ref Points);
        YVectorSurfPoint.Add(Points);
      }
    }
    else
    {
      for (int index = 0; index <= HatchLines2.Count - 1; ++index)
      {
        if (!DevideLines)
        {
          YVectorSurfPoint.Add(new List<Pnt3D>()
          {
            new Pnt3D(HatchLines2[index].Vertice[0]),
            new Pnt3D(HatchLines2[index].Vertice[1])
          });
        }
        else
        {
          List<Pnt3D> Points = new List<Pnt3D>();
          this.EntitiesToPoint((eEntities) new eLine(new Pnt3D(HatchLines2[index].Vertice[0]), new Pnt3D(HatchLines2[index].Vertice[1])), new EntitiesResolution()
          {
            LineResolution = {
              ResolutionTypes = EntityResolutionType.ByLength,
              GeometricLength = Distances.Y
            }
          }, ref Points);
          YVectorSurfPoint.Add(Points);
        }
      }
    }
    if (XVectorSurfPoint.Count > 0)
      this.Move(new Pnt3D(), new Pnt3D(0.0, 0.0, ZValue), ref XVectorSurfPoint);
    if (YVectorSurfPoint.Count <= 0)
      return;
    this.Move(new Pnt3D(), new Pnt3D(0.0, 0.0, ZValue), ref YVectorSurfPoint);
  }

  public void SurfaceBsplineKnotVector(
    List<Pnt3D>[] ControlPoints,
    double du,
    double dw,
    ref List<Triangle3D> Triangles,
    ref List<Pnt3D>[] GridPoints)
  {
    List<int> KnotVector1 = new List<int>();
    List<int> KnotVector2 = new List<int>();
    List<double> BasisFunctions1 = new List<double>();
    List<double> BasisFunctions2 = new List<double>();
    List<Pnt3D> pnt3DList = new List<Pnt3D>();
    Pnt3D pnt3D = new Pnt3D();
    int num1 = 0;
    pnt3DList.Clear();
    int int32_1 = Convert.ToInt32(1.0 / du);
    int int32_2 = Convert.ToInt32(1.0 / dw);
    buVector.KnotBSpline(ControlPoints.Length, ControlPoints.Length, KnotVector1);
    GridPoints = new List<Pnt3D>[int32_1 + 1];
    for (int index1 = 0; index1 <= int32_1; ++index1)
    {
      GridPoints[index1] = new List<Pnt3D>();
      double Parameter1 = (double) index1 * du;
      for (int index2 = 0; index2 <= int32_2; ++index2)
      {
        double num2 = (double) index2 * dw;
        double Parameter2 = num1 % 2 != 0 ? 1.0 - (double) index2 * dw : (double) index2 * dw;
        buVector.BasisBSpline(ControlPoints.Length, Parameter1, ControlPoints.Length, KnotVector1, BasisFunctions1);
        double num3 = 0.0;
        double num4 = 0.0;
        double num5 = 0.0;
        for (int index3 = 0; index3 <= ControlPoints.Length - 1; ++index3)
        {
          if (BasisFunctions1[index3] != 0.0)
          {
            buVector.KnotBSpline(ControlPoints[index3].Count, ControlPoints[index3].Count, KnotVector2);
            buVector.BasisBSpline(ControlPoints[index3].Count, Parameter2, ControlPoints[index3].Count, KnotVector2, BasisFunctions2);
            for (int index4 = 0; index4 <= ControlPoints[index3].Count - 1; ++index4)
            {
              if (BasisFunctions2[index4] != 0.0)
              {
                num3 += ControlPoints[index3][index4].X * BasisFunctions1[index3] * BasisFunctions2[index4];
                num4 += ControlPoints[index3][index4].Y * BasisFunctions1[index3] * BasisFunctions2[index4];
                num5 += ControlPoints[index3][index4].Z * BasisFunctions1[index3] * BasisFunctions2[index4];
              }
            }
          }
        }
        pnt3D.X = num3;
        pnt3D.Y = num4;
        pnt3D.Z = num5;
        pnt3DList.Add(pnt3D);
        GridPoints[index1].Add(pnt3D);
      }
      if (num1 % 2 == 0)
        GridPoints[index1].Reverse();
      if (index1 > 0)
      {
        for (int index5 = 1; index5 <= GridPoints[index1].Count - 1; ++index5)
        {
          Quad3D Quad = new Quad3D();
          Triangle3D FirstTriangle = new Triangle3D();
          Triangle3D SecondTriangle = new Triangle3D();
          Quad.FirstPoint = GridPoints[index1 - 1][index5 - 1];
          Quad.SecondPoint = GridPoints[index1 - 1][index5];
          Quad.ThirdPoint = GridPoints[index1][index5];
          Quad.FourthPoint = GridPoints[index1][index5 - 1];
          this.QuadToTriangle(Quad, ref FirstTriangle, ref SecondTriangle);
          Triangles.Add(FirstTriangle);
          Triangles.Add(SecondTriangle);
        }
      }
      ++num1;
    }
  }

  public void SurfaceBsplineRationalKnotVector(
    List<Pnt3D>[] ControlPoints,
    List<double>[] Weigths,
    double du,
    double dw,
    ref List<Triangle3D> Triangles,
