                num4 += ControlPoints[index3][index4].Y * doubleList1[index3] * doubleList2[index4];
                num5 += ControlPoints[index3][index4].Z * doubleList1[index3] * doubleList2[index4] / num6;
              }
            }
          }
        }
        pnt3D.X = num3;
        pnt3D.Y = num4;
        pnt3D.Z = num5;
        pnt3DList.Add(pnt3D);
        GridPoints[index1].Add(pnt3D);
      }
      if (num1 % 2 == 0)
        GridPoints[index1].Reverse();
