  public void SurfaceExtrudeByPoints(
    List<Pnt3D> Points,
    Vec3D Direction,
    double Length,
    bool CloseSides,
    ref List<Triangle3D> Triangles)
  {
    List<List<Pnt3D>> ProfilePoints = new List<List<Pnt3D>>();
    this.SurfaceExtrudeByPoints(Points, Direction, Length, CloseSides, ref Triangles, ref ProfilePoints);
  }

  public void SurfaceExtrudeByPoints(
    List<Pnt3D> Points,
    Vec3D Direction,
    double Length,
    bool CloseSides,
    ref List<Triangle3D> Triangles,
    ref List<List<Pnt3D>> ProfilePoints)
  {
    bool flag = this.IsClosed(Points);
    double Angle = this.PointAngle(new Pnt3D(Direction.X, Direction.Y, Direction.Z), new Pnt3D());
    Vec3D vec3D = new Vec3D();
    Vec3D.Normalise(Direction);
    OrientationAngle orientationAngle = new OrientationAngle();
    this.Vector3dToOrientationAngle(Direction);
    ProfilePoints.Clear();
    ProfilePoints = new List<List<Pnt3D>>();
    for (int index = 1; index <= Points.Count - 1; ++index)
    {
      List<Pnt3D> pnt3DList = new List<Pnt3D>();
      Triangle3D FirstTriangle = new Triangle3D();
      Triangle3D SecondTriangle = new Triangle3D();
      Pnt3D EndPnt1 = new Pnt3D();
      Pnt3D EndPnt2 = new Pnt3D();
      this.LineWithLengthAndAngle(Points[index - 1], Length, Angle, new WorkPlane(), ref EndPnt1);
      this.LineWithLengthAndAngle(Points[index], Length, Angle, new WorkPlane(), ref EndPnt2);
      Quad3D Quad = new Quad3D(Points[index - 1], Points[index], EndPnt2, EndPnt1);
      if (index == 1)
      {
        pnt3DList.Add(new Pnt3D(Points[index - 1]));
        pnt3DList.Add(new Pnt3D(EndPnt1));
        ProfilePoints.Add(pnt3DList);
      }
      ProfilePoints.Add(new List<Pnt3D>()
      {
        new Pnt3D(Points[index]),
        new Pnt3D(EndPnt2)
      });
      this.QuadToTriangle(Quad, ref FirstTriangle, ref SecondTriangle);
      Triangles.Add(FirstTriangle);
      Triangles.Add(SecondTriangle);
    }
    if (!(flag & CloseSides))
      return;
    TriangulationPoints calcData = new TriangulationPoints();
    this.SurfaceFromTriangulation(Points, new List<List<Pnt3D>>(), new SurfaceFromXYPlane()
    {
      Height = Length
    }, ref calcData);
    if (calcData.Triangles.Count <= 0)
      return;
    for (int index = 0; index <= calcData.Triangles.Count - 1; ++index)
    {
      Triangle3D triangle3D = new Triangle3D(calcData.Triangles[index]);
      Triangles.Add(triangle3D);
    }
  }

  public void SurfaceProfileFromContour(
    List<Pnt3D> Points,
    Pnt3D RefPoint,
    SurfaceByVector surfData,
    ref List<Triangle3D> Triangles,
    ref List<List<Pnt3D>> ProfilePoints)
  {
    WorkPlane PlaneFound = new WorkPlane();
    Triangles.Clear();
    Triangles = new List<Triangle3D>();
    this.GetPointsPlane(Points, ref PlaneFound);
    if (!this.IsClosed(Points))
    {
      if (surfData.BaseHeight <= 0.0)
      {
        Pnt3D pnt3D = new Pnt3D(Points[0]);
        Points.Add(pnt3D);
      }
      else
      {
        Pnt3D Pnt = new Pnt3D(Points[0]);
        Pnt3D pnt3D = new Pnt3D(Points[Points.Count - 1]);
        if (WorkPlane.isPlaneXY(PlaneFound))
        {
          Pnt.Y -= surfData.BaseHeight;
          pnt3D.Y -= surfData.BaseHeight;
        }
        if (WorkPlane.isPlaneXZ(PlaneFound) | WorkPlane.isPlaneYZ(PlaneFound))
        {
          Pnt.Z -= surfData.BaseHeight;
          pnt3D.Z -= surfData.BaseHeight;
        }
        Points.Insert(0, Pnt);
        Points.Add(pnt3D);
        Points.Add(new Pnt3D(Pnt));
      }
    }
    Pnt3D MinPoint1 = new Pnt3D();
    Pnt3D MaxPoint1 = new Pnt3D();
    Pnt3D MidPoint1 = new Pnt3D();
    this.BoxSizeCalculate(Points, ref MinPoint1, ref MidPoint1, ref MaxPoint1);
    if (WorkPlane.isPlaneXY(PlaneFound) & surfData.Direction == VectorType.YVector)
      this.RotateByMatrix(MinPoint1, 90.0, VectorType.XVector, ref Points);
    if (WorkPlane.isPlaneXY(PlaneFound) & surfData.Direction == VectorType.XVector)
    {
      this.RotateByMatrix(MinPoint1, 90.0, VectorType.XVector, ref Points);
      this.RotateByMatrix(MinPoint1, 90.0, VectorType.ZVector, ref Points);
    }
    if (WorkPlane.isPlaneXZ(PlaneFound) & surfData.Direction == VectorType.ZVector)
      this.RotateByMatrix(MinPoint1, -90.0, VectorType.XVector, ref Points);
    Pnt3D MinPoint2 = new Pnt3D();
    Pnt3D MaxPoint2 = new Pnt3D();
    Pnt3D MidPoint2 = new Pnt3D();
    this.BoxSizeCalculate(Points, ref MinPoint2, ref MidPoint2, ref MaxPoint2);
    this.Move(MinPoint2, RefPoint, ref Points);
    TriangulationPoints triangulationPoints = new TriangulationPoints();
    Vec3D Direction = new Vec3D(1.0, 0.0, 0.0);
    if (surfData.Direction == VectorType.XVector)
      Direction = new Vec3D(1.0, 0.0, 0.0);
    if (surfData.Direction == VectorType.YVector)
      Direction = new Vec3D(0.0, 1.0, 0.0);
    if (surfData.Direction == VectorType.ZVector)
      Direction = new Vec3D(0.0, 0.0, 1.0);
    this.SurfaceExtrudeByPoints(Points, Direction, surfData.Length, true, ref Triangles, ref ProfilePoints);
  }

  public void SurfaceFromContour(
    List<Pnt3D> ContourPoints,
    double XGridDistance,
    double YGridDistance,
    SurfaceFromProfileAndHeight SurfData,
    ref List<List<Pnt3D>> XDirPoints,
    ref List<List<Pnt3D>> YDirPoints)
  {
    Pnt3D MinPoint1 = new Pnt3D();
    Pnt3D MaxPoint1 = new Pnt3D();
    Pnt3D MidPoint = new Pnt3D();
    List<List<Pnt3D>> pts1 = new List<List<Pnt3D>>();
    List<List<Pnt3D>> pts2 = new List<List<Pnt3D>>();
    List<List<Pnt3D>> CopiedPnt1 = new List<List<Pnt3D>>();
    List<List<Pnt3D>> CopiedPnt2 = new List<List<Pnt3D>>();
    List<Pnt3D> pnt3DList = new List<Pnt3D>();
    List<List<Pnt4D>> pnt4DListList1 = new List<List<Pnt4D>>();
    List<List<Pnt4D>> pnt4DListList2 = new List<List<Pnt4D>>();
    XDirPoints = new List<List<Pnt3D>>();
    YDirPoints = new List<List<Pnt3D>>();
    this.BoxSizeCalculate(ContourPoints, ref MinPoint1, ref MaxPoint1);
    double z = MinPoint1.Z;
    this.GridFromBoxsize(MinPoint1, MaxPoint1, new Vec3D(XGridDistance, YGridDistance, 0.0), MinPoint1.Z, true, true, false, ref pts1, ref pts2);
    Pnt3D.Copy(pts1, ref CopiedPnt1);
    Pnt3D.Copy(pts2, ref CopiedPnt2);
    for (int index1 = 0; index1 <= CopiedPnt1.Count - 1; ++index1)
    {
      for (int index2 = 0; index2 <= CopiedPnt1[index1].Count - 1; ++index2)
        pnt3DList.Add(new Pnt3D(CopiedPnt1[index1][index2]));
    }
    this.TrimGridPointsFromContourPoints(ContourPoints, ref pts1, ref pts2);
    for (int index3 = 0; index3 <= pts1.Count - 1; ++index3)
    {
      List<Pnt4D> pnt4DList = new List<Pnt4D>();
      Pnt3D MinPoint2 = new Pnt3D();
      Pnt3D MaxPoint2 = new Pnt3D();
      this.BoxSizeCalculate(pts1[index3], ref MinPoint2, ref MidPoint, ref MaxPoint2);
      double num = MidPoint.X - MinPoint2.X;
      for (int index4 = 0; index4 <= pts1[index3].Count - 1; ++index4)
      {
        double w = (pts1[index3][index4].X > MidPoint.X ? MaxPoint2.X - pts1[index3][index4].X : pts1[index3][index4].X - MinPoint2.X) / num;
        Pnt4D pnt4D = new Pnt4D(pts1[index3][index4].X, pts1[index3][index4].Y, pts1[index3][index4].Z, w);
        pnt4DList.Add(pnt4D);
      }
      pnt4DListList1.Add(pnt4DList);
    }
    for (int index5 = 0; index5 <= pts2.Count - 1; ++index5)
    {
      List<Pnt4D> pnt4DList = new List<Pnt4D>();
      Pnt3D MinPoint3 = new Pnt3D();
      Pnt3D MaxPoint3 = new Pnt3D();
      this.BoxSizeCalculate(pts2[index5], ref MinPoint3, ref MidPoint, ref MaxPoint3);
      double num = MidPoint.Y - MinPoint3.Y;
      for (int index6 = 0; index6 <= pts2[index5].Count - 1; ++index6)
      {
        double w = (pts2[index5][index6].Y > MidPoint.Y ? MaxPoint3.Y - pts2[index5][index6].Y : pts2[index5][index6].Y - MinPoint3.Y) / num;
        Pnt4D pnt4D = new Pnt4D(pts2[index5][index6].X, pts2[index5][index6].Y, pts2[index5][index6].Z, w);
        pnt4DList.Add(pnt4D);
      }
      pnt4DListList2.Add(pnt4DList);
    }
    for (int index7 = 0; index7 <= pnt3DList.Count - 1; ++index7)
    {
      bool flag1 = false;
      bool flag2 = false;
      double num1 = 1.0;
      double num2 = 1.0;
      double num3 = 0.0;
      int index8 = -1;
      int index9 = -1;
      int index10 = -1;
      int index11 = -1;
      Pnt3D RefP1 = new Pnt3D(pnt3DList[index7]);
      for (int index12 = 0; index12 <= pnt4DListList1.Count - 1; ++index12)
      {
        for (int index13 = 0; index13 <= pnt4DListList1[index12].Count - 1; ++index13)
        {
          Pnt4D Pnt = new Pnt4D(pnt4DListList1[index12][index13]);
          if (Pnt3D.EqualXY(RefP1, new Pnt3D(Pnt)))
          {
            num1 = Pnt.W;
            flag1 = true;
            index8 = index12;
            index9 = index13;
            goto label_27;
          }
        }
      }
label_27:
      for (int index14 = 0; index14 <= pnt4DListList2.Count - 1; ++index14)
      {
        for (int index15 = 0; index15 <= pnt4DListList2[index14].Count - 1; ++index15)
        {
          Pnt4D Pnt = new Pnt4D(pnt4DListList2[index14][index15]);
          if (Pnt3D.EqualXY(RefP1, new Pnt3D(Pnt)))
          {
            num2 = Pnt.W;
            flag2 = true;
            index10 = index14;
            index11 = index15;
            goto label_35;
          }
        }
      }
label_35:
      if (flag1)
        num3 = num1;
      if (flag2)
        num3 *= num2;
      if (flag1)
        pts1[index8][index9] = new Pnt3D(pts1[index8][index9].X, pts1[index8][index9].Y, num3 * 10.0 + z);
      if (flag2)
        pts2[index10][index11] = new Pnt3D(pts2[index10][index11].X, pts2[index10][index11].Y, num3 * 10.0 + z);
    }
    Pnt3D.Copy(pts1, ref XDirPoints);
    Pnt3D.Copy(pts2, ref YDirPoints);
  }

  public void SurfaceFromTriangulation(
    List<Pnt3D> ContourPoints,
    List<List<Pnt3D>> InnerContour,
    SurfaceFromXYPlane SurfData,
    ref TriangulationPoints calcData)
  {
    TriangulationPoints RefPoint = new TriangulationPoints();
    TriangulationPoints triangulationPoints = new TriangulationPoints();
    Pnt3D pnt3D1 = new Pnt3D(ContourPoints[0]);
    WorkPlane PlaneFound = new WorkPlane();
    this.GetPointsPlane(ContourPoints, ref PlaneFound);
    if (WorkPlane.isPlaneXZ(PlaneFound))
    {
      for (int index = 0; index <= ContourPoints.Count - 1; ++index)
      {
        Pnt3D CalcPoint = new Pnt3D();
        this.PointConversionByPlane(PlaneFound, new WorkPlane(planeType.XY, 1), ContourPoints[index], ref CalcPoint);
        ContourPoints[index] = new Pnt3D(CalcPoint);
      }
    }
    if (WorkPlane.isPlaneYZ(PlaneFound))
    {
      for (int index = 0; index <= ContourPoints.Count - 1; ++index)
      {
        Pnt3D CalcPoint = new Pnt3D();
        this.PointConversionByPlane(PlaneFound, new WorkPlane(planeType.XY, 1), ContourPoints[index], ref CalcPoint);
        ContourPoints[index] = new Pnt3D(CalcPoint);
      }
    }
    calcData = new TriangulationPoints();
    Pnt3D.Copy(ContourPoints, ref RefPoint.Points);
    Pnt3D.Copy(InnerContour, ref RefPoint.Holes);
    this.Triangulation(RefPoint, false, ref calcData);
    if (WorkPlane.isPlaneXZ(PlaneFound) | WorkPlane.isPlaneYZ(PlaneFound))
    {
      for (int index = 0; index <= calcData.Points.Count - 1; ++index)
      {
        Pnt3D CalcPoint = new Pnt3D();
        this.PointConversionByPlane(new WorkPlane(planeType.XY, 1), PlaneFound, calcData.Points[index], ref CalcPoint);
        calcData.Points[index] = new Pnt3D(CalcPoint);
      }
      for (int index1 = 0; index1 <= calcData.Holes.Count - 1; ++index1)
      {
        for (int index2 = 0; index2 <= calcData.Holes[index1].Count - 1; ++index2)
        {
          Pnt3D CalcPoint = new Pnt3D();
          this.PointConversionByPlane(new WorkPlane(planeType.XY, 1), PlaneFound, calcData.Holes[index1][index2], ref CalcPoint);
          calcData.Holes[index1][index2] = new Pnt3D(CalcPoint);
        }
      }
      for (int index = 0; index <= calcData.Triangles.Count - 1; ++index)
      {
        Pnt3D CalcPoint1 = new Pnt3D();
        Pnt3D CalcPoint2 = new Pnt3D();
        Pnt3D CalcPoint3 = new Pnt3D();
        this.PointConversionByPlane(new WorkPlane(planeType.XY, 1), PlaneFound, calcData.Triangles[index].FirstPoint, ref CalcPoint1);
        calcData.Triangles[index].FirstPoint = new Pnt3D(CalcPoint1);
        this.PointConversionByPlane(new WorkPlane(planeType.XY, 1), PlaneFound, calcData.Triangles[index].SecondPoint, ref CalcPoint2);
        calcData.Triangles[index].SecondPoint = new Pnt3D(CalcPoint2);
        this.PointConversionByPlane(new WorkPlane(planeType.XY, 1), PlaneFound, calcData.Triangles[index].ThirdPoint, ref CalcPoint3);
        calcData.Triangles[index].ThirdPoint = new Pnt3D(CalcPoint3);
      }
      if (WorkPlane.isPlaneYZ(PlaneFound))
      {
        Pnt3D pnt3D2 = new Pnt3D(calcData.Points[0]);
        this.Move(new Pnt3D(pnt3D2.X, 0.0), new Pnt3D(pnt3D1.X, 0.0), ref calcData.Points);
        this.Move(new Pnt3D(pnt3D2.X, 0.0), new Pnt3D(pnt3D1.X, 0.0), ref calcData.Holes);
        this.Move(new Pnt3D(pnt3D2.X, 0.0), new Pnt3D(pnt3D1.X, 0.0), ref calcData.Triangles);
      }
      if (WorkPlane.isPlaneXZ(PlaneFound))
      {
        Pnt3D pnt3D3 = new Pnt3D(calcData.Points[0]);
        this.Move(new Pnt3D(0.0, pnt3D3.Y, 0.0), new Pnt3D(0.0, pnt3D1.Y, 0.0), ref calcData.Points);
        this.Move(new Pnt3D(0.0, pnt3D3.Y, 0.0), new Pnt3D(0.0, pnt3D1.Y, 0.0), ref calcData.Holes);
        this.Move(new Pnt3D(0.0, pnt3D3.Y, 0.0), new Pnt3D(0.0, pnt3D1.Y, 0.0), ref calcData.Triangles);
      }
    }
    List<Triangle3D> CopiedPnt = new List<Triangle3D>();
    Triangle3D.Copy(calcData.Triangles, ref CopiedPnt);
    if (SurfData.Height == 0.0)
      return;
    if (WorkPlane.isPlaneXY(PlaneFound))
    {
      for (int index = 0; index <= CopiedPnt.Count - 1; ++index)
      {
        Triangle3D Triangle = new Triangle3D(CopiedPnt[index]);
        this.Move(new Pnt3D(), new Pnt3D(0.0, 0.0, SurfData.Height), ref Triangle);
        calcData.Triangles.Add(Triangle);
      }
      List<Pnt3D> SecondVertice = new List<Pnt3D>();
      Pnt3D.Copy(calcData.Points, ref SecondVertice);
      Pnt3D.Offset(ref SecondVertice, 0.0, 0.0, SurfData.Height);
      List<Triangle3D> SurfaceTriangles = new List<Triangle3D>();
      this.SurfaceWithTwoVerticeList(calcData.Points, SecondVertice, ref SurfaceTriangles);
      Triangle3D.Add(SurfaceTriangles, ref calcData.Triangles);
    }
    if (WorkPlane.isPlaneXZ(PlaneFound))
    {
      for (int index = 0; index <= CopiedPnt.Count - 1; ++index)
      {
        Triangle3D Triangle = new Triangle3D(CopiedPnt[index]);
        this.Move(new Pnt3D(), new Pnt3D(0.0, SurfData.Height, 0.0), ref Triangle);
        calcData.Triangles.Add(Triangle);
      }
      List<Pnt3D> SecondVertice = new List<Pnt3D>();
      Pnt3D.Copy(calcData.Points, ref SecondVertice);
      Pnt3D.Offset(ref SecondVertice, 0.0, SurfData.Height, 0.0);
      List<Triangle3D> SurfaceTriangles = new List<Triangle3D>();
      this.SurfaceWithTwoVerticeList(calcData.Points, SecondVertice, ref SurfaceTriangles);
      Triangle3D.Add(SurfaceTriangles, ref calcData.Triangles);
    }
    if (!WorkPlane.isPlaneYZ(PlaneFound))
      return;
    for (int index = 0; index <= CopiedPnt.Count - 1; ++index)
    {
      Triangle3D Triangle = new Triangle3D(CopiedPnt[index]);
      this.Move(new Pnt3D(), new Pnt3D(SurfData.Height, 0.0, 0.0), ref Triangle);
      calcData.Triangles.Add(Triangle);
    }
    List<Pnt3D> SecondVertice1 = new List<Pnt3D>();
    Pnt3D.Copy(calcData.Points, ref SecondVertice1);
    Pnt3D.Offset(ref SecondVertice1, SurfData.Height, 0.0, 0.0);
    List<Triangle3D> SurfaceTriangles1 = new List<Triangle3D>();
    this.SurfaceWithTwoVerticeList(calcData.Points, SecondVertice1, ref SurfaceTriangles1);
    Triangle3D.Add(SurfaceTriangles1, ref calcData.Triangles);
  }

  public void TrimGridPointsFromContourPoints(
    List<Pnt3D> ContourPoints,
    ref List<List<Pnt3D>> XDirPoints,
    ref List<List<Pnt3D>> YDirPoints)
  {
    List<List<Pnt3D>> pts1 = new List<List<Pnt3D>>();
    List<List<Pnt3D>> pts2 = new List<List<Pnt3D>>();
    for (int index1 = 0; index1 <= XDirPoints.Count - 1; ++index1)
    {
      List<Pnt3D> Points = new List<Pnt3D>();
      for (int index2 = 0; index2 <= XDirPoints[index1].Count - 1; ++index2)
      {
        Pnt3D RefPoint = new Pnt3D(XDirPoints[index1][index2]);
        if (this.IsPointInsidePolygon(ContourPoints, RefPoint, true))
          Points.Add(RefPoint);
      }
      if (Points.Count > 0)
      {
        for (int index3 = 1; index3 <= ContourPoints.Count - 1; ++index3)
        {
          Pnt3D IntersectionPoint1 = new Pnt3D();
          this.LineLineIntersection(ContourPoints[index3 - 1], ContourPoints[index3], Points[0], Points[1], new WorkPlane(), ref IntersectionPoint1);
          if (this.IsPointOverAndInsideLine(ContourPoints[index3 - 1], ContourPoints[index3], IntersectionPoint1, new WorkPlane(), 0.01) && IntersectionPoint1.X < Points[0].X)
            Points.Insert(0, IntersectionPoint1);
          Pnt3D IntersectionPoint2 = new Pnt3D();
          this.LineLineIntersection(ContourPoints[index3 - 1], ContourPoints[index3], Points[Points.Count - 2], Points[Points.Count - 1], new WorkPlane(), ref IntersectionPoint2);
          if (this.IsPointOverAndInsideLine(ContourPoints[index3 - 1], ContourPoints[index3], IntersectionPoint2, new WorkPlane(), 0.01) && IntersectionPoint2.X > Points[Points.Count - 1].X)
            Points.Add(IntersectionPoint2);
        }
      }
      this.CheckDuplicatedPointsWithPrevious(ref Points);
      if (Points.Count > 1)
        pts1.Add(Points);
    }
    for (int index4 = 0; index4 <= YDirPoints.Count - 1; ++index4)
    {
      List<Pnt3D> Points = new List<Pnt3D>();
      for (int index5 = 0; index5 <= YDirPoints[index4].Count - 1; ++index5)
      {
        Pnt3D RefPoint = new Pnt3D(YDirPoints[index4][index5]);
        if (this.IsPointInsidePolygon(ContourPoints, RefPoint))
          Points.Add(RefPoint);
      }
      if (Points.Count > 0)
      {
        for (int index6 = 1; index6 <= ContourPoints.Count - 1; ++index6)
        {
          Pnt3D IntersectionPoint3 = new Pnt3D();
          this.LineLineIntersection(ContourPoints[index6 - 1], ContourPoints[index6], Points[0], Points[1], new WorkPlane(), ref IntersectionPoint3);
          if (this.IsPointOverAndInsideLine(ContourPoints[index6 - 1], ContourPoints[index6], IntersectionPoint3, new WorkPlane(), 0.01) && IntersectionPoint3.Y < Points[0].Y)
            Points.Insert(0, IntersectionPoint3);
          Pnt3D IntersectionPoint4 = new Pnt3D();
          this.LineLineIntersection(ContourPoints[index6 - 1], ContourPoints[index6], Points[Points.Count - 2], Points[Points.Count - 1], new WorkPlane(), ref IntersectionPoint4);
          if (this.IsPointOverAndInsideLine(ContourPoints[index6 - 1], ContourPoints[index6], IntersectionPoint4, new WorkPlane(), 0.01) && IntersectionPoint4.Y > Points[Points.Count - 1].Y)
            Points.Add(IntersectionPoint4);
        }
      }
      this.CheckDuplicatedPointsWithPrevious(ref Points);
      if (Points.Count > 1)
        pts2.Add(Points);
    }
    XDirPoints.Clear();
    XDirPoints = new List<List<Pnt3D>>();
    YDirPoints.Clear();
    YDirPoints = new List<List<Pnt3D>>();
    Pnt3D.Copy(pts1, ref XDirPoints);
    Pnt3D.Copy(pts2, ref YDirPoints);
  }

  public void SurfaceRevolve(
    List<Pnt3D> RefPoints,
    Pnt3D RotatePoint,
    double StartAngle,
    double EndAngle,
    double AngleResolution,
    Vec3D RevolveDir,
    EntityResolution EntityResolution,
    ref List<Triangle3D> calcTriangles)
  {
    List<List<Pnt3D>> calcRevolvePoints = new List<List<Pnt3D>>();
    this.SurfaceRevolve(RefPoints, RotatePoint, StartAngle, EndAngle, AngleResolution, RevolveDir, EntityResolution, ref calcRevolvePoints, ref calcTriangles);
  }

  public void SurfaceRevolve(
    List<Pnt3D> RefPoints,
    Pnt3D RotatePoint,
    double StartAngle,
    double EndAngle,
    double AngleResolution,
    Vec3D RevolveDir,
    EntityResolution EntityResolution,
    ref List<List<Pnt3D>> calcRevolvePoints,
    ref List<Triangle3D> calcTriangles)
  {
    WorkPlane PlaneFound = new WorkPlane();
    List<Pnt3D> pnt3DList = new List<Pnt3D>();
    calcRevolvePoints.Clear();
    calcTriangles.Clear();
    if (StartAngle > EndAngle)
      return;
    double num1 = EndAngle - StartAngle;
    int int32 = Convert.ToInt32(buNumeric.RoundToUpper(num1 / AngleResolution));
    double num2 = num1 / Convert.ToDouble(int32);
    Pnt3D.Copy(RefPoints, ref pnt3DList);
    this.GetPointsPlane(RefPoints, ref PlaneFound);
    Pnt3D MinPoint = new Pnt3D();
    Pnt3D MaxPoint = new Pnt3D();
    Pnt3D MidPoint = new Pnt3D();
    if (Vec3D.isVectorZAxis(RevolveDir))
    {
      this.RotateByMatrix(MinPoint, 90.0, VectorType.YVector, ref pnt3DList);
      this.RotateByMatrix(MinPoint, 90.0, VectorType.XVector, ref pnt3DList);
    }
    this.BoxSizeCalculate(pnt3DList, ref MinPoint, ref MidPoint, ref MaxPoint);
    this.Move(pnt3DList[0], new Pnt3D(), ref pnt3DList);
    for (int index = 0; index <= int32; ++index)
    {
      List<Pnt3D> CalcPoints = new List<Pnt3D>();
      if (Vec3D.isVectorYAxis(RevolveDir))
      {
        this.Rotate(RotatePoint, (double) index * num2, new WorkPlane(planeType.XZ, 1), pnt3DList, ref CalcPoints);
        calcRevolvePoints.Add(CalcPoints);
      }
      if (Vec3D.isVectorZAxis(RevolveDir))
      {
        this.Rotate(RotatePoint, (double) index * num2, new WorkPlane(planeType.XY, 1), pnt3DList, ref CalcPoints);
        calcRevolvePoints.Add(CalcPoints);
      }
      if (index > 0)
      {
        List<Triangle3D> SurfaceTriangles = new List<Triangle3D>();
        this.SurfaceWithTwoVerticeList(calcRevolvePoints[calcRevolvePoints.Count - 2], calcRevolvePoints[calcRevolvePoints.Count - 1], ref SurfaceTriangles);
        calcTriangles.AddRange((IEnumerable<Triangle3D>) SurfaceTriangles);
      }
    }
  }

  public void WrapPointToCircle(
    double Radius,
    Pnt3D CenterPoint,
    WrapShapeParameter Pars,
    List<Pnt3D> RefPoints,
    ref List<Pnt3D> WrapedPoints)
  {
    if (RefPoints == null || RefPoints.Count == 0)
      return;
    List<Pnt4D> Vertices = new List<Pnt4D>();
    List<Pnt3D> pnt3DList = new List<Pnt3D>();
    EntityResolution EntResolution = new EntityResolution(0.05, 10, 10.0, EntityResolutionType.ByLength);
    this.CircleWithCenter(CenterPoint, Radius, new WorkPlane(planeType.XY, 1), EntResolution, ref Vertices);
    WrapedPoints = new List<Pnt3D>();
    if (Pars.CenterVector != VectorType.YVector)
      return;
    for (int index = 0; index <= RefPoints.Count - 1; ++index)
    {
      double calcAngle = 0.0;
      this.CirclePointAngleByLenght(Radius, RefPoints[index].X, ref calcAngle);
      double y = RefPoints[index].Y;
      double x = Radius * Math.Cos(buConversion.DegreeToRadian(calcAngle));
      double z = Radius * Math.Sin(buConversion.DegreeToRadian(calcAngle));
      Pnt3D pnt3D = new Pnt3D(x, y, z);
      WrapedPoints.Add(pnt3D);
    }
  }

  public void WrapPointToEllipse(
    double MajorRadius,
    double MinorRadius,
    Pnt3D CenterPoint,
    WrapShapeParameter Pars,
    List<List<Pnt3D>> RefPoints,
    double Resolution,
    ref List<List<Pnt3D>> WrapedPoints)
  {
    if (RefPoints == null || RefPoints.Count == 0)
      return;
    WrapedPoints = new List<List<Pnt3D>>();
    for (int index = 0; index <= RefPoints.Count - 1; ++index)
    {
      List<Pnt3D> CopiedPnt = new List<Pnt3D>();
      List<Pnt3D> WrapedPoints1 = new List<Pnt3D>();
      Pnt3D.Copy(RefPoints[index], ref CopiedPnt);
      this.WrapPointToEllipse(MajorRadius, MinorRadius, CenterPoint, Pars, CopiedPnt, Resolution, ref WrapedPoints1);
      WrapedPoints.Add(WrapedPoints1);
    }
  }

  public void WrapPointToEllipse(
    double MajorRadius,
    double MinorRadius,
    Pnt3D CenterPoint,
    WrapShapeParameter Pars,
    List<Pnt3D> RefPoints,
    double Resolution,
    ref List<Pnt3D> WrapedPoints)
  {
    if (RefPoints == null || RefPoints.Count == 0)
      return;
    List<Pnt4D> pnt4DList = new List<Pnt4D>();
    List<Pnt3D> pnt3DList = new List<Pnt3D>();
    EntityResolution entityResolution = new EntityResolution(0.05, 10, 10.0, EntityResolutionType.ByLength);
    WrapedPoints = new List<Pnt3D>();
    if (Pars.CenterVector != VectorType.YVector)
      return;
    for (int index = 0; index <= RefPoints.Count - 1; ++index)
    {
      double calcAngle = 0.0;
      this.EllipsePointAngleByLenght(MajorRadius, MinorRadius, 0.0, RefPoints[index].X, Resolution, ref calcAngle);
      double num1 = 2.0 * Math.PI;
      double num2 = Math.Sin(num1);
      double num3 = Math.Cos(num1);
      double radianGreat360 = buConversion.DegreeToRadianGreat360(calcAngle);
      double num4 = MajorRadius * Math.Cos(radianGreat360);
      double y = RefPoints[index].Y;
      double num5 = MinorRadius * Math.Sin(radianGreat360);
      Pnt3D pnt3D = new Pnt3D();
      pnt3D.X = CenterPoint.X + num4 * num3 + num5 * num2;
      pnt3D.Y = y;
      pnt3D.Z = CenterPoint.Z - num4 * num2 + num5 * num3;
      WrapedPoints.Add(pnt3D);
    }
  }

  public void CreatEntityFromShapeData(ShapeData Data, WorkPlane Plane, ref eEntities Entity)
  {
    if (Data.GetType() == typeof (PointData))
    {
      PointData pointData1 = new PointData();
      PointData pointData2 = (PointData) Data;
      Entity = (eEntities) new ePoint(pointData2.StartPoint);
      Entity.Shape = new ShapeData();
      ShapeData.Copy(Data, ref Entity.Shape);
    }
    if (Data.GetType() == typeof (LineData))
    {
      LineData lineData1 = new LineData();
      LineData lineData2 = (LineData) Data;
      List<Pnt3D> pnt3DList = new List<Pnt3D>();
      Pnt3D EndPnt = new Pnt3D();
      this.LineWithLengthAndAngle(lineData2.StartPoint, lineData2.Length, lineData2.Angle, Plane, ref EndPnt);
      lineData2.EndPoint = new Pnt3D(EndPnt);
      Entity = (eEntities) new eLine(lineData2.StartPoint, EndPnt);
      Entity.Shape = new ShapeData();
      ShapeData.Copy(Data, ref Entity.Shape);
    }
    if (Data.GetType() == typeof (RectangleCornerData))
    {
