  {
    try
    {
      for (int index1 = 0; index1 <= SelectedIndex.Count - 1; ++index1)
      {
        for (int index2 = RefEntities.Count - 1; index2 >= 0; --index2)
        {
          if (RefEntities[index2].GetType() == typeof (eCam) && ((eCam) RefEntities[index2]).BaseEntityIndex == SelectedIndex[index1])
