    }
  }

  public void CreateSurfaceGridFromTeachFile(
    SurfaceReadGridData Data,
    List<Pnt3D> TeachData,
    ref List<List<Pnt3D>> GridData)
  {
    Pnt3D MinPoint = new Pnt3D();
    Pnt3D MaxPoint = new Pnt3D();
    this.BoxSizeCalculate(TeachData, ref MinPoint, ref MaxPoint);
    List<List<Pnt3D>> pnt3DListList = new List<List<Pnt3D>>();
    List<List<Pnt3D>> YVectorSurfPoint = new List<List<Pnt3D>>();
    this.GridFromBoxsize(MinPoint, MaxPoint, new Vec3D(Data.GridDistance.X, Data.GridDistance.Y), 0.0, true, false, true, ref GridData, ref YVectorSurfPoint);
    for (int index = 0; index <= TeachData.Count - 1; ++index)
    {
      int int32_1 = Convert.ToInt32(TeachData[index].X);
      int int32_2 = Convert.ToInt32(TeachData[index].Y);
      if (int32_2 <= GridData.Count - 1 && int32_1 <= GridData[int32_2].Count - 1)
        GridData[int32_2][int32_1] = new Pnt3D(GridData[int32_2][int32_1].X, GridData[int32_2][int32_1].Y, TeachData[index].Z);
    }
    for (int index1 = 0; index1 <= GridData.Count - 1; ++index1)
    {
      double z1 = 0.0;
      for (int index2 = 0; index2 <= GridData[index1].Count - 1; ++index2)
      {
        if (!buCompare.EQ(GridData[index1][index2].Z, 0.0, 0.001))
        {
          z1 = GridData[index1][index2].Z;
          index2 = GridData[index1].Count;
        }
      }
      List<int> intList = new List<int>();
      for (int index3 = 0; index3 <= GridData[index1].Count - 1; ++index3)
      {
        if (buCompare.EQ(GridData[index1][index3].Z, 0.0, 0.001))
        {
          intList.Add(index3);
          GridData[index1][index3] = new Pnt3D(GridData[index1][index3].X, GridData[index1][index3].Y, z1);
        }
        else
        {
          double z2 = GridData[index1][index3].Z;
          if (intList.Count > 0)
          {
            double num = (z2 - z1) / (double) (intList.Count + 1);
            for (int index4 = 0; index4 <= intList.Count - 1; ++index4)
            {
              int index5 = intList[index4];
              GridData[index1][index5] = new Pnt3D(GridData[index1][index5].X, GridData[index1][index5].Y, GridData[index1][index5].Z + (double) (index4 + 1) * num);
            }
            intList.Clear();
          }
          z1 = GridData[index1][index3].Z;
        }
      }
    }
    if (GridData.Count <= 0)
      return;
    int count = GridData[0].Count;
    for (int index6 = 0; index6 <= count - 1; ++index6)
    {
      double z3 = 0.0;
      for (int index7 = 0; index7 <= GridData.Count - 1; ++index7)
      {
        if (!buCompare.EQ(GridData[index7][index6].Z, 0.0, 0.001))
        {
          z3 = GridData[index7][index6].Z;
          index7 = 2147483645;
        }
      }
      List<int> intList = new List<int>();
      for (int index8 = 0; index8 <= GridData.Count - 1; ++index8)
      {
        if (buCompare.EQ(GridData[index8][index6].Z, 0.0, 0.001))
        {
          intList.Add(index8);
          GridData[index8][index6] = new Pnt3D(GridData[index8][index6].X, GridData[index8][index6].Y, z3);
        }
        else
        {
          double z4 = GridData[index8][index6].Z;
          if (intList.Count > 0)
          {
            double num = (z4 - z3) / (double) (intList.Count + 1);
            for (int index9 = 0; index9 <= intList.Count - 1; ++index9)
            {
              int index10 = intList[index9];
              GridData[index10][index6] = new Pnt3D(GridData[index10][index6].X, GridData[index10][index6].Y, GridData[index10][index6].Z + (double) (index9 + 1) * num);
            }
            intList.Clear();
          }
          z3 = GridData[index8][index6].Z;
        }
      }
    }
  }

  public void EntityEntityTouchPoint(
    eEntities FirstEntity,
    eEntities SecondEntity,
    double Resolution,
    ref bool isTouch,
    ref StartEndType FirstEntityTouchPoint,
    ref StartEndType SecondEntityTouchPoint)
  {
    isTouch = false;
    if (buCompare.EQ(FirstEntity.Vertice[0], SecondEntity.Vertice[0], Resolution))
    {
      FirstEntityTouchPoint = StartEndType.Start;
      SecondEntityTouchPoint = StartEndType.Start;
      isTouch = true;
    }
    if (buCompare.EQ(FirstEntity.Vertice[0], SecondEntity.Vertice[SecondEntity.Vertice.Count - 1], Resolution))
    {
      FirstEntityTouchPoint = StartEndType.Start;
      SecondEntityTouchPoint = StartEndType.End;
      isTouch = true;
    }
    if (buCompare.EQ(FirstEntity.Vertice[FirstEntity.Vertice.Count - 1], SecondEntity.Vertice[0], Resolution))
    {
      FirstEntityTouchPoint = StartEndType.End;
      SecondEntityTouchPoint = StartEndType.Start;
      isTouch = true;
    }
    if (!buCompare.EQ(FirstEntity.Vertice[FirstEntity.Vertice.Count - 1], SecondEntity.Vertice[SecondEntity.Vertice.Count - 1], Resolution))
      return;
    FirstEntityTouchPoint = StartEndType.End;
    SecondEntityTouchPoint = StartEndType.End;
    isTouch = true;
  }

