  public void GetTangentStartAngleOfEntitiyByCamDir(
    eEntities RefEntity,
    WorkPlane Plane,
    ref double TangentAngle)
  {
    double StartAngle = 0.0;
    double EndAngle = 0.0;
    this.GetTangentAngleOfEntity(RefEntity, Plane, ref StartAngle, ref EndAngle);
    if (RefEntity.camDirections == camPathDirectionType.Normal)
      TangentAngle = StartAngle;
    else
      TangentAngle = EndAngle - 180.0;
  }

  public void GetTangentEndAngleOfEntitiyByCamDir(
    eEntities RefEntity,
    WorkPlane Plane,
    ref double TangentAngle)
  {
    double StartAngle = 0.0;
    double EndAngle = 0.0;
    this.GetTangentAngleOfEntity(RefEntity, Plane, ref StartAngle, ref EndAngle);
    if (RefEntity.camDirections == camPathDirectionType.Normal)
      TangentAngle = EndAngle;
    else
      TangentAngle = StartAngle - 180.0;
  }

  public void GetTangentAngleOfEntity(
    eEntities RefEntity,
    WorkPlane Plane,
    ref double StartAngle,
    ref double EndAngle)
  {
    if (RefEntity.GetType() == typeof (eArc))
    {
      StartAngle = ((eArc) RefEntity).StartAngle + 90.0;
      EndAngle = ((eArc) RefEntity).EndAngle + 90.0;
    }
    else if (RefEntity.GetType() == typeof (eLine))
    {
      StartAngle = this.PointAngle(RefEntity.Vertice[RefEntity.Vertice.Count - 1], RefEntity.Vertice[RefEntity.Vertice.Count - 2], Plane);
      EndAngle = StartAngle;
    }
    else if (RefEntity.GetType() == typeof (ePolyline))
    {
      StartAngle = this.PointAngle(RefEntity.Vertice[1], RefEntity.Vertice[0], Plane);
      EndAngle = this.PointAngle(RefEntity.Vertice[RefEntity.Vertice.Count - 1], RefEntity.Vertice[RefEntity.Vertice.Count - 2], Plane);
    }
    else
    {
      StartAngle = this.PointAngle(RefEntity.Vertice[1], RefEntity.Vertice[0], Plane);
      EndAngle = this.PointAngle(RefEntity.Vertice[RefEntity.Vertice.Count - 1], RefEntity.Vertice[RefEntity.Vertice.Count - 2], Plane);
    }
  }

  public void UpdateEntityIndex(ref List<eEntities> refEntities)
  {
    try
    {
      for (int index = 0; index <= refEntities.Count - 1; ++index)
        refEntities[index].EntityIndex = index;
    }
    catch (Exception ex)
    {
      string str = "Entities: " + refEntities.Count.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public bool GetEntitiesPlane(List<eEntities> Entities, ref WorkPlane PlaneFound)
  {
    try
    {
      Pnt3D MinPoint = new Pnt3D();
      Pnt3D MaxPoint = new Pnt3D();
      this.BoxSizeCalculate(Entities, ref MinPoint, ref MaxPoint);
      if (buCompare.EQ(MaxPoint.Z - MinPoint.Z, 0.0))
      {
        PlaneFound = new WorkPlane();
        return true;
      }
      if (buCompare.EQ(MaxPoint.Y - MinPoint.Y, 0.0))
      {
        PlaneFound = new WorkPlane(planeType.XZ, 1);
        return true;
      }
      if (!buCompare.EQ(MaxPoint.X - MinPoint.X, 0.0))
        return false;
      PlaneFound = new WorkPlane(planeType.YZ, 1);
      return true;
    }
    catch (Exception ex)
    {
      string str = "Entities: " + Entities.Count.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return false;
    }
  }

