  public void PolylineGroupToPolyline(
    eEntities PolygroupEntity,
    ref List<eEntities> PolylineEntites)
  {
    PolylineEntites.Clear();
    if (!(PolygroupEntity.GetType() == typeof (ePolylineGroup)))
      return;
    for (int index = 0; index <= ((ePolylineGroup) PolygroupEntity).GroupVertices.Count - 1; ++index)
    {
      List<Pnt3D> CopiedPnt = new List<Pnt3D>();
      Pnt3D.Copy(((ePolylineGroup) PolygroupEntity).GroupVertices[index], ref CopiedPnt);
