  public void EntitiesGuideOffsetCalculate(
    List<eEntities> RefEntities,
    double Offset,
    WorkPlane Plane,
    double PlaneOffset,
    ref List<List<Pnt3D>> GuidePoints)
  {
    GuidePoints.Clear();
    for (int index1 = 0; index1 <= RefEntities.Count - 1; ++index1)
    {
      List<Pnt3D> CopiedPnt1 = new List<Pnt3D>();
      Pnt3D.Copy(RefEntities[index1].Vertice, ref CopiedPnt1);
      if (!this.IsClosed(CopiedPnt1))
      {
        List<List<Pnt3D>> OffsetedPoints = new List<List<Pnt3D>>();
        this.OffsetContour(CopiedPnt1, Math.Abs(Offset), OffsetCornerType.Chamfer, CamOpenContourType2.ClosedNoTips, Plane, PlaneOffset, ref OffsetedPoints);
        for (int index2 = 0; index2 <= OffsetedPoints.Count - 1; ++index2)
        {
          if (OffsetedPoints[index2].Count > 1)
          {
            List<Pnt3D> CopiedPnt2 = new List<Pnt3D>();
            Pnt3D.Copy(OffsetedPoints[index2], ref CopiedPnt2);
            GuidePoints.Add(CopiedPnt2);
          }
        }
      }
    }
  }

  public void GetEntitiesInVisibleScreen(
