  public bool GetOtherPointOfEntity(Pnt3D RefPoint, eEntities RefEntity, ref Pnt3D OtherPoint)
  {
    try
    {
      if (RefEntity.Vertice.Count == 0)
        return false;
      if (RefEntity.Vertice[0] == RefPoint)
      {
        OtherPoint = new Pnt3D(RefEntity.Vertice[RefEntity.Vertice.Count - 1]);
        return true;
      }
      if (!(RefEntity.Vertice[RefEntity.Vertice.Count - 1] == RefPoint))
        return false;
      OtherPoint = new Pnt3D(RefEntity.Vertice[0]);
      return true;
    }
    catch (Exception ex)
    {
      string str = $"RefPoint: {RefPoint.ToString()} - RefEntity: {RefEntity.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return false;
    }
  }

  public void CamDirectionSet(Pnt3D RefPoint, ref eEntities RefEntity)
  {
    try
    {
      if (!(RefEntity.GetType() == typeof (eLine) | RefEntity.GetType() == typeof (ePolyline) | RefEntity.GetType() == typeof (eBSpline) | RefEntity.GetType() == typeof (eBezeir) | RefEntity.GetType() == typeof (eCircle) | RefEntity.GetType() == typeof (eEllipse) | RefEntity.GetType() == typeof (eArc)))
        return;
      if (RefPoint == RefEntity.Vertice[0])
        RefEntity.camDirections = camPathDirectionType.Normal;
      else
        RefEntity.camDirections = camPathDirectionType.Reverse;
    }
    catch (Exception ex)
    {
      string str = "RefPoint: " + RefPoint.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public ClockDirectionType EntitiesClockDirection(List<eEntities> Entities, WorkPlane Plane)
  {
    try
    {
      List<Pnt3D> Points = new List<Pnt3D>();
      this.EntityToPoint(Entities, buSystem.EntitiesResolution, ref Points);
      if (Points.Count <= 1)
        return ClockDirectionType.CW;
      if (!this.IsClosed(Points))
        Points.Add(new Pnt3D(Points[0]));
      return this.PolygonDirection(Points, Plane);
    }
    catch (Exception ex)
    {
      string str = $"Entities: {Entities.Count.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return ClockDirectionType.CW;
    }
  }

