  public void EntityUpdateByLength(
    eEntities BaseEntity,
    double NewLength,
    StartPointType PointType,
    ref eEntities CalcEntity)
  {
    try
    {
      WorkPlane Plane = new WorkPlane();
      if (BaseEntity.Vertice.Count <= 0)
        return;
      if (BaseEntity.GetType() == typeof (eLine))
      {
        if (PointType == StartPointType.Start)
        {
          double Angle = this.PointAngle(BaseEntity.Vertice[0], BaseEntity.Vertice[1], Plane);
          Pnt3D EndPnt = new Pnt3D();
          this.LineWithLengthAndAngle(BaseEntity.Vertice[1], NewLength, Angle, Plane, ref EndPnt);
          CalcEntity = (eEntities) new eLine(EndPnt, BaseEntity.Vertice[1], BaseEntity.dispThickness, BaseEntity.dispColor);
          CalcEntity.camDirections = BaseEntity.camDirections;
          eEntities.CopyCommonPorperties(BaseEntity, false, true, true, ref CalcEntity);
        }
        if (PointType == StartPointType.End)
        {
          double Angle = this.PointAngle(BaseEntity.Vertice[1], BaseEntity.Vertice[0], Plane);
          Pnt3D EndPnt = new Pnt3D();
          this.LineWithLengthAndAngle(BaseEntity.Vertice[0], NewLength, Angle, Plane, ref EndPnt);
          CalcEntity = (eEntities) new eLine(BaseEntity.Vertice[0], EndPnt, BaseEntity.dispThickness, BaseEntity.dispColor);
          CalcEntity.camDirections = BaseEntity.camDirections;
          eEntities.CopyCommonPorperties(BaseEntity, false, true, true, ref CalcEntity);
        }
        if (PointType == StartPointType.StartAndEnd)
        {
          double Angle1 = this.PointAngle(BaseEntity.Vertice[0], BaseEntity.Vertice[1], Plane);
          Pnt3D EndPnt1 = new Pnt3D();
          this.LineWithLengthAndAngle(BaseEntity.Vertice[1], NewLength, Angle1, Plane, ref EndPnt1);
          double Angle2 = this.PointAngle(BaseEntity.Vertice[1], BaseEntity.Vertice[0], Plane);
          Pnt3D EndPnt2 = new Pnt3D();
          this.LineWithLengthAndAngle(BaseEntity.Vertice[0], NewLength, Angle2, Plane, ref EndPnt2);
          CalcEntity = (eEntities) new eLine(EndPnt1, EndPnt2, BaseEntity.dispThickness, BaseEntity.dispColor);
          CalcEntity.camDirections = BaseEntity.camDirections;
          eEntities.CopyCommonPorperties(BaseEntity, false, true, true, ref CalcEntity);
        }
        CalcEntity.Update();
      }
      if (!(BaseEntity.GetType() == typeof (eArc)))
        return;
      eArc eArc1 = new eArc();
      eArc eArc2 = (eArc) BaseEntity;
      double num1 = this.ArcCircumference(eArc2.Radius, 0.0, 360.0);
      double num2 = (BaseEntity.geoLength - NewLength) * 360.0 / num1;
      if (PointType == StartPointType.Start)
      {
        CalcEntity = (eEntities) new eArc(eArc2.CenterPoint, eArc2.Radius, eArc2.StartAngle + num2, eArc2.EndAngle, eArc2.Plane);
        eEntities.CopyCommonPorperties(BaseEntity, false, true, true, ref CalcEntity);
      }
      if (PointType == StartPointType.End)
      {
        CalcEntity = (eEntities) new eArc(eArc2.CenterPoint, eArc2.Radius, eArc2.StartAngle, eArc2.EndAngle - num2, eArc2.Plane);
        eEntities.CopyCommonPorperties(BaseEntity, false, true, true, ref CalcEntity);
      }
      if (PointType == StartPointType.StartAndEnd)
      {
        CalcEntity = (eEntities) new eArc(eArc2.CenterPoint, eArc2.Radius, eArc2.StartAngle + num2, eArc2.EndAngle - num2, eArc2.Plane);
        eEntities.CopyCommonPorperties(BaseEntity, false, true, true, ref CalcEntity);
      }
      CalcEntity.Update();
    }
    catch (Exception ex)
    {
      string str = "BaseEntity: " + BaseEntity.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

