  public void EntityUpdateByNewPoint(
    eEntities BaseEntity,
    Pnt3D CatchPoint,
    Pnt3D NewPoint,
    ref eEntities CalcEntity,
    ref List<Pnt3D> Vertices)
  {
    if (BaseEntity.Vertice.Count <= 0)
      return;
    if (BaseEntity.GetType() == typeof (ePoint))
      this.Move(BaseEntity.Vertice[0], NewPoint, BaseEntity, ref CalcEntity);
    if (BaseEntity.GetType() == typeof (eLine))
    {
      if (BaseEntity.Vertice[0] == CatchPoint)
      {
        CalcEntity = (eEntities) new eLine(NewPoint, BaseEntity.Vertice[BaseEntity.Vertice.Count - 1]);
        eEntities.CopyCommonPorperties(BaseEntity, ref CalcEntity);
      }
      if (BaseEntity.Vertice[BaseEntity.Vertice.Count - 1] == CatchPoint)
      {
        CalcEntity = (eEntities) new eLine(BaseEntity.Vertice[0], NewPoint);
        eEntities.CopyCommonPorperties(BaseEntity, ref CalcEntity);
      }
    }
    if (BaseEntity.GetType() == typeof (ePolyline))
    {
      List<Pnt3D> CopiedPnt = new List<Pnt3D>();
      Pnt3D.Copy(BaseEntity.Vertice, ref CopiedPnt);
      for (int index = 0; index <= CopiedPnt.Count - 1; ++index)
      {
        if (CopiedPnt[index] == CatchPoint)
          CopiedPnt[index] = new Pnt3D(NewPoint);
      }
      CalcEntity = (eEntities) new ePolyline(CopiedPnt);
      eEntities.CopyCommonPorperties(BaseEntity, ref CalcEntity);
    }
    if (BaseEntity.GetType() == typeof (eArc))
    {
      eArc eArc = new eArc(BaseEntity);
      if (eArc.CenterPoint == CatchPoint)
        this.Move(eArc.CenterPoint, NewPoint, BaseEntity, ref CalcEntity);
      if (eArc.StartPoint == CatchPoint)
      {
        Pnt3D Center = new Pnt3D();
        double Radius = 0.0;
        double StartAngle = 0.0;
        double EndAngle = 0.0;
        this.Arc3Point(NewPoint, eArc.MiddlePoint, eArc.EndPoint, eArc.Plane, ref Center, ref Radius, ref StartAngle, ref EndAngle);
        CalcEntity = (eEntities) new eArc(Center, Radius, StartAngle, EndAngle, eArc.Plane);
        eEntities.CopyCommonPorperties(BaseEntity, ref CalcEntity);
      }
      if (eArc.MiddlePoint == CatchPoint)
      {
        Pnt3D Center = new Pnt3D();
        double Radius = 0.0;
        double StartAngle = 0.0;
        double EndAngle = 0.0;
        this.Arc3Point(eArc.StartPoint, NewPoint, eArc.EndPoint, eArc.Plane, ref Center, ref Radius, ref StartAngle, ref EndAngle);
        CalcEntity = (eEntities) new eArc(Center, Radius, StartAngle, EndAngle, eArc.Plane);
        eEntities.CopyCommonPorperties(BaseEntity, ref CalcEntity);
      }
      if (eArc.EndPoint == CatchPoint)
      {
        Pnt3D Center = new Pnt3D();
        double Radius = 0.0;
        double StartAngle = 0.0;
        double EndAngle = 0.0;
        this.Arc3Point(eArc.StartPoint, eArc.MiddlePoint, NewPoint, eArc.Plane, ref Center, ref Radius, ref StartAngle, ref EndAngle);
        CalcEntity = (eEntities) new eArc(Center, Radius, StartAngle, EndAngle, eArc.Plane);
        eEntities.CopyCommonPorperties(BaseEntity, ref CalcEntity);
      }
    }
    if (BaseEntity.GetType() == typeof (eCircle))
    {
      eCircle eCircle = new eCircle(BaseEntity);
      if (eCircle.CenterPoint == CatchPoint)
        this.Move(eCircle.CenterPoint, NewPoint, BaseEntity, ref CalcEntity);
      if (eCircle.Vertice[0] == CatchPoint)
      {
        double Radius = this.Length3D(NewPoint, eCircle.CenterPoint);
        CalcEntity = (eEntities) new eCircle(eCircle.CenterPoint, Radius, eCircle.Plane);
        eEntities.CopyCommonPorperties(BaseEntity, ref CalcEntity);
      }
    }
    if (BaseEntity.GetType() == typeof (eEllipse))
    {
      eEllipse eEllipse = new eEllipse(BaseEntity);
      if (eEllipse.CenterPoint == CatchPoint)
        this.Move(eEllipse.CenterPoint, NewPoint, BaseEntity, ref CalcEntity);
    }
    if (BaseEntity.GetType() == typeof (eEllipseArc))
    {
      eEllipseArc eEllipseArc = new eEllipseArc(BaseEntity);
      if (eEllipseArc.CenterPoint == CatchPoint)
        this.Move(eEllipseArc.CenterPoint, NewPoint, BaseEntity, ref CalcEntity);
    }
    if (BaseEntity.GetType() == typeof (eBezeir))
    {
      eBezeir eBezeir = new eBezeir(BaseEntity);
      List<Pnt3D> CopiedPnt = new List<Pnt3D>();
      Pnt3D.Copy(eBezeir.ControlPoints, ref CopiedPnt);
      for (int index = 0; index <= CopiedPnt.Count - 1; ++index)
      {
        if (CopiedPnt[index] == CatchPoint)
          CopiedPnt[index] = new Pnt3D(NewPoint);
      }
      CalcEntity = (eEntities) new eBezeir(CopiedPnt);
      eEntities.CopyCommonPorperties(BaseEntity, ref CalcEntity);
    }
    if (BaseEntity.GetType() == typeof (eBSpline))
    {
      eBSpline eBspline = new eBSpline(BaseEntity);
      List<Pnt3D> CopiedPnt = new List<Pnt3D>();
      Pnt3D.Copy(eBspline.ControlPoints, ref CopiedPnt);
      for (int index = 0; index <= CopiedPnt.Count - 1; ++index)
      {
        if (CopiedPnt[index] == CatchPoint)
          CopiedPnt[index] = new Pnt3D(NewPoint);
      }
      CalcEntity = (eEntities) new eBSpline(CopiedPnt, eBspline.bClosed, eBspline.BType);
      eEntities.CopyCommonPorperties(BaseEntity, ref CalcEntity);
    }
    if (BaseEntity.GetType() == typeof (ePicture))
    {
      ePicture ePicture = new ePicture(BaseEntity);
      List<Pnt3D> CopiedPnt = new List<Pnt3D>();
      Pnt3D.Copy(BaseEntity.Vertice, ref CopiedPnt);
      for (int index = 0; index <= CopiedPnt.Count - 1; ++index)
      {
        if (CopiedPnt[index] == CatchPoint)
          CopiedPnt[index] = new Pnt3D(NewPoint);
      }
      Pnt3D MinPoint = new Pnt3D();
      Pnt3D MaxPoint = new Pnt3D();
      this.BoxSizeCalculate(CopiedPnt, ref MinPoint, ref MaxPoint);
      CalcEntity = (eEntities) new ePicture(MinPoint, MaxPoint, ePicture.PicturePath);
      eEntities.CopyCommonPorperties(BaseEntity, ref CalcEntity);
    }
    if (BaseEntity.GetType() == typeof (eText))
    {
      eText eText = new eText(BaseEntity);
      this.Move(BaseEntity.Vertice[0], NewPoint, BaseEntity, ref CalcEntity);
      eEntities.CopyCommonPorperties(BaseEntity, ref CalcEntity);
    }
    Vertices = new List<Pnt3D>();
    Pnt3D.Copy(CalcEntity.Vertice, ref Vertices);
  }

