  public void EntityLengthModify(
    eEntities RefEntity,
    StartPointType ModifyDirType,
    double ModifyLength,
    ref eEntities ModifiedEntity)
  {
    ModifiedEntity = new eEntities();
    double CutLength = ModifyLength / Math.Cos(buConversion.DegreeToRadian(RefEntity.Orientation.A));
    if (ModifyDirType == StartPointType.Start)
    {
      if (RefEntity.camDirections == camPathDirectionType.Normal)
        this.EntityUpdateByLengthUsingCamDirection(eEntities.CopyEntity(RefEntity), CutLength, StartPointType.Start, new WorkPlane(), ref ModifiedEntity);
      else
        this.EntityUpdateByLengthUsingCamDirection(eEntities.CopyEntity(RefEntity), CutLength, StartPointType.End, new WorkPlane(), ref ModifiedEntity);
    }
    if (ModifyDirType == StartPointType.End)
    {
      if (RefEntity.camDirections == camPathDirectionType.Normal)
        this.EntityUpdateByLengthUsingCamDirection(eEntities.CopyEntity(RefEntity), CutLength, StartPointType.End, new WorkPlane(), ref ModifiedEntity);
      else
        this.EntityUpdateByLengthUsingCamDirection(eEntities.CopyEntity(RefEntity), CutLength, StartPointType.Start, new WorkPlane(), ref ModifiedEntity);
    }
    if (ModifyDirType == StartPointType.StartAndEnd)
      this.EntityUpdateByLengthUsingCamDirection(eEntities.CopyEntity(RefEntity), CutLength, StartPointType.StartAndEnd, new WorkPlane(), ref ModifiedEntity);
    ModifiedEntity.bCamSelected = false;
    ModifiedEntity.bSelected = false;
  }

  public void EntityCornerModifyByConvexConcave(
    eEntities FirstEntity,
    eEntities LastEntity,
    ClockDirectionType ClockDir,
    bool ReverseThetaCalculation,
    double ModifyLength,
    ref eEntities ModifiedFirstEntity,
    ref eEntities ModifiedLastEntity)
  {
    ModifiedFirstEntity = new eEntities();
    ModifiedLastEntity = new eEntities();
    bool isTouch = false;
    StartEndType FirstEntityTouchPoint = StartEndType.Start;
    StartEndType SecondEntityTouchPoint = StartEndType.Start;
    this.EntityEntityTouchPoint(FirstEntity, LastEntity, 0.01, ref isTouch, ref FirstEntityTouchPoint, ref SecondEntityTouchPoint);
    Pnt3D pnt3D1 = new Pnt3D();
    Pnt3D pnt3D2 = new Pnt3D();
    Pnt3D pnt3D3 = new Pnt3D();
    Pnt3D pnt3D4 = new Pnt3D();
    Pnt3D FirstLineStart;
    Pnt3D FirstLineEnd;
    if (FirstEntityTouchPoint == StartEndType.End)
    {
      FirstLineStart = new Pnt3D(FirstEntity.Vertice[FirstEntity.Vertice.Count - 1]);
      FirstLineEnd = new Pnt3D(FirstEntity.Vertice[FirstEntity.Vertice.Count - 2]);
    }
    else
    {
      FirstLineStart = new Pnt3D(FirstEntity.Vertice[0]);
      FirstLineEnd = new Pnt3D(FirstEntity.Vertice[1]);
    }
    Pnt3D SecondLineStart;
    Pnt3D SecondLineEnd;
    if (SecondEntityTouchPoint == StartEndType.End)
    {
      SecondLineStart = new Pnt3D(LastEntity.Vertice[LastEntity.Vertice.Count - 1]);
      SecondLineEnd = new Pnt3D(LastEntity.Vertice[LastEntity.Vertice.Count - 2]);
    }
    else
    {
      SecondLineStart = new Pnt3D(LastEntity.Vertice[0]);
      SecondLineEnd = new Pnt3D(LastEntity.Vertice[1]);
    }
    if (180.0 - Math.Abs(this.AngleOfTwoLines(FirstLineStart, FirstLineEnd, SecondLineStart, SecondLineEnd, new WorkPlane())) <= 30.0)
    {
      eEntities.CopyEntity(FirstEntity, ref ModifiedFirstEntity);
      ModifiedFirstEntity.bCamSelected = false;
      ModifiedFirstEntity.bSelected = false;
      eEntities.CopyEntity(LastEntity, ref ModifiedLastEntity);
      ModifiedLastEntity.bCamSelected = false;
      ModifiedLastEntity.bSelected = false;
    }
    else
    {
      double num1 = 0.0;
      double num2 = ModifyLength;
      List<Pnt3D> pnt3DList = new List<Pnt3D>();
      List<Pnt3D> Points = new List<Pnt3D>();
      if (FirstEntity.GetType() == typeof (eLine))
        this.EntityToPoint(FirstEntity, ref Points);
      if (FirstEntity.GetType() == typeof (eArc))
      {
        this.ArcTo3Point(FirstEntity, ref Points);
        Points.RemoveAt(0);
      }
      Pnt3D.Add(Points, ref pnt3DList);
      Points = new List<Pnt3D>();
      if (LastEntity.GetType() == typeof (eLine))
        this.EntityToPoint(LastEntity, ref Points);
      if (LastEntity.GetType() == typeof (eArc))
      {
        this.ArcTo3Point(LastEntity, ref Points);
        Points.RemoveAt(Points.Count - 1);
      }
      Pnt3D.Add(Points, ref pnt3DList);
      this.CheckDuplicatedPointsWithPrevious(ref pnt3DList);
      if (pnt3DList.Count == 3)
        num1 = this.CrossProductLength(pnt3DList[0], pnt3DList[1], pnt3DList[pnt3DList.Count - 1]);
      if (pnt3DList.Count > 3)
        num1 = this.CrossProductLength(pnt3DList[0], pnt3DList[1], pnt3DList[2]);
      if (ReverseThetaCalculation)
        num1 *= -1.0;
      if (ClockDir == ClockDirectionType.CCW)
      {
        if (num1 <= 0.0)
        {
          eEntities.CopyEntity(FirstEntity, ref ModifiedFirstEntity);
          ModifiedFirstEntity.bCamSelected = false;
          ModifiedFirstEntity.bSelected = false;
          eEntities.CopyEntity(LastEntity, ref ModifiedLastEntity);
          ModifiedLastEntity.bCamSelected = false;
          ModifiedLastEntity.bSelected = false;
        }
        else
        {
          double num3 = num2 / Math.Cos(buConversion.DegreeToRadian(FirstEntity.Orientation.A));
          if (FirstEntityTouchPoint == StartEndType.Start)
            this.EntityUpdateByLength(eEntities.CopyEntity(FirstEntity), FirstEntity.geoLength - num3, StartPointType.Start, ref ModifiedFirstEntity);
          if (FirstEntityTouchPoint == StartEndType.End)
            this.EntityUpdateByLength(eEntities.CopyEntity(FirstEntity), FirstEntity.geoLength - num3, StartPointType.End, ref ModifiedFirstEntity);
          if (SecondEntityTouchPoint == StartEndType.Start)
            this.EntityUpdateByLength(eEntities.CopyEntity(LastEntity), LastEntity.geoLength - num3, StartPointType.Start, ref ModifiedLastEntity);
          if (SecondEntityTouchPoint == StartEndType.End)
            this.EntityUpdateByLength(eEntities.CopyEntity(LastEntity), LastEntity.geoLength - num3, StartPointType.End, ref ModifiedLastEntity);
          ModifiedFirstEntity.bCamSelected = false;
          ModifiedFirstEntity.bSelected = false;
        }
      }
      else if (num1 >= 0.0)
      {
        eEntities.CopyEntity(FirstEntity, ref ModifiedFirstEntity);
        ModifiedFirstEntity.bCamSelected = false;
        ModifiedFirstEntity.bSelected = false;
        eEntities.CopyEntity(LastEntity, ref ModifiedLastEntity);
        ModifiedLastEntity.bCamSelected = false;
        ModifiedLastEntity.bSelected = false;
      }
      else
      {
        eEntities eEntities1 = new eEntities();
        eEntities eEntities2 = new eEntities();
        double num4 = num2 / Math.Cos(buConversion.DegreeToRadian(FirstEntity.Orientation.A));
        if (FirstEntityTouchPoint == StartEndType.Start)
          this.EntityUpdateByLength(eEntities.CopyEntity(FirstEntity), FirstEntity.geoLength - num4, StartPointType.Start, ref ModifiedFirstEntity);
        if (FirstEntityTouchPoint == StartEndType.End)
          this.EntityUpdateByLength(eEntities.CopyEntity(FirstEntity), FirstEntity.geoLength - num4, StartPointType.End, ref ModifiedFirstEntity);
        if (SecondEntityTouchPoint == StartEndType.Start)
          this.EntityUpdateByLength(eEntities.CopyEntity(LastEntity), LastEntity.geoLength - num4, StartPointType.Start, ref ModifiedLastEntity);
        if (SecondEntityTouchPoint == StartEndType.End)
          this.EntityUpdateByLength(eEntities.CopyEntity(LastEntity), LastEntity.geoLength - num4, StartPointType.End, ref ModifiedLastEntity);
        ModifiedFirstEntity.bCamSelected = false;
        ModifiedFirstEntity.bSelected = false;
      }
    }
  }

