  public void EntityOutsidePoints(eEntities Entity, ref List<Pnt3D> OutsidePoints)
  {
    try
    {
      if (Entity.GetType() == typeof (eArc))
        this.ArcOutsidePoints(((ePlaneEntities) Entity).CenterPoint, ((eCircle) Entity).Radius, ((eArc) Entity).StartAngle, ((eArc) Entity).EndAngle, ((ePlaneEntities) Entity).Plane, ref OutsidePoints);
      if (!(Entity.GetType() == typeof (eCircle)))
        return;
      this.ArcOutsidePoints(((ePlaneEntities) Entity).CenterPoint, ((eCircle) Entity).Radius, 0.0, 360.0, ((ePlaneEntities) Entity).Plane, ref OutsidePoints);
    }
    catch (Exception ex)
    {
      string str = "Entity: " + Entity.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void SelectEntityByClick(
    List<eEntities> RefEntitites,
    Pnt3D ClickPoint,
    WorkPlane Plane,
    ref eEntities SelectedEntity)
  {
    try
    {
      SelectedEntity = new eEntities();
      double num = double.MaxValue;
      for (int index = 0; index <= RefEntitites.Count - 1; ++index)
      {
        Pnt3D CalculatedPoint = new Pnt3D();
        double maxValue = double.MaxValue;
        if (this.IsPointOverEntity(RefEntitites[index], ClickPoint, Plane, ref CalculatedPoint, ref maxValue) && maxValue < num)
        {
          num = maxValue;
          SelectedEntity = new eEntities();
          eEntities.CopyEntity(RefEntitites[index], ref SelectedEntity);
        }
      }
    }
    catch (Exception ex)
    {
      string str = $"RefEntitites: {RefEntitites.Count.ToString()} - ClickPoint: {ClickPoint.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void DirectionArrowCalculateByTwoPoint(
    Pnt3D FirstPoint,
