  public void PolylineToLineConversion(
    List<eEntities> RefEntities,
    ref List<eEntities> ConvertedEntitites)
  {
    try
    {
      ConvertedEntitites.Clear();
      for (int index1 = 0; index1 <= RefEntities.Count - 1; ++index1)
      {
        if (RefEntities[index1].GetType() != typeof (ePolyline))
        {
          ConvertedEntitites.Add(eEntities.CopyEntity(RefEntities[index1]));
        }
        else
        {
          for (int index2 = 1; index2 <= RefEntities[index1].Vertice.Count - 1; ++index2)
          {
            eEntities copiedEnt = (eEntities) new eLine(RefEntities[index1].Vertice[index2 - 1], RefEntities[index1].Vertice[index2]);
            eEntities.CopyCommonPorperties(RefEntities[index1], ref copiedEnt);
            ConvertedEntitites.Add(copiedEnt);
          }
        }
      }
    }
    catch (Exception ex)
    {
      string str = "RefEntity: " + RefEntities.Count.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void AnalyseEntities(
    List<eEntities> RefEntities,
    List<LayerBase> Layers,
    int LayerIndex,
    ref List<eEntities> AddedEntitites,
    Color FilterColor)
  {
    AnalyseEntitiesOptions Options = new AnalyseEntitiesOptions();
    Options.FilterColor = FilterColor;
