  public void EntitiesToPoint(
    eEntities RefEntity,
    EntitiesResolution Resolution,
    ref List<Pnt3D> Points)
  {
    try
    {
      if (RefEntity.GetType() == typeof (ePoint))
        Points.Add(new Pnt3D(RefEntity.Vertice[0]));
      if (RefEntity.GetType() == typeof (eLine))
      {
        if (Resolution.LineResolution.ResolutionTypes == EntityResolutionType.None)
        {
          if (RefEntity.camDirections == camPathDirectionType.Normal)
            Pnt3D.Copy(RefEntity.Vertice, ref Points);
          if (RefEntity.camDirections == camPathDirectionType.Reverse)
          {
            Pnt3D.Copy(RefEntity.Vertice, ref Points);
            Points.Reverse();
          }
        }
        else if (Resolution.LineResolution.ResolutionTypes == EntityResolutionType.ByNumber)
        {
          double Length = this.Length3D(RefEntity.Vertice[0], RefEntity.Vertice[RefEntity.Vertice.Count - 1]) / (double) Resolution.LineResolution.GeometricCount;
          if (RefEntity.camDirections == camPathDirectionType.Normal)
            this.LineerToLineer(RefEntity.Vertice[0], RefEntity.Vertice[RefEntity.Vertice.Count - 1], Length, ref Points);
          if (RefEntity.camDirections == camPathDirectionType.Reverse)
            this.LineerToLineer(RefEntity.Vertice[RefEntity.Vertice.Count - 1], RefEntity.Vertice[0], Length, ref Points);
        }
        else
        {
          double num1 = this.Length3D(RefEntity.Vertice[0], RefEntity.Vertice[RefEntity.Vertice.Count - 1]);
          double num2 = buNumeric.RoundToUpper(num1 / Resolution.LineResolution.GeometricLength);
          if (num2 <= 1.0)
            num2 = 2.0;
          double Length = num1 / num2;
          if (RefEntity.camDirections == camPathDirectionType.Normal)
            this.LineerToLineer(RefEntity.Vertice[0], RefEntity.Vertice[RefEntity.Vertice.Count - 1], Length, ref Points);
          if (RefEntity.camDirections == camPathDirectionType.Reverse)
            this.LineerToLineer(RefEntity.Vertice[RefEntity.Vertice.Count - 1], RefEntity.Vertice[0], Length, ref Points);
        }
      }
      if (RefEntity.GetType() == typeof (ePolyline))
      {
        if (Resolution.PolylineResolution.ResolutionTypes == EntityResolutionType.None)
        {
          if (RefEntity.camDirections == camPathDirectionType.Normal)
            Pnt3D.Copy(RefEntity.Vertice, ref Points);
          if (RefEntity.camDirections == camPathDirectionType.Reverse)
          {
            Pnt3D.Copy(RefEntity.Vertice, ref Points);
            Points.Reverse();
          }
        }
        else
        {
          List<Pnt3D> CopiedPnt = new List<Pnt3D>();
          Pnt3D.Copy(RefEntity.Vertice, ref CopiedPnt);
          if (RefEntity.camDirections == camPathDirectionType.Reverse)
            CopiedPnt.Reverse();
          if (Resolution.PolylineResolution.ResolutionTypes == EntityResolutionType.ByNumber)
          {
