              this.LineerToLineer(CopiedPnt[index - 1], CopiedPnt[index], Length, ref Vertices);
              Points.AddRange((IEnumerable<Pnt3D>) Vertices);
            }
          }
          else
          {
            for (int index = 1; index <= CopiedPnt.Count - 1; ++index)
            {
              List<Pnt3D> Vertices = new List<Pnt3D>();
              double num = this.Length3D(CopiedPnt[index - 1], CopiedPnt[index]);
              double upper = buNumeric.RoundToUpper(num / Resolution.PolylineResolution.GeometricLength);
              if (upper > 1.0)
                ;
              double Length = num / upper;
              this.LineerToLineer(CopiedPnt[index - 1], CopiedPnt[index], Length, ref Vertices);
              Points.AddRange((IEnumerable<Pnt3D>) Vertices);
            }
