            Points.Add(new Pnt6D(new Pnt3D(Vertices[index]), new OrientationAngle(RefEntity.Orientation.A, RefEntity.Orientation.B, c)));
          }
        }
        if (RefEntity.camDirections == camPathDirectionType.Reverse)
        {
          Vertices.Reverse();
          for (int index = 0; index <= Vertices.Count - 1; ++index)
          {
            double c = 0.0;
            if (index < Vertices.Count - 1)
              c = this.PointAngle(Vertices[index + 1], Vertices[index]);
            if (index == Vertices.Count - 1)
              c = this.PointAngle(Vertices[index], Vertices[index - 1]);
