  public void GetAvailableGroupIndex(
    List<eEntities> Entities,
    List<int> AlreadyUsedGroupIndex,
    ref int GroupIndex,
    ref List<int> UsedGroupList)
  {
    try
    {
      UsedGroupList = new List<int>();
      for (int index = 0; index <= AlreadyUsedGroupIndex.Count - 1; ++index)
        UsedGroupList.Add(AlreadyUsedGroupIndex[index]);
      for (int index1 = 0; index1 <= Entities.Count - 1; ++index1)
      {
        if (Entities[index1].GroupIndex > 0)
        {
          if (UsedGroupList.Count == 0)
          {
            UsedGroupList.Add(Entities[index1].GroupIndex);
          }
          else
          {
            bool flag = false;
            for (int index2 = 0; index2 <= UsedGroupList.Count - 1; ++index2)
            {
              if (Entities[index1].GroupIndex == UsedGroupList[index2])
                flag = true;
            }
            if (!flag)
              UsedGroupList.Add(Entities[index1].GroupIndex);
          }
        }
      }
      if (UsedGroupList.Count == 0)
        GroupIndex = 1;
      if (UsedGroupList.Count == 1)
        GroupIndex = UsedGroupList[0] + 1;
      if (UsedGroupList.Count <= 1)
        return;
      this.SortList(SortDirectionType.Lower, ref UsedGroupList);
      bool flag1 = false;
      for (int index = 1; index <= UsedGroupList.Count - 1; ++index)
      {
        if (UsedGroupList[index] - UsedGroupList[index - 1] >= 2)
        {
          GroupIndex = UsedGroupList[index - 1] + 1;
          flag1 = true;
        }
      }
      if (flag1)
        return;
      GroupIndex = UsedGroupList[UsedGroupList.Count - 1] + 1;
    }
    catch (Exception ex)
    {
      string str = "Entities: " + Entities.Count.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

