  public void SetPointOfEntity(
    ref eEntities Entity,
    double X,
    double Y,
    double Z,
    AxesEnableXYZ Enable)
  {
    if (Entity.GetType() == typeof (ePoint))
    {
      Pnt3D Pnt = new Pnt3D(((ePoint) Entity).StartPoint);
      if (Enable.X)
        Pnt.X = X;
      if (Enable.Y)
        Pnt.Y = Y;
      if (Enable.Z)
        Pnt.Z = Z;
      ((ePoint) Entity).StartPoint = new Pnt3D(Pnt);
      Entity.Update();
    }
    if (Entity.GetType() == typeof (eLine))
    {
      Pnt3D Pnt1 = new Pnt3D(((eLine) Entity).StartPoint);
      Pnt3D Pnt2 = new Pnt3D(((eLine) Entity).EndPoint);
      if (Enable.X)
      {
        Pnt1.X = X;
        Pnt2.X = X;
      }
      if (Enable.Y)
      {
        Pnt1.Y = Y;
        Pnt2.Y = Y;
      }
      if (Enable.Z)
      {
        Pnt1.Z = Z;
        Pnt2.Z = Z;
      }
      ((eLine) Entity).StartPoint = new Pnt3D(Pnt1);
      ((eLine) Entity).EndPoint = new Pnt3D(Pnt2);
      Entity.Update();
    }
    if (Entity.GetType() == typeof (eArc))
    {
      Pnt3D Pnt = new Pnt3D(((ePlaneEntities) Entity).CenterPoint);
      if (Enable.X)
        Pnt.X = X;
      if (Enable.Y)
        Pnt.Y = Y;
      if (Enable.Z)
        Pnt.Z = Z;
      ((ePlaneEntities) Entity).CenterPoint = new Pnt3D(Pnt);
      Entity.Update();
    }
    if (Entity.GetType() == typeof (eCircle))
    {
      Pnt3D Pnt = new Pnt3D(((ePlaneEntities) Entity).CenterPoint);
      if (Enable.X)
        Pnt.X = X;
      if (Enable.Y)
        Pnt.Y = Y;
      if (Enable.Z)
        Pnt.Z = Z;
      ((ePlaneEntities) Entity).CenterPoint = new Pnt3D(Pnt);
      Entity.Update();
    }
    if (Entity.GetType() == typeof (eEllipse))
    {
      Pnt3D Pnt = new Pnt3D(((ePlaneEntities) Entity).CenterPoint);
      if (Enable.X)
        Pnt.X = X;
      if (Enable.Y)
        Pnt.Y = Y;
      if (Enable.Z)
        Pnt.Z = Z;
      ((ePlaneEntities) Entity).CenterPoint = new Pnt3D(Pnt);
      Entity.Update();
    }
    if (Entity.GetType() == typeof (ePolyline))
    {
      List<Pnt3D> pnt3DList = new List<Pnt3D>();
      Pnt3D.Copy(Entity.Vertice, ref pnt3DList);
      if (Enable.X)
        Pnt3D.SetValue(X, AxesXYZ.X, ref pnt3DList);
      if (Enable.Y)
        Pnt3D.SetValue(Y, AxesXYZ.Y, ref pnt3DList);
      if (Enable.Z)
        Pnt3D.SetValue(Z, AxesXYZ.Z, ref pnt3DList);
      Entity.Vertice.Clear();
      for (int index = 0; index <= pnt3DList.Count - 1; ++index)
        Entity.Vertice.Add(new Pnt3D(pnt3DList[index]));
      Entity.Update();
    }
    if (Entity.GetType() == typeof (eBSpline))
    {
      List<Pnt3D> pnt3DList = new List<Pnt3D>();
      Pnt3D.Copy(((eCurveEntities) Entity).ControlPoints, ref pnt3DList);
      if (Enable.X)
        Pnt3D.SetValue(X, AxesXYZ.X, ref pnt3DList);
      if (Enable.Y)
        Pnt3D.SetValue(Y, AxesXYZ.Y, ref pnt3DList);
      if (Enable.Z)
        Pnt3D.SetValue(Z, AxesXYZ.Z, ref pnt3DList);
      ((eCurveEntities) Entity).ControlPoints.Clear();
      for (int index = 0; index <= pnt3DList.Count - 1; ++index)
