  public void SetShapeDataToEntity(ShapeData Shape, ref eEntities Entitiy)
  {
    if (Shape != null)
    {
      ShapeData Copied = new ShapeData();
      ShapeData.Copy(Shape, ref Copied);
      Entitiy.Shape = new ShapeData();
      Entitiy.Shape = Copied;
    }
    else
      Entitiy.Shape = (ShapeData) null;
  }

  public void SetShapeDataToLastEntity(ShapeData Shape, ref List<eEntities> Entities)
  {
    if (Entities.Count <= 0)
      return;
    if (Shape != null)
    {
      ShapeData Copied = new ShapeData();
      ShapeData.Copy(Shape, ref Copied);
      Entities[Entities.Count - 1].Shape = new ShapeData();
      Entities[Entities.Count - 1].Shape = Copied;
    }
    else
      Entities[Entities.Count - 1].Shape = (ShapeData) null;
  }

  public void SetSelectedPropertiesToEntities(bool Selected, ref List<eEntities> Entities)
  {
    if (Entities.Count <= 0)
      return;
    for (int index = 0; index <= Entities.Count - 1; ++index)
      Entities[index].bSelected = Selected;
  }

  public void EntityTtoEntityE(geoEntity EntityFrom, ref List<eEntities> EntityTo)
  {
    if (EntityFrom.GetType() == typeof (geoLine))
    {
      geoLine geoLine = new geoLine((geoLine) EntityFrom);
      EntityTo.Add((eEntities) new eLine(geoLine.StartPoint, geoLine.EndPoint));
      EntityTo[0].LayerIndex = EntityFrom.Layer;
      EntityTo[0].Mode = EntityFrom.Mode;
      EntityTo[0].camToolNo = EntityFrom.ToolNo;
      EntityTo[0].GroupIndex = EntityFrom.Index;
    }
    if (EntityFrom.GetType() == typeof (geoPolyline))
    {
      geoPolyline geoPolyline = new geoPolyline((geoPolyline) EntityFrom);
      List<Pnt3D> Vertices = new List<Pnt3D>();
      for (int index = 0; index <= geoPolyline.Vertice.Count - 1; ++index)
        Vertices.Add(new Pnt3D(geoPolyline.Vertice[index]));
      EntityTo.Add((eEntities) new ePolyline(Vertices));
      EntityTo[0].LayerIndex = EntityFrom.Layer;
      EntityTo[0].Mode = EntityFrom.Mode;
      EntityTo[0].camToolNo = EntityFrom.ToolNo;
      EntityTo[0].GroupIndex = EntityFrom.Index;
    }
    if (EntityFrom.GetType() == typeof (geoArc))
    {
      geoArc geoArc = new geoArc((geoArc) EntityFrom);
      EntityTo.Add((eEntities) new eArc(geoArc.CenterPoint, geoArc.Radius, geoArc.StartAngle, geoArc.EndAngle, geoArc.Plane));
      EntityTo[0].LayerIndex = EntityFrom.Layer;
      EntityTo[0].Mode = EntityFrom.Mode;
      EntityTo[0].camToolNo = EntityFrom.ToolNo;
      EntityTo[0].GroupIndex = EntityFrom.Index;
    }
    if (EntityFrom.GetType() == typeof (geoCircle))
    {
      geoCircle geoCircle = new geoCircle((geoCircle) EntityFrom);
      EntityTo.Add((eEntities) new eCircle(geoCircle.CenterPoint, geoCircle.Radius, geoCircle.Plane));
      EntityTo[0].LayerIndex = EntityFrom.Layer;
      EntityTo[0].Mode = EntityFrom.Mode;
      EntityTo[0].camToolNo = EntityFrom.ToolNo;
      EntityTo[0].GroupIndex = EntityFrom.Index;
    }
    if (!(EntityFrom.GetType() == typeof (geoQuad)))
      return;
    geoQuad geoQuad = new geoQuad((geoQuad) EntityFrom);
    EntityTo.Add((eEntities) new eLine(geoQuad.FirstPoint, geoQuad.SecondPoint));
    EntityTo[0].LayerIndex = EntityFrom.Layer;
    EntityTo[0].Mode = EntityFrom.Mode;
    EntityTo[0].camToolNo = EntityFrom.ToolNo;
    EntityTo[0].GroupIndex = EntityFrom.Index;
    EntityTo.Add((eEntities) new eLine(geoQuad.SecondPoint, geoQuad.ThirdPoint));
    EntityTo[1].LayerIndex = EntityFrom.Layer;
    EntityTo[1].Mode = EntityFrom.Mode;
    EntityTo[1].camToolNo = EntityFrom.ToolNo;
    EntityTo[1].GroupIndex = EntityFrom.Index;
    EntityTo.Add((eEntities) new eLine(geoQuad.ThirdPoint, geoQuad.FourthPoint));
    EntityTo[2].LayerIndex = EntityFrom.Layer;
    EntityTo[2].Mode = EntityFrom.Mode;
    EntityTo[2].camToolNo = EntityFrom.ToolNo;
    EntityTo[2].GroupIndex = EntityFrom.Index;
    EntityTo.Add((eEntities) new eLine(geoQuad.FourthPoint, geoQuad.FirstPoint));
    EntityTo[3].LayerIndex = EntityFrom.Layer;
    EntityTo[3].Mode = EntityFrom.Mode;
    EntityTo[3].camToolNo = EntityFrom.ToolNo;
    EntityTo[3].GroupIndex = EntityFrom.Index;
  }

  public void EntityEtoEntityT(eEntities EntityFrom, ref geoEntity EntityTo)
  {
    if (EntityFrom.GetType() == typeof (eLine))
    {
      eLine eLine = new eLine(EntityFrom);
      EntityTo = (geoEntity) new geoLine(eLine.StartPoint, eLine.EndPoint);
    }
    if (EntityFrom.GetType() == typeof (eArc))
    {
      eArc eArc = new eArc(EntityFrom);
      EntityTo = (geoEntity) new geoArc(eArc.CenterPoint, eArc.Radius, eArc.StartAngle, eArc.EndAngle, ((ePlaneEntities) EntityFrom).Plane);
    }
    if (EntityFrom.GetType() == typeof (ePoint))
    {
      ePoint ePoint = new ePoint(EntityFrom);
      EntityTo = (geoEntity) new geoPoint(ePoint.StartPoint);
    }
    if (EntityFrom.GetType() == typeof (eCircle))
    {
      eCircle eCircle = new eCircle(EntityFrom);
      EntityTo = (geoEntity) new geoCircle(eCircle.CenterPoint, eCircle.Radius, eCircle.Plane);
    }
    if (EntityFrom.GetType() == typeof (ePolyline))
    {
      ePolyline ePolyline = new ePolyline(EntityFrom);
      EntityTo = (geoEntity) new geoPolyline(ePolyline.Vertice);
    }
    EntityTo.Layer = EntityFrom.LayerIndex;
    EntityTo.Mode = EntityFrom.Mode;
    EntityTo.ToolNo = EntityFrom.camToolNo;
    EntityTo.Index = EntityFrom.GroupIndex;
  }

  public void EntityTListToEntityEList(List<geoEntity> EntityFrom, ref List<eEntities> EntityTo)
  {
    EntityTo.Clear();
    for (int index1 = 0; index1 <= EntityFrom.Count - 1; ++index1)
    {
      List<eEntities> EntityTo1 = new List<eEntities>();
      this.EntityTtoEntityE(EntityFrom[index1], ref EntityTo1);
