  public bool isEntityDerivatedFromEntity(
    ref eEntities RefEntity,
    List<eEntities> EntitiyList,
    EntityDerivatedData Data,
    EntityDerivatedType Type)
  {
    try
    {
      for (int index = 0; index <= EntitiyList.Count - 1; ++index)
      {
        if (EntitiyList[index].GetType() == RefEntity.GetType() && RefEntity.GetType() == typeof (eLine) && Type == EntityDerivatedType.Offset)
        {
          Pnt3D pnt3D1 = new Pnt3D();
          Pnt3D pnt3D2 = new Pnt3D();
          if (buCompare.EQ(Math.Abs(this.Length3D(this.MiddlePointOfLine(RefEntity.Vertice[0], RefEntity.Vertice[1]), this.MiddlePointOfLine(EntitiyList[index].Vertice[0], EntitiyList[index].Vertice[1]))), Math.Abs(Data.Offset)))
          {
            if (Data.ApplyAllEntityData)
              eEntities.CopyCommonPorperties(EntitiyList[index], ref RefEntity);
            return true;
          }
        }
      }
      return false;
    }
    catch (Exception ex)
    {
      string str = "";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return false;
    }
  }

  public void CreateEntitiesFromCustomText(
    string Text,
    double CharSpace,
    double SpaceValue,
    double CharHeight,
    List<CharLibrary> CharLib,
    ref List<eEntities> TextEntities)
  {
    try
    {
      TextEntities.Clear();
      TextEntities = new List<eEntities>();
      double num1 = 1.0;
      if (Text.Length <= 0)
        return;
      char[] charArray = Text.ToCharArray();
      double x = 0.0;
      if (charArray == null)
        return;
      for (int index1 = 0; index1 <= charArray.Length - 1; ++index1)
      {
        bool flag = false;
        List<eEntities> eEntitiesList = new List<eEntities>();
        for (int index2 = 0; index2 <= CharLib.Count - 1; ++index2)
        {
          string str = charArray[index1].ToString();
          if (str == CharLib[index2].Char)
          {
            geoEntity.GeoEntitiyToEEntity(CharLib[index2].CharEntities, ref eEntitiesList);
            index2 = 2147483645;
          }
          if (str == " ")
            flag = true;
        }
        if (flag)
          x += SpaceValue;
        else if (eEntitiesList.Count > 0)
        {
          Pnt3D MinPoint = new Pnt3D();
          Pnt3D MaxPoint = new Pnt3D();
          this.BoxSizeCalculate(eEntitiesList, ref MinPoint, ref MaxPoint);
          double num2 = MaxPoint.Y - MinPoint.Y;
          if (num2 > 0.0 & CharHeight > 0.0 & TextEntities.Count == 0)
            num1 = CharHeight / num2;
          this.Scale(MinPoint, num1, num1, 1.0, true, true, false, new WorkPlane(), ref eEntitiesList);
          this.Move(MinPoint, new Pnt3D(x, 0.0, 0.0), ref eEntitiesList);
          this.BoxSizeCalculate(eEntitiesList, ref MinPoint, ref MaxPoint);
          eEntities.AddEntities(eEntitiesList, ref TextEntities);
          x = MaxPoint.X + CharSpace;
        }
        else
          x += SpaceValue;
      }
    }
    catch (Exception ex)
    {
    }
  }

