  public void Rotate(
    Pnt3D CenterPoint,
    double Angle,
    WorkPlane Plane,
    List<Pnt3D> RefPoints,
    ref List<Pnt3D> CalcPoints)
  {
    try
    {
      CalcPoints.Clear();
      Pnt3D.Copy(RefPoints, ref CalcPoints);
      this.Rotate(CenterPoint, Angle, Plane, ref CalcPoints);
    }
    catch (Exception ex)
    {
      string str = $"CenterPoint: {CenterPoint.ToString()} - Angle: {Angle.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void Rotate(Pnt3D CenterPoint, double Angle, WorkPlane Plane, ref List<Pnt3D> Points)
  {
    try
    {
      Pnt3D pnt3D = new Pnt3D();
      for (int index = 0; index <= Points.Count - 1; ++index)
      {
        double num = this.Length3D(Points[index], CenterPoint, Plane);
        double Degree = this.PointAngle(Points[index], CenterPoint, Plane) + Angle;
        pnt3D = new Pnt3D();
        if (WorkPlane.isPlaneXY(Plane))
        {
          Pnt3D Pnt = new Pnt3D(Points[index]);
          Pnt.X = CenterPoint.X + num * Math.Cos(buConversion.DegreeToRadian(Degree));
          Pnt.Y = CenterPoint.Y + num * Math.Sin(buConversion.DegreeToRadian(Degree));
          Points[index] = new Pnt3D(Pnt);
        }
        if (WorkPlane.isPlaneXZ(Plane))
        {
          Pnt3D Pnt = new Pnt3D(Points[index]);
          Pnt.X = CenterPoint.X + num * Math.Cos(buConversion.DegreeToRadian(Degree));
          Pnt.Z = CenterPoint.Z + num * Math.Sin(buConversion.DegreeToRadian(Degree));
          Points[index] = new Pnt3D(Pnt);
        }
        if (WorkPlane.isPlaneYZ(Plane))
        {
          Pnt3D Pnt = new Pnt3D(Points[index]);
          Pnt.Y = CenterPoint.Y + num * Math.Cos(buConversion.DegreeToRadian(Degree));
          Pnt.Z = CenterPoint.Z + num * Math.Sin(buConversion.DegreeToRadian(Degree));
          Points[index] = new Pnt3D(Pnt);
        }
      }
    }
    catch (Exception ex)
    {
      string str = $"CenterPoint: {CenterPoint.ToString()} - Angle: {Angle.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void Rotate(
    Pnt3D CenterPoint,
    double Angle,
    WorkPlane Plane,
    ref List<List<Pnt3D>> Points)
  {
    try
    {
      for (int index1 = 0; index1 <= Points.Count - 1; ++index1)
      {
        List<Pnt3D> pnt3DList = new List<Pnt3D>();
        buGeneral.CopyLists(Points[index1], ref pnt3DList);
        this.Rotate(CenterPoint, Angle, Plane, ref pnt3DList);
        Points[index1].Clear();
        for (int index2 = 0; index2 <= pnt3DList.Count - 1; ++index2)
          Points[index1].Add(new Pnt3D(pnt3DList[index2]));
      }
    }
    catch (Exception ex)
    {
      string str = $"CenterPoint: {CenterPoint.ToString()} - Angle: {Angle.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

