            X = CenterPoint.X + num * Math.Cos(buConversion.DegreeToRadian(Degree)),
            Y = CenterPoint.Y + num * Math.Sin(buConversion.DegreeToRadian(Degree))
          });
        if (WorkPlane.isPlaneXZ(Plane))
          Points[index] = new Pnt6D(new Pnt6D(Points[index])
          {
            X = CenterPoint.X + num * Math.Cos(buConversion.DegreeToRadian(Degree)),
            Z = CenterPoint.Z + num * Math.Sin(buConversion.DegreeToRadian(Degree))
          });
        if (WorkPlane.isPlaneYZ(Plane))
          Points[index] = new Pnt6D(new Pnt6D(Points[index])
          {
            Y = CenterPoint.Y + num * Math.Cos(buConversion.DegreeToRadian(Degree)),
            Z = CenterPoint.Z + num * Math.Sin(buConversion.DegreeToRadian(Degree))
          });
      }
    }
    catch (Exception ex)
    {
      string str = $"CenterPoint: {CenterPoint.ToString()} - Angle: {Angle.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void Rotate(Pnt3D CenterPoint, double Angle, WorkPlane Plane, ref List<Pnt9D> Points)
  {
    try
    {
      Pnt9D pnt9D = new Pnt9D();
      for (int index = 0; index <= Points.Count - 1; ++index)
      {
        double num = this.Length3D(new Pnt3D(Points[index]), CenterPoint, Plane);
        double Degree = this.PointAngle(new Pnt3D(Points[index]), CenterPoint, Plane) + Angle;
        pnt9D = new Pnt9D();
        if (WorkPlane.isPlaneXY(Plane))
        {
          Pnt9D Pnt = new Pnt9D(Points[index]);
          Pnt.X = CenterPoint.X + num * Math.Cos(buConversion.DegreeToRadian(Degree));
          Pnt.Y = CenterPoint.Y + num * Math.Sin(buConversion.DegreeToRadian(Degree));
          Points[index] = new Pnt9D(Pnt);
        }
        if (WorkPlane.isPlaneXZ(Plane))
        {
          Pnt9D Pnt = new Pnt9D(Points[index]);
          Pnt.X = CenterPoint.X + num * Math.Cos(buConversion.DegreeToRadian(Degree));
          Pnt.Z = CenterPoint.Z + num * Math.Sin(buConversion.DegreeToRadian(Degree));
          Points[index] = new Pnt9D(Pnt);
        }
        if (WorkPlane.isPlaneYZ(Plane))
        {
          Pnt9D Pnt = new Pnt9D(Points[index]);
          Pnt.Y = CenterPoint.Y + num * Math.Cos(buConversion.DegreeToRadian(Degree));
          Pnt.Z = CenterPoint.Z + num * Math.Sin(buConversion.DegreeToRadian(Degree));
          Points[index] = new Pnt9D(Pnt);
        }
      }
    }
    catch (Exception ex)
    {
      string str = $"CenterPoint: {CenterPoint.ToString()} - Angle: {Angle.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void Rotate(
    Pnt3D CenterPoint,
    double Angle,
    WorkPlane Plane,
    ref List<List<Pnt9D>> Points)
  {
    try
    {
      for (int index1 = 0; index1 <= Points.Count - 1; ++index1)
      {
        List<Pnt9D> pnt9DList = new List<Pnt9D>();
        buGeneral.CopyLists(Points[index1], ref pnt9DList);
        this.Rotate(CenterPoint, Angle, Plane, ref pnt9DList);
        Points[index1].Clear();
        for (int index2 = 0; index2 <= pnt9DList.Count - 1; ++index2)
          Points[index1].Add(new Pnt9D(pnt9DList[index2]));
      }
    }
    catch (Exception ex)
    {
      string str = $"CenterPoint: {CenterPoint.ToString()} - Angle: {Angle.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void Rotate(
    Pnt3D CenterPoint,
    double Angle,
    WorkPlane Plane,
    eEntities RefEntities,
    ref eEntities CalcEntities)
  {
    try
    {
      WorkPlane CalcPlane = new WorkPlane();
      Pnt3D pnt3D1 = new Pnt3D();
      Pnt3D pnt3D2 = new Pnt3D();
      List<Pnt3D> pnt3DList = new List<Pnt3D>();
      List<Pnt3D> Points1 = new List<Pnt3D>();
      List<eEntities> eEntitiesList = new List<eEntities>();
      pnt3DList.Clear();
      Points1.Clear();
      buGeneral.CopyLists(RefEntities.Vertice, ref pnt3DList);
      if (RefEntities.GetType() == typeof (eBSpline))
        buGeneral.CopyLists(((eCurveEntities) RefEntities).ControlPoints, ref Points1);
      if (RefEntities.GetType() == typeof (eBezeir))
        buGeneral.CopyLists(((eCurveEntities) RefEntities).ControlPoints, ref Points1);
      this.Rotate(CenterPoint, Angle, Plane, ref pnt3DList);
      this.Rotate(CenterPoint, Angle, Plane, ref Points1);
      if (RefEntities.GetType() == typeof (ePoint))
      {
        Pnt3D Points2 = new Pnt3D(((ePoint) RefEntities).StartPoint);
        this.Rotate(CenterPoint, Angle, Plane, ref Points2);
        CalcEntities = (eEntities) new ePoint(Points2, RefEntities.dispThickness, RefEntities.dispColor);
        eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
        CalcEntities.Update();
      }
      Pnt3D Points3;
      Pnt3D Points4;
      if (RefEntities.GetType() == typeof (eLine))
      {
        Points3 = new Pnt3D(((eLine) RefEntities).StartPoint);
        Points4 = new Pnt3D(((eLine) RefEntities).EndPoint);
        this.Rotate(CenterPoint, Angle, Plane, ref Points3);
        this.Rotate(CenterPoint, Angle, Plane, ref Points4);
        CalcEntities = (eEntities) new eLine(Points3, Points4, RefEntities.dispThickness, RefEntities.dispColor);
        eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
        CalcEntities.Update();
      }
      if (RefEntities.GetType() == typeof (eUpperLine))
      {
        Points3 = new Pnt3D(((eLine) RefEntities).StartPoint);
        Points4 = new Pnt3D(((eLine) RefEntities).EndPoint);
        this.Rotate(CenterPoint, Angle, Plane, ref Points3);
        this.Rotate(CenterPoint, Angle, Plane, ref Points4);
        CalcEntities = (eEntities) new eUpperLine(Points3, Points4);
        eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
        CalcEntities.Update();
      }
      if (RefEntities.GetType() == typeof (eCircle))
      {
        Points3 = new Pnt3D(((ePlaneEntities) RefEntities).CenterPoint);
        this.Rotate(CenterPoint, Angle, Plane, ref Points3);
        double radius = ((eCircle) RefEntities).Radius;
        if (Plane.PlaneType == ((ePlaneEntities) RefEntities).Plane.PlaneType)
          CalcPlane = ((ePlaneEntities) RefEntities).Plane;
        else
          this.PlaneRotation(((ePlaneEntities) RefEntities).Plane, Plane, Angle, ref CalcPlane);
        CalcEntities = (eEntities) new eCircle(Points3, radius, CalcPlane);
        eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
        CalcEntities.Update();
      }
      if (RefEntities.GetType() == typeof (eArc))
      {
        Points3 = new Pnt3D(((ePlaneEntities) RefEntities).CenterPoint);
        this.Rotate(CenterPoint, Angle, Plane, ref Points3);
        double radius = ((eCircle) RefEntities).Radius;
        double StartAngle;
        double EndAngle;
        if (Plane.PlaneType == ((ePlaneEntities) RefEntities).Plane.PlaneType)
        {
          CalcPlane = ((ePlaneEntities) RefEntities).Plane;
          StartAngle = ((eArc) RefEntities).StartAngle + Angle;
          EndAngle = ((eArc) RefEntities).EndAngle + Angle;
        }
        else
        {
          StartAngle = ((eArc) RefEntities).StartAngle;
          EndAngle = ((eArc) RefEntities).EndAngle;
          this.PlaneRotation(((ePlaneEntities) RefEntities).Plane, Plane, Angle, ref CalcPlane);
        }
        CalcEntities = (eEntities) new eArc(Points3, radius, StartAngle, EndAngle, CalcPlane);
        eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
        CalcEntities.Update();
      }
      if (RefEntities.GetType() == typeof (eEllipse))
      {
        Points3 = new Pnt3D(((ePlaneEntities) RefEntities).CenterPoint);
        this.Rotate(CenterPoint, Angle, Plane, ref Points3);
        double majorRadius = ((eEllipse) RefEntities).MajorRadius;
        double minorRadius = ((eEllipse) RefEntities).MinorRadius;
        double Angle1;
        if (Plane.PlaneType == ((ePlaneEntities) RefEntities).Plane.PlaneType)
        {
          CalcPlane = ((ePlaneEntities) RefEntities).Plane;
          Angle1 = ((eEllipse) RefEntities).Angle + Angle;
        }
        else
        {
          Angle1 = ((eEllipse) RefEntities).Angle;
          this.PlaneRotation(((ePlaneEntities) RefEntities).Plane, Plane, Angle, ref CalcPlane);
        }
        CalcEntities = (eEntities) new eEllipse(Points3, majorRadius, minorRadius, Angle1, CalcPlane);
        eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
        CalcEntities.Update();
      }
      if (RefEntities.GetType() == typeof (eEllipseArc))
      {
        Points3 = new Pnt3D(((ePlaneEntities) RefEntities).CenterPoint);
        this.Rotate(CenterPoint, Angle, Plane, ref Points3);
        double majorRadius = ((eEllipse) RefEntities).MajorRadius;
        double minorRadius = ((eEllipse) RefEntities).MinorRadius;
        double startAngle;
        double endAngle;
        double Angle2;
        if (Plane.PlaneType == ((ePlaneEntities) RefEntities).Plane.PlaneType)
        {
          CalcPlane = ((ePlaneEntities) RefEntities).Plane;
          startAngle = ((eEllipseArc) RefEntities).StartAngle;
          endAngle = ((eEllipseArc) RefEntities).EndAngle;
          Angle2 = ((eEllipse) RefEntities).Angle + Angle;
        }
        else
        {
          startAngle = ((eEllipseArc) RefEntities).StartAngle;
          endAngle = ((eEllipseArc) RefEntities).EndAngle;
          Angle2 = ((eEllipse) RefEntities).Angle;
          this.PlaneRotation(((ePlaneEntities) RefEntities).Plane, Plane, Angle, ref CalcPlane);
        }
        CalcEntities = (eEntities) new eEllipseArc(Points3, majorRadius, minorRadius, startAngle, endAngle, Angle2, CalcPlane);
        eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
        CalcEntities.Update();
      }
      if (RefEntities.GetType() == typeof (ePolyline) | RefEntities.GetType() == typeof (eBSpline) | RefEntities.GetType() == typeof (eBezeir))
      {
        if (RefEntities.GetType() == typeof (ePolyline))
        {
          CalcEntities = (eEntities) new ePolyline(pnt3DList, RefEntities.dispThickness, RefEntities.dispColor);
          eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
          CalcEntities.Update();
        }
        if (RefEntities.GetType() == typeof (eBSpline))
        {
          CalcEntities = (eEntities) new eBSpline(Points1, RefEntities.dispThickness, RefEntities.dispColor, RefEntities.bClosed, ((eBSpline) RefEntities).BType);
          eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
          CalcEntities.Update();
        }
        if (RefEntities.GetType() == typeof (eBezeir))
        {
          CalcEntities = (eEntities) new eBezeir(Points1, RefEntities.dispThickness, RefEntities.dispColor);
          eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
          CalcEntities.Update();
        }
      }
      if (RefEntities.GetType() == typeof (eSurface))
      {
        List<Triangle3D> triangles = new List<Triangle3D>();
        for (int index = 0; index <= RefEntities.Triangles.Count - 1; ++index)
        {
          Triangle3D triangle3D = new Triangle3D(RefEntities.Triangles[index]);
          this.Rotate(CenterPoint, Angle, Plane, ref triangle3D.FirstPoint);
          this.Rotate(CenterPoint, Angle, Plane, ref triangle3D.SecondPoint);
          this.Rotate(CenterPoint, Angle, Plane, ref triangle3D.ThirdPoint);
          triangles.Add(triangle3D);
        }
        CalcEntities = (eEntities) new eSurface(triangles, RefEntities.dispColor);
        eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
        CalcEntities.Update();
      }
      if (!(RefEntities.GetType() == typeof (eMesh)))
        return;
      CalcEntities = (eEntities) new eMesh(((eMesh) RefEntities).TriIndex, pnt3DList);
      eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
      CalcEntities.Update();
    }
    catch (Exception ex)
    {
      string str = $"CenterPoint: {CenterPoint.ToString()} - Angle: {Angle.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

