  public void Rotate(
    Pnt3D CenterPoint,
    double Angle,
    WorkPlane Plane,
    geoEntity RefEntities,
    ref geoEntity CalcEntities)
  {
    try
    {
      WorkPlane CalcPlane = new WorkPlane();
      Pnt3D pnt3D1 = new Pnt3D();
      Pnt3D pnt3D2 = new Pnt3D();
      List<Pnt3D> vertice = new List<Pnt3D>();
      List<Pnt3D> controls = new List<Pnt3D>();
      List<eEntities> eEntitiesList = new List<eEntities>();
      vertice.Clear();
      controls.Clear();
      buGeneral.CopyLists(RefEntities.Vertice, ref vertice);
      if (RefEntities.GetType() == typeof (eBSpline))
        buGeneral.CopyLists(((geoBSpline) RefEntities).ControlPoints, ref controls);
      this.Rotate(CenterPoint, Angle, Plane, ref vertice);
      this.Rotate(CenterPoint, Angle, Plane, ref controls);
      if (RefEntities.GetType() == typeof (geoPoint))
      {
        Pnt3D Points = new Pnt3D(((geoPoint) RefEntities).StartPoint);
        this.Rotate(CenterPoint, Angle, Plane, ref Points);
        CalcEntities = (geoEntity) new geoPoint(Points, RefEntities.Color, RefEntities.Thickness);
      }
      Pnt3D Points1;
      if (RefEntities.GetType() == typeof (geoLine))
      {
        Points1 = new Pnt3D(((geoLine) RefEntities).StartPoint);
        Pnt3D Points2 = new Pnt3D(((geoLine) RefEntities).EndPoint);
        this.Rotate(CenterPoint, Angle, Plane, ref Points1);
        this.Rotate(CenterPoint, Angle, Plane, ref Points2);
        CalcEntities = (geoEntity) new geoLine(Points1, Points2, RefEntities.Color, RefEntities.Thickness);
      }
      if (RefEntities.GetType() == typeof (geoCircle))
      {
        Points1 = new Pnt3D(((geoCircle) RefEntities).CenterPoint);
        this.Rotate(CenterPoint, Angle, Plane, ref Points1);
        double radius = ((geoCircle) RefEntities).Radius;
        if (Plane.PlaneType == RefEntities.Plane.PlaneType)
          CalcPlane = RefEntities.Plane;
        else
          this.PlaneRotation(RefEntities.Plane, Plane, Angle, ref CalcPlane);
        CalcEntities = (geoEntity) new geoCircle(Points1, radius, CalcPlane, RefEntities.Color, RefEntities.Thickness);
      }
      if (RefEntities.GetType() == typeof (geoArc))
      {
        Points1 = new Pnt3D(((geoArc) RefEntities).CenterPoint);
        this.Rotate(CenterPoint, Angle, Plane, ref Points1);
        double radius = ((geoArc) RefEntities).Radius;
        double StartAng;
        double EndAng;
        if (Plane.PlaneType == RefEntities.Plane.PlaneType)
        {
          CalcPlane = RefEntities.Plane;
          StartAng = ((geoArc) RefEntities).StartAngle + Angle;
          EndAng = ((geoArc) RefEntities).EndAngle + Angle;
        }
        else
        {
          StartAng = ((geoArc) RefEntities).StartAngle;
          EndAng = ((geoArc) RefEntities).EndAngle;
          this.PlaneRotation(RefEntities.Plane, Plane, Angle, ref CalcPlane);
        }
        CalcEntities = (geoEntity) new geoArc(Points1, radius, StartAng, EndAng, CalcPlane, RefEntities.Color, RefEntities.Thickness);
      }
      if (RefEntities.GetType() == typeof (geoEllipse))
      {
        Points1 = new Pnt3D(((geoEllipse) RefEntities).CenterPoint);
        this.Rotate(CenterPoint, Angle, Plane, ref Points1);
        double majorRadius = ((geoEllipse) RefEntities).MajorRadius;
        double minorRadius = ((geoEllipse) RefEntities).MinorRadius;
        double Angle1;
        if (Plane.PlaneType == RefEntities.Plane.PlaneType)
        {
          CalcPlane = RefEntities.Plane;
          Angle1 = ((geoEllipse) RefEntities).Angle + Angle;
        }
        else
        {
          Angle1 = ((geoEllipse) RefEntities).Angle;
          this.PlaneRotation(RefEntities.Plane, Plane, Angle, ref CalcPlane);
        }
        CalcEntities = (geoEntity) new geoEllipse(Points1, majorRadius, minorRadius, Angle1, CalcPlane, RefEntities.Color, RefEntities.Thickness);
      }
      if (RefEntities.GetType() == typeof (geoPolyline) | RefEntities.GetType() == typeof (geoBSpline))
      {
        if (RefEntities.GetType() == typeof (geoPolyline))
          CalcEntities = (geoEntity) new geoPolyline(vertice, RefEntities.Color, RefEntities.Thickness);
        if (RefEntities.GetType() == typeof (geoBSpline))
          CalcEntities = (geoEntity) new geoBSpline(controls, ((geoBSpline) RefEntities).Closed, ((geoBSpline) RefEntities).BType, RefEntities.Color, RefEntities.Thickness);
      }
      CalcEntities.TypeDefination = RefEntities.TypeDefination;
      geoEntity.CopyProperties(RefEntities, ref CalcEntities);
    }
    catch (Exception ex)
    {
      string str = $"CenterPoint: {CenterPoint.ToString()} - Angle: {Angle.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

