        CalcEntities = (eEntities) new eEllipse(Points3, majorRadius, minorRadius, Angle1, CalcPlane);
        eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
        CalcEntities.Update();
      }
      if (RefEntities.GetType() == typeof (eEllipseArc))
      {
        Points3 = new Pnt3D(((ePlaneEntities) RefEntities).CenterPoint);
        this.Rotate(CenterPoint, Angle, Plane, ref Points3);
        double majorRadius = ((eEllipse) RefEntities).MajorRadius;
        double minorRadius = ((eEllipse) RefEntities).MinorRadius;
        double startAngle;
        double endAngle;
        double Angle2;
        if (Plane.PlaneType == ((ePlaneEntities) RefEntities).Plane.PlaneType)
        {
          CalcPlane = ((ePlaneEntities) RefEntities).Plane;
          startAngle = ((eEllipseArc) RefEntities).StartAngle;
          endAngle = ((eEllipseArc) RefEntities).EndAngle;
          Angle2 = ((eEllipse) RefEntities).Angle + Angle;
        }
        else
        {
          startAngle = ((eEllipseArc) RefEntities).StartAngle;
          endAngle = ((eEllipseArc) RefEntities).EndAngle;
          Angle2 = ((eEllipse) RefEntities).Angle;
          this.PlaneRotation(((ePlaneEntities) RefEntities).Plane, Plane, Angle, ref CalcPlane);
        }
        CalcEntities = (eEntities) new eEllipseArc(Points3, majorRadius, minorRadius, startAngle, endAngle, Angle2, CalcPlane);
        eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
        CalcEntities.Update();
      }
      if (RefEntities.GetType() == typeof (ePolyline) | RefEntities.GetType() == typeof (eBSpline) | RefEntities.GetType() == typeof (eBezeir))
      {
        if (RefEntities.GetType() == typeof (ePolyline))
        {
          CalcEntities = (eEntities) new ePolyline(pnt3DList, RefEntities.dispThickness, RefEntities.dispColor);
          eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
          CalcEntities.Update();
        }
        if (RefEntities.GetType() == typeof (eBSpline))
        {
          CalcEntities = (eEntities) new eBSpline(Points1, RefEntities.dispThickness, RefEntities.dispColor, RefEntities.bClosed, ((eBSpline) RefEntities).BType);
          eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
          CalcEntities.Update();
        }
        if (RefEntities.GetType() == typeof (eBezeir))
        {
          CalcEntities = (eEntities) new eBezeir(Points1, RefEntities.dispThickness, RefEntities.dispColor);
          eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
          CalcEntities.Update();
        }
      }
      if (RefEntities.GetType() == typeof (eSurface))
      {
        List<Triangle3D> triangles = new List<Triangle3D>();
        for (int index = 0; index <= RefEntities.Triangles.Count - 1; ++index)
        {
          Triangle3D triangle3D = new Triangle3D(RefEntities.Triangles[index]);
          this.Rotate(CenterPoint, Angle, Plane, ref triangle3D.FirstPoint);
          this.Rotate(CenterPoint, Angle, Plane, ref triangle3D.SecondPoint);
          this.Rotate(CenterPoint, Angle, Plane, ref triangle3D.ThirdPoint);
          triangles.Add(triangle3D);
        }
        CalcEntities = (eEntities) new eSurface(triangles, RefEntities.dispColor);
        eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
        CalcEntities.Update();
      }
      if (!(RefEntities.GetType() == typeof (eMesh)))
        return;
      CalcEntities = (eEntities) new eMesh(((eMesh) RefEntities).TriIndex, pnt3DList);
      eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
      CalcEntities.Update();
    }
    catch (Exception ex)
    {
      string str = $"CenterPoint: {CenterPoint.ToString()} - Angle: {Angle.ToString()} - Direction: {Direction.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

