  public void PlaneRotation(
    WorkPlane EntityPlane,
    WorkPlane OperationPlane,
    double Angle,
    ref WorkPlane CalcPlane)
  {
    try
    {
      if (buCompare.EQ(Math.Abs(Angle), 90.0) | buCompare.EQ(Math.Abs(Angle), 270.0))
      {
        if (EntityPlane.PlaneType == planeType.XY)
        {
          if (OperationPlane.PlaneType == planeType.YZ)
            CalcPlane = new WorkPlane(planeType.XZ, 1);
          if (OperationPlane.PlaneType == planeType.XZ)
            CalcPlane = new WorkPlane(planeType.YZ, 1);
        }
        if (EntityPlane.PlaneType == planeType.XZ)
        {
          if (OperationPlane.PlaneType == planeType.YZ)
            CalcPlane = new WorkPlane(planeType.XY, 1);
          if (OperationPlane.PlaneType == planeType.XY)
            CalcPlane = new WorkPlane(planeType.XZ, 1);
        }
        if (EntityPlane.PlaneType != planeType.YZ)
          return;
        if (OperationPlane.PlaneType == planeType.XZ)
          CalcPlane = new WorkPlane(planeType.XY, 1);
        if (OperationPlane.PlaneType != planeType.XY)
          return;
        CalcPlane = new WorkPlane(planeType.XZ, 1);
      }
      else
        CalcPlane = new WorkPlane(EntityPlane);
    }
    catch (Exception ex)
    {
      string str = $"EntityPlane: {EntityPlane.ToString()} - OperationPlane: {OperationPlane.ToString()} - Angle: {Angle.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void LineerArray(
    Pnt3D BasePoint,
    Vec3D DistanceVector,
    int XCount,
    int YCount,
    int ZCount,
    bool AcceptFirstEntity,
    Vec3D OffsetVector,
    eEntities RefEntities,
    ref List<eEntities> CalcEntities)
  {
    try
    {
      Pnt3D pnt3D1 = new Pnt3D();
      Pnt3D pnt3D2 = new Pnt3D();
      eEntities CalcEnt = new eEntities();
      eEntities eEntities = new eEntities();
      CalcEntities = new List<eEntities>();
      int num1;
      int num2;
      int num3;
      if (AcceptFirstEntity)
      {
        num1 = XCount;
        num2 = YCount;
        num3 = ZCount;
      }
      else
      {
        num1 = XCount + 1;
        num2 = YCount + 1;
        num3 = ZCount + 1;
      }
      eEntities copiedEnt = new eEntities();
      eEntities.CopyEntity(RefEntities, ref copiedEnt);
      CalcEntities.Add(copiedEnt);
      for (int index1 = 0; index1 <= num3 - 1; ++index1)
      {
        for (int index2 = 0; index2 <= num1 - 1; ++index2)
        {
          for (int index3 = 0; index3 <= num2 - 1; ++index3)
          {
            pnt3D2 = new Pnt3D();
            if (index2 != 0 | index3 != 0 | index1 != 0)
            {
              pnt3D1.X = (double) index2 * DistanceVector.X + (double) index2 * OffsetVector.X;
              pnt3D1.Y = (double) index3 * DistanceVector.Y + (double) index3 * OffsetVector.Y;
              pnt3D1.Z = (double) index1 * DistanceVector.Z;
              Pnt3D pnt3D3 = BasePoint + pnt3D1;
              this.Move(BasePoint, pnt3D3, RefEntities, ref CalcEnt);
              RefEntities = new eEntities();
              eEntities.CopyEntity(copiedEnt, ref RefEntities);
              if (RefEntities.Shape != null)
              {
                CalcEnt.Shape = new ShapeData();
                ShapeData.Copy(RefEntities.Shape, ref CalcEnt.Shape);
                this.ShapeDataMove(BasePoint, pnt3D3, ref CalcEnt.Shape);
              }
              CalcEntities.Add(CalcEnt);
            }
          }
        }
      }
    }
    catch (Exception ex)
    {
      string str = $"BasePoint: {BasePoint.ToString()} - DistanceVector: {DistanceVector.ToString()} - X Count: {XCount.ToString()} - Y Count: {YCount.ToString()} - Z Count: {ZCount.ToString()}- RefEntities{RefEntities.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

