  public void PolarArray(
    Pnt3D Center,
    ClockDirectionType Direction,
    int Count,
    double PolarAngle,
    WorkPlane Plane,
    bool AcceptFirstEntity,
    List<Pnt3D>[] RefVertices,
    ref List<Pnt3D>[] Vertices)
  {
    try
    {
      Pnt3D pnt3D1 = new Pnt3D();
      int num1 = !AcceptFirstEntity ? Count + 1 : Count;
      Vertices = new List<Pnt3D>[RefVertices.Length * num1];
      int index1 = 0;
      for (int index2 = 0; index2 <= num1 - 1; ++index2)
      {
        for (int index3 = 0; index3 <= RefVertices.Length - 1; ++index3)
        {
          Vertices[index1] = new List<Pnt3D>();
          for (int index4 = 0; index4 <= RefVertices[index3].Count - 1; ++index4)
          {
            double num2 = this.Length3D(RefVertices[index3][index4], Center);
            double num3 = this.PointAngle(RefVertices[index3][index4], Center, Plane);
            double Degree = Direction != ClockDirectionType.CW ? num3 - (double) index2 * PolarAngle : num3 + (double) index2 * PolarAngle;
            Pnt3D pnt3D2 = new Pnt3D();
            if (WorkPlane.isPlaneXY(Plane))
            {
              pnt3D2.X = Center.X + num2 * Math.Cos(buConversion.DegreeToRadian(Degree));
              pnt3D2.Y = Center.Y + num2 * Math.Sin(buConversion.DegreeToRadian(Degree));
              pnt3D2.Z = RefVertices[index3][index4].Z;
            }
            if (WorkPlane.isPlaneXZ(Plane))
            {
              pnt3D2.X = Center.X + num2 * Math.Cos(buConversion.DegreeToRadian(Degree));
              pnt3D2.Y = RefVertices[index3][index4].Y;
              pnt3D2.Z = Center.Z + num2 * Math.Sin(buConversion.DegreeToRadian(Degree));
            }
            if (WorkPlane.isPlaneYZ(Plane))
            {
              pnt3D2.X = RefVertices[index3][index4].X;
              pnt3D2.Y = Center.Y + num2 * Math.Cos(buConversion.DegreeToRadian(Degree));
              pnt3D2.Z = Center.Z + num2 * Math.Sin(buConversion.DegreeToRadian(Degree));
            }
            Vertices[index1].Add(pnt3D2);
          }
          ++index1;
        }
      }
    }
    catch (Exception ex)
    {
      string str = $"Center: {Center.ToString()} - Direction: {Direction.ToString()} - Count: {Count.ToString()} - PolarAngle: {PolarAngle.ToString()} - Plane: {Plane.ToString()}";
