  public void Mirror(
    Pnt3D BasePoint,
    Pnt3D VectorPoint,
    Pnt3D RefPoint,
    WorkPlane Plane,
    double ExtraOffset,
    ref Pnt3D CalcPoint)
  {
    try
    {
      double Distance = 0.0;
      Pnt3D PerpendicularPoint = new Pnt3D();
      this.PerpendicularDistancePointToLine(BasePoint, VectorPoint, RefPoint, Plane, ref PerpendicularPoint, ref Distance);
      double Angle = this.PointAngle(PerpendicularPoint, RefPoint, Plane);
      this.LineWithLengthAndAngle(RefPoint, 2.0 * Distance + ExtraOffset, Angle, Plane, ref BasePoint, ref CalcPoint);
    }
    catch (Exception ex)
    {
      string str = $"BasePoint: {BasePoint.ToString()} - VectorPoint: {VectorPoint.ToString()} - ExtraOffset: {ExtraOffset.ToString()} - RefPoint: {RefPoint.ToString()}Plane: {Plane.ToString()}";
