  public void Mirror(
    Pnt3D BasePoint,
    Pnt3D VectorPoint,
    geoEntity RefEntity,
    WorkPlane Plane,
    double ExtraOffset,
    ref geoEntity CalcEntity)
  {
    try
    {
      Pnt3D CalcPoint1 = new Pnt3D();
      Pnt3D CalcPoint2 = new Pnt3D();
      Pnt3D CalcPoint3 = new Pnt3D();
      List<Pnt3D> pnt3DList = new List<Pnt3D>();
      List<Pnt3D> vertice = new List<Pnt3D>();
      List<Pnt3D> controls = new List<Pnt3D>();
      if (RefEntity.GetType() == typeof (geoArc))
      {
        this.Mirror(BasePoint, VectorPoint, ((geoArc) RefEntity).CenterPoint, Plane, ExtraOffset, ref CalcPoint1);
        this.Mirror(BasePoint, VectorPoint, RefEntity.Vertice[0], Plane, ExtraOffset, ref CalcPoint2);
        this.Mirror(BasePoint, VectorPoint, RefEntity.Vertice[RefEntity.Vertice.Count - 1], Plane, ExtraOffset, ref CalcPoint3);
        Plane = RefEntity.Plane;
        double radius = ((geoArc) RefEntity).Radius;
        double StartAng = this.PointAngle(CalcPoint3, CalcPoint1, Plane);
        double EndAng = this.PointAngle(CalcPoint2, CalcPoint1, Plane);
        if (StartAng > EndAng)
          EndAng += 360.0;
        CalcEntity = (geoEntity) new geoArc(CalcPoint1, radius, StartAng, EndAng, Plane);
      }
      if (!(RefEntity.GetType() == typeof (eEllipseArc)))
        ;
      if (RefEntity.GetType() == typeof (geoPoint))
      {
        this.Mirror(BasePoint, VectorPoint, ((geoPoint) RefEntity).StartPoint, Plane, ExtraOffset, ref CalcPoint2);
        CalcEntity = (geoEntity) new geoPoint(CalcPoint2);
      }
      if (RefEntity.GetType() == typeof (geoLine))
      {
        this.Mirror(BasePoint, VectorPoint, ((geoLine) RefEntity).StartPoint, Plane, ExtraOffset, ref CalcPoint2);
        this.Mirror(BasePoint, VectorPoint, ((geoLine) RefEntity).EndPoint, Plane, ExtraOffset, ref CalcPoint3);
        CalcEntity = (geoEntity) new geoLine(CalcPoint2, CalcPoint3);
      }
      if (RefEntity.GetType() == typeof (geoCircle))
      {
        double radius = ((geoCircle) RefEntity).Radius;
        Plane = RefEntity.Plane;
        this.Mirror(BasePoint, VectorPoint, ((geoCircle) RefEntity).CenterPoint, Plane, ExtraOffset, ref CalcPoint1);
        CalcEntity = (geoEntity) new geoCircle(CalcPoint1, radius, Plane);
      }
      if (RefEntity.GetType() == typeof (geoEllipse))
      {
        double majorRadius = ((geoEllipse) RefEntity).MajorRadius;
        double minorRadius = ((geoEllipse) RefEntity).MinorRadius;
        Plane = RefEntity.Plane;
        this.Mirror(BasePoint, VectorPoint, ((geoEllipse) RefEntity).CenterPoint, Plane, ExtraOffset, ref CalcPoint1);
        double Angle = 360.0 - ((geoEllipse) RefEntity).Angle;
        CalcEntity = (geoEntity) new geoEllipse(CalcPoint1, majorRadius, minorRadius, Angle, Plane);
      }
      if (RefEntity.GetType() == typeof (geoText))
      {
        this.Mirror(BasePoint, VectorPoint, ((geoText) RefEntity).StartPoint, Plane, ExtraOffset, ref CalcPoint2);
        CalcEntity = (geoEntity) new geoText(CalcPoint2, ((geoText) RefEntity).TextString, ((geoText) RefEntity).TextFont, RefEntity.Color, ((geoText) RefEntity).Height, ((geoText) RefEntity).Angle);
      }
      for (int index = 0; index <= RefEntity.Vertice.Count - 1; ++index)
      {
        this.Mirror(BasePoint, VectorPoint, RefEntity.Vertice[index], Plane, ExtraOffset, ref CalcPoint2);
        vertice.Add(new Pnt3D(CalcPoint2));
      }
      if (RefEntity.GetType() == typeof (geoPolyline))
        CalcEntity = (geoEntity) new geoPolyline(vertice);
      if (RefEntity.GetType() == typeof (eBSpline))
      {
        for (int index = 0; index <= ((geoBSpline) RefEntity).ControlPoints.Count - 1; ++index)
        {
          this.Mirror(BasePoint, VectorPoint, ((geoBSpline) RefEntity).ControlPoints[index], Plane, ExtraOffset, ref CalcPoint2);
          controls.Add(new Pnt3D(CalcPoint2));
        }
        CalcEntity = (geoEntity) new geoBSpline(controls, ((geoBSpline) RefEntity).Closed, ((geoBSpline) RefEntity).BType, RefEntity.Color, RefEntity.Thickness);
      }
      CalcEntity.TypeDefination = RefEntity.TypeDefination;
      geoEntity.CopyProperties(RefEntity, ref CalcEntity);
    }
    catch (Exception ex)
    {
      string str = $"BasePoint: {BasePoint.ToString()} - VectorPoint: {VectorPoint.ToString()} - ExtraOffset: {ExtraOffset.ToString()} - RefEntity: {RefEntity.ToString()}Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void Mirror(
    Pnt3D BasePoint,
    Pnt3D VectorPoint,
    eEntities RefEntity,
    WorkPlane Plane,
    double ExtraOffset,
    ref eEntities CalcEntity)
  {
    try
    {
      Pnt3D CalcPoint1 = new Pnt3D();
      Pnt3D CalcPoint2 = new Pnt3D();
      Pnt3D CalcPoint3 = new Pnt3D();
      List<Pnt3D> pnt3DList = new List<Pnt3D>();
      List<Pnt3D> Vertices = new List<Pnt3D>();
      List<Pnt3D> Points = new List<Pnt3D>();
      if (RefEntity.GetType() == typeof (eArc))
      {
        this.Mirror(BasePoint, VectorPoint, ((ePlaneEntities) RefEntity).CenterPoint, Plane, ExtraOffset, ref CalcPoint1);
        this.Mirror(BasePoint, VectorPoint, ((eArc) RefEntity).StartPoint, Plane, ExtraOffset, ref CalcPoint2);
        this.Mirror(BasePoint, VectorPoint, ((eArc) RefEntity).EndPoint, Plane, ExtraOffset, ref CalcPoint3);
        Plane = ((ePlaneEntities) RefEntity).Plane;
        double radius = ((eCircle) RefEntity).Radius;
        double StartAngle = this.PointAngle(CalcPoint3, CalcPoint1, Plane);
        double EndAngle = this.PointAngle(CalcPoint2, CalcPoint1, Plane);
        if (StartAngle > EndAngle)
          EndAngle += 360.0;
        CalcEntity = (eEntities) new eArc(CalcPoint1, radius, StartAngle, EndAngle, Plane);
        eEntities.CopyCommonPorperties(RefEntity, ref CalcEntity);
      }
      if (!(RefEntity.GetType() == typeof (eEllipseArc)))
        ;
      if (RefEntity.GetType() == typeof (ePoint))
      {
        this.Mirror(BasePoint, VectorPoint, ((ePoint) RefEntity).StartPoint, Plane, ExtraOffset, ref CalcPoint2);
        CalcEntity = (eEntities) new ePoint(CalcPoint2);
        eEntities.CopyCommonPorperties(RefEntity, ref CalcEntity);
      }
      if (RefEntity.GetType() == typeof (eLine))
      {
        this.Mirror(BasePoint, VectorPoint, ((eLine) RefEntity).StartPoint, Plane, ExtraOffset, ref CalcPoint2);
        this.Mirror(BasePoint, VectorPoint, ((eLine) RefEntity).EndPoint, Plane, ExtraOffset, ref CalcPoint3);
        CalcEntity = (eEntities) new eLine(CalcPoint2, CalcPoint3);
        eEntities.CopyCommonPorperties(RefEntity, ref CalcEntity);
      }
      if (RefEntity.GetType() == typeof (eCircle))
      {
        double radius = ((eCircle) RefEntity).Radius;
        Plane = ((ePlaneEntities) RefEntity).Plane;
        this.Mirror(BasePoint, VectorPoint, ((ePlaneEntities) RefEntity).CenterPoint, Plane, ExtraOffset, ref CalcPoint1);
        CalcEntity = (eEntities) new eCircle(CalcPoint1, radius, Plane);
        eEntities.CopyCommonPorperties(RefEntity, ref CalcEntity);
      }
      if (RefEntity.GetType() == typeof (eEllipse))
      {
        double majorRadius = ((eEllipse) RefEntity).MajorRadius;
        double minorRadius = ((eEllipse) RefEntity).MinorRadius;
        Plane = ((ePlaneEntities) RefEntity).Plane;
        this.Mirror(BasePoint, VectorPoint, ((ePlaneEntities) RefEntity).CenterPoint, Plane, ExtraOffset, ref CalcPoint1);
        double Angle = 360.0 - ((eEllipse) RefEntity).Angle;
        CalcEntity = (eEntities) new eEllipse(CalcPoint1, majorRadius, minorRadius, Angle, Plane);
        eEntities.CopyCommonPorperties(RefEntity, ref CalcEntity);
      }
      if (RefEntity.GetType() == typeof (ePicture))
      {
        this.Mirror(BasePoint, VectorPoint, ((ePicture) RefEntity).StartPoint, Plane, ExtraOffset, ref CalcPoint2);
        this.Mirror(BasePoint, VectorPoint, ((ePicture) RefEntity).EndPoint, Plane, ExtraOffset, ref CalcPoint3);
        CalcEntity = (eEntities) new ePicture(CalcPoint2, CalcPoint3, ((ePicture) RefEntity).PicturePath, ((ePlaneEntities) RefEntity).Plane);
        eEntities.CopyCommonPorperties(RefEntity, ref CalcEntity);
      }
      if (RefEntity.GetType() == typeof (eText))
      {
        this.Mirror(BasePoint, VectorPoint, ((eText) RefEntity).StartPoint, Plane, ExtraOffset, ref CalcPoint2);
        CalcEntity = (eEntities) new eText(CalcPoint2, ((eText) RefEntity).TextString, ((eText) RefEntity).Height, ((ePlaneEntities) RefEntity).Plane);
        eEntities.CopyCommonPorperties(RefEntity, ref CalcEntity);
      }
      for (int index = 0; index <= RefEntity.Vertice.Count - 1; ++index)
      {
        this.Mirror(BasePoint, VectorPoint, RefEntity.Vertice[index], Plane, ExtraOffset, ref CalcPoint2);
        Vertices.Add(new Pnt3D(CalcPoint2));
      }
      if (RefEntity.GetType() == typeof (ePolyline))
      {
        CalcEntity = (eEntities) new ePolyline(Vertices);
        eEntities.CopyCommonPorperties(RefEntity, ref CalcEntity);
      }
      if (RefEntity.GetType() == typeof (eBSpline))
      {
        for (int index = 0; index <= ((eCurveEntities) RefEntity).ControlPoints.Count - 1; ++index)
        {
          this.Mirror(BasePoint, VectorPoint, ((eCurveEntities) RefEntity).ControlPoints[index], Plane, ExtraOffset, ref CalcPoint2);
          Points.Add(new Pnt3D(CalcPoint2));
        }
        CalcEntity = (eEntities) new eBSpline(Points, ((eBSpline) RefEntity).BType, ((eBSpline) RefEntity).Order, ((eBSpline) RefEntity).Weigth);
        eEntities.CopyCommonPorperties(RefEntity, ref CalcEntity);
      }
      if (RefEntity.GetType() == typeof (eBezeir))
      {
        for (int index = 0; index <= ((eCurveEntities) RefEntity).ControlPoints.Count - 1; ++index)
        {
          this.Mirror(BasePoint, VectorPoint, ((eCurveEntities) RefEntity).ControlPoints[index], Plane, ExtraOffset, ref CalcPoint2);
          Points.Add(new Pnt3D(CalcPoint2));
        }
        CalcEntity = (eEntities) new eBezeir(Points);
        eEntities.CopyCommonPorperties(RefEntity, ref CalcEntity);
      }
      if (!(RefEntity.GetType() == typeof (eSurface)))
        return;
      List<Triangle3D> triangles = new List<Triangle3D>();
      for (int index = 0; index <= RefEntity.Triangles.Count - 1; ++index)
      {
        Triangle3D CalcTriangle = new Triangle3D();
        this.Mirror(BasePoint, VectorPoint, RefEntity.Triangles[index], Plane, ExtraOffset, ref CalcTriangle);
        triangles.Add(CalcTriangle);
      }
      CalcEntity = (eEntities) new eSurface(triangles);
      eEntities.CopyCommonPorperties(RefEntity, ref CalcEntity);
      RefEntity.Update();
    }
    catch (Exception ex)
    {
      string str = $"BasePoint: {BasePoint.ToString()} - VectorPoint: {VectorPoint.ToString()} - ExtraOffset: {ExtraOffset.ToString()} - RefEntity: {RefEntity.ToString()}Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

