  public void Tangent(
    eEntities RefEntity,
    Pnt3D RefTangentPoint,
    ref eEntities MovedEntity,
    Pnt3D MovedTangentPoint,
    double Offset,
    bool ReverseAngle,
    WorkPlane Plane)
  {
    try
    {
      double Angle1 = 0.0;
      double num1 = 1.0;
      ClosestPointType ClosestPoint = ClosestPointType.Start;
      Pnt3D EndPnt1 = new Pnt3D();
      if (ReverseAngle)
        num1 = -1.0;
      if (RefEntity.GetType() == typeof (eLine))
      {
        this.FindClosestPointOfLine(RefEntity.Vertice[0], RefEntity.Vertice[RefEntity.Vertice.Count - 1], RefTangentPoint, ref ClosestPoint);
        double Angle2;
        if (ClosestPoint == ClosestPointType.Start)
        {
          Angle2 = this.PointAngle(RefEntity.Vertice[RefEntity.Vertice.Count - 1], RefEntity.Vertice[0], Plane);
          EndPnt1 = new Pnt3D(RefEntity.Vertice[0]);
          if (!buCompare.EQ(Offset, 0.0))
          {
            Pnt3D BasePnt = new Pnt3D();
            this.LineWithLengthAndAngle(EndPnt1, Offset, Angle2, Plane, ref BasePnt, ref EndPnt1);
          }
        }
        else
        {
          Angle2 = this.PointAngle(RefEntity.Vertice[0], RefEntity.Vertice[RefEntity.Vertice.Count - 1], Plane);
          EndPnt1 = new Pnt3D(RefEntity.Vertice[RefEntity.Vertice.Count - 1]);
          if (!buCompare.EQ(Offset, 0.0))
          {
            Pnt3D BasePnt = new Pnt3D();
            this.LineWithLengthAndAngle(EndPnt1, Offset, Angle2, Plane, ref BasePnt, ref EndPnt1);
          }
        }
        Angle1 = Angle2 + 180.0;
      }
      if (RefEntity.GetType() == typeof (eArc))
      {
        this.FindClosestPointOfLine(RefEntity.Vertice[0], RefEntity.Vertice[RefEntity.Vertice.Count - 1], RefTangentPoint, ref ClosestPoint);
        if (ClosestPoint == ClosestPointType.Start)
        {
          Angle1 = ((eArc) RefEntity).StartAngle + 90.0 * num1 - 180.0;
          EndPnt1 = new Pnt3D(RefEntity.Vertice[0]);
          if (!buCompare.EQ(Offset, 0.0))
          {
            Pnt3D BasePnt = new Pnt3D();
            this.LineWithLengthAndAngle(EndPnt1, Offset, Angle1, Plane, ref BasePnt, ref EndPnt1);
          }
        }
        else
        {
          Angle1 = ((eArc) RefEntity).EndAngle + 90.0 * num1;
          EndPnt1 = new Pnt3D(RefEntity.Vertice[RefEntity.Vertice.Count - 1]);
          if (!buCompare.EQ(Offset, 0.0))
          {
            Pnt3D BasePnt = new Pnt3D();
            this.LineWithLengthAndAngle(EndPnt1, Offset, Angle1, Plane, ref BasePnt, ref EndPnt1);
          }
        }
      }
      if (RefEntity.GetType() == typeof (eCircle))
      {
        double Angle3 = this.PointAngle(RefTangentPoint, ((ePlaneEntities) RefEntity).CenterPoint, Plane);
        Pnt3D BasePnt1 = new Pnt3D();
        this.LineWithLengthAndAngle(((ePlaneEntities) RefEntity).CenterPoint, ((eCircle) RefEntity).Radius, Angle3, Plane, ref BasePnt1, ref EndPnt1);
        Angle1 = Angle3 + 90.0 * num1;
        if (!buCompare.EQ(Offset, 0.0))
        {
          Pnt3D BasePnt2 = new Pnt3D();
          this.LineWithLengthAndAngle(EndPnt1, Offset, Angle1, Plane, ref BasePnt2, ref EndPnt1);
        }
      }
      if (RefEntity.GetType() == typeof (eEllipse) | RefEntity.GetType() == typeof (eEllipseArc) | RefEntity.GetType() == typeof (eBSpline) | RefEntity.GetType() == typeof (eBezeir))
      {
        Pnt3D CalculatedPoint = new Pnt3D();
        double Distance = 0.0;
        int VerticeIndex = 0;
        ePolyline RefEntity1 = new ePolyline(RefEntity.Vertice);
        if (this.IsPointOverEntity((eEntities) RefEntity1, RefTangentPoint, Plane, buSystem.resolutionCompare, ref CalculatedPoint, ref Distance, ref VerticeIndex) && VerticeIndex >= 0 & VerticeIndex < RefEntity1.Vertice.Count - 1)
        {
          Angle1 = this.PointAngle(RefEntity1.Vertice[VerticeIndex + 1], RefEntity1.Vertice[VerticeIndex], Plane);
          if (ReverseAngle)
            Angle1 += 180.0;
          EndPnt1 = new Pnt3D(RefEntity1.Vertice[VerticeIndex]);
          if (!buCompare.EQ(Offset, 0.0))
          {
            Pnt3D BasePnt = new Pnt3D();
            this.LineWithLengthAndAngle(EndPnt1, Offset, Angle1, Plane, ref BasePnt, ref EndPnt1);
          }
        }
      }
      if (Angle1 < 0.0)
        Angle1 += 360.0;
      double num2 = 0.0;
      Pnt3D EndPnt2 = new Pnt3D();
      bool flag = false;
      if (MovedEntity.GetType() == typeof (eLine))
      {
        this.FindClosestPointOfLine(MovedEntity.Vertice[0], MovedEntity.Vertice[MovedEntity.Vertice.Count - 1], MovedTangentPoint, ref ClosestPoint);
        if (ClosestPoint == ClosestPointType.Start)
        {
          num2 = this.PointAngle(MovedEntity.Vertice[MovedEntity.Vertice.Count - 1], MovedEntity.Vertice[0], Plane);
          EndPnt2 = new Pnt3D(MovedEntity.Vertice[0]);
        }
        else
        {
          num2 = this.PointAngle(MovedEntity.Vertice[0], MovedEntity.Vertice[MovedEntity.Vertice.Count - 1], Plane);
          EndPnt2 = new Pnt3D(MovedEntity.Vertice[MovedEntity.Vertice.Count - 1]);
        }
        flag = true;
      }
      if (MovedEntity.GetType() == typeof (eArc))
      {
        this.FindClosestPointOfLine(MovedEntity.Vertice[0], MovedEntity.Vertice[MovedEntity.Vertice.Count - 1], MovedTangentPoint, ref ClosestPoint);
        if (ClosestPoint == ClosestPointType.Start)
        {
          num2 = ((eArc) MovedEntity).StartAngle + 90.0;
          EndPnt2 = new Pnt3D(MovedEntity.Vertice[0]);
        }
        else
        {
          num2 = ((eArc) MovedEntity).EndAngle - 90.0;
          EndPnt2 = new Pnt3D(MovedEntity.Vertice[MovedEntity.Vertice.Count - 1]);
        }
        flag = true;
      }
      if (MovedEntity.GetType() == typeof (eCircle))
      {
        double Angle4 = this.PointAngle(MovedTangentPoint, ((ePlaneEntities) MovedEntity).CenterPoint, Plane);
        Pnt3D BasePnt = new Pnt3D();
        this.LineWithLengthAndAngle(((ePlaneEntities) MovedEntity).CenterPoint, ((eCircle) MovedEntity).Radius, Angle4, Plane, ref BasePnt, ref EndPnt2);
        num2 = Angle4 + 90.0;
        flag = true;
      }
      if (!flag)
        return;
      eEntities eEntities = new eEntities();
      eEntities baseEnt = eEntities.CopyEntity(MovedEntity);
      this.Rotate(EndPnt2, Angle1 - num2, ClockDirectionType.CW, Plane, ref baseEnt);
      this.Move(EndPnt2, EndPnt1, ref baseEnt);
      MovedEntity = eEntities.CopyEntity(baseEnt);
    }
    catch (Exception ex)
    {
      string str = $"RefEntity: {RefEntity.ToString()} - RefTangentPoint: {RefTangentPoint.ToString()} - MovedEntity: {MovedEntity.ToString()} - MovedTangentPoint: {MovedTangentPoint.ToString()} - Offset: {Offset.ToString()} - ReverseAngle: {ReverseAngle.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void Paralel(
    eEntities RefEntity,
    Pnt3D RefTangentPoint,
    ref eEntities MovedEntity,
    Pnt3D MovedTangentPoint,
    double Distance,
    WorkPlane Plane)
  {
    try
    {
      Pnt3D EndPnt = new Pnt3D();
      double Angle = 0.0;
      ClosestPointType ClosestPoint = ClosestPointType.Start;
      double num1 = -90.0;
      if (Distance < 0.0)
        num1 = 90.0;
      if (RefEntity.GetType() == typeof (eLine))
      {
        this.FindClosestPointOfLine(RefEntity.Vertice[0], RefEntity.Vertice[RefEntity.Vertice.Count - 1], RefTangentPoint, ref ClosestPoint);
        if (ClosestPoint == ClosestPointType.Start)
        {
          Angle = this.PointAngle(RefEntity.Vertice[RefEntity.Vertice.Count - 1], RefEntity.Vertice[0], Plane);
          EndPnt = new Pnt3D(RefEntity.Vertice[0]);
          if (!buCompare.EQ(Distance, 0.0))
          {
            Pnt3D BasePnt = new Pnt3D();
            this.LineWithLengthAndAngle(EndPnt, Math.Abs(Distance), Angle + num1, Plane, ref BasePnt, ref EndPnt);
          }
        }
        else
        {
          Angle = this.PointAngle(RefEntity.Vertice[0], RefEntity.Vertice[RefEntity.Vertice.Count - 1], Plane);
          EndPnt = new Pnt3D(RefEntity.Vertice[RefEntity.Vertice.Count - 1]);
          if (!buCompare.EQ(Distance, 0.0))
          {
            Pnt3D BasePnt = new Pnt3D();
            this.LineWithLengthAndAngle(EndPnt, Math.Abs(Distance), Angle + num1, Plane, ref BasePnt, ref EndPnt);
          }
        }
      }
      if (RefEntity.GetType() == typeof (eArc))
      {
        this.FindClosestPointOfLine(RefEntity.Vertice[0], RefEntity.Vertice[RefEntity.Vertice.Count - 1], RefTangentPoint, ref ClosestPoint);
        if (ClosestPoint == ClosestPointType.Start)
        {
          Angle = ((eArc) RefEntity).StartAngle + 90.0;
          EndPnt = new Pnt3D(RefEntity.Vertice[0]);
          if (!buCompare.EQ(Distance, 0.0))
          {
            Pnt3D BasePnt = new Pnt3D();
            this.LineWithLengthAndAngle(EndPnt, Distance, Angle + num1, Plane, ref BasePnt, ref EndPnt);
          }
        }
        else
        {
          Angle = ((eArc) RefEntity).EndAngle + 90.0;
          EndPnt = new Pnt3D(RefEntity.Vertice[RefEntity.Vertice.Count - 1]);
          if (!buCompare.EQ(Distance, 0.0))
          {
            Pnt3D BasePnt = new Pnt3D();
            this.LineWithLengthAndAngle(EndPnt, Distance, Angle + num1, Plane, ref BasePnt, ref EndPnt);
          }
        }
      }
      if (RefEntity.GetType() == typeof (eCircle))
      {
        Angle = this.PointAngle(RefTangentPoint, ((ePlaneEntities) RefEntity).CenterPoint, Plane) + 90.0;
        Pnt3D BasePnt1 = new Pnt3D();
        this.LineWithLengthAndAngle(((ePlaneEntities) RefEntity).CenterPoint, ((eCircle) RefEntity).Radius, Angle, Plane, ref BasePnt1, ref EndPnt);
        if (!buCompare.EQ(Distance, 0.0))
        {
          Pnt3D BasePnt2 = new Pnt3D();
          this.LineWithLengthAndAngle(EndPnt, Distance, Angle + num1, Plane, ref BasePnt2, ref EndPnt);
        }
      }
      if (RefEntity.GetType() == typeof (eEllipse) | RefEntity.GetType() == typeof (eEllipseArc) | RefEntity.GetType() == typeof (eBSpline) | RefEntity.GetType() == typeof (eBezeir))
      {
        Pnt3D pnt3D = new Pnt3D();
        double Distance1 = 0.0;
        int VerticeIndex = 0;
        ePolyline RefEntity1 = new ePolyline(RefEntity.Vertice);
        if (this.IsPointOverEntity((eEntities) RefEntity1, RefTangentPoint, Plane, buSystem.resolutionCompare, ref pnt3D, ref Distance1, ref VerticeIndex) && VerticeIndex >= 0 & VerticeIndex < RefEntity1.Vertice.Count - 1)
        {
          Angle = this.PointAngle(RefEntity1.Vertice[VerticeIndex + 1], RefEntity1.Vertice[VerticeIndex], Plane);
          EndPnt = new Pnt3D(RefEntity1.Vertice[VerticeIndex]);
          if (!buCompare.EQ(Distance, 0.0))
          {
            pnt3D = new Pnt3D();
            this.LineWithLengthAndAngle(EndPnt, Distance, Angle + num1, Plane, ref pnt3D, ref EndPnt);
          }
        }
      }
      if (Angle < 0.0)
        Angle += 360.0;
      double num2 = 0.0;
      Pnt3D pnt3D1 = new Pnt3D();
      bool flag = false;
      if (MovedEntity.GetType() == typeof (eLine))
      {
        this.FindClosestPointOfLine(MovedEntity.Vertice[0], MovedEntity.Vertice[MovedEntity.Vertice.Count - 1], MovedTangentPoint, ref ClosestPoint);
        if (ClosestPoint == ClosestPointType.Start)
        {
          num2 = this.PointAngle(MovedEntity.Vertice[MovedEntity.Vertice.Count - 1], MovedEntity.Vertice[0], Plane);
          pnt3D1 = new Pnt3D(MovedEntity.Vertice[0]);
        }
        else
        {
          num2 = this.PointAngle(MovedEntity.Vertice[0], MovedEntity.Vertice[MovedEntity.Vertice.Count - 1], Plane);
          pnt3D1 = new Pnt3D(MovedEntity.Vertice[MovedEntity.Vertice.Count - 1]);
        }
        flag = true;
      }
      if (!flag)
        return;
      eEntities eEntities = new eEntities();
      eEntities baseEnt = eEntities.CopyEntity(MovedEntity);
      this.Rotate(pnt3D1, Angle - num2, ClockDirectionType.CW, Plane, ref baseEnt);
      if (!buCompare.EQ(Distance, 0.0))
        this.Move(pnt3D1, EndPnt, ref baseEnt);
      MovedEntity = eEntities.CopyEntity(baseEnt);
    }
    catch (Exception ex)
    {
      string str = $"RefEntity: {RefEntity.ToString()} - RefTangentPoint: {RefTangentPoint.ToString()} - MovedEntity: {MovedEntity.ToString()} - MovedTangentPoint: {MovedTangentPoint.ToString()} - Distance: {Distance.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void Scale(
    Pnt3D Center,
    double RatioX,
    double RatioY,
    double RatioZ,
    bool ScaleX,
    bool ScaleY,
    bool ScaleZ,
    ref Pnt3D CalcPnt)
  {
    try
    {
      Pnt3D pnt3D1 = new Pnt3D();
      Pnt3D pnt3D2 = new Pnt3D(CalcPnt) - Center;
      if (RatioX > 0.0 & ScaleX)
        pnt3D2.X *= RatioX;
      if (RatioY > 0.0 & ScaleY)
        pnt3D2.Y *= RatioY;
      if (RatioZ > 0.0 & ScaleZ)
        pnt3D2.Z *= RatioZ;
      Pnt3D Pnt = pnt3D2 + Center;
      CalcPnt = new Pnt3D(Pnt);
    }
    catch (Exception ex)
    {
      string str = $"Center: {Center.ToString()} - RatioX: {RatioX.ToString()} - RatioY: {RatioY.ToString()} - RatioZ: {RatioZ.ToString()} - ScaleX: {ScaleX.ToString()} - ScaleY: {ScaleY.ToString()} - ScaleZ: {ScaleZ.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

