    Pnt3D Center,
    double RatioX,
    double RatioY,
    double RatioZ,
    bool ScaleX,
    bool ScaleY,
    bool ScaleZ,
    WorkPlane Plane,
    eEntities RefEntities,
    ref eEntities CalcEntities)
  {
    try
    {
      Pnt3D CalcPoint1 = new Pnt3D();
      Pnt3D CalcPoint2 = new Pnt3D();
      Pnt3D CalcPoint3 = new Pnt3D();
      double num = 0.0;
      double MinorRadius = 0.0;
      List<Pnt3D> CalcPoint4 = new List<Pnt3D>();
      List<Pnt3D> CalcPoint5 = new List<Pnt3D>();
      List<eEntities> eEntitiesList = new List<eEntities>();
      eEntities eEntities = new eEntities();
      if (RatioX <= 0.0)
        RatioX = 1.0;
      if (RatioY <= 0.0)
        RatioY = 1.0;
      if (RatioZ <= 0.0)
        RatioZ = 1.0;
      if (WorkPlane.isPlaneXY(Plane) && !buCompare.EQ(RatioX, RatioY))
      {
        if (RefEntities.GetType() == typeof (eCircle) | RefEntities.GetType() == typeof (eArc) | RefEntities.GetType() == typeof (eEllipseArc))
        {
          if (RefEntities.camDirections == camPathDirectionType.Normal)
            RefEntities = (eEntities) new ePolyline(RefEntities.Vertice, RefEntities.dispThickness, RefEntities.dispColor);
          if (RefEntities.camDirections == camPathDirectionType.Reverse)
          {
            List<Pnt3D> TargetList = new List<Pnt3D>();
            buGeneral.CopyLists(RefEntities.Vertice, ref TargetList);
            TargetList.Reverse();
            RefEntities = (eEntities) new ePolyline(TargetList, RefEntities.dispThickness, RefEntities.dispColor);
          }
        }
        if (RefEntities.GetType() == typeof (eEllipse) && ((eEllipse) RefEntities).Angle != 0.0)
        {
          if (RefEntities.camDirections == camPathDirectionType.Normal)
            RefEntities = (eEntities) new ePolyline(RefEntities.Vertice, RefEntities.dispThickness, RefEntities.dispColor);
          if (RefEntities.camDirections == camPathDirectionType.Reverse)
          {
            List<Pnt3D> TargetList = new List<Pnt3D>();
            buGeneral.CopyLists(RefEntities.Vertice, ref TargetList);
            TargetList.Reverse();
            RefEntities = (eEntities) new ePolyline(TargetList, RefEntities.dispThickness, RefEntities.dispColor);
          }
        }
      }
      if (WorkPlane.isPlaneXZ(Plane) && !buCompare.EQ(RatioX, RatioZ) && RefEntities.GetType() == typeof (eCircle) | RefEntities.GetType() == typeof (eArc) | RefEntities.GetType() == typeof (eEllipse) | RefEntities.GetType() == typeof (eEllipseArc))
        RefEntities = (eEntities) new ePolyline(RefEntities.Vertice, RefEntities.dispThickness, RefEntities.dispColor);
      if (WorkPlane.isPlaneYZ(Plane) && !buCompare.EQ(RatioY, RatioZ) && RefEntities.GetType() == typeof (eCircle) | RefEntities.GetType() == typeof (eArc) | RefEntities.GetType() == typeof (eEllipse) | RefEntities.GetType() == typeof (eEllipseArc))
        RefEntities = (eEntities) new ePolyline(RefEntities.Vertice, RefEntities.dispThickness, RefEntities.dispColor);
      if (RefEntities.GetType() == typeof (eUpperLine))
      {
        this.Scale(Center, RatioX, RatioY, RatioZ, ScaleX, ScaleY, ScaleZ, ((eLine) RefEntities).StartPoint, ref CalcPoint1);
        this.Scale(Center, RatioX, RatioY, RatioZ, ScaleX, ScaleY, ScaleZ, ((eLine) RefEntities).EndPoint, ref CalcPoint2);
        CalcEntities = (eEntities) new eUpperLine(CalcPoint1, CalcPoint2, RefEntities.dispThickness, RefEntities.dispColor);
      }
      if (RefEntities.GetType() == typeof (ePoint))
      {
        this.Scale(Center, RatioX, RatioY, RatioZ, ScaleX, ScaleY, ScaleZ, RefEntities.Vertice[0], ref CalcPoint1);
        CalcEntities = (eEntities) new ePoint(CalcPoint1, RefEntities.dispThickness, RefEntities.dispColor);
      }
      if (RefEntities.GetType() == typeof (eLine))
      {
        this.Scale(Center, RatioX, RatioY, RatioZ, ScaleX, ScaleY, ScaleZ, RefEntities.Vertice[0], ref CalcPoint1);
        this.Scale(Center, RatioX, RatioY, RatioZ, ScaleX, ScaleY, ScaleZ, RefEntities.Vertice[1], ref CalcPoint2);
        CalcEntities = (eEntities) new eLine(CalcPoint1, CalcPoint2, RefEntities.dispThickness, RefEntities.dispColor);
      }
      if (RefEntities.GetType() == typeof (eCircle))
      {
        this.Scale(Center, RatioX, RatioY, RatioZ, ScaleX, ScaleY, ScaleZ, ((ePlaneEntities) RefEntities).CenterPoint, ref CalcPoint1);
        if (ScaleZ & (WorkPlane.isPlaneYZ(Plane) | WorkPlane.isPlaneXZ(Plane)))
          num = ((eCircle) RefEntities).Radius * RatioZ;
        if (ScaleY & (WorkPlane.isPlaneYZ(Plane) | WorkPlane.isPlaneXY(Plane)))
          num = ((eCircle) RefEntities).Radius * RatioY;
        if (ScaleX & (WorkPlane.isPlaneXY(Plane) | WorkPlane.isPlaneXZ(Plane)))
          num = ((eCircle) RefEntities).Radius * RatioX;
        CalcEntities = (eEntities) new eCircle(CalcPoint1, num, ((ePlaneEntities) RefEntities).Plane, RefEntities.dispThickness, RefEntities.dispColor);
      }
      if (RefEntities.GetType() == typeof (eArc))
      {
        this.Scale(Center, RatioX, RatioY, RatioZ, ScaleX, ScaleY, ScaleZ, ((ePlaneEntities) RefEntities).CenterPoint, ref CalcPoint1);
        if (ScaleZ & (WorkPlane.isPlaneYZ(Plane) | WorkPlane.isPlaneXZ(Plane)))
          num = ((eCircle) RefEntities).Radius * RatioZ;
        if (ScaleY & (WorkPlane.isPlaneYZ(Plane) | WorkPlane.isPlaneXY(Plane)))
          num = ((eCircle) RefEntities).Radius * RatioY;
        if (ScaleX & (WorkPlane.isPlaneXY(Plane) | WorkPlane.isPlaneXZ(Plane)))
          num = ((eCircle) RefEntities).Radius * RatioX;
        CalcEntities = (eEntities) new eArc(CalcPoint1, num, ((eArc) RefEntities).StartAngle, ((eArc) RefEntities).EndAngle, ((ePlaneEntities) RefEntities).Plane, RefEntities.dispThickness, RefEntities.dispColor);
      }
      if (RefEntities.GetType() == typeof (eEllipse))
      {
        this.Scale(Center, RatioX, RatioY, RatioZ, ScaleX, ScaleY, ScaleZ, ((ePlaneEntities) RefEntities).CenterPoint, ref CalcPoint1);
        if (ScaleY & (WorkPlane.isPlaneYZ(Plane) | WorkPlane.isPlaneXY(Plane)))
          num = ((eEllipse) RefEntities).MajorRadius * RatioY;
        if (ScaleX & (WorkPlane.isPlaneXY(Plane) | WorkPlane.isPlaneXZ(Plane)))
          num = ((eEllipse) RefEntities).MajorRadius * RatioX;
        if (ScaleZ & (WorkPlane.isPlaneYZ(Plane) | WorkPlane.isPlaneXZ(Plane)))
          MinorRadius = ((eEllipse) RefEntities).MinorRadius * RatioZ;
        if (ScaleY & (WorkPlane.isPlaneYZ(Plane) | WorkPlane.isPlaneXY(Plane)))
          MinorRadius = ((eEllipse) RefEntities).MinorRadius * RatioY;
        CalcEntities = (eEntities) new eEllipse(CalcPoint1, num, MinorRadius, ((eEllipse) RefEntities).Angle, ((ePlaneEntities) RefEntities).Plane, RefEntities.dispThickness, RefEntities.dispColor);
      }
      if (RefEntities.GetType() == typeof (eEllipseArc))
      {
        this.Scale(Center, RatioX, RatioY, RatioZ, ScaleX, ScaleY, ScaleZ, ((ePlaneEntities) RefEntities).CenterPoint, ref CalcPoint1);
        if (ScaleY & (WorkPlane.isPlaneYZ(Plane) | WorkPlane.isPlaneXY(Plane)))
          num = ((eEllipse) RefEntities).MajorRadius * RatioY;
        if (ScaleX & (WorkPlane.isPlaneXY(Plane) | WorkPlane.isPlaneXZ(Plane)))
          num = ((eEllipse) RefEntities).MajorRadius * RatioX;
        if (ScaleZ & (WorkPlane.isPlaneYZ(Plane) | WorkPlane.isPlaneXZ(Plane)))
          MinorRadius = ((eEllipse) RefEntities).MinorRadius * RatioZ;
        if (ScaleY & (WorkPlane.isPlaneYZ(Plane) | WorkPlane.isPlaneXY(Plane)))
          MinorRadius = ((eEllipse) RefEntities).MinorRadius * RatioY;
        CalcEntities = (eEntities) new eEllipseArc(CalcPoint1, num, MinorRadius, ((eEllipseArc) RefEntities).StartAngle, ((eEllipseArc) RefEntities).EndAngle, ((eEllipse) RefEntities).Angle, ((ePlaneEntities) RefEntities).Plane, RefEntities.dispThickness, RefEntities.dispColor);
      }
      if (RefEntities.GetType() == typeof (ePicture))
      {
        this.Scale(Center, RatioX, RatioY, RatioZ, ScaleX, ScaleY, ScaleZ, ((ePicture) RefEntities).StartPoint, ref CalcPoint1);
        this.Scale(Center, RatioX, RatioY, RatioZ, ScaleX, ScaleY, ScaleZ, ((ePicture) RefEntities).EndPoint, ref CalcPoint2);
        CalcEntities = (eEntities) new ePicture(CalcPoint1, CalcPoint2, ((ePicture) RefEntities).PicturePath, ((ePlaneEntities) RefEntities).Plane);
      }
      if (RefEntities.GetType() == typeof (eText))
      {
        this.Scale(Center, RatioX, RatioY, RatioZ, ScaleX, ScaleY, ScaleZ, ((eText) RefEntities).StartPoint, ref CalcPoint1);
        CalcEntities = (eEntities) new eText(CalcPoint1, ((eText) RefEntities).TextString, num, RefEntities.dispColor, ((ePlaneEntities) RefEntities).Plane);
      }
      if (RefEntities.GetType() == typeof (eDimLineer))
      {
        Pnt3D CalcPoint6 = new Pnt3D();
        Pnt3D CalcPoint7 = new Pnt3D();
        this.Scale(Center, RatioX, RatioY, RatioZ, ScaleX, ScaleY, ScaleZ, ((eDimLineer) RefEntities).StartPoint, ref CalcPoint1);
        this.Scale(Center, RatioX, RatioY, RatioZ, ScaleX, ScaleY, ScaleZ, ((eDimLineer) RefEntities).EndPoint, ref CalcPoint2);
        this.Scale(Center, RatioX, RatioY, RatioZ, ScaleX, ScaleY, ScaleZ, ((eDimLineer) RefEntities).SetPoint, ref CalcPoint3);
        this.Scale(Center, RatioX, RatioY, RatioZ, ScaleX, ScaleY, ScaleZ, ((eDimension) RefEntities).DimData.BasePoint, ref CalcPoint6);
        this.Scale(Center, RatioX, RatioY, RatioZ, ScaleX, ScaleY, ScaleZ, ((eDimension) RefEntities).DimData.CatchPoint, ref CalcPoint7);
        ((eDimension) RefEntities).DimData.Distance = this.Length3D(CalcPoint6, CalcPoint7);
        CalcEntities = (eEntities) new eDimLineer(CalcPoint1, CalcPoint2, CalcPoint3, ((eDimLineer) RefEntities).Aligned, RefEntities.dispThickness, RefEntities.dispColor);
        ((eDimension) CalcEntities).DimData = new DimensionData(((eDimension) RefEntities).DimData);
      }
      if (RefEntities.GetType() == typeof (eSurface))
      {
        List<Triangle3D> triangles = new List<Triangle3D>();
        for (int index = 0; index <= RefEntities.Triangles.Count - 1; ++index)
        {
          Pnt3D CalcPoint8 = new Pnt3D();
          CalcPoint2 = new Pnt3D();
          Pnt3D CalcPoint9 = new Pnt3D();
          this.Scale(Center, RatioX, RatioY, RatioZ, ScaleX, ScaleY, ScaleZ, RefEntities.Triangles[index].FirstPoint, ref CalcPoint8);
          this.Scale(Center, RatioX, RatioY, RatioZ, ScaleX, ScaleY, ScaleZ, RefEntities.Triangles[index].SecondPoint, ref CalcPoint2);
          this.Scale(Center, RatioX, RatioY, RatioZ, ScaleX, ScaleY, ScaleZ, RefEntities.Triangles[index].ThirdPoint, ref CalcPoint9);
          triangles.Add(new Triangle3D()
          {
            FirstPoint = CalcPoint8,
            SecondPoint = CalcPoint2,
            ThirdPoint = CalcPoint9
          });
        }
        CalcEntities = (eEntities) new eSurface(triangles, RefEntities.dispColor);
      }
      if (RefEntities.GetType() == typeof (ePolyline) | RefEntities.GetType() == typeof (eBSpline) | RefEntities.GetType() == typeof (eBezeir))
      {
        CalcPoint4.Clear();
        this.Scale(Center, RatioX, RatioY, RatioZ, ScaleX, ScaleY, ScaleZ, RefEntities.Vertice, ref CalcPoint4);
        CalcPoint5.Clear();
        if (RefEntities.GetType() == typeof (ePolyline))
          CalcEntities = (eEntities) new ePolyline(CalcPoint4, RefEntities.dispThickness, RefEntities.dispColor);
        if (RefEntities.GetType() == typeof (eBSpline))
        {
          this.Scale(Center, RatioX, RatioY, RatioZ, ScaleX, ScaleY, ScaleZ, ((eCurveEntities) RefEntities).ControlPoints, ref CalcPoint5);
          CalcEntities = (eEntities) new eBSpline(CalcPoint5, RefEntities.dispThickness, RefEntities.dispColor, RefEntities.bClosed, ((eBSpline) RefEntities).BType);
        }
        if (RefEntities.GetType() == typeof (eBezeir))
        {
          this.Scale(Center, RatioX, RatioY, RatioZ, ScaleX, ScaleY, ScaleZ, ((eCurveEntities) RefEntities).ControlPoints, ref CalcPoint5);
          CalcEntities = (eEntities) new eBezeir(CalcPoint5, RefEntities.dispThickness, RefEntities.dispColor);
        }
      }
      eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
    }
    catch (Exception ex)
    {
      string str = $"Center: {Center.ToString()} - RatioX: {RatioX.ToString()} - RatioY: {RatioY.ToString()} - RatioZ: {RatioZ.ToString()} - ScaleX: {ScaleX.ToString()} - ScaleY: {ScaleY.ToString()} - ScaleZ: {ScaleZ.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

