  public void Scale(
    Pnt3D Center,
    double RatioX,
    double RatioY,
    double RatioZ,
    bool ScaleX,
    bool ScaleY,
    bool ScaleZ,
    ref List<ContourPoints> Points)
  {
    try
    {
      List<ContourPoints> contourPointsList = new List<ContourPoints>();
      for (int index = 0; index <= Points.Count - 1; ++index)
      {
        ContourPoints contourPoints = new ContourPoints();
        this.Scale(Center, RatioX, RatioY, RatioZ, ScaleX, ScaleY, ScaleZ, Points[index].Outter, ref contourPoints.Outter);
        this.Scale(Center, RatioX, RatioY, RatioZ, ScaleX, ScaleY, ScaleZ, Points[index].Holes, ref contourPoints.Holes);
        contourPointsList.Add(contourPoints);
      }
      Points.Clear();
      Points = new List<ContourPoints>();
      for (int index = 0; index <= contourPointsList.Count - 1; ++index)
      {
        ContourPoints contourPoints = new ContourPoints();
        Pnt3D.Copy(contourPointsList[index].Outter, ref contourPoints.Outter);
        Pnt3D.Copy(contourPointsList[index].Holes, ref contourPoints.Holes);
        Points.Add(contourPoints);
      }
    }
    catch (Exception ex)
    {
      string str = $"Center: {Center.ToString()} - RatioX: {RatioX.ToString()} - RatioY: {RatioY.ToString()} - RatioZ: {RatioZ.ToString()} - ScaleX: {ScaleX.ToString()} - ScaleY: {ScaleY.ToString()} - ScaleZ: {ScaleZ.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void FitEntityToWidthHeight(
    Vec3D StartSpace,
    Vec3D EndSpace,
    Pnt3D MinPoint,
    Pnt3D MaxPoint,
    double SetWidth,
    double SetHeight,
    WorkPlane Plane,
    ref eEntities RefEntity)
  {
    try
    {
      if (RefEntity == null || RefEntity.Vertice.Count == 0)
        return;
      double num1 = Math.Abs(MaxPoint.X - MinPoint.X);
      double num2 = Math.Abs(MaxPoint.Y - MinPoint.Y);
      double num3 = Math.Abs(SetWidth - StartSpace.X - EndSpace.X);
      double num4 = Math.Abs(SetHeight - StartSpace.Y - EndSpace.Y);
      double RatioX = 1.0;
      double RatioY = 1.0;
      if (num3 > 0.0 & num1 > 0.0)
        RatioX = num3 / num1;
      if (num4 > 0.0 & num2 > 0.0)
        RatioY = num4 / num2;
      this.Move(MinPoint, new Pnt3D(MinPoint.X + StartSpace.X, MinPoint.Y + StartSpace.Y), ref RefEntity);
      this.Scale(new Pnt3D(MinPoint.X + StartSpace.X, MinPoint.Y + StartSpace.Y), RatioX, RatioY, 1.0, true, true, false, Plane, ref RefEntity);
    }
    catch (Exception ex)
    {
      string str = $"StartSpace: {StartSpace.ToString()} - EndSpace: {EndSpace.ToString()} - MinPoint: {MinPoint.ToString()} - MaxPoint: {MaxPoint.ToString()} - SetWidth: {SetWidth.ToString()} - SetHeight: {SetHeight.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void FitEntityToWidthHeight(
    Vec3D StartSpace,
    Vec3D EndSpace,
    Pnt3D MinPoint,
    Pnt3D MaxPoint,
    double SetWidth,
    double SetHeight,
    WorkPlane Plane,
    ref List<eEntities> RefEntities)
  {
    try
    {
      for (int index = 0; index <= RefEntities.Count - 1; ++index)
      {
        eEntities eEntities = new eEntities();
        eEntities.CopyEntity(RefEntities[index], ref eEntities);
        this.FitEntityToWidthHeight(StartSpace, EndSpace, MinPoint, MaxPoint, SetWidth, SetHeight, Plane, ref eEntities);
        RefEntities[index] = eEntities;
      }
    }
    catch (Exception ex)
    {
      string str = $"StartSpace: {StartSpace.ToString()} - EndSpace: {EndSpace.ToString()} - MinPoint: {MinPoint.ToString()} - MaxPoint: {MaxPoint.ToString()} - SetWidth: {SetWidth.ToString()} - SetHeight: {SetHeight.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

