  public void Fillet(
    Pnt3D FirstLineStart,
    Pnt3D FirstLineEnd,
    Pnt3D SecondLineStart,
    Pnt3D SecondLineEnd,
    double Radius,
    WorkPlane Plane,
    ref List<eArc> CalcArc)
  {
    try
    {
      Pnt3D IntersectionPoint = new Pnt3D();
      Pnt3D pnt3D1 = new Pnt3D();
      Pnt3D pnt3D2 = new Pnt3D();
      Pnt3D pnt3D3 = new Pnt3D();
      Pnt3D pnt3D4 = new Pnt3D();
      List<Pnt3D> CheckList = new List<Pnt3D>();
      List<Pnt3D> ArcCenter = new List<Pnt3D>();
      List<double> doubleList1 = new List<double>();
      List<double> doubleList2 = new List<double>();
      List<double> ArcSA = new List<double>();
      List<double> ArcEA = new List<double>();
      List<Pnt3D> pnt3DList1 = new List<Pnt3D>();
      List<Pnt3D> pnt3DList2 = new List<Pnt3D>();
      double num1 = this.AngleOfTwoLines(FirstLineStart, FirstLineEnd, SecondLineStart, SecondLineEnd, Plane);
      this.LineLineIntersection(FirstLineStart, FirstLineEnd, SecondLineStart, SecondLineEnd, Plane, ref IntersectionPoint);
      for (int index = 0; index <= 1; ++index)
      {
        Pnt3D RefPoint1 = new Pnt3D();
        Pnt3D RefPoint2 = new Pnt3D();
        Pnt3D pnt3D5 = new Pnt3D();
        Pnt3D pnt3D6 = new Pnt3D();
        if (index == 1)
          num1 = 180.0 - num1;
        double num2 = Radius / Math.Tan(buConversion.DegreeToRadian(num1 / 2.0));
        if (buCompare.EQ(FirstLineStart.X, FirstLineEnd.X, 0.01))
        {
          RefPoint1.X = FirstLineStart.X;
          RefPoint2.X = FirstLineEnd.X;
          RefPoint1.Y = IntersectionPoint.Y + num2;
          RefPoint2.Y = IntersectionPoint.Y - num2;
        }
        else
        {
          double x = this.Slope(FirstLineStart, FirstLineEnd, Plane);
          RefPoint1.X = (Math.Pow(x, 2.0) * IntersectionPoint.X + IntersectionPoint.X + Math.Sqrt(1.0 + Math.Pow(x, 2.0)) * num2) / (1.0 + Math.Pow(x, 2.0));
          RefPoint2.X = (Math.Pow(x, 2.0) * IntersectionPoint.X + IntersectionPoint.X - Math.Sqrt(1.0 + Math.Pow(x, 2.0)) * num2) / (1.0 + Math.Pow(x, 2.0));
          RefPoint1.Y = (x * Math.Sqrt(1.0 + Math.Pow(x, 2.0)) * num2 + IntersectionPoint.Y + IntersectionPoint.Y * Math.Pow(x, 2.0)) / (1.0 + Math.Pow(x, 2.0));
          RefPoint2.Y = (-x * Math.Sqrt(1.0 + Math.Pow(x, 2.0)) * num2 + IntersectionPoint.Y + IntersectionPoint.Y * Math.Pow(x, 2.0)) / (1.0 + Math.Pow(x, 2.0));
        }
        if (this.IsPointInsideLine(FirstLineStart, FirstLineEnd, RefPoint1, Plane))
          pnt3DList1.Add(RefPoint1);
        if (this.IsPointInsideLine(FirstLineStart, FirstLineEnd, RefPoint2, Plane))
          pnt3DList1.Add(RefPoint2);
        if (buCompare.EQ(SecondLineStart.X, SecondLineEnd.X, 0.001))
        {
          pnt3D5.X = SecondLineStart.X;
          pnt3D6.X = SecondLineEnd.X;
          pnt3D5.Y = IntersectionPoint.Y + num2;
          pnt3D6.Y = IntersectionPoint.Y - num2;
        }
        else
        {
          double x = this.Slope(SecondLineStart, SecondLineEnd, Plane);
          pnt3D5.X = (Math.Pow(x, 2.0) * IntersectionPoint.X + IntersectionPoint.X + Math.Sqrt(1.0 + Math.Pow(x, 2.0)) * num2) / (1.0 + Math.Pow(x, 2.0));
          pnt3D6.X = (Math.Pow(x, 2.0) * IntersectionPoint.X + IntersectionPoint.X - Math.Sqrt(1.0 + Math.Pow(x, 2.0)) * num2) / (1.0 + Math.Pow(x, 2.0));
          pnt3D5.Y = (x * Math.Sqrt(1.0 + Math.Pow(x, 2.0)) * num2 + IntersectionPoint.Y + IntersectionPoint.Y * Math.Pow(x, 2.0)) / (1.0 + Math.Pow(x, 2.0));
          pnt3D6.Y = (-x * Math.Sqrt(1.0 + Math.Pow(x, 2.0)) * num2 + IntersectionPoint.Y + IntersectionPoint.Y * Math.Pow(x, 2.0)) / (1.0 + Math.Pow(x, 2.0));
        }
        if (this.IsPointInsideLine(SecondLineStart, SecondLineEnd, pnt3D5, Plane))
          pnt3DList2.Add(new Pnt3D(pnt3D5));
        if (this.IsPointInsideLine(SecondLineStart, SecondLineEnd, pnt3D6, Plane))
          pnt3DList2.Add(new Pnt3D(pnt3D6));
      }
      if (pnt3DList1.Count > 0 & pnt3DList2.Count > 0)
      {
        double num3 = this.Slope(FirstLineStart, FirstLineEnd, Plane);
        double num4 = this.Slope(SecondLineStart, SecondLineEnd, Plane);
        for (int index1 = 0; index1 <= pnt3DList1.Count - 1; ++index1)
        {
          for (int index2 = 0; index2 <= pnt3DList2.Count - 1; ++index2)
          {
            this.ArcWithTwoPointAndRadius(pnt3DList1[index1], pnt3DList2[index2], Radius, false, Plane, ref ArcCenter, ref ArcSA, ref ArcEA);
            for (int index3 = 0; index3 <= ArcCenter.Count - 1; ++index3)
            {
              double num5 = this.Slope(pnt3DList1[index1], ArcCenter[index3], Plane);
              double num6 = this.Slope(pnt3DList2[index2], ArcCenter[index3], Plane);
              double num7 = num5 * num3;
              double num8 = num6 * num4;
              if (buCompare.EQ(num7, -1.0, 0.001) & buCompare.EQ(num8, -1.0, 0.001))
              {
                if (!buNumeric.IsValueInsideList(CheckList, ArcCenter[index3]))
                {
                  CheckList.Add(new Pnt3D(ArcCenter[index3]));
                  doubleList1.Add(ArcSA[index3]);
                  doubleList2.Add(ArcEA[index3]);
                }
              }
              else
              {
