        double CalcEA = 0.0;
        this.ArcByLength(ent4.CenterPoint, ent4.Radius, ent4.StartAngle, ent4.EndAngle, ent4.geoLength - ChamferLength, ArcDirectionType.FromStart, ref CalcSA, ref CalcEA);
