        }
        if (RefEntities.GetType() == typeof (eArc))
        {
          eArc baseEnt = new eArc(RefEntities);
          double num = this.PointAngle(CalculatedPoint, baseEnt.CenterPoint, Plane);
          eEntities copiedEnt3 = (eEntities) new eArc(baseEnt.CenterPoint, baseEnt.Radius, baseEnt.StartAngle, num, baseEnt.Plane, baseEnt.dispThickness, baseEnt.dispColor);
          if (((eArc) copiedEnt3).StartAngle > ((eArc) copiedEnt3).EndAngle)
            ((eArc) copiedEnt3).EndAngle += 360.0;
          if (((eArc) copiedEnt3).EndAngle - ((eArc) copiedEnt3).StartAngle > 360.0 && ((eArc) copiedEnt3).EndAngle > ((eArc) copiedEnt3).StartAngle)
            ((eArc) copiedEnt3).EndAngle -= 360.0;
