  public void Connect(ref eEntities FirstEntity, ref eEntities SecondEntity, WorkPlane Plane)
  {
    int PolylineSubSequance1 = 0;
    int PolylineSubSequance2 = 0;
    if (FirstEntity.GetType() == typeof (ePolyline))
    {
      Pnt3D StartPoint1 = new Pnt3D(FirstEntity.Vertice[0]);
      Pnt3D StartPoint2 = new Pnt3D(FirstEntity.Vertice[FirstEntity.Vertice.Count - 1]);
      Pnt3D EndPoint1 = new Pnt3D(SecondEntity.Vertice[0]);
      Pnt3D EndPoint2 = new Pnt3D(SecondEntity.Vertice[SecondEntity.Vertice.Count - 1]);
      double num1 = double.MaxValue;
      double num2 = this.Length3D(StartPoint1, EndPoint1);
      double num3 = this.Length3D(StartPoint1, EndPoint2);
      double num4 = this.Length3D(StartPoint2, EndPoint1);
      double num5 = this.Length3D(StartPoint2, EndPoint2);
      if (num2 < num1)
      {
        PolylineSubSequance1 = 0;
        num1 = num2;
      }
      if (num3 < num1)
      {
        PolylineSubSequance1 = 0;
        num1 = num3;
      }
      if (num4 < num1)
      {
        PolylineSubSequance1 = FirstEntity.Vertice.Count - 1;
        num1 = num4;
      }
      if (num5 < num1)
        PolylineSubSequance1 = FirstEntity.Vertice.Count - 1;
    }
    if (SecondEntity.GetType() == typeof (ePolyline))
    {
      Pnt3D StartPoint3 = new Pnt3D(FirstEntity.Vertice[0]);
      Pnt3D StartPoint4 = new Pnt3D(FirstEntity.Vertice[FirstEntity.Vertice.Count - 1]);
      Pnt3D EndPoint3 = new Pnt3D(SecondEntity.Vertice[0]);
      Pnt3D EndPoint4 = new Pnt3D(SecondEntity.Vertice[SecondEntity.Vertice.Count - 1]);
      double num6 = double.MaxValue;
      double num7 = this.Length3D(StartPoint3, EndPoint3);
      double num8 = this.Length3D(StartPoint3, EndPoint4);
      double num9 = this.Length3D(StartPoint4, EndPoint3);
      double num10 = this.Length3D(StartPoint4, EndPoint4);
      if (num7 < num6)
      {
        PolylineSubSequance2 = 0;
        num6 = num7;
      }
      if (num8 < num6)
      {
        PolylineSubSequance2 = SecondEntity.Vertice.Count - 1;
        num6 = num8;
      }
      if (num9 < num6)
      {
        PolylineSubSequance2 = 0;
        num6 = num9;
      }
      if (num10 < num6)
        PolylineSubSequance2 = SecondEntity.Vertice.Count - 1;
    }
    this.Connect(ref FirstEntity, ref SecondEntity, Plane, PolylineSubSequance1, PolylineSubSequance2);
  }

  public void Connect(
    ref eEntities FirstEntity,
    ref eEntities SecondEntity,
    WorkPlane Plane,
    int PolylineSubSequance1,
    int PolylineSubSequance2)
  {
    eEntities copiedEnt1 = new eEntities();
    eEntities copiedEnt2 = new eEntities();
    List<eEntities> RefEntities = new List<eEntities>();
    eEntities.CopyEntity(FirstEntity, ref copiedEnt1);
    eEntities.CopyEntity(SecondEntity, ref copiedEnt2);
    RefEntities.Add(copiedEnt1);
    RefEntities.Add(copiedEnt2);
    this.Connect(PolylineSubSequance1, PolylineSubSequance2, Plane, ref RefEntities);
    if (RefEntities.Count < 2)
      return;
    eEntities copiedEnt3 = new eEntities();
    eEntities copiedEnt4 = new eEntities();
    eEntities.CopyEntity(RefEntities[0], ref copiedEnt3);
    eEntities.CopyEntity(RefEntities[1], ref copiedEnt4);
    eEntities.CopyEntity(copiedEnt3, ref FirstEntity);
    eEntities.CopyEntity(copiedEnt4, ref SecondEntity);
  }

