  public void Stretch(StretchEventArg e, ref List<eEntities> CalcEntitites)
  {
    List<eEntities> baseEnt = new List<eEntities>();
    for (int index = 0; index <= CalcEntitites.Count - 1; ++index)
    {
      eEntities eEntities = new eEntities();
      eEntities.CopyEntity(CalcEntitites[index], ref eEntities);
      this.Stretch(e, ref eEntities);
      baseEnt.Add(eEntities);
    }
    CalcEntitites.Clear();
    eEntities.CopyEntities(baseEnt, ref CalcEntitites);
    baseEnt.Clear();
  }

