  public void Stretch(
    Pnt3D BasePoint,
    VectorType StretchDirection,
    double StretchValue,
    PlusMinus Sign,
    ref List<Pnt3D> Points)
  {
    try
    {
      Pnt3D pnt3D1 = new Pnt3D();
      if (StretchDirection == VectorType.XVector)
      {
        for (int index = 0; index <= Points.Count - 1; ++index)
        {
          pnt3D1 = new Pnt3D();
          Pnt3D pnt3D2 = Points[index];
          if (Sign == PlusMinus.Plus && pnt3D2.X > BasePoint.X)
            pnt3D2.X += StretchValue;
          if (Sign == PlusMinus.Minus && pnt3D2.X < BasePoint.X)
            pnt3D2.X -= StretchValue;
          Points[index] = pnt3D2;
        }
      }
      if (StretchDirection != VectorType.YVector)
        return;
      for (int index = 0; index <= Points.Count - 1; ++index)
      {
        pnt3D1 = new Pnt3D();
        Pnt3D pnt3D3 = Points[index];
        if (Sign == PlusMinus.Plus && pnt3D3.Y > BasePoint.Y)
          pnt3D3.Y += StretchValue;
        if (Sign == PlusMinus.Minus && pnt3D3.Y < BasePoint.Y)
          pnt3D3.Y -= StretchValue;
        Points[index] = pnt3D3;
      }
    }
    catch (Exception ex)
    {
      string str = $"BasePoint: {BasePoint.ToString()} - StretchDirection: {StretchDirection.ToString()} - StretchValue: {StretchValue.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void Stretch(
    Pnt3D BasePoint,
    VectorType StretchDirection,
    double StretchValue,
    PlusMinus Sign,
    ref List<List<Pnt3D>> Points)
  {
    List<List<Pnt3D>> pts = new List<List<Pnt3D>>();
    for (int index = 0; index <= Points.Count - 1; ++index)
    {
      List<Pnt3D> pnt3DList = new List<Pnt3D>();
      Pnt3D.Copy(Points[index], ref pnt3DList);
      this.Stretch(BasePoint, StretchDirection, StretchValue, Sign, ref pnt3DList);
      pts.Add(pnt3DList);
    }
    Points.Clear();
    Points = new List<List<Pnt3D>>();
    Pnt3D.Copy(pts, ref Points);
  }

  public void Extend(
    List<eEntities> RefEntities,
    eEntities ExtendEntity,
    Pnt3D ExtendPoint,
    double Length,
    WorkPlane Plane,
    double Resolution,
    ref eEntities ExtendedEntity,
    ref bool Done)
  {
    try
    {
      double Angle = 0.0;
      Pnt3D pnt3D1 = new Pnt3D();
      Pnt3D pnt3D2 = new Pnt3D();
      Pnt3D pnt3D3 = new Pnt3D();
      Pnt3D pnt3D4 = new Pnt3D();
      Pnt3D CenterPnt = new Pnt3D();
      double num1 = double.MaxValue;
      ExtendedEntity = new eEntities();
      Done = false;
      if (ExtendEntity.GetType() == typeof (eLine))
      {
        if (this.Length3D(ExtendEntity.Vertice[0], ExtendPoint) < this.Length3D(ExtendEntity.Vertice[ExtendEntity.Vertice.Count - 1], ExtendPoint))
        {
          pnt3D4 = new Pnt3D(ExtendEntity.Vertice[ExtendEntity.Vertice.Count - 1]);
          CenterPnt = new Pnt3D(ExtendEntity.Vertice[0]);
          Angle = this.PointAngle(ExtendEntity.Vertice[0], ExtendEntity.Vertice[ExtendEntity.Vertice.Count - 1], Plane);
        }
        else
        {
          pnt3D4 = new Pnt3D(ExtendEntity.Vertice[0]);
          CenterPnt = new Pnt3D(ExtendEntity.Vertice[ExtendEntity.Vertice.Count - 1]);
          Angle = this.PointAngle(ExtendEntity.Vertice[ExtendEntity.Vertice.Count - 1], ExtendEntity.Vertice[0], Plane);
        }
        for (int index1 = 0; index1 <= RefEntities.Count - 1; ++index1)
        {
          if (RefEntities[index1].GetType() == typeof (eLine))
          {
            pnt3D1 = new Pnt3D();
            pnt3D2 = new Pnt3D();
            this.LineLineIntersection(ExtendEntity.Vertice[0], ExtendEntity.Vertice[ExtendEntity.Vertice.Count - 1], RefEntities[index1].Vertice[0], RefEntities[index1].Vertice[RefEntities[index1].Vertice.Count - 1], Plane, ref pnt3D1);
            if (this.IsPointInsideLine(RefEntities[index1].Vertice[0], RefEntities[index1].Vertice[RefEntities[index1].Vertice.Count - 1], pnt3D1, Plane) && !this.IsPointInsideLine(ExtendEntity.Vertice[0], ExtendEntity.Vertice[ExtendEntity.Vertice.Count - 1], pnt3D1, Plane) && buCompare.EQ(this.PointAngle(pnt3D1, ExtendPoint, Plane), Angle, Resolution))
            {
              double num2 = this.Length3D(ExtendPoint, pnt3D1);
              if (num2 < num1)
              {
                num1 = num2;
                Pnt3D pnt3D5 = new Pnt3D(pnt3D1);
                if (Length <= 0.0)
                {
                  ExtendedEntity = (eEntities) new eLine(pnt3D1, pnt3D4);
                }
                else
                {
                  this.LineWithLengthAndAngle(CenterPnt, Length, Angle, Plane, ref pnt3D1, ref pnt3D2);
                  ExtendedEntity = (eEntities) new eLine(pnt3D2, pnt3D4);
