            if (this.IsPointInsideAndOverArc(eArc.CenterPoint, eArc.Radius, eArc.StartAngle, eArc.EndAngle, pnt3D1, Plane, Resolution) && !this.IsPointInsideLine(ExtendEntity.Vertice[0], ExtendEntity.Vertice[ExtendEntity.Vertice.Count - 1], pnt3D1, Plane) && buCompare.EQ(this.PointAngle(pnt3D1, ExtendPoint, Plane), Angle, Resolution))
            {
              double num3 = this.Length3D(ExtendPoint, pnt3D1);
              if (num3 < num1)
              {
                num1 = num3;
                Pnt3D pnt3D6 = new Pnt3D(pnt3D1);
                if (Length <= 0.0)
                {
                  ExtendedEntity = (eEntities) new eLine(pnt3D1, pnt3D4);
                }
                else
                {
                  this.LineWithLengthAndAngle(CenterPnt, Length, Angle, Plane, ref pnt3D1, ref pnt3D2);
                  ExtendedEntity = (eEntities) new eLine(pnt3D2, pnt3D4);
                }
                Done = true;
              }
            }
            if (this.IsPointInsideAndOverArc(eArc.CenterPoint, eArc.Radius, eArc.StartAngle, eArc.EndAngle, pnt3D2, Plane, Resolution) && !this.IsPointInsideLine(ExtendEntity.Vertice[0], ExtendEntity.Vertice[ExtendEntity.Vertice.Count - 1], pnt3D2, Plane) && buCompare.EQ(this.PointAngle(pnt3D2, ExtendPoint, Plane), Angle, Resolution))
            {
              double num4 = this.Length3D(ExtendPoint, pnt3D2);
