      this.LineWithLengthAndAngle(CenterPnt, Length, Angle, Plane, ref pnt3D1, ref pnt3D2);
      ExtendedEntity = (eEntities) new eLine(pnt3D2, pnt3D4);
      Done = true;
    }
    catch (Exception ex)
    {
      string str = $"RefEntities: {RefEntities.ToString()} - BaseEntity: {ExtendEntity.ToString()} - ExtendPoint: {ExtendPoint.ToString()} - Length: {Length.ToString()} - Resolution: {Resolution.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void Explode(
    ExplodeEventVar Options,
    List<eEntities> RefEntities,
    ref List<eEntities> CalcEntities)
  {
    CalcEntities.Clear();
    for (int index = 0; index <= RefEntities.Count - 1; ++index)
      this.Explode(Options, RefEntities[index], ref CalcEntities);
  }

  public void Explode(
    ExplodeEventVar Options,
    eEntities RefEntity,
    ref List<eEntities> CalcEntities)
  {
    try
    {
      eEntities eEntities1 = new eEntities();
      eEntities eEntities2 = eEntities.CopyEntity(RefEntity);
      if (RefEntity.GetType() == typeof (eLine) && Options.PolylineToLine)
      {
        eEntities2.GroupIndex = 0;
        CalcEntities.Add(eEntities2);
      }
      if (RefEntity.GetType() == typeof (ePolyline) && Options.PolylineToLine)
      {
        for (int index = 1; index <= RefEntity.Vertice.Count - 1; ++index)
        {
          eEntities2 = (eEntities) new eLine(RefEntity.Vertice[index - 1], RefEntity.Vertice[index], RefEntity.dispThickness, RefEntity.dispColor);
          eEntities2.LayerIndex = RefEntity.LayerIndex;
          CalcEntities.Add(eEntities2);
        }
      }
      if (RefEntity.GetType() == typeof (eCircle))
      {
        if (Options.CircleToPolyline)
        {
          eEntities2 = (eEntities) new ePolyline(RefEntity.Vertice, RefEntity.dispThickness, RefEntity.dispColor);
          eEntities2.LayerIndex = RefEntity.LayerIndex;
          CalcEntities.Add(eEntities2);
        }
        if (Options.CircleToArc)
        {
          for (int index = 0; index <= 3; ++index)
          {
            eEntities2 = (eEntities) new eArc(((ePlaneEntities) RefEntity).CenterPoint, ((eCircle) RefEntity).Radius, (double) index * 90.0, (double) (index + 1) * 90.0, ((ePlaneEntities) RefEntity).Plane, RefEntity.dispThickness, RefEntity.dispColor);
            eEntities2.LayerIndex = RefEntity.LayerIndex;
            CalcEntities.Add(eEntities2);
          }
        }
      }
      if (RefEntity.GetType() == typeof (eArc))
      {
        if (Options.ArcToPolyline)
        {
          eEntities eEntities3 = (eEntities) new ePolyline(RefEntity.Vertice, RefEntity.dispThickness, RefEntity.dispColor);
          eEntities3.LayerIndex = RefEntity.LayerIndex;
          CalcEntities.Add(eEntities3);
        }
        else
        {
          eEntities2.GroupIndex = -1;
          CalcEntities.Add(eEntities2);
        }
      }
      if (RefEntity.GetType() == typeof (eEllipse) && Options.EllipseToPolyline)
      {
        eEntities eEntities4 = (eEntities) new ePolyline(RefEntity.Vertice, RefEntity.dispThickness, RefEntity.dispColor);
        eEntities4.LayerIndex = RefEntity.LayerIndex;
        CalcEntities.Add(eEntities4);
      }
      if (RefEntity.GetType() == typeof (eEllipseArc) && Options.ArcEllipseToPolyline)
      {
        eEntities eEntities5 = (eEntities) new ePolyline(RefEntity.Vertice, RefEntity.dispThickness, RefEntity.dispColor);
        eEntities5.LayerIndex = RefEntity.LayerIndex;
        CalcEntities.Add(eEntities5);
      }
      if (RefEntity.GetType() == typeof (eBSpline))
      {
        if (Options.CurveToPolyline)
        {
          eEntities eEntities6 = (eEntities) new ePolyline(RefEntity.Vertice, RefEntity.dispThickness, RefEntity.dispColor);
          eEntities6.LayerIndex = RefEntity.LayerIndex;
          CalcEntities.Add(eEntities6);
        }
        if (Options.CurveToControlPoints)
        {
          eEntities eEntities7 = (eEntities) new ePolyline(((eCurveEntities) RefEntity).ControlPoints, RefEntity.dispThickness, RefEntity.dispColor);
          eEntities7.LayerIndex = RefEntity.LayerIndex;
          CalcEntities.Add(eEntities7);
        }
      }
      if (!(RefEntity.GetType() == typeof (eBezeir)))
        return;
      if (Options.CurveToPolyline)
      {
        eEntities eEntities8 = (eEntities) new ePolyline(RefEntity.Vertice, RefEntity.dispThickness, RefEntity.dispColor);
        eEntities8.LayerIndex = RefEntity.LayerIndex;
        CalcEntities.Add(eEntities8);
      }
      if (!Options.CurveToControlPoints)
        return;
      eEntities eEntities9 = (eEntities) new ePolyline(((eCurveEntities) RefEntity).ControlPoints, RefEntity.dispThickness, RefEntity.dispColor);
      eEntities9.LayerIndex = RefEntity.LayerIndex;
      CalcEntities.Add(eEntities9);
    }
    catch (Exception ex)
    {
      string str = "RefEntity: " + RefEntity.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public int Combine(
    eEntities FirstEntity,
    eEntities SecondEntity,
    Pnt3D RefPoint,
    ref eEntities CombinedEntity)
  {
    try
    {
      this.Combine(new List<eEntities>()
      {
        eEntities.CopyEntity(FirstEntity),
        eEntities.CopyEntity(SecondEntity)
      }, RefPoint, new WorkPlane(), ref CombinedEntity);
      return 1;
    }
