  public int Combine(
    List<eEntities> RefEntities,
    Pnt3D RefPoint,
    WorkPlane Plane,
    ref eEntities CombinedEntity)
  {
    try
    {
      List<eEntities> eEntitiesList1 = new List<eEntities>();
      List<eEntities> eEntitiesList2 = new List<eEntities>();
      Pnt3D pnt3D1 = new Pnt3D();
      Pnt3D pnt3D2 = new Pnt3D();
      if (RefEntities.Count <= 0)
        return -1;
      eEntitiesList1.Add(eEntities.CopyEntity(RefEntities[0]));
      for (int index = 1; index <= RefEntities.Count - 1; ++index)
      {
        if (RefEntities[0].GetType() == RefEntities[index].GetType())
          eEntitiesList1.Add(eEntities.CopyEntity(RefEntities[index]));
      }
      if (eEntitiesList1[0].GetType() == typeof (eLine))
      {
        double num1 = this.PointAngle(eEntitiesList2[0].Vertice[eEntitiesList2[0].Vertice.Count - 1], eEntitiesList2[0].Vertice[0], Plane);
        Pnt3D StartPoint = eEntitiesList2[0].camDirections != camPathDirectionType.Normal ? new Pnt3D(eEntitiesList2[0].Vertice[eEntitiesList2[0].Vertice.Count - 1]) : new Pnt3D(eEntitiesList2[0].Vertice[0]);
        bool flag = false;
        for (int index = 1; index <= eEntitiesList2.Count - 1; ++index)
        {
          double num2 = Math.Abs(this.PointAngle(eEntitiesList2[index].Vertice[eEntitiesList2[index].Vertice.Count - 1], eEntitiesList2[index].Vertice[0], Plane) - num1);
          flag = true;
          if (buCompare.EQ(num2, 0.0, 0.01) | buCompare.EQ(num2, 180.0, 0.01))
            flag = false;
        }
        if (flag)
          return -1;
        Pnt3D EndPoint = eEntitiesList2[eEntitiesList2.Count - 1].camDirections != camPathDirectionType.Normal ? new Pnt3D(eEntitiesList2[eEntitiesList2.Count - 1].Vertice[0]) : new Pnt3D(eEntitiesList2[eEntitiesList2.Count - 1].Vertice[eEntitiesList2[eEntitiesList2.Count - 1].Vertice.Count - 1]);
        CombinedEntity = (eEntities) new eLine(StartPoint, EndPoint, RefEntities[0].dispThickness, RefEntities[0].dispColor);
        eEntities.CopyCommonPorperties(RefEntities[0], ref CombinedEntity);
      }
      if (eEntitiesList1[0].GetType() == typeof (eArc))
      {
        bool flag = false;
        double EndAngle = -9999999.0;
        double StartAngle = 9999999.0;
        for (int index = 0; index <= eEntitiesList1.Count - 1; ++index)
        {
          flag = false;
          if (buCompare.EQ(((ePlaneEntities) eEntitiesList1[index]).CenterPoint, ((ePlaneEntities) eEntitiesList1[0]).CenterPoint, 0.01) && buCompare.EQ(((eCircle) eEntitiesList1[index]).Radius, ((eCircle) eEntitiesList1[0]).Radius, 0.01))
          {
            flag = true;
            if (((eArc) eEntitiesList1[index]).StartAngle < StartAngle)
              StartAngle = ((eArc) eEntitiesList1[index]).StartAngle;
            if (((eArc) eEntitiesList1[index]).EndAngle > EndAngle)
              EndAngle = ((eArc) eEntitiesList1[index]).EndAngle;
          }
        }
        if (!flag)
          return -1;
        CombinedEntity = (eEntities) new eArc(((ePlaneEntities) eEntitiesList1[0]).CenterPoint, ((eCircle) eEntitiesList1[0]).Radius, StartAngle, EndAngle, ((ePlaneEntities) eEntitiesList1[0]).Plane, RefEntities[0].dispThickness, RefEntities[0].dispColor);
        eEntities.CopyCommonPorperties(RefEntities[0], ref CombinedEntity);
      }
      return 1;
    }
    catch (Exception ex)
    {
      return -1;
    }
  }

  public void OffsetEntitiesByDynamicalOffset(
    List<eEntities> RefEntities,
    CamOpenContourType2 OpenContourDirection,
    ref List<eEntities> OffsetEntities)
  {
    try
    {
      List<Pnt3D> Points = new List<Pnt3D>();
      List<eEntities> eEntitiesList = new List<eEntities>();
      bool flag = this.IsClosed(RefEntities);
      this.EntityToPoint(RefEntities, buSystem.EntitiesResolution, ref Points);
      ClockDirectionType clockDirectionType = this.PolygonDirection(Points);
      OffsetEntities.Clear();
      if (flag)
      {
        for (int index = 0; index <= RefEntities.Count - 1; ++index)
        {
          eEntities copiedEnt = new eEntities();
          eEntities eEntities = new eEntities();
          eEntities.CopyEntity(RefEntities[index], ref copiedEnt);
          if (clockDirectionType == ClockDirectionType.CW)
          {
            if (copiedEnt.auxValue < 0.0)
              this.OffsetEntity(copiedEnt, copiedEnt.auxValue, CamOpenContourType2.Right, 0.0, ref eEntities);
            else
              this.OffsetEntity(copiedEnt, copiedEnt.auxValue, CamOpenContourType2.Left, 0.0, ref eEntities);
          }
          if (clockDirectionType == ClockDirectionType.CCW)
          {
            if (copiedEnt.auxValue < 0.0)
              this.OffsetEntity(copiedEnt, copiedEnt.auxValue, CamOpenContourType2.Left, 0.0, ref eEntities);
            else if (copiedEnt.auxValue > 0.0)
              this.OffsetEntity(copiedEnt, copiedEnt.auxValue, CamOpenContourType2.Right, 0.0, ref eEntities);
            else
              eEntities.CopyEntity(copiedEnt, ref eEntities);
          }
          OffsetEntities.Add(eEntities);
        }
        eEntities eEntities1 = new eEntities();
        eEntities eEntities2 = new eEntities();
        eEntities eEntities3;
        for (int index = 1; index <= OffsetEntities.Count - 1; ++index)
        {
          eEntities eEntities4 = new eEntities();
          eEntities3 = new eEntities();
          eEntities.CopyEntity(OffsetEntities[index - 1], ref eEntities4);
          eEntities.CopyEntity(OffsetEntities[index], ref eEntities3);
          if (index != 22)
            ;
          this.Connect(ref eEntities4, ref eEntities3, new WorkPlane());
          OffsetEntities[index - 1] = eEntities4;
          OffsetEntities[index] = eEntities3;
        }
        eEntities eEntities5 = new eEntities();
        eEntities3 = new eEntities();
        eEntities.CopyEntity(OffsetEntities[OffsetEntities.Count - 1], ref eEntities5);
        eEntities.CopyEntity(OffsetEntities[0], ref eEntities3);
        this.Connect(ref eEntities5, ref eEntities3, new WorkPlane(), 0, 0);
        OffsetEntities[OffsetEntities.Count - 1] = eEntities5;
        OffsetEntities[0] = eEntities3;
      }
      else
      {
        if (RefEntities.Count == 1)
        {
          eEntities copiedEnt = new eEntities();
          eEntities OffsetedEntity = new eEntities();
          eEntities.CopyEntity(RefEntities[0], ref copiedEnt);
          if (copiedEnt.auxValue > 0.0)
            this.OffsetEntity(copiedEnt, copiedEnt.auxValue, OpenContourDirection, 0.0, ref OffsetedEntity);
          else if (OpenContourDirection == CamOpenContourType2.Right)
            this.OffsetEntity(copiedEnt, copiedEnt.auxValue, CamOpenContourType2.Left, 0.0, ref OffsetedEntity);
          else
            this.OffsetEntity(copiedEnt, copiedEnt.auxValue, CamOpenContourType2.Right, 0.0, ref OffsetedEntity);
          OffsetEntities.Add(OffsetedEntity);
        }
        if (RefEntities.Count <= 1)
          return;
        for (int index = 0; index <= RefEntities.Count - 1; ++index)
        {
          eEntities copiedEnt = new eEntities();
          eEntities OffsetedEntity = new eEntities();
          eEntities.CopyEntity(RefEntities[index], ref copiedEnt);
          if (copiedEnt.GetType() == typeof (eArc))
          {
            double Offset = copiedEnt.auxValue;
            if (copiedEnt.camDirections == camPathDirectionType.Reverse & OpenContourDirection == CamOpenContourType2.Right)
              Offset = -copiedEnt.auxValue;
            if (copiedEnt.camDirections == camPathDirectionType.Normal & OpenContourDirection == CamOpenContourType2.Left)
              Offset = -copiedEnt.auxValue;
            this.OffsetEntity(copiedEnt, Offset, OpenContourDirection, 0.0, ref OffsetedEntity);
          }
          else
            this.OffsetEntity(copiedEnt, copiedEnt.auxValue, OpenContourDirection, 0.0, ref OffsetedEntity);
          OffsetEntities.Add(OffsetedEntity);
        }
        eEntities eEntities6 = new eEntities();
        eEntities eEntities7 = new eEntities();
        for (int index = 1; index <= OffsetEntities.Count - 1; ++index)
        {
          eEntities eEntities8 = new eEntities();
          eEntities eEntities9 = new eEntities();
          eEntities.CopyEntity(OffsetEntities[index - 1], ref eEntities8);
          eEntities.CopyEntity(OffsetEntities[index], ref eEntities9);
          this.Connect(ref eEntities8, ref eEntities9, new WorkPlane());
          OffsetEntities[index - 1] = eEntities8;
          OffsetEntities[index] = eEntities9;
        }
      }
    }
    catch (Exception ex)
    {
      string str = "RefEntities: " + RefEntities.Count.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void OffsetContour(
    List<Pnt3D> RefPoints,
    double Offset,
    OffsetCornerType CornerTypes,
    CamOpenContourType2 OpenContourType,
    WorkPlane Plane,
    double PlaneOffset,
    ref List<Pnt3D> OffsetedPoints)
  {
    List<List<Pnt3D>> OffsetedPoints1 = new List<List<Pnt3D>>();
    this.OffsetContour(RefPoints, Offset, CornerTypes, OpenContourType, Plane, PlaneOffset, ref OffsetedPoints1);
    if (OffsetedPoints1.Count <= 0)
