  public void OffsetContour(
    List<Pnt3D> RefPoints,
    double Offset,
    OffsetCornerType CornerTypes,
    CamOpenContourType2 OpenContourType,
    WorkPlane Plane,
    double PlaneOffset,
    ref List<List<Pnt3D>> OffsetedPoints)
  {
    bool flag = false;
    ClipperOffset clipperOffset = new ClipperOffset();
    clipperOffset.MiterLimit = 100.0;
    buClipper buClipper = new buClipper();
    List<IntPoint> collection = new List<IntPoint>();
    List<IntPoint> intPointList = new List<IntPoint>();
    List<List<IntPoint>> solution = new List<List<IntPoint>>();
    OffsetedPoints = new List<List<Pnt3D>>();
    if (RefPoints.Count > 1 && buCompare.EQ(RefPoints[0], RefPoints[RefPoints.Count - 1], buSystem.resolutionCompare))
      flag = true;
    JoinType joinType = JoinType.jtRound;
    if (CornerTypes == OffsetCornerType.Round)
      joinType = JoinType.jtRound;
    if (CornerTypes == OffsetCornerType.Line)
      joinType = JoinType.jtMiter;
    if (CornerTypes == OffsetCornerType.Chamfer)
      joinType = JoinType.jtSquare;
    if (WorkPlane.isPlaneXZ(Plane))
    {
      for (int index = 0; index <= RefPoints.Count - 1; ++index)
      {
        Pnt3D CalcPoint = new Pnt3D();
        this.PointConversionByPlane(Plane, new WorkPlane(planeType.XY, 1), RefPoints[index], ref CalcPoint);
        RefPoints[index] = new Pnt3D(CalcPoint);
      }
    }
    if (WorkPlane.isPlaneYZ(Plane))
    {
      for (int index = 0; index <= RefPoints.Count - 1; ++index)
      {
        Pnt3D CalcPoint = new Pnt3D();
        this.PointConversionByPlane(Plane, new WorkPlane(planeType.XY, 1), RefPoints[index], ref CalcPoint);
        RefPoints[index] = new Pnt3D(CalcPoint);
      }
    }
    for (int index = 0; index <= RefPoints.Count - 1; ++index)
    {
      IntPoint intPoint = new IntPoint((long) Convert.ToInt32(RefPoints[index].X * (double) buSystem.DoubleToIntegerConts), (long) Convert.ToInt32(RefPoints[index].Y * (double) buSystem.DoubleToIntegerConts));
      collection.Add(intPoint);
    }
    List<IntPoint> path = new List<IntPoint>((IEnumerable<IntPoint>) collection);
    EndType endType = EndType.etClosedPolygon;
    if (!flag)
    {
      if (CornerTypes == OffsetCornerType.Line | CornerTypes == OffsetCornerType.Chamfer)
        endType = EndType.etOpenSquare;
      if (CornerTypes == OffsetCornerType.Round)
        endType = EndType.etOpenRound;
      if (OpenContourType == CamOpenContourType2.Left | OpenContourType == CamOpenContourType2.Right | OpenContourType == CamOpenContourType2.ClosedNoTips)
        endType = EndType.etOpenButt;
      Offset = Math.Abs(Offset);
    }
    clipperOffset.AddPath(path, joinType, endType);
    clipperOffset.Execute(ref solution, Offset * (double) buSystem.DoubleToIntegerConts);
    if (solution.Count >= 1)
    {
      for (int index1 = 0; index1 <= solution.Count - 1; ++index1)
      {
        List<Pnt3D> pnt3DList = new List<Pnt3D>();
        for (int index2 = 0; index2 <= solution[index1].Count - 1; ++index2)
          pnt3DList.Add(new Pnt3D((double) solution[index1][index2].X / (double) buSystem.DoubleToIntegerConts, (double) solution[index1][index2].Y / (double) buSystem.DoubleToIntegerConts, (double) solution[index1][index2].Z)
          {
            Z = PlaneOffset
          });
        if (pnt3DList.Count >= 2 && !buCompare.EQ(pnt3DList[0], pnt3DList[pnt3DList.Count - 1], buSystem.resolutionCompare))
        {
          new Pnt3D(pnt3DList[0]).Z = PlaneOffset;
          pnt3DList.Add(new Pnt3D(pnt3DList[0]));
        }
        OffsetedPoints.Add(pnt3DList);
      }
    }
    if (WorkPlane.isPlaneXZ(Plane))
    {
      for (int index3 = 0; index3 <= OffsetedPoints.Count - 1; ++index3)
      {
        for (int index4 = 0; index4 <= OffsetedPoints[index3].Count - 1; ++index4)
        {
          Pnt3D CalcPoint = new Pnt3D();
          this.PointConversionByPlane(new WorkPlane(planeType.XY, 1), Plane, OffsetedPoints[index3][index4], ref CalcPoint);
          OffsetedPoints[index3][index4] = new Pnt3D(CalcPoint);
        }
      }
    }
    if (!WorkPlane.isPlaneYZ(Plane))
      return;
    for (int index5 = 0; index5 <= OffsetedPoints.Count - 1; ++index5)
    {
      for (int index6 = 0; index6 <= OffsetedPoints[index5].Count - 1; ++index6)
      {
        Pnt3D CalcPoint = new Pnt3D();
        this.PointConversionByPlane(new WorkPlane(planeType.XY, 1), Plane, OffsetedPoints[index5][index6], ref CalcPoint);
        OffsetedPoints[index5][index6] = new Pnt3D(CalcPoint);
      }
    }
  }

  public void OffsetContour(
    List<List<Pnt3D>> RefPoints,
    double Offset,
    OffsetCornerType CornerTypes,
    CamOpenContourType2 OpenContourType,
    WorkPlane Plane,
    double PlaneOffset,
    ref List<List<Pnt3D>> OffsetedPoints)
  {
    ClipperOffset clipperOffset = new ClipperOffset();
    List<IntPoint> intPointList1 = new List<IntPoint>();
    List<List<IntPoint>> paths = new List<List<IntPoint>>();
    List<List<IntPoint>> solution = new List<List<IntPoint>>();
    OffsetedPoints = new List<List<Pnt3D>>();
    JoinType joinType = JoinType.jtRound;
    if (CornerTypes == OffsetCornerType.Round)
      joinType = JoinType.jtRound;
    if (CornerTypes == OffsetCornerType.Line)
      joinType = JoinType.jtMiter;
    if (CornerTypes == OffsetCornerType.Chamfer)
      joinType = JoinType.jtSquare;
    if (WorkPlane.isPlaneXZ(Plane))
    {
      for (int index1 = 0; index1 <= RefPoints.Count - 1; ++index1)
      {
        for (int index2 = 0; index2 <= RefPoints[index1].Count - 1; ++index2)
        {
          Pnt3D CalcPoint = new Pnt3D();
          this.PointConversionByPlane(Plane, new WorkPlane(planeType.XY, 1), RefPoints[index1][index2], ref CalcPoint);
          RefPoints[index1][index2] = new Pnt3D(CalcPoint);
        }
      }
    }
    if (WorkPlane.isPlaneYZ(Plane))
    {
      for (int index3 = 0; index3 <= RefPoints.Count - 1; ++index3)
      {
        for (int index4 = 0; index4 <= RefPoints[index3].Count - 1; ++index4)
        {
          Pnt3D CalcPoint = new Pnt3D();
          this.PointConversionByPlane(Plane, new WorkPlane(planeType.XY, 1), RefPoints[index3][index4], ref CalcPoint);
          RefPoints[index3][index4] = new Pnt3D(CalcPoint);
        }
      }
    }
    ClockDirectionType clockDirectionType = this.PolygonDirection(RefPoints[0], new WorkPlane());
    for (int index5 = 0; index5 <= RefPoints.Count - 1; ++index5)
    {
      if (index5 > 0 && this.PolygonDirection(RefPoints[index5], new WorkPlane()) == clockDirectionType)
        RefPoints[index5].Reverse();
      List<IntPoint> collection = new List<IntPoint>();
      for (int index6 = 0; index6 <= RefPoints[index5].Count - 1; ++index6)
      {
        IntPoint intPoint = new IntPoint((long) Convert.ToInt32(RefPoints[index5][index6].X * (double) buSystem.DoubleToIntegerConts), (long) Convert.ToInt32(RefPoints[index5][index6].Y * (double) buSystem.DoubleToIntegerConts));
        collection.Add(intPoint);
      }
      List<IntPoint> intPointList2 = new List<IntPoint>((IEnumerable<IntPoint>) collection);
      paths.Add(intPointList2);
    }
    clipperOffset.AddPaths(paths, joinType, EndType.etClosedPolygon);
    clipperOffset.Execute(ref solution, Offset * (double) buSystem.DoubleToIntegerConts);
    if (solution.Count >= 1)
    {
      for (int index7 = 0; index7 <= solution.Count - 1; ++index7)
      {
        List<Pnt3D> pnt3DList = new List<Pnt3D>();
        for (int index8 = 0; index8 <= solution[index7].Count - 1; ++index8)
        {
          Pnt3D pnt3D = new Pnt3D((double) solution[index7][index8].X / (double) buSystem.DoubleToIntegerConts, (double) solution[index7][index8].Y / (double) buSystem.DoubleToIntegerConts, (double) solution[index7][index8].Z);
          pnt3DList.Add(pnt3D);
        }
        if (pnt3DList.Count >= 2 && !buCompare.EQ(pnt3DList[0], pnt3DList[pnt3DList.Count - 1]))
          pnt3DList.Add(new Pnt3D(pnt3DList[0])
          {
            Z = PlaneOffset
          });
        OffsetedPoints.Add(pnt3DList);
      }
    }
    if (WorkPlane.isPlaneXZ(Plane))
    {
      for (int index9 = 0; index9 <= OffsetedPoints.Count - 1; ++index9)
      {
        for (int index10 = 0; index10 <= OffsetedPoints[index9].Count - 1; ++index10)
        {
          Pnt3D CalcPoint = new Pnt3D();
          this.PointConversionByPlane(new WorkPlane(planeType.XY, 1), Plane, OffsetedPoints[index9][index10], ref CalcPoint);
          OffsetedPoints[index9][index10] = new Pnt3D(CalcPoint);
        }
      }
    }
    if (!WorkPlane.isPlaneYZ(Plane))
      return;
    for (int index11 = 0; index11 <= OffsetedPoints.Count - 1; ++index11)
    {
      for (int index12 = 0; index12 <= OffsetedPoints[index11].Count - 1; ++index12)
      {
        Pnt3D CalcPoint = new Pnt3D();
        this.PointConversionByPlane(new WorkPlane(planeType.XY, 1), Plane, OffsetedPoints[index11][index12], ref CalcPoint);
        OffsetedPoints[index11][index12] = new Pnt3D(CalcPoint);
      }
    }
  }

  public void OffsetContour(
    List<Pnt3D> OutterPoints,
    List<List<Pnt3D>> InnerPoints,
    double Offset,
    OffsetCornerType CornerTypes,
    CamOpenContourType2 OpenContourType,
    WorkPlane Plane,
    double PlaneOffset,
    ref List<List<Pnt3D>> OffsetedPoints)
  {
    List<List<Pnt3D>> RefPoints = new List<List<Pnt3D>>();
    List<Pnt3D> CopiedPnt1 = new List<Pnt3D>();
    Pnt3D.Copy(OutterPoints, ref CopiedPnt1);
    RefPoints.Add(CopiedPnt1);
    ClockDirectionType clockDirectionType = this.PolygonDirection(OutterPoints, Plane);
    for (int index1 = 0; index1 <= InnerPoints.Count - 1; ++index1)
    {
      bool flag = true;
      List<Pnt3D> CopiedPnt2 = new List<Pnt3D>();
      Pnt3D.Copy(InnerPoints[index1], ref CopiedPnt2);
      for (int index2 = 0; index2 <= CopiedPnt2.Count - 1; ++index2)
        flag &= this.IsPointInsidePolygon(OutterPoints, CopiedPnt2[index2], Plane);
      if (flag)
      {
        if (this.PolygonDirection(CopiedPnt2, Plane) == clockDirectionType)
        {
          CopiedPnt2.Reverse();
          RefPoints.Add(CopiedPnt2);
        }
        else
          RefPoints.Add(CopiedPnt2);
      }
    }
    this.OffsetContour(RefPoints, Offset, CornerTypes, OpenContourType, Plane, PlaneOffset, ref OffsetedPoints);
  }

