      {
        if (Closed = this.IsClosed(contourPointsList[index1].Holes[index2]))
        {
          List<Pnt3D> CopiedPnt4 = new List<Pnt3D>();
          Pnt3D.Copy(contourPointsList[index1].Holes[index2], ref CopiedPnt4);
          InnerPoints1.Add(CopiedPnt4);
        }
      }
      if (CopiedPnt1.Count > 0)
      {
        Pnt3D pnt3D2 = new Pnt3D(CopiedPnt1[0]);
        Pnt3D.Copy(CopiedPnt1, ref CopiedPnt2);
        CopiedPnt3.Add(CopiedPnt2);
        do
        {
          List<List<Pnt3D>> OffsetedPoints = new List<List<Pnt3D>>();
          List<List<Pnt3D>> TargetList = new List<List<Pnt3D>>();
          List<Pnt3D> pnt3DList = new List<Pnt3D>();
          if (num != 0)
          {
            for (int index3 = 0; index3 <= CopiedPnt3.Count - 1; ++index3)
            {
              if (InnerPoints1.Count == 0)
                this.OffsetContour(CopiedPnt3[index3], Offset, OffsetCornerType.Line, CamOpenContourType2.Closed, Plane, PlaneOffset, ref OffsetedPoints);
              else
                this.OffsetContour(CopiedPnt3[index3], InnerPoints1, Offset, OffsetCornerType.Line, CamOpenContourType2.Closed, Plane, PlaneOffset, ref OffsetedPoints);
              Pnt3D.Add(OffsetedPoints, ref TargetList);
            }
          }
          else
            goto label_40;
label_18:
          ++num;
          CopiedPnt3.Clear();
          if (TargetList.Count == 1)
          {
            if (pocketPoints.Pockets.Count > 0)
            {
              pnt3DList = new List<Pnt3D>();
              Pnt3D.Copy(TargetList, ref pnt3DList);
              this.ShiftPointsByLength(new Pnt3D(Pnt), ref pnt3DList);
              pnt3DList.Add(new Pnt3D(pnt3DList[0]));
              this.CheckDuplicatedPointsWithPrevious(ref pnt3DList);
            }
            else
              Pnt3D.Copy(TargetList, ref pnt3DList);
            Pnt3D.Copy(TargetList, ref CopiedPnt3);
            if (this.PolygonDirection(pnt3DList, new WorkPlane()) != NeededDirection)
              pnt3DList.Reverse();
            List<eEntities> eEntitiesList = new List<eEntities>();
            pocketPoints.Pockets.Add(pnt3DList);
            CalcEntities = new List<eEntities>();
            PointsToEntitiesPar Pars = new PointsToEntitiesPar();
            this.PointsToEntities(pnt3DList, Plane, Pars, ref CalcEntities);
            PocketEntities.Add(CalcEntities);
            Pnt = new Pnt3D(pnt3DList[pnt3DList.Count - 1]);
          }
          if (TargetList.Count > 1)
          {
            pnt3DList = new List<Pnt3D>();
            Pnt3D.Copy(TargetList[0], ref pnt3DList);
            this.ShiftPointsByLength(new Pnt3D(Pnt), ref pnt3DList);
            pnt3DList.Add(new Pnt3D(pnt3DList[0]));
            this.CheckDuplicatedPointsWithPrevious(ref pnt3DList);
            pocketPoints.Pockets.Add(pnt3DList);
            CalcEntities = new List<eEntities>();
            PointsToEntitiesPar Pars = new PointsToEntitiesPar();
