            PocketEntities.Add(CalcEntities);
            CopiedPnt3.Add(pnt3DList);
            Pnt = new Pnt3D(pnt3DList[pnt3DList.Count - 1]);
            for (int index4 = 1; index4 <= TargetList.Count - 1; ++index4)
            {
              if (this.PolygonDirection(TargetList[index4], new WorkPlane()) != NeededDirection)
                TargetList[index4].Reverse();
              pnt3DList = new List<Pnt3D>();
              Pnt3D.Copy(TargetList[index4], ref pnt3DList);
              if (!this.IsPointsSame(RefPoints, pnt3DList))
                RefPoints.Add(pnt3DList);
            }
          }
          if (TargetList.Count == 0 & RefPoints.Count == 0)
            flag = false;
          if (TargetList.Count == 0 & RefPoints.Count > 0)
          {
            CopiedPnt1.Clear();
            pnt3DList = new List<Pnt3D>();
            if (this.PolygonDirection(RefPoints[0], new WorkPlane()) != NeededDirection)
              RefPoints[0].Reverse();
            Pnt3D.Copy(RefPoints[0], ref pnt3DList);
            pocketPoints.Pockets.Add(pnt3DList);
            CalcEntities = new List<eEntities>();
            PointsToEntitiesPar Pars = new PointsToEntitiesPar();
            this.PointsToEntities(pnt3DList, Plane, Pars, ref CalcEntities);
