            CopiedPnt3.Add(pnt3DList);
            RefPoints.RemoveAt(0);
          }
          TargetList.Clear();
          continue;
label_40:
          for (int index5 = 0; index5 <= CopiedPnt3.Count - 1; ++index5)
          {
            if (InnerPoints1.Count == 0)
              this.OffsetContour(CopiedPnt3[index5], Offset, OffsetCornerType.Line, CamOpenContourType2.Closed, Plane, PlaneOffset, ref OffsetedPoints);
            else
              this.OffsetContour(CopiedPnt3[index5], InnerPoints1, Offset, OffsetCornerType.Line, CamOpenContourType2.Closed, Plane, PlaneOffset, ref OffsetedPoints);
            List<eEntities> CalcEnt = new List<eEntities>();
            this.AddPointOffsetedPath(OffsetedPoints, CopiedPnt2, Offset, Closed, NeededDirection, 0.1, ref CalcEnt);
            for (int index6 = 0; index6 <= CalcEnt.Count - 1; ++index6)
            {
              pnt3DList = new List<Pnt3D>();
              Pnt3D.Copy(CalcEnt[index6].Vertice, ref pnt3DList);
              this.ShiftPointsByLength(pnt3D2, ref pnt3DList);
              pnt3DList.Add(new Pnt3D(pnt3DList[0]));
              this.CheckDuplicatedPointsWithPrevious(ref pnt3DList);
              TargetList.Add(pnt3DList);
            }
            if (TargetList.Count > 1)
            {
              for (int index7 = 0; index7 <= TargetList.Count - 1; ++index7)
              {
                for (int index8 = 1; index8 <= TargetList.Count - 1; ++index8)
                {
                  if (this.Length3D(pnt3D2, TargetList[index8][0]) < this.Length3D(pnt3D2, TargetList[index8 - 1][0]))
                  {
                    List<Pnt3D> CopiedPnt5 = new List<Pnt3D>();
                    List<Pnt3D> CopiedPnt6 = new List<Pnt3D>();
                    Pnt3D.Copy(TargetList[index8 - 1], ref CopiedPnt5);
                    Pnt3D.Copy(TargetList[index8], ref CopiedPnt6);
                    TargetList[index8 - 1] = CopiedPnt6;
                    TargetList[index8] = CopiedPnt5;
                  }
                }
              }
            }
          }
          goto label_18;
        }
        while (flag);
