  public void OpenProfileCalculation(
    List<Pnt3D> OffsetedPoints,
    List<Pnt3D> EntityPoints,
    double Offset,
    WorkPlane Plane,
    CamOpenContourType2 ContourDirection,
    ref List<Pnt3D> CalcPoints)
  {
    if (Offset == 0.0 || ContourDirection == CamOpenContourType2.Center)
      return;
    int num1 = -1;
    int num2 = -1;
    List<Pnt3D> pnt3DList = new List<Pnt3D>();
    Pnt3D.Copy(OffsetedPoints, ref pnt3DList);
    this.CheckDuplicatedPointsWithPrevious(ref pnt3DList);
    this.ShiftPointsByLength(EntityPoints[0], EntityPoints[1], true, ref pnt3DList);
    this.Length3D(pnt3DList[0], EntityPoints[0]);
    this.Length3D(pnt3DList[1], EntityPoints[1]);
    if (pnt3DList.Count > 1 && buCompare.EQ(this.Length3D(pnt3DList[0], EntityPoints[0], Plane), this.Length3D(pnt3DList[1], EntityPoints[0], Plane)))
      this.ShiftList(ref pnt3DList, -1);
    for (int index = 0; index <= pnt3DList.Count - 1; ++index)
    {
      double num3 = this.Length3D(EntityPoints[0], pnt3DList[index], Plane);
      double num4 = this.Length3D(EntityPoints[EntityPoints.Count - 1], pnt3DList[index], Plane);
      if (buCompare.EQ(num3, Math.Abs(Offset)) & num1 == -1)
        num1 = index;
      if (buCompare.EQ(num4, Math.Abs(Offset)))
        num2 = index;
    }
    List<Pnt3D> pts1 = new List<Pnt3D>();
    List<Pnt3D> pts2 = new List<Pnt3D>();
    for (int index = num1; index < num2; ++index)
    {
      if (index >= 0)
      {
        Pnt3D pnt3D = new Pnt3D(pnt3DList[index]);
        pts1.Add(pnt3D);
      }
    }
    for (int index = num2; index <= pnt3DList.Count - 1; ++index)
    {
      if (index >= 0)
      {
        Pnt3D pnt3D = new Pnt3D(pnt3DList[index]);
        pts2.Add(pnt3D);
      }
    }
    pts2.Reverse();
    if (pts2.Count > 1)
    {
      if (buCompare.EQ(this.Length3D(pts2[0], EntityPoints[0], Plane), this.Length3D(pts2[1], EntityPoints[0], Plane)))
        pts2.RemoveAt(0);
      if (pts2.Count > 1 && buCompare.EQ(this.Length3D(pts2[pts2.Count - 1], EntityPoints[EntityPoints.Count - 1], Plane), this.Length3D(pts2[pts2.Count - 2], EntityPoints[EntityPoints.Count - 1], Plane)))
        pts2.RemoveAt(pts2.Count - 1);
    }
    if (pts1.Count > 1)
    {
      if (buCompare.EQ(this.Length3D(pts1[0], EntityPoints[0], Plane), this.Length3D(pts1[1], EntityPoints[0], Plane)))
        pts1.RemoveAt(0);
      if (buCompare.EQ(this.Length3D(pts1[pts1.Count - 1], EntityPoints[EntityPoints.Count - 1], Plane), this.Length3D(pts1[pts1.Count - 2], EntityPoints[EntityPoints.Count - 1], Plane)))
        pts1.RemoveAt(pts1.Count - 1);
    }
    double num5 = 0.0;
    double num6 = 0.0;
    if (pts1.Count > 1)
      num5 = this.PointAngle(pts1[1], EntityPoints[0], Plane);
    if (pts2.Count > 1)
      num6 = this.PointAngle(pts2[1], EntityPoints[0], Plane);
    if (Math.Abs(num5 - num6) > 180.0)
    {
      if (num5 < num6)
        num5 += 360.0;
      else
        num6 += 360.0;
    }
    if (ContourDirection == CamOpenContourType2.Right)
    {
      if (num5 < num6)
        Pnt3D.Copy(pts1, ref CalcPoints);
      else
        Pnt3D.Copy(pts2, ref CalcPoints);
    }
    if (ContourDirection != CamOpenContourType2.Left)
      return;
    if (num5 > num6)
      Pnt3D.Copy(pts1, ref CalcPoints);
    else
      Pnt3D.Copy(pts2, ref CalcPoints);
  }

  public void OffsetEntity(
    eEntities RefEntity,
    double Offset,
    CamOpenContourType2 OpenContourType,
    double PlaneOffset,
    ref eEntities OffsetedEntity)
  {
    try
    {
      if (RefEntity.GetType() == typeof (eLine))
      {
        eEntities copiedEnt = (eEntities) new eLine(RefEntity.Vertice[0], RefEntity.Vertice[1]);
        if (RefEntity.camDirections == camPathDirectionType.Reverse)
          copiedEnt = (eEntities) new eLine(RefEntity.Vertice[1], RefEntity.Vertice[0]);
        eEntities.CopyCommonPorperties(RefEntity, ref copiedEnt);
        List<List<Pnt3D>> OffsetedPoints = new List<List<Pnt3D>>();
        this.OffsetContour(copiedEnt.Vertice, Offset, OffsetCornerType.Line, OpenContourType, new WorkPlane(), PlaneOffset, ref OffsetedPoints);
        if (OffsetedPoints.Count > 0)
        {
          double num1 = this.PointAngle(copiedEnt.Vertice[1], copiedEnt.Vertice[0]);
          for (int index = 1; index <= OffsetedPoints[0].Count - 1; ++index)
          {
            Pnt3D pnt3D1 = new Pnt3D(OffsetedPoints[0][index - 1]);
            Pnt3D pnt3D2 = new Pnt3D(OffsetedPoints[0][index]);
            double num2 = this.Length3D(pnt3D1, pnt3D2, new WorkPlane());
            if (buCompare.EQ(copiedEnt.geoLength, num2))
            {
              double num3 = this.Length3D(pnt3D1, copiedEnt.Vertice[0], new WorkPlane());
              double num4 = this.Length3D(pnt3D2, copiedEnt.Vertice[0], new WorkPlane());
              if (buCompare.EQ(Math.Abs(Offset), num3, 0.05))
              {
                double num5 = this.PointAngle(pnt3D2, copiedEnt.Vertice[0]);
                double num6 = num5 - num1;
                if (num6 > 180.0)
                {
                  num1 += 360.0;
                  num6 = num5 - num1;
                }
                if (num6 < -180.0)
                  num6 = num5 + 360.0 - num1;
                if (OpenContourType == CamOpenContourType2.Left && num6 > 0.0)
                  OffsetedEntity = (eEntities) new eLine(pnt3D1, pnt3D2);
                if (OpenContourType == CamOpenContourType2.Right && num6 < 0.0)
                  OffsetedEntity = (eEntities) new eLine(pnt3D1, pnt3D2);
              }
              if (buCompare.EQ(Math.Abs(Offset), num4, 0.05))
              {
                double num7 = this.PointAngle(pnt3D1, copiedEnt.Vertice[0]);
                double num8 = num7 - num1;
                if (num8 > 180.0)
                {
                  num1 += 360.0;
                  num8 = num7 - num1;
                }
                if (num8 < -180.0)
                  num8 = num7 + 360.0 - num1;
                if (OpenContourType == CamOpenContourType2.Left && num8 > 0.0)
                  OffsetedEntity = (eEntities) new eLine(pnt3D2, pnt3D1);
                if (OpenContourType == CamOpenContourType2.Right && num8 < 0.0)
                  OffsetedEntity = (eEntities) new eLine(pnt3D2, pnt3D1);
              }
            }
          }
          eEntities.CopyCommonPorperties(RefEntity, ref OffsetedEntity);
        }
      }
      if (RefEntity.GetType() == typeof (ePolyline))
      {
        List<List<Pnt3D>> OffsetedPoints = new List<List<Pnt3D>>();
        this.OffsetContour(RefEntity.Vertice, Offset, OffsetCornerType.Line, OpenContourType, new WorkPlane(), PlaneOffset, ref OffsetedPoints);
        if (OffsetedPoints.Count > 0)
        {
          List<Pnt3D> CalcPoints = new List<Pnt3D>();
          this.OpenProfileCalculation(OffsetedPoints[0], RefEntity.Vertice, Offset, new WorkPlane(), OpenContourType, ref CalcPoints);
          OffsetedEntity = (eEntities) new ePolyline(CalcPoints);
          eEntities.CopyCommonPorperties(RefEntity, ref OffsetedEntity);
        }
      }
      if (RefEntity.GetType() == typeof (eCircle))
      {
        OffsetedEntity = (eEntities) new eCircle(((ePlaneEntities) RefEntity).CenterPoint, ((eCircle) RefEntity).Radius + Offset, ((ePlaneEntities) RefEntity).Plane);
        eEntities.CopyCommonPorperties(RefEntity, ref OffsetedEntity);
      }
      if (RefEntity.GetType() == typeof (eArc))
      {
        OffsetedEntity = (eEntities) new eArc(((ePlaneEntities) RefEntity).CenterPoint, ((eCircle) RefEntity).Radius + Offset, ((eArc) RefEntity).StartAngle, ((eArc) RefEntity).EndAngle, ((ePlaneEntities) RefEntity).Plane);
        eEntities.CopyCommonPorperties(RefEntity, ref OffsetedEntity);
      }
      if (!(RefEntity.GetType() == typeof (eEllipse)))
        return;
      OffsetedEntity = (eEntities) new eEllipse(((ePlaneEntities) RefEntity).CenterPoint, ((eEllipse) RefEntity).MajorRadius + Offset, ((eEllipse) RefEntity).MinorRadius + Offset, ((eEllipse) RefEntity).Angle, ((ePlaneEntities) RefEntity).Plane);
      eEntities.CopyCommonPorperties(RefEntity, ref OffsetedEntity);
    }
    catch (Exception ex)
    {
      string str = $"RefEntity: {RefEntity.ToString()}- Offset: {Offset.ToString()}- OpenContourType: {OpenContourType.ToString()}- PlaneOffset: {PlaneOffset.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void OffsetEntity(
    ref eEntities RefEntity,
    double Offset,
    CamOpenContourType2 OpenContourType,
    double PlaneOffset)
  {
    eEntities OffsetedEntity = new eEntities();
    this.OffsetEntity(RefEntity, Offset, OpenContourType, PlaneOffset, ref OffsetedEntity);
    RefEntity = new eEntities();
    eEntities.CopyEntity(OffsetedEntity, ref RefEntity);
  }

  public void AddPointOffsetedPath(
    List<List<Pnt3D>> PLL,
    List<Pnt3D> SortedPoints,
    double Offset,
    bool Closed,
    ClockDirectionType ClockDir,
    double Resolution,
    ref List<eEntities> CalcEnt)
  {
    for (int index1 = 0; index1 <= PLL.Count - 1; ++index1)
    {
      double num = this.PointAngle(SortedPoints[1], SortedPoints[0], new WorkPlane());
      Pnt3D BasePnt1 = new Pnt3D();
      Pnt3D EndPnt1 = new Pnt3D();
      Pnt3D BasePnt2 = new Pnt3D();
      Pnt3D EndPnt2 = new Pnt3D();
      this.LineWithLengthAndAngle(SortedPoints[0], Math.Abs(Offset), num + 90.0, new WorkPlane(), ref BasePnt1, ref EndPnt1);
      this.LineWithLengthAndAngle(SortedPoints[0], Math.Abs(Offset), num - 90.0, new WorkPlane(), ref BasePnt2, ref EndPnt2);
      List<Pnt3D> CopiedPnt = new List<Pnt3D>();
      Pnt3D.Copy(PLL[index1], ref CopiedPnt);
      for (int index2 = 1; index2 <= CopiedPnt.Count - 1; ++index2)
      {
        Pnt3D CalculatedPoint = new Pnt3D();
        double Distance = 0.0;
        if (this.IsPointOverLine(CopiedPnt[index2 - 1], CopiedPnt[index2], EndPnt1, new WorkPlane(), Resolution, ref CalculatedPoint, ref Distance) && Distance < Resolution)
        {
          CopiedPnt.Insert(index2, CalculatedPoint);
          index2 = CopiedPnt.Count;
          PLL.RemoveAt(index1);
          PLL.Insert(index1, CopiedPnt);
        }
        if (index2 <= CopiedPnt.Count - 1 && this.IsPointOverLine(CopiedPnt[index2 - 1], CopiedPnt[index2], EndPnt2, new WorkPlane(), Resolution, ref CalculatedPoint, ref Distance) && Distance < Resolution)
        {
          CopiedPnt.Insert(index2, CalculatedPoint);
          index2 = CopiedPnt.Count;
          PLL.RemoveAt(index1);
          PLL.Insert(index1, CopiedPnt);
        }
      }
      if (this.PolygonDirection(PLL[index1], new WorkPlane()) != ClockDir & Closed)
        PLL[index1].Reverse();
      ePolyline ePolyline = new ePolyline(PLL[index1]);
      CalcEnt.Add((eEntities) ePolyline);
    }
  }

  public void AddPointOffsetedPath(
    List<Pnt3D> ModifiedPoints,
    List<Pnt3D> SortedOriginalPoints,
    double Offset,
    bool Closed,
    ClockDirectionType ClockDir,
    double Resolution,
    ref List<Pnt3D> CalcPoints)
  {
    double num = this.PointAngle(SortedOriginalPoints[1], SortedOriginalPoints[0], new WorkPlane());
    Pnt3D BasePnt1 = new Pnt3D();
    Pnt3D EndPnt1 = new Pnt3D();
    Pnt3D BasePnt2 = new Pnt3D();
    Pnt3D EndPnt2 = new Pnt3D();
    this.LineWithLengthAndAngle(SortedOriginalPoints[0], Math.Abs(Offset), num + 90.0, new WorkPlane(), ref BasePnt1, ref EndPnt1);
    this.LineWithLengthAndAngle(SortedOriginalPoints[0], Math.Abs(Offset), num - 90.0, new WorkPlane(), ref BasePnt2, ref EndPnt2);
    List<Pnt3D> CopiedPnt = new List<Pnt3D>();
    Pnt3D.Copy(ModifiedPoints, ref CopiedPnt);
    for (int index = 1; index <= CopiedPnt.Count - 1; ++index)
    {
      Pnt3D CalculatedPoint = new Pnt3D();
      double Distance = 0.0;
      if (this.IsPointOverLine(CopiedPnt[index - 1], CopiedPnt[index], EndPnt1, new WorkPlane(), Resolution, ref CalculatedPoint, ref Distance) && Distance < Resolution)
      {
        CopiedPnt.Insert(index, new Pnt3D(CalculatedPoint.X, CalculatedPoint.Y, CopiedPnt[index].Z));
        index = CopiedPnt.Count;
      }
      if (index <= CopiedPnt.Count - 1 && this.IsPointOverLine(CopiedPnt[index - 1], CopiedPnt[index], EndPnt2, new WorkPlane(), Resolution, ref CalculatedPoint, ref Distance) && Distance < Resolution)
      {
        CopiedPnt.Insert(index, new Pnt3D(CalculatedPoint.X, CalculatedPoint.Y, CopiedPnt[index].Z));
        index = CopiedPnt.Count;
      }
    }
    if (this.PolygonDirection(ModifiedPoints, new WorkPlane()) != ClockDir & Closed)
      ModifiedPoints.Reverse();
    CalcPoints = new List<Pnt3D>((IEnumerable<Pnt3D>) CopiedPnt);
  }

  public void ShiftPointsAndPointsToEntities(
    Pnt3D StartPoint,
    double OverlapDistance,
    WorkPlane Plane,
    ClockDirectionType ClockDir,
    bool Closed,
    double Resolution,
    ref List<eEntities> CalcEnt)
  {
    List<eEntities> eEntitiesList = new List<eEntities>();
    for (int index1 = 0; index1 <= CalcEnt.Count - 1; ++index1)
    {
      List<Pnt3D> RefPoint = new List<Pnt3D>();
      Pnt3D.Copy(CalcEnt[index1].Vertice, ref RefPoint);
      this.ShiftPointsByLength(StartPoint, ref RefPoint);
      RefPoint.Add(new Pnt3D(RefPoint[0]));
      this.CheckDuplicatedPointsWithPrevious(ref RefPoint);
      List<eEntities> CalcEntities = new List<eEntities>();
      this.PointsToEntities(RefPoint, Plane, new PointsToEntitiesPar()
      {
        LengthFilter = Resolution
      }, ref CalcEntities);
      for (int index2 = 0; index2 <= CalcEntities.Count - 1; ++index2)
      {
        if (CalcEntities[index2].geoLength > 0.0)
          eEntitiesList.Add(eEntities.CopyEntity(CalcEntities[index2]));
      }
    }
    CalcEnt.Clear();
    List<Pnt3D> pnt3DList = new List<Pnt3D>();
  }

  public void OffsetAndTrimSingleEntityFromGroup(
    ref List<eEntities> Entities,
    int EntityIndex,
    double Offset,
    double PlaneOffset,
    CamOpenContourType2 OpenContourType)
  {
    if (EntityIndex < 0 || EntityIndex > Entities.Count - 1)
      return;
    eEntities copiedEnt = new eEntities();
    List<Pnt3D> Points = new List<Pnt3D>();
    List<List<Pnt3D>> OffsetedPoints = new List<List<Pnt3D>>();
    eEntities.CopyEntity(Entities[EntityIndex], ref copiedEnt);
    this.EntityToPoint(copiedEnt, ref Points);
    this.OffsetContour(Points, Offset, OffsetCornerType.Line, OpenContourType, new WorkPlane(), PlaneOffset, ref OffsetedPoints);
  }

  public void AreaCorrection(
