    Pnt3D CenterPoint,
    WorkPlane Plane,
    AxesXYZ Direction,
    ref eEntities Entity)
  {
    List<Pnt3D> Vertices = new List<Pnt3D>();
    double width = AreaData.Width;
    if (AreaData.Type == AreaBrushType.Rectangle)
      this.RectangleAngleWithCenter(CenterPoint, AreaData.Width, AreaData.Height, AreaData.Angle, Plane, ref Vertices);
    if (AreaData.Type == AreaBrushType.Circle)
      this.CircleWithCenter(CenterPoint, AreaData.Width, Plane, buSystem.EntitiesResolution, ref Vertices);
    if (AreaData.Type == AreaBrushType.Ellipse)
      this.EllipseWithCenter(CenterPoint, AreaData.Width, AreaData.Height, AreaData.Angle, Plane, buSystem.EntitiesResolution, ref Vertices);
    if (Entity.GetType() == typeof (ePoint))
    {
      Pnt3D pnt3D = new Pnt3D(((ePoint) Entity).StartPoint);
      if (this.IsPointInsidePolygon(Vertices, pnt3D))
      {
        double Angle = this.PointAngle(pnt3D, CenterPoint, Plane);
        if (AreaData.Type == AreaBrushType.Rectangle)
          this.RectangleEdgeDistanceByAngle(AreaData.Width, AreaData.Height, Angle, ref width);
        if (AreaData.Type == AreaBrushType.Circle)
          width = AreaData.Width;
        if (AreaData.Type == AreaBrushType.Ellipse)
          this.EllipseRadiusByAngle(AreaData.Width, AreaData.Height, Angle, ref width);
        if (Direction == AxesXYZ.X)
        {
          double num1 = this.Length3D(CenterPoint, pnt3D, Plane);
          double num2 = buNumeric.ValueFromMinMaxValues(0.0, width, num1, AreaData.DistanceCenter, MinMaxValuesType.MinIsBigValue);
          pnt3D.X += num2;
        }
        if (Direction == AxesXYZ.Y)
        {
          double num3 = this.Length3D(CenterPoint, pnt3D, Plane);
          double num4 = buNumeric.ValueFromMinMaxValues(0.0, width, num3, AreaData.DistanceCenter, MinMaxValuesType.MinIsBigValue);
