  public void SelectionToSelectedProperties(
    List<List<Selection>> SelectedList,
    ref SelectedEntities SelectedProps)
  {
    try
    {
      SelectedProps.AlingPoints.MovePoints.Clear();
      SelectedProps.AlingPoints.TipPoints.Clear();
      SelectedProps.AlingPoints.BoxSizePoints.Clear();
      SelectedProps.AlingPoints.RotatePoints.Clear();
      List<eEntities> Entities = new List<eEntities>();
      for (int index1 = 0; index1 <= SelectedList.Count - 1; ++index1)
      {
        for (int index2 = 0; index2 <= SelectedList[index1].Count - 1; ++index2)
        {
          if (SelectedProps.ClickPointOfEntity.Clicked)
          {
            if (SelectedList[index1][index2].Entity.GetType() == typeof (ePoint) | SelectedList[index1][index2].Entity.GetType() == typeof (eLine) | SelectedList[index1][index2].Entity.GetType() == typeof (ePolyline) | SelectedList[index1][index2].Entity.GetType() == typeof (eArc) | SelectedList[index1][index2].Entity.GetType() == typeof (eCircle) | SelectedList[index1][index2].Entity.GetType() == typeof (eEllipse) | SelectedList[index1][index2].Entity.GetType() == typeof (ePicture))
            {
              for (int index3 = 0; index3 <= SelectedList[index1][index2].Entity.Vertice.Count - 1; ++index3)
              {
                if (SelectedProps.ClickPointOfEntity.PointOfEntity == SelectedList[index1][index2].Entity.Vertice[index3])
                  SelectedProps.ClickPointOfEntity.VerticeIndex = index3;
              }
            }
            if (SelectedList[index1][index2].Entity.GetType() == typeof (eBSpline))
            {
              for (int index4 = 0; index4 <= ((eCurveEntities) SelectedList[index1][index2].Entity).ControlPoints.Count - 1; ++index4)
              {
                if (SelectedProps.ClickPointOfEntity.PointOfEntity == ((eCurveEntities) SelectedList[index1][index2].Entity).ControlPoints[index4])
                  SelectedProps.ClickPointOfEntity.ControlIndex = index4;
              }
            }
            if (SelectedList[index1][index2].Entity.GetType() == typeof (eBezeir))
            {
              for (int index5 = 0; index5 <= ((eCurveEntities) SelectedList[index1][index2].Entity).ControlPoints.Count - 1; ++index5)
              {
                if (SelectedProps.ClickPointOfEntity.PointOfEntity == ((eCurveEntities) SelectedList[index1][index2].Entity).ControlPoints[index5])
                  SelectedProps.ClickPointOfEntity.ControlIndex = index5;
              }
            }
          }
          if (SelectedList[index1][index2].Entity.GetType() == typeof (ePoint))
          {
            ePoint ePoint = new ePoint(SelectedList[index1][index2].Entity);
            SelectedProps.AlingPoints.MovePoints.Add(new Pnt3D(ePoint.StartPoint));
            Entities.Add((eEntities) ePoint);
          }
          if (SelectedList[index1][index2].Entity.GetType() == typeof (eLine))
          {
            eLine eLine = new eLine(SelectedList[index1][index2].Entity);
            for (int index6 = 0; index6 <= SelectedList[index1][index2].Entity.Vertice.Count - 1; ++index6)
              SelectedProps.AlingPoints.TipPoints.Add(new Pnt3D(SelectedList[index1][index2].Entity.Vertice[index6]));
            SelectedProps.AlingPoints.MovePoints.Add(new Pnt3D(this.MiddlePointOfLine(eLine.StartPoint, eLine.EndPoint)));
            Entities.Add((eEntities) eLine);
          }
          if (SelectedList[index1][index2].Entity.GetType() == typeof (ePolyline))
          {
            ePolyline ePolyline = new ePolyline(SelectedList[index1][index2].Entity);
            for (int index7 = 0; index7 <= SelectedList[index1][index2].Entity.Vertice.Count - 1; ++index7)
            {
              SelectedProps.AlingPoints.TipPoints.Add(new Pnt3D(SelectedList[index1][index2].Entity.Vertice[index7]));
              if (index7 >= 1)
                SelectedProps.AlingPoints.MovePoints.Add(new Pnt3D(this.MiddlePointOfLine(ePolyline.Vertice[index7 - 1], ePolyline.Vertice[index7])));
            }
            Entities.Add((eEntities) ePolyline);
          }
          if (SelectedList[index1][index2].Entity.GetType() == typeof (ePolylineGroup))
          {
            ePolylineGroup ePolylineGroup = new ePolylineGroup(SelectedList[index1][index2].Entity);
            List<List<Pnt3D>> Points = new List<List<Pnt3D>>();
            for (int index8 = 0; index8 <= ePolylineGroup.GroupVertices.Count - 1; ++index8)
            {
              List<Pnt3D> CopiedPnt = new List<Pnt3D>();
              Pnt3D.Copy(ePolylineGroup.GroupVertices[index8], ref CopiedPnt);
              Points.Add(CopiedPnt);
            }
            Pnt3D MinPoint = new Pnt3D();
            Pnt3D MidPoint = new Pnt3D();
            Pnt3D MaxPoint = new Pnt3D();
            this.BoxSizeCalculate(Points, ref MinPoint, ref MidPoint, ref MaxPoint);
            SelectedProps.AlingPoints.MovePoints.Add(MidPoint);
            Entities.Add((eEntities) ePolylineGroup);
          }
          if (SelectedList[index1][index2].Entity.GetType() == typeof (eCircle))
          {
            eCircle eCircle = new eCircle(SelectedList[index1][index2].Entity);
            SelectedProps.AlingPoints.MovePoints.Add(new Pnt3D(eCircle.CenterPoint));
            if (WorkPlane.isPlaneXY(eCircle.Plane))
              SelectedProps.AlingPoints.TipPoints.Add(new Pnt3D(eCircle.CenterPoint.X + eCircle.Radius, eCircle.CenterPoint.Y, eCircle.CenterPoint.Z));
            if (WorkPlane.isPlaneXZ(eCircle.Plane))
              SelectedProps.AlingPoints.TipPoints.Add(new Pnt3D(eCircle.CenterPoint.X + eCircle.Radius, eCircle.CenterPoint.Y, eCircle.CenterPoint.Z));
            if (WorkPlane.isPlaneYZ(eCircle.Plane))
              SelectedProps.AlingPoints.TipPoints.Add(new Pnt3D(eCircle.CenterPoint.X, eCircle.CenterPoint.Y + eCircle.Radius, eCircle.CenterPoint.Z));
            Entities.Add((eEntities) eCircle);
          }
          if (SelectedList[index1][index2].Entity.GetType() == typeof (eArc))
