  public void SelectionSplitByGroupIndex(
    List<Selection> SelectedList,
    ref List<List<Selection>> SelectionSplitedGroups)
  {
    try
    {
      for (int index1 = 0; index1 <= SelectedList.Count - 1; ++index1)
      {
        int index2 = SelectedList[index1].Index;
        eEntities eEntities = new eEntities();
        eEntities baseEnt = eEntities.CopyEntity(SelectedList[index1].Entity);
        bool flag = false;
        for (int index3 = 0; index3 <= SelectionSplitedGroups.Count - 1; ++index3)
        {
          for (int index4 = 0; index4 <= SelectionSplitedGroups[index3].Count - 1; ++index4)
          {
            if (baseEnt.GroupIndex > 0 & baseEnt.GroupIndex == SelectionSplitedGroups[index3][index4].GroupIndex)
            {
              SelectionSplitedGroups[index3].Add(new Selection()
              {
                Entity = eEntities.CopyEntity(baseEnt),
                Index = index2,
                GroupIndex = baseEnt.GroupIndex
              });
              flag = true;
              goto label_11;
            }
          }
        }
label_11:
        if (!flag)
          SelectionSplitedGroups.Add(new List<Selection>()
          {
            new Selection()
            {
              Entity = eEntities.CopyEntity(baseEnt),
              Index = index2,
              GroupIndex = baseEnt.GroupIndex
            }
          });
      }
    }
    catch (Exception ex)
    {
      string str = "SelectedList: " + SelectedList.Count.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

