  public void SelectEntitiesAllByVisibleLayer(
    List<eEntities> RefEntities,
    List<LayerBase> Layers,
    ref List<Selection> SelectedList)
  {
    for (int index1 = 0; index1 <= RefEntities.Count - 1; ++index1)
    {
      bool bVisible = RefEntities[index1].bVisible;
      int layerIndex = RefEntities[index1].LayerIndex;
      if (layerIndex >= 0 & layerIndex <= Layers.Count - 1)
        bVisible &= Layers[layerIndex].Enable;
      if (RefEntities[index1].bSelectable & bVisible)
      {
        Selection selection = new Selection(index1);
        eEntities.CopyEntity(RefEntities[index1], ref selection.Entity);
        if (RefEntities[index1].GetType() == typeof (eBSpline) | RefEntities[index1].GetType() == typeof (eBezeir))
        {
          Pnt3D.Copy(((eCurveEntities) RefEntities[index1]).ControlPoints, ref selection.ControlPoints);
          for (int index2 = 0; index2 <= ((eCurveEntities) RefEntities[index1]).ControlPoints.Count - 1; ++index2)
            selection.ControlPointsIndex.Add(index2);
        }
        else
        {
          Pnt3D.Copy(selection.Entity.Vertice, ref selection.Vertices);
          for (int index3 = 0; index3 <= RefEntities[index1].Vertice.Count - 1; ++index3)
            selection.VerticeIndex.Add(index3);
        }
        SelectedList.Add(selection);
      }
    }
  }

  public int DevidePointList(
    List<Pnt6D> refPoints,
    double DevideLength,
    double StartLength,
    double EndLength,
    bool DevideMiddlePoints,
    DevideTipType DevidePoint,
    ref List<Pnt6D> calcPoints)
  {
    try
    {
      List<Pnt6D> calcStartPoints = new List<Pnt6D>();
      List<Pnt6D> calcMiddlePoints = new List<Pnt6D>();
      List<Pnt6D> calcEndPoints = new List<Pnt6D>();
      int num = this.DevidePointList(refPoints, DevideLength, StartLength, EndLength, DevideMiddlePoints, DevidePoint, ref calcStartPoints, ref calcMiddlePoints, ref calcEndPoints);
      calcPoints.Clear();
      calcPoints.AddRange((IEnumerable<Pnt6D>) calcStartPoints);
      calcPoints.AddRange((IEnumerable<Pnt6D>) calcMiddlePoints);
      calcPoints.AddRange((IEnumerable<Pnt6D>) calcEndPoints);
      this.CheckDuplicatedPointsWithPrevious(ref calcPoints);
      return num;
    }
    catch (Exception ex)
    {
      string str = $"DevideLength: {DevideLength.ToString()} - StartLength: {StartLength.ToString()} - EndLength: {EndLength.ToString()} - DevidePoint: {DevidePoint.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return -1;
    }
  }

  public int DevidePointList(
    List<Pnt6D> refPoints,
    double DevideLength,
    double StartLength,
    double EndLength,
    bool DevideMiddlePoints,
    DevideTipType DevidePoint,
    ref List<Pnt6D> calcStartPoints,
    ref List<Pnt6D> calcMiddlePoints,
    ref List<Pnt6D> calcEndPoints)
  {
    try
    {
      double num1 = 0.0;
      double num2 = 0.0;
      bool flag1 = false;
      bool flag2 = false;
      calcStartPoints.Clear();
      calcMiddlePoints.Clear();
      calcEndPoints.Clear();
      double num3 = this.Length3D(refPoints);
      double num4 = num3;
      if (refPoints.Count <= 1)
        return 0;
      if (num3 < StartLength + EndLength)
      {
        Pnt6D.Copy(refPoints, ref calcMiddlePoints);
        return 1;
      }
      calcStartPoints.Add(new Pnt6D(refPoints[0]));
      for (int index = 1; index <= refPoints.Count - 1; ++index)
      {
        double num5 = this.Length3D(refPoints[index - 1], refPoints[index]);
        num1 += num5;
        double num6 = num3 - num1;
        if (num2 < StartLength & num1 > StartLength)
        {
          double Angle = this.PointAngle(refPoints[index], refPoints[index - 1]);
          double calcAngle = 0.0;
          Pnt3D EndPnt = new Pnt3D();
          this.LineWithLengthAndAngle(new Pnt3D(refPoints[index - 1]), StartLength - num2, Angle, new WorkPlane(), ref EndPnt);
          Pnt6D CurrentPoint = new Pnt6D(EndPnt);
          this.GetAngleOfPointFromPreAndNextPoint(refPoints[index - 1], refPoints[index], ref CurrentPoint, ref calcAngle);
          calcStartPoints.Add(new Pnt6D(EndPnt.X, EndPnt.Y, EndPnt.Z, 0.0, 0.0, calcAngle));
          calcMiddlePoints.Add(new Pnt6D(EndPnt.X, EndPnt.Y, EndPnt.Z, 0.0, 0.0, calcAngle));
          flag1 = true;
        }
        else if (!flag1)
          calcStartPoints.Add(new Pnt6D(refPoints[index]));
        if (num6 < EndLength & num4 > EndLength)
        {
          double Angle = this.PointAngle(refPoints[index - 1], refPoints[index]);
          double calcAngle = 0.0;
          Pnt3D EndPnt = new Pnt3D();
          this.LineWithLengthAndAngle(new Pnt3D(refPoints[index]), EndLength - num6, Angle, new WorkPlane(), ref EndPnt);
          Pnt6D CurrentPoint = new Pnt6D(EndPnt);
          this.GetAngleOfPointFromPreAndNextPoint(refPoints[index - 1], refPoints[index], ref CurrentPoint, ref calcAngle);
          calcEndPoints.Add(new Pnt6D(EndPnt.X, EndPnt.Y, EndPnt.Z, 0.0, 0.0, calcAngle));
          if (!flag2)
            calcMiddlePoints.Add(new Pnt6D(EndPnt.X, EndPnt.Y, EndPnt.Z, 0.0, 0.0, calcAngle));
          flag2 = true;
        }
        else if (flag1 & !flag2)
          calcMiddlePoints.Add(new Pnt6D(refPoints[index]));
        if (calcEndPoints.Count > 0)
          calcEndPoints.Add(new Pnt6D(refPoints[index]));
        num2 = num1;
        num4 = num6;
      }
      this.DevidePointsByLength(ref calcStartPoints, DevideLength);
      this.DevidePointsByLength(ref calcEndPoints, DevideLength);
      if (DevideMiddlePoints)
        this.DevidePointsByLength(ref calcMiddlePoints, DevideLength);
      return 2;
    }
    catch (Exception ex)
    {
      string str = $"DevideLength: {DevideLength.ToString()} - StartLength: {StartLength.ToString()} - EndLength: {EndLength.ToString()} - DevidePoint: {DevidePoint.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return -1;
    }
  }

  public int GetAngleOfPointFromPreAndNextPoint(
    Pnt6D PrePoint,
    Pnt6D NextPoint,
    ref Pnt6D CurrentPoint,
    ref double calcAngle)
  {
    try
    {
      double num1 = this.Length3D(PrePoint, NextPoint);
      double num2 = this.Length3D(PrePoint, CurrentPoint);
      double num3 = this.Length3D(NextPoint, CurrentPoint);
      double c = PrePoint.C * (num2 / num1) + NextPoint.C * (num3 / num1);
      CurrentPoint = new Pnt6D(CurrentPoint.X, CurrentPoint.Y, CurrentPoint.Z, CurrentPoint.A, CurrentPoint.B, c);
      calcAngle = c;
      return 1;
    }
    catch (Exception ex)
    {
      string str = "";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return -1;
    }
  }

  public int DevidePointsByLength(ref List<Pnt6D> Points, double DevideLength)
  {
    try
    {
      List<Pnt6D> CopiedPnt = new List<Pnt6D>();
      if (DevideLength <= 0.0)
        return 0;
      Pnt6D.Copy(Points, ref CopiedPnt);
      Points.Clear();
      this.PolylineToPolyline(CopiedPnt, DevideLength, ref Points);
      return 1;
    }
    catch (Exception ex)
    {
      string str = "DevideLength: " + DevideLength.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return -1;
    }
  }

  public void CircleDevide(
    Pnt3D Center,
    double Radius,
    DevideData DevideData,
    WorkPlane Plane,
    ref List<eEntities> DevidedEntities)
  {
    try
    {
      DevidedEntities.Clear();
      if (DevideData.Type == DevideType.NotDevide)
        DevidedEntities.Add((eEntities) new eCircle(Center, Radius, Plane));
      if (DevideData.Type == DevideType.HalfArc)
      {
        eEntities FirstArc = new eEntities();
        eEntities SecondArc = new eEntities();
        this.CircleToArcByHalf((eEntities) new eCircle(Center, Radius, Plane), ref FirstArc, ref SecondArc);
        DevidedEntities.Add(FirstArc);
        DevidedEntities.Add(SecondArc);
      }
      if (DevideData.Type == DevideType.QuadraticArc)
      {
        eEntities FirstArc = new eEntities();
        eEntities SecondArc = new eEntities();
        eEntities ThirdArc = new eEntities();
        eEntities FourthArc = new eEntities();
        this.CircleToArcByQuadratic((eEntities) new eCircle(Center, Radius, Plane), ref FirstArc, ref SecondArc, ref ThirdArc, ref FourthArc);
        DevidedEntities.Add(FirstArc);
        DevidedEntities.Add(SecondArc);
        DevidedEntities.Add(ThirdArc);
        DevidedEntities.Add(FourthArc);
      }
      if (DevideData.Type == DevideType.LineByLength)
      {
        List<Pnt3D> Vertices = new List<Pnt3D>();
        this.CircleToLineer(Center, Radius, DevideData.Length, Plane, ref Vertices);
        eEntities eEntities = (eEntities) new ePolyline(Vertices);
        DevidedEntities.Add(eEntities);
      }
      if (DevideData.Type != DevideType.ArcByLength)
        return;
      List<eArc> CalculatedArcs = new List<eArc>();
      this.ArcToArc(Center, Radius, 0.0, 360.0, DevideData.Length, Plane, ref CalculatedArcs);
      for (int index = 0; index <= CalculatedArcs.Count - 1; ++index)
      {
        eEntities copiedEnt = new eEntities();
        eEntities.CopyEntity((eEntities) CalculatedArcs[index], ref copiedEnt);
        DevidedEntities.Add(copiedEnt);
      }
    }
    catch (Exception ex)
    {
      string str = $"Center: {Center.ToString()} - Radius: {Radius.ToString()} - DevideData: {DevideData.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

