  public void ArcToArc(
    Pnt3D Center,
    double Radius,
    double SA,
    double EA,
    double Length,
    WorkPlane Plane,
    ref List<eArc> CalculatedArcs)
  {
    try
    {
      int int32 = Convert.ToInt32(this.ArcCircumference(Radius, SA, EA) / Length);
      double num = (EA - SA) / (double) int32;
      CalculatedArcs.Clear();
      for (int index = 1; index <= int32; ++index)
      {
        eArc eArc = new eArc(new Pnt3D(Center), Radius, SA + (double) (index - 1) * num, SA + (double) index * num, Plane);
        CalculatedArcs.Add(eArc);
      }
    }
    catch (Exception ex)
    {
      string str = $"Center: {Center.ToString()} - Rad: {Radius.ToString()} - SA: {SA.ToString()} - EA: {EA.ToString()} - Len: {Length.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void LineerToLineer(
    Pnt3D StartPoint,
    Pnt3D EndPoint,
    double Length,
    ref List<Pnt3D> Vertices)
  {
    try
    {
      double num = this.Length3D(StartPoint, EndPoint);
      if (Length <= 0.0)
      {
        Vertices.Add(new Pnt3D(StartPoint));
        Vertices.Add(new Pnt3D(EndPoint));
      }
      else
      {
        int int32 = Convert.ToInt32(num / Length);
        Vertices.Clear();
        if (int32 <= 1)
        {
          Vertices.Add(new Pnt3D(StartPoint));
          Vertices.Add(new Pnt3D(EndPoint));
        }
        else
        {
          double dt = 1.0 / (double) int32;
          this.LineerInterpolation(StartPoint, EndPoint, dt, ref Vertices);
        }
      }
    }
    catch (Exception ex)
    {
      string str = $"SP: {StartPoint.ToString()} - EP: {EndPoint.ToString()} - Len: {Length.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

