  public void ArcToLineer(
    Pnt3D Center,
    double Radius,
    double SA,
    double EA,
    double Length,
    WorkPlane Plane,
    ref List<Pnt3D> Vertices)
  {
    try
    {
      double num1 = 0.0;
      Pnt3D pnt3D1 = new Pnt3D();
      if (buCompare.EQ(SA, EA))
      {
        Vertices.Clear();
      }
      else
      {
        if (EA < SA)
          EA += 360.0;
        double num2 = EA - SA;
        int num3 = (int) (2.0 * Math.PI * Radius * (EA - SA) / 360.0 / Length);
        if (num3 <= 0)
        {
          Vertices.Clear();
        }
        else
        {
          if (num3 > 0)
            num1 = num2 / (double) num3;
          Vertices.Clear();
          for (int index = 0; index <= num3; ++index)
          {
            Pnt3D pnt3D2 = new Pnt3D();
            if (WorkPlane.isPlaneXY(Plane))
            {
              pnt3D2.X = Center.X + Radius * Math.Cos(buConversion.DegreeToRadian(SA + (double) index * num1));
              pnt3D2.Y = Center.Y + Radius * Math.Sin(buConversion.DegreeToRadian(SA + (double) index * num1));
              pnt3D2.Z = Center.Z;
            }
            if (WorkPlane.isPlaneXZ(Plane))
            {
              pnt3D2.X = Center.X + Radius * Math.Cos(buConversion.DegreeToRadian(SA + (double) index * num1));
              pnt3D2.Y = Center.Y;
              pnt3D2.Z = Center.Z + Radius * Math.Sin(buConversion.DegreeToRadian(SA + (double) index * num1));
            }
            if (WorkPlane.isPlaneYZ(Plane))
            {
              pnt3D2.X = Center.X;
              pnt3D2.Y = Center.Y + Radius * Math.Cos(buConversion.DegreeToRadian(SA + (double) index * num1));
              pnt3D2.Z = Center.Z + Radius * Math.Sin(buConversion.DegreeToRadian(SA + (double) index * num1));
            }
            Vertices.Add(pnt3D2);
          }
        }
      }
    }
    catch (Exception ex)
    {
      string str = $"Center:{Center.ToString()}R: {Radius.ToString()} - SA: {SA.ToString()} - EA: {EA.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

