  public void EntitiesToLineer(
    List<eEntities> RefEntities,
    double Length,
    ref List<Pnt3D> CalcPoints)
  {
    try
    {
      CalcPoints.Clear();
      for (int index = 0; index <= RefEntities.Count - 1; ++index)
      {
        List<Pnt3D> CalcPoints1 = new List<Pnt3D>();
        this.EntitiesToLineer(RefEntities[index], Length, ref CalcPoints1);
        CalcPoints.AddRange((IEnumerable<Pnt3D>) CalcPoints1);
      }
      this.CheckDuplicatedPointsWithPrevious(ref CalcPoints);
    }
    catch (Exception ex)
    {
      string str = "Len: " + Length.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
