  public void EntitiesToLineer(
    List<eEntities> RefEntities,
    double Length,
    ref List<List<Pnt3D>> CalcPoints)
  {
    try
    {
      List<Pnt3D> CopiedPnt = new List<Pnt3D>();
      for (int index = 0; index <= RefEntities.Count - 1; ++index)
      {
        List<Pnt3D> CalcPoints1 = new List<Pnt3D>();
        this.EntitiesToLineer(RefEntities[index], Length, ref CalcPoints1);
        if (RefEntities[index].camDirections == camPathDirectionType.Reverse)
          CalcPoints1.Reverse();
        if (index == 0)
        {
          List<Pnt3D> CalcPoints2 = new List<Pnt3D>();
          if (RefEntities.Count > 1)
            this.EntitiesToLineer(RefEntities[index + 1], Length, ref CalcPoints2);
          if (CalcPoints1.Count > 1 & CalcPoints2.Count > 1)
          {
            bool flag = false;
            if (buCompare.EQ(CalcPoints1[CalcPoints1.Count - 1], CalcPoints2[0]) | buCompare.EQ(CalcPoints1[CalcPoints1.Count - 1], CalcPoints2[CalcPoints2.Count - 1]))
            {
              Pnt3D.Add(CalcPoints1, ref CopiedPnt);
              flag = true;
            }
            if (buCompare.EQ(CalcPoints1[0], CalcPoints2[0]) | buCompare.EQ(CalcPoints1[0], CalcPoints2[CalcPoints2.Count - 1]))
            {
              CalcPoints1.Reverse();
              Pnt3D.Add(CalcPoints1, ref CopiedPnt);
              flag = true;
            }
            if (!flag)
              Pnt3D.Add(CalcPoints1, ref CopiedPnt);
          }
        }
        if (index > 0)
        {
          if (CopiedPnt.Count > 0 & CalcPoints1.Count > 0)
          {
            bool flag = false;
            if (buCompare.EQ(CalcPoints1[CalcPoints1.Count - 1], CopiedPnt[CopiedPnt.Count - 1]))
            {
              Pnt3D.Add(CalcPoints1, ref CopiedPnt);
              flag = true;
            }
            if (buCompare.EQ(CalcPoints1[0], CopiedPnt[CopiedPnt.Count - 1]))
            {
              CalcPoints1.Reverse();
              Pnt3D.Add(CalcPoints1, ref CopiedPnt);
              flag = true;
            }
            if (!flag)
            {
              CalcPoints.Add(CopiedPnt);
              CopiedPnt = new List<Pnt3D>();
            }
          }
          if (CopiedPnt.Count == 0 & CalcPoints1.Count > 0)
            Pnt3D.Add(CalcPoints1, ref CopiedPnt);
        }
      }
    }
    catch (Exception ex)
    {
      string str = "Len: " + Length.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void EntitiesToLineer(eEntities RefEntity, double Length, ref List<Pnt3D> CalcPoints)
  {
    try
    {
      List<Pnt3D> pnt3DList = new List<Pnt3D>();
      if (RefEntity.GetType() == typeof (eLine))
        this.LineerToLineer(new Pnt3D(RefEntity.Vertice[0]), new Pnt3D(RefEntity.Vertice[1]), Length, ref CalcPoints);
      if (RefEntity.GetType() == typeof (ePolyline))
        this.PolylineToPolyline(RefEntity.Vertice, Length, ref CalcPoints);
      if (RefEntity.GetType() == typeof (eArc))
        this.ArcToLineer(new Pnt3D(((ePlaneEntities) RefEntity).CenterPoint), ((eCircle) RefEntity).Radius, ((eArc) RefEntity).StartAngle, ((eArc) RefEntity).EndAngle, Length, ((ePlaneEntities) RefEntity).Plane, ref CalcPoints);
      if (RefEntity.GetType() == typeof (eCircle))
        this.CircleToLineer(new Pnt3D(((ePlaneEntities) RefEntity).CenterPoint), ((eCircle) RefEntity).Radius, Length, ((ePlaneEntities) RefEntity).Plane, ref CalcPoints);
      if (RefEntity.GetType() == typeof (eEllipse))
        this.EllipseToLineer(new Pnt3D(((ePlaneEntities) RefEntity).CenterPoint), ((eEllipse) RefEntity).MajorRadius, ((eEllipse) RefEntity).MinorRadius, ((eEllipse) RefEntity).Angle, Length, ((ePlaneEntities) RefEntity).Plane, ref CalcPoints);
      if (!(RefEntity.GetType() == typeof (eEllipseArc)))
        return;
      this.ArcEllipseToLineer(new Pnt3D(((ePlaneEntities) RefEntity).CenterPoint), ((eEllipse) RefEntity).MajorRadius, ((eEllipse) RefEntity).MinorRadius, ((eEllipseArc) RefEntity).StartAngle, ((eEllipseArc) RefEntity).EndAngle, ((eEllipse) RefEntity).Angle, Length, ((ePlaneEntities) RefEntity).Plane, ref CalcPoints);
    }
