  public void SortPointByDistance(
    Pnt3D RefPoint,
    SortDirectionType Direction,
    ref List<Pnt3D> SortingPoints)
  {
    try
    {
      for (int index1 = 0; index1 < SortingPoints.Count - 1; ++index1)
      {
        for (int index2 = 1; index2 < SortingPoints.Count - index1; ++index2)
        {
          if (this.Length3D(RefPoint, SortingPoints[index2]) < this.Length3D(RefPoint, SortingPoints[index2 - 1]))
          {
            Pnt3D Pnt = new Pnt3D(SortingPoints[index2 - 1]);
            SortingPoints[index2 - 1] = new Pnt3D(SortingPoints[index2]);
            SortingPoints[index2] = new Pnt3D(Pnt);
          }
        }
      }
      if (Direction != SortDirectionType.Bigger)
        return;
      SortingPoints.Reverse();
    }
    catch (Exception ex)
    {
      string str = $"RefPoint: {RefPoint.ToString()} - Direction: {Direction.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void SortQuickDeltaX(Pnt3D RefPoint, int Lower, int Upper, ref List<Pnt3D> PntLst)
  {
    try
    {
      Pnt3D pnt3D = new Pnt3D();
      int num1 = Lower;
      int num2 = Upper;
      if (PntLst.Count <= 0)
        return;
      double num3 = this.DeltaX(RefPoint, PntLst[Convert.ToInt32(Math.Floor((double) (Lower + Upper) / 2.0))]);
      do
      {
        while (this.DeltaX(RefPoint, PntLst[num1]) < num3)
          ++num1;
        while (num3 < this.DeltaX(RefPoint, PntLst[num2]))
          --num2;
        if (num1 <= num2)
        {
          Pnt3D Pnt = new Pnt3D(PntLst[num1]);
          PntLst[num1++] = new Pnt3D(PntLst[num2]);
          PntLst[num2--] = new Pnt3D(Pnt);
        }
      }
      while (num1 < num2);
      if (num2 > Lower)
        this.SortQuickDeltaX(RefPoint, Lower, num2, ref PntLst);
      if (num1 >= Upper)
        return;
      this.SortQuickDeltaX(RefPoint, num1, Upper, ref PntLst);
    }
    catch (Exception ex)
    {
      string str = $"RefPoint: {RefPoint.ToString()} - Lower: {Lower.ToString()} - Upper: {Upper.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

