  public void CamStepCalculation(camStep Steps, ref List<double> CalcValues)
  {
    try
    {
      CalcValues.Clear();
      if (!Steps.Enable)
        return;
      if (Steps.StepType == CamStepType.StartByCountAndStep & Steps.Step != 0.0 & Steps.Count > 0)
      {
        for (int index = 1; index <= Steps.Count; ++index)
        {
          double num = Steps.StartValue + Steps.Step * (double) index;
          CalcValues.Add(Math.Round(num, 5));
        }
      }
      if (Steps.StepType == CamStepType.StartToEndByStep & Steps.Step != 0.0)
      {
        double num1 = Steps.EndValue - Steps.StartValue;
        double num2 = 1.0;
        if (Steps.EndValue < Steps.StartValue)
          num2 = -1.0;
        int int32 = Convert.ToInt32(buNumeric.RoundToLower(Math.Abs(num1) / Math.Abs(Steps.Step)));
        double step = Steps.Step;
        if (step != 0.0)
        {
          double num3 = 0.0;
          for (int index = 1; index <= int32; ++index)
          {
            double num4 = Steps.StartValue + num2 * Math.Abs(step) * (double) index;
            CalcValues.Add(Math.Round(num4, 5));
            num3 = num4;
          }
          if (CalcValues.Count > 0 && !buCompare.EQ(num3, Steps.EndValue, 0.001))
            CalcValues.Add(Steps.EndValue);
        }
      }
      if (Steps.StepType == CamStepType.StartToEndByCount & Steps.Count > 0)
      {
        double num5 = Steps.EndValue - Steps.StartValue;
        double num6 = 1.0;
        if (Steps.EndValue < Steps.StartValue)
          num6 = -1.0;
        double num7 = Convert.ToDouble(Math.Abs(num5) / (double) Steps.Count);
        if (num7 != 0.0)
        {
          for (int index = 1; index <= Steps.Count; ++index)
          {
            double num8 = Steps.StartValue + num6 * Math.Abs(num7) * (double) index;
            CalcValues.Add(num8);
          }
        }
      }
      if (Steps.StepType == CamStepType.StartToDistanceByCount & Steps.Count > 0)
      {
        double num9 = Steps.StartValue + Steps.Distance;
        double num10 = num9 - Steps.StartValue;
        double num11 = 1.0;
        if (num9 < Steps.StartValue)
          num11 = -1.0;
        double num12 = Convert.ToDouble(Math.Abs(num10) / (double) Steps.Count);
        if (num12 != 0.0)
        {
          for (int index = 1; index <= Steps.Count; ++index)
          {
            double num13 = Steps.StartValue + num11 * Math.Abs(num12) * (double) index;
            CalcValues.Add(num13);
          }
        }
      }
      if (Steps.StepType == CamStepType.StartToDistanceByStep & Steps.Step != 0.0)
      {
        double num14 = Steps.StartValue + Steps.Distance;
        double num15 = num14 - Steps.StartValue;
        double num16 = 1.0;
        if (num14 < Steps.StartValue)
          num16 = -1.0;
        int int32 = Convert.ToInt32(buNumeric.RoundToUpper(Math.Abs(num15) / Steps.Step));
        double num17 = Math.Abs(num15) / (double) int32;
        if (num17 != 0.0)
        {
          for (int index = 1; index <= int32; ++index)
          {
            double num18 = Steps.StartValue + num16 * Math.Abs(num17) * (double) index;
            CalcValues.Add(Math.Round(num18, 5));
          }
        }
      }
      if (!(Steps.StepType == CamStepType.StartToDistanceByTrueStep & Steps.Step != 0.0))
        return;
      double num19 = Steps.StartValue + Steps.Distance;
      double num20 = num19 - Steps.StartValue;
      double num21 = 1.0;
      if (num19 < Steps.StartValue)
        num21 = -1.0;
      int int32_1 = Convert.ToInt32(buNumeric.RoundToLower(Math.Abs(num20) / Steps.Step));
      double step1 = Steps.Step;
      if (step1 == 0.0)
        return;
      double num22 = 0.0;
      for (int index = 1; index <= int32_1; ++index)
      {
        double num23 = Steps.StartValue + num21 * Math.Abs(step1) * (double) index;
        CalcValues.Add(Math.Round(num23, 5));
        num22 = num23;
      }
      if (buCompare.EQ(num22, num19, 0.01))
        return;
      CalcValues.Add(Math.Round(num19, 5));
    }
    catch (Exception ex)
    {
      string str = "Steps : " + Steps.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
