  public void EllipseLineIntersection(
    double MajorR,
    double MinorR,
    Pnt3D EllipseCenter,
    Pnt3D LineStart,
    Pnt3D LineEnd,
    ref double xi1,
    ref double xi2,
    ref double yi1,
    ref double yi2,
    ref bool IsIntersect)
  {
    double num1 = 0.0;
    double num2;
    double num3;
    double num4;
    if (LineStart.X != LineEnd.X)
    {
      num1 = (LineEnd.Y - LineStart.Y) / (LineEnd.X - LineStart.X);
      double num5 = LineStart.Y - num1 * LineStart.X;
      num2 = MinorR * MinorR + MajorR * MajorR * num1 * num1;
      num3 = 2.0 * MajorR * MajorR * num5 * num1 - 2.0 * MajorR * MajorR * EllipseCenter.Y * num1 - 2.0 * EllipseCenter.X * MinorR * MinorR;
      num4 = MinorR * MinorR * EllipseCenter.X * EllipseCenter.X + MajorR * MajorR * num5 * num5 - 2.0 * MajorR * MajorR * EllipseCenter.Y * num5 + MajorR * MajorR * EllipseCenter.Y * EllipseCenter.Y - MajorR * MajorR * MinorR * MinorR;
    }
    else
    {
      num2 = MajorR * MajorR;
      num3 = -2.0 * EllipseCenter.Y * MajorR * MajorR;
      num4 = -MajorR * MajorR * MinorR * MinorR + MinorR * MinorR * (LineStart.X - EllipseCenter.X) * (LineStart.X - EllipseCenter.X);
    }
    double d = num3 * num3 - 4.0 * num2 * num4;
    if (d > 0.0)
    {
      IsIntersect = true;
      if (LineStart.X != LineEnd.X)
      {
        xi1 = (-num3 + Math.Sqrt(d)) / (2.0 * num2);
        xi2 = (-num3 - Math.Sqrt(d)) / (2.0 * num2);
        yi1 = LineStart.Y + num1 * (xi1 - LineStart.X);
        yi2 = LineStart.Y + num1 * (xi2 - LineStart.X);
      }
      else
      {
        yi1 = (-num3 + Math.Sqrt(d)) / (2.0 * num2);
        yi2 = (-num3 - Math.Sqrt(d)) / (2.0 * num2);
        xi1 = LineStart.X;
        xi2 = LineStart.X;
      }
    }
    else
      IsIntersect = false;
  }

