  public void ProfileZHeightFromDistance(
    ZHeightAdjustmentByDistance ZHeightData,
    Pnt3D pntLevel,
    List<Pnt3D> ProfilePoints,
    ref List<Pnt3D> SortedOriginalPoints,
    ref List<Pnt3D> CalculatedPoints)
  {
    string callMethod = nameof (ProfileZHeightFromDistance);
    try
    {
      List<Pnt3D> pts = new List<Pnt3D>();
      Pnt3D MinPoint = new Pnt3D();
      Pnt3D MaxPoint = new Pnt3D();
      Pnt3D.Copy(ProfilePoints, ref pts);
      this.BoxSizeCalculate(ProfilePoints, ref MinPoint, ref MaxPoint);
      CalculatedPoints.Clear();
      CalculatedPoints = new List<Pnt3D>();
      if (ZHeightData.ZType == ZHeightProfileType.Linear)
      {
        if (ZHeightData.Direction == VectorXYType.XVector)
        {
          this.SortDeltaX(new Pnt3D(0.0, MinPoint.X - 10.0, 0.0), SortDirectionType.Lower, ref pts);
          SortedOriginalPoints.Clear();
          SortedOriginalPoints = new List<Pnt3D>();
          Pnt3D.Copy(pts, ref SortedOriginalPoints);
          if (pts.Count > 0)
          {
            double num1 = pts[0].X;
            double num2 = pts[pts.Count - 1].X;
            if (ZHeightData.LevelMax != ZHeightData.LevelMin && ZHeightData.LevelMax > ZHeightData.LevelMin)
            {
              num1 = ZHeightData.LevelMin;
              num2 = ZHeightData.LevelMax;
            }
            double num3 = num2 - pntLevel.X;
            double num4 = pntLevel.X - num1;
            for (int index = 0; index <= pts.Count - 1; ++index)
            {
              Pnt3D pnt3D = new Pnt3D(pts[index]);
              double num5 = Math.Abs(this.DeltaX(pntLevel, pts[index]));
              if (pts[index].X >= pntLevel.X)
              {
                if (num3 > 0.0 & pts[index].X <= num2)
                  pnt3D.Z += (num3 - num5) / num3 * ZHeightData.ZHeightValue;
              }
              else if (num4 > 0.0 & pts[index].X >= num1)
                pnt3D.Z += (num4 - num5) / num4 * ZHeightData.ZHeightValue;
              CalculatedPoints.Add(new Pnt3D(pnt3D.X, pnt3D.Y, pnt3D.Z));
            }
          }
        }
        if (ZHeightData.Direction == VectorXYType.YVector)
