  public int HeightFromFreeDrawing(
    VectorType Axis,
    Pnt3D MinPoint,
    Pnt3D MaxPoint,
    List<Pnt3D> ProfilePoints,
    double Resolution,
    double Offset,
    List<Pnt3D> RefPoint,
    ref List<Pnt3D> CalcPoints,
    ref List<double> AnglesVersusProfile)
  {
    Pnt3D pnt3D1 = new Pnt3D();
    List<Pnt3D> pnt3DList1 = new List<Pnt3D>();
    List<Pnt3D> pnt3DList2 = new List<Pnt3D>();
    if (Resolution > 0.0)
      this.PolylineToPolyline(ProfilePoints, Resolution, ref pnt3DList2);
    else
      Pnt3D.Copy(ProfilePoints, ref pnt3DList2);
    if (RefPoint.Count > 1)
    {
      if (Resolution > 0.0)
        this.PolylineToPolyline(RefPoint, Resolution, ref pnt3DList1);
      else
        Pnt3D.Copy(RefPoint, ref pnt3DList1);
    }
    if (RefPoint.Count == 1)
      Pnt3D.Copy(RefPoint, ref pnt3DList1);
    CalcPoints = new List<Pnt3D>();
    if (Axis == VectorType.YVector)
    {
      for (int index1 = 0; index1 <= pnt3DList1.Count - 1; ++index1)
      {
        Pnt3D pnt3D2 = new Pnt3D(pnt3DList1[index1]);
        for (int index2 = 0; index2 <= pnt3DList2.Count - 2; ++index2)
        {
          Pnt3D PntCenter = new Pnt3D(pnt3DList2[index2]);
          Pnt3D PntEnd = new Pnt3D(pnt3DList2[index2 + 1]);
          if ((PntCenter.X <= pnt3D2.X | buCompare.EQ(pnt3D2.X, PntCenter.X, buSystem.resolutionCompare)) & (pnt3D2.X <= PntEnd.X | buCompare.EQ(pnt3D2.X, PntEnd.X, buSystem.resolutionCompare)))
          {
            index2 = pnt3DList2.Count;
            double X3 = 0.0;
            buNumeric.EquationLineer(PntCenter.Z, PntEnd.Z, PntCenter.X, PntEnd.X, pnt3D2.X, ref X3);
            pnt3D2.Z = X3;
            double num = this.PointAngle(PntEnd, PntCenter, new WorkPlane(planeType.XZ, 1));
            AnglesVersusProfile.Add(num);
            CalcPoints.Add(pnt3D2);
          }
        }
      }
    }
    return 1;
  }

  public Pnt3D SnapFunction(Pnt3D Base, Vec3D SnapDistances, WorkPlane Plane)
  {
    try
    {
      Pnt3D pnt3D = new Pnt3D();
      if (WorkPlane.isPlaneXY(Plane))
      {
        pnt3D.X = Math.Round(Base.X / SnapDistances.X) * SnapDistances.X;
        pnt3D.Y = Math.Round(Base.Y / SnapDistances.Y) * SnapDistances.Y;
        pnt3D.Z = 0.0;
      }
      if (WorkPlane.isPlaneXZ(Plane))
      {
        pnt3D.X = Math.Round(Base.X / SnapDistances.X) * SnapDistances.X;
        pnt3D.Y = 0.0;
        pnt3D.Z = Math.Round(Base.Z / SnapDistances.Z) * SnapDistances.Z;
      }
      if (WorkPlane.isPlaneYZ(Plane))
      {
        pnt3D.X = 0.0;
        pnt3D.Y = Math.Round(Base.Y / SnapDistances.Y) * SnapDistances.Y;
        pnt3D.Z = Math.Round(Base.Z / SnapDistances.Z) * SnapDistances.Z;
      }
      return pnt3D;
    }
    catch (Exception ex)
    {
      string str = $"Base: {Base.ToString()} - SnapDistances: {SnapDistances.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return new Pnt3D();
    }
  }

  public void OrthoFunction(
    Pnt3D RefPnt,
    Pnt3D CenterPnt,
    WorkPlane Plane,
    ref Pnt3D OrthoPnt,
    ref int OrthoDir)
  {
    try
    {
      Pnt3D pnt3D = new Pnt3D();
      if (WorkPlane.isPlaneXY(Plane))
      {
        pnt3D.X = CenterPnt.X;
        pnt3D.Y = CenterPnt.Y;
        if (RefPnt.X - pnt3D.X != 0.0)
        {
          OrthoPnt.X = RefPnt.X;
          OrthoPnt.Y = RefPnt.Y;
          double num = (RefPnt.Y - pnt3D.Y) / (RefPnt.X - pnt3D.X);
          if (RefPnt.X > pnt3D.X & RefPnt.Y > pnt3D.Y & num > 1.0)
          {
            OrthoPnt.X = pnt3D.X;
            OrthoPnt.Y = RefPnt.Y;
            OrthoDir = 2;
          }
          if (RefPnt.X > pnt3D.X & RefPnt.Y > pnt3D.Y & num < 1.0)
          {
            OrthoPnt.X = RefPnt.X;
            OrthoPnt.Y = pnt3D.Y;
            OrthoDir = 1;
          }
          if (RefPnt.X > pnt3D.X & RefPnt.Y < pnt3D.Y & num < -1.0)
          {
            OrthoPnt.X = pnt3D.X;
            OrthoPnt.Y = RefPnt.Y;
            OrthoDir = 4;
          }
