  public bool IsAngleInsideArcAngles(ref double Angle, double ArcStartAngle, double ArcEndAngle)
  {
    try
    {
      if (buCompare.EQ(Angle, ArcStartAngle) | buCompare.EQ(Angle, ArcEndAngle) || Angle >= ArcStartAngle & Angle <= ArcEndAngle)
        return true;
      if (ArcStartAngle < 0.0 & Angle > 0.0)
      {
        double num = Angle - 360.0;
        if (num >= ArcStartAngle & num <= ArcEndAngle)
        {
          Angle = num;
          return true;
        }
      }
      Angle += 360.0;
      return Angle >= ArcStartAngle & Angle <= ArcEndAngle;
    }
    catch (Exception ex)
    {
      string str = $"Angle: {Angle.ToString()} - ArcStartAngle: {ArcStartAngle.ToString()} - ArcEndAngle: {ArcEndAngle.ToString()}";
