          double double_2 = Vertices[(index + 1) % Vertices.Count].Y - RefPoint.Y;
          double double_0 = Vertices[(index + 1) % Vertices.Count].Z - RefPoint.Z;
          num += Class30.smethod_131(double_0, double_1, double_2, this, double_3);
        }
      }
      return !(Math.Abs(num) < Math.PI | buCompare.EQ(Math.Abs(num), Math.PI));
    }
    catch (Exception ex)
