  public void IsPointLeftOrRightOfOpenContour(
    List<Pnt3D> Vertices,
    Pnt3D RefPoint,
    WorkPlane Plane,
    ref CamOpenContourType2 Direction)
  {
    try
    {
      List<Pnt3D> CopiedPnt = new List<Pnt3D>();
      if (Vertices.Count > 2)
      {
        Pnt3D.Copy(Vertices, ref CopiedPnt);
        CopiedPnt.Add(new Pnt3D(CopiedPnt[0]));
        if (this.PolygonDirection(CopiedPnt, Plane) == ClockDirectionType.CCW)
        {
          Vertices.Reverse();
          CopiedPnt.Reverse();
        }
        if (CopiedPnt.Count > 2)
        {
          bool flag = this.IsPointInsidePolygon(CopiedPnt, RefPoint);
          Direction = CamOpenContourType2.Left;
          if (flag)
            Direction = CamOpenContourType2.Right;
        }
      }
      if (Vertices.Count != 2)
        return;
      if (this.Length3D(RefPoint, Vertices[0]) < this.Length3D(RefPoint, Vertices[1]))
      {
        double num1 = this.PointAngle(Vertices[0], Vertices[1], Plane);
        double num2 = this.PointAngle(RefPoint, Vertices[1], Plane);
        if (Math.Abs(num1 - num2) > 180.0)
        {
          if (num1 < num2)
            num1 += 360.0;
          else
            num2 += 360.0;
        }
        if (num1 > num2)
          Direction = CamOpenContourType2.Left;
        else
          Direction = CamOpenContourType2.Right;
      }
      else
      {
        double num3 = this.PointAngle(Vertices[1], Vertices[0], Plane);
        double num4 = this.PointAngle(RefPoint, Vertices[0], Plane);
        if (Math.Abs(num3 - num4) > 180.0)
        {
          if (num3 < num4)
            num3 += 360.0;
          else
            num4 += 360.0;
        }
        if (num3 > num4)
          Direction = CamOpenContourType2.Right;
        else
          Direction = CamOpenContourType2.Left;
      }
    }
    catch (Exception ex)
    {
      string str = $"Vertices: {Vertices.Count.ToString()} - RefPoint: {RefPoint.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

