  public bool IsPointOverArc(
    Pnt3D Center,
    double Radius,
    double StartAngle,
    double EndAngle,
    Pnt3D RefPoint,
    WorkPlane Plane,
    double Resolution,
    ref Pnt3D CalculatedPoint,
    ref double Distance)
  {
    try
    {
      int ClosestPoint = 0;
      double Degree = this.PointAngle(RefPoint, Center, Plane);
      CalculatedPoint = new Pnt3D();
      if (WorkPlane.isPlaneXY(Plane))
      {
        CalculatedPoint.X = Center.X + Radius * Math.Cos(buConversion.DegreeToRadian(Degree));
        CalculatedPoint.Y = Center.Y + Radius * Math.Sin(buConversion.DegreeToRadian(Degree));
        CalculatedPoint.Z = Center.Z;
      }
      if (WorkPlane.isPlaneXZ(Plane))
      {
        CalculatedPoint.X = Center.X + Radius * Math.Cos(buConversion.DegreeToRadian(Degree));
        CalculatedPoint.Y = Center.Y;
        CalculatedPoint.Z = Center.Z + Radius * Math.Sin(buConversion.DegreeToRadian(Degree));
      }
      if (WorkPlane.isPlaneYZ(Plane))
      {
        CalculatedPoint.X = Center.X;
        CalculatedPoint.Y = Center.Y + Radius * Math.Cos(buConversion.DegreeToRadian(Degree));
        CalculatedPoint.Z = Center.Z + Radius * Math.Sin(buConversion.DegreeToRadian(Degree));
      }
      Distance = this.Length3D(Center, RefPoint, Plane) - Radius;
      bool flag;
      if (!(flag = this.IsPointInsideArc(Center, Radius, StartAngle, EndAngle, RefPoint, Plane, Resolution, ref ClosestPoint)) & (StartAngle > 360.0 | EndAngle > 360.0))
      {
        double num = Degree + 360.0;
        flag = this.IsPointInsideArc(Center, Radius, StartAngle, EndAngle, RefPoint, Plane, Resolution, ref ClosestPoint);
      }
      if (!buCompare.EQ(Distance, 0.0, Resolution))
        flag = false;
      return flag;
    }
    catch (Exception ex)
    {
      string str = $"Center: {Center.ToString()} - Radius: {Radius.ToString()} - StartAngle: {StartAngle.ToString()} - EndAngle: {EndAngle.ToString()} - RefPoint: {RefPoint.ToString()} - Resolution: {Resolution.ToString()}";
