      this.PointToVariables(EndPoint, ref X2, ref Y2, ref Z2);
      if (WorkPlane.isPlaneXY(Plane))
      {
        if (buCompare.EQ(X1, X2, Resolution))
        {
          CalculatedPoint.X = X1;
          CalculatedPoint.Y = RefPoint.Y;
          CalculatedPoint.Z = RefPoint.Z;
          goto label_25;
        }
        if (buCompare.EQ(Y1, Y2, Resolution))
        {
          CalculatedPoint.X = RefPoint.X;
