        if (!buCompare.EQ(X1, X2, Resolution) & !buCompare.EQ(Y1, Y2, Resolution))
        {
          double x = (Y2 - Y1) / (X2 - X1);
          CalculatedPoint.X = -(-1.0 * Math.Pow(x, 2.0) * X2 + Y2 * x - RefPoint.X - RefPoint.Y * x) / (1.0 + Math.Pow(x, 2.0));
          CalculatedPoint.Y = (Y2 - x * X2 + RefPoint.X * x + RefPoint.Y * Math.Pow(x, 2.0)) / (1.0 + Math.Pow(x, 2.0));
