        CalculatedPoint.Z = this.ZFromXYZ(StartPoint, EndPoint, CalculatedPoint);
      }
      if (WorkPlane.isPlaneXZ(Plane))
      {
        if (buCompare.EQ(X1, X2, Resolution))
        {
          CalculatedPoint.X = X1;
          CalculatedPoint.Y = RefPoint.Y;
          CalculatedPoint.Z = RefPoint.Z;
          goto label_25;
        }
        if (buCompare.EQ(Z1, Z2, Resolution))
        {
          CalculatedPoint.X = RefPoint.X;
          CalculatedPoint.Y = RefPoint.Y;
          CalculatedPoint.Z = Z1;
          goto label_25;
        }
        if (!buCompare.EQ(X1, X2, Resolution) & !buCompare.EQ(Z1, Z2, Resolution))
        {
          double x = (Z2 - Z1) / (X2 - X1);
          CalculatedPoint.X = -(-1.0 * Math.Pow(x, 2.0) * X2 + Z2 * x - RefPoint.X - RefPoint.Z * x) / (1.0 + Math.Pow(x, 2.0));
          CalculatedPoint.Z = (Z2 - x * X2 + RefPoint.X * x + RefPoint.Z * Math.Pow(x, 2.0)) / (1.0 + Math.Pow(x, 2.0));
        }
        CalculatedPoint.Y = this.YFromXYZ(StartPoint, EndPoint, CalculatedPoint);
