        {
          CalculatedPoint.X = RefPoint.X;
          CalculatedPoint.Y = Y1;
          CalculatedPoint.Z = RefPoint.Z;
        }
        else if (buCompare.EQ(Z1, Z2, Resolution))
        {
          CalculatedPoint.X = RefPoint.X;
