            CalculatedPoint.Z = (Z2 - x * Y2 + RefPoint.Y * x + RefPoint.Z * Math.Pow(x, 2.0)) / (1.0 + Math.Pow(x, 2.0));
          }
          CalculatedPoint.X = this.XFromXYZ(StartPoint, EndPoint, CalculatedPoint);
