    ref Pnt3D CalculatedPoint,
    ref double Distance,
    ref int VerticeIndex,
    ref int ClosestVerticeIndex)
  {
    try
    {
      bool flag = false;
      Pnt3D CalculatedPoint1 = new Pnt3D();
      double Distance1 = 0.0;
      double num = double.MaxValue;
      ClosestVerticeIndex = 0;
      for (int index = 1; index <= Points.Count - 1; ++index)
      {
        if (this.IsPointOverLine(Points[index - 1], Points[index], RefPoint, Plane, ref CalculatedPoint1, ref Distance1))
        {
          int ClosestPoint = -1;
          if (this.IsPointInsideLine(Points[index - 1], Points[index], RefPoint, Plane, Resolution, ref ClosestPoint) && Distance1 < num)
          {
            ClosestVerticeIndex = ClosestPoint != 0 ? index : index - 1;
            flag = true;
            VerticeIndex = index - 1;
            num = Distance1;
            CalculatedPoint = new Pnt3D(CalculatedPoint1);
          }
        }
      }
      Distance = num;
      return flag;
    }
    catch (Exception ex)
    {
      string str = $"Points: {Points.Count.ToString()} - RefPoint: {RefPoint.ToString()} - Plane: {Plane.ToString()} - Resolution: {Resolution.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return false;
    }
  }

  public void CreatMachine(KinematicBase Kinematic, ref List<eEntities> MachineEntities)
  {
    try
    {
      MachineEntities.Clear();
      if (Kinematic.Type != KinemeticType.CartezianXYZ_WristAC_5Axis)
        return;
      Vec3D vec3D = new Vec3D(Kinematic.RotateCenterOffsetOfA.X - Kinematic.RotateCenterOffsetOfC.X, Kinematic.RotateCenterOffsetOfA.Y - Kinematic.RotateCenterOffsetOfC.Y, Kinematic.RotateCenterOffsetOfA.Z - Kinematic.RotateCenterOffsetOfC.Z);
      Pnt3D StartPoint = new Pnt3D(0.0, 0.0, 0.0);
      Pnt3D EndPoint = new Pnt3D(vec3D.X, vec3D.Y, 0.0);
      if (vec3D.Y != 0.0)
      {
        eLine eLine = new eLine(StartPoint, EndPoint);
        MachineEntities.Add((eEntities) eLine);
      }
      eLine eLine1 = new eLine(new Pnt3D(vec3D.X, vec3D.Y, 0.0), new Pnt3D(vec3D.X, vec3D.Y, -Kinematic.RotateCenterOffsetOfC.Z));
      MachineEntities.Add((eEntities) eLine1);
      eLine eLine2 = new eLine(new Pnt3D(vec3D.X, vec3D.Y, -Kinematic.RotateCenterOffsetOfC.Z), new Pnt3D(vec3D.X, vec3D.Y - Kinematic.RotateCenterOffsetOfA.Y, -Kinematic.RotateCenterOffsetOfC.Z));
      MachineEntities.Add((eEntities) eLine2);
    }
    catch (Exception ex)
    {
      string str = "Kinematic: " + Kinematic.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

