  public int FontToVectorConvert(
    Pnt3D Location,
    Font fFont,
    string ConvertString,
    WorkPlane Plane,
    Pnt3D PlaneOffset,
    ref List<TriangulationPoints> CalculatedPoints)
  {
    Graphics fx = (Graphics) null;
    List<TriangulationPoints> CalculatedPoints1 = new List<TriangulationPoints>();
    int vectorConvert = this.FontToVectorConvert(fx, fFont, ConvertString, ref CalculatedPoints1);
    for (int index1 = 0; index1 <= CalculatedPoints1.Count - 1; ++index1)
    {
      TriangulationPoints Triangulation = new TriangulationPoints();
      for (int index2 = 0; index2 <= CalculatedPoints1[index1].Points.Count - 1; ++index2)
      {
        Pnt3D pnt3D = new Pnt3D(CalculatedPoints1[index1].Points[index2]);
        if (WorkPlane.isPlaneXY(Plane))
          pnt3D.Z = PlaneOffset.Z;
        if (WorkPlane.isPlaneXZ(Plane))
        {
          pnt3D.Z = pnt3D.Y;
          pnt3D.Y = PlaneOffset.Y;
        }
        if (WorkPlane.isPlaneYZ(Plane))
        {
          double y = pnt3D.Y;
          pnt3D.Y = pnt3D.X;
          pnt3D.Z = y;
          pnt3D.X = PlaneOffset.X;
        }
        Triangulation.Points.Add(pnt3D);
      }
      for (int index3 = 0; index3 <= CalculatedPoints1[index1].Holes.Count - 1; ++index3)
      {
        List<Pnt3D> pnt3DList = new List<Pnt3D>();
        for (int index4 = 0; index4 <= CalculatedPoints1[index1].Holes[index3].Count - 1; ++index4)
        {
          Pnt3D pnt3D = new Pnt3D(CalculatedPoints1[index1].Holes[index3][index4]);
          if (WorkPlane.isPlaneXY(Plane))
            pnt3D.Z = PlaneOffset.Z;
          if (WorkPlane.isPlaneXZ(Plane))
          {
            pnt3D.Z = pnt3D.Y;
            pnt3D.Y = PlaneOffset.Y;
          }
          if (WorkPlane.isPlaneYZ(Plane))
          {
            double y = pnt3D.Y;
            pnt3D.Y = pnt3D.X;
            pnt3D.Z = y;
            pnt3D.X = PlaneOffset.X;
          }
          pnt3DList.Add(pnt3D);
        }
        Triangulation.Holes.Add(pnt3DList);
      }
      for (int index5 = 0; index5 <= CalculatedPoints1[index1].Triangles.Count - 1; ++index5)
      {
        Triangle3D triangle3D = new Triangle3D(CalculatedPoints1[index1].Triangles[index5]);
        if (WorkPlane.isPlaneXY(Plane))
        {
          triangle3D.FirstPoint.Z = PlaneOffset.Z;
          triangle3D.SecondPoint.Z = PlaneOffset.Z;
          triangle3D.ThirdPoint.Z = PlaneOffset.Z;
        }
        if (WorkPlane.isPlaneXZ(Plane))
        {
          triangle3D.FirstPoint.Z = triangle3D.FirstPoint.Y;
          triangle3D.SecondPoint.Z = triangle3D.SecondPoint.Y;
          triangle3D.ThirdPoint.Z = triangle3D.ThirdPoint.Y;
          triangle3D.FirstPoint.Y = PlaneOffset.Y;
          triangle3D.SecondPoint.Y = PlaneOffset.Y;
          triangle3D.ThirdPoint.Y = PlaneOffset.Y;
        }
        if (WorkPlane.isPlaneYZ(Plane))
        {
          double y1 = triangle3D.FirstPoint.Y;
          triangle3D.FirstPoint.Y = triangle3D.FirstPoint.X;
          triangle3D.FirstPoint.Z = y1;
          triangle3D.FirstPoint.X = PlaneOffset.X;
          double y2 = triangle3D.SecondPoint.Y;
          triangle3D.SecondPoint.Y = triangle3D.SecondPoint.X;
          triangle3D.SecondPoint.Z = y2;
          triangle3D.SecondPoint.X = PlaneOffset.X;
          double y3 = triangle3D.ThirdPoint.Y;
          triangle3D.ThirdPoint.Y = triangle3D.ThirdPoint.X;
          triangle3D.ThirdPoint.Z = y3;
          triangle3D.ThirdPoint.X = PlaneOffset.X;
        }
        Triangulation.Triangles.Add(triangle3D);
      }
      this.Move(new Pnt3D(), Location, ref Triangulation);
      CalculatedPoints.Add(Triangulation);
    }
    return vectorConvert;
  }

  public int FontToVectorConvert(
